import type { PQSubject } from "../previous-questions-types";
export const PQ_DATA: PQSubject[] = JSON.parse("[{\"slug\":\"cpl-meteorology\",\"subjectId\":\"meteorology\",\"title\":\"CPL Meteorology\",\"short\":\"Meteorology\",\"published\":true,\"checked\":\"17 Oct 2026\",\"sittings\":[\"Oct 2021 · Attempt 2\",\"Mar 2022 · Regular\",\"May 2022 · Regular\",\"Jul 2022 · OLODE 05\",\"2022 · Regular 03\",\"Jun 2023 · Regular\",\"Jul 2023 · OLODE\",\"Sep 2023 · Regular 03\",\"Oct 2023 · OLODE\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"May 2024 · OLODE\",\"Aug 2024 · OLODE\",\"Sep 2024 · Regular 03\",\"Oct 2024 · OLODE 07\",\"Nov 2024 · OLODE 08\",\"Dec 2024 · Regular 04\",\"Jan 2025 · OLODE 01\",\"Feb 2025 · OLODE 02\",\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\",\"Jul 2025 · OLODE 05\",\"Aug 2025 · OLODE 06\",\"Sep 2025 · Regular 03\",\"Oct 2025 · OLODE 07\",\"Dec 2025 · Regular 04\",\"Jan 2026 · OLODE 01\",\"Mar 2026 · Regular 01\",\"Apr 2026 · OLODE 03\",\"May 2026 · OLODE 04\",\"Aug 2026 · OLODE 06\"],\"firstYear\":2021,\"lastYear\":2026,\"questions\":[{\"id\":\"CPLMET-001\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The atmosphere up to about 80 km has a nearly uniform composition and is called the homosphere. Its uniform composition is due to\",\"opts\":[\"Pressure\",\"Gravitation of the earth\",\"Mixing due to turbulence\"],\"ans\":2,\"exp\":\"Below about 80 km the air is constantly stirred by turbulence and convection, so nitrogen, oxygen and argon stay in the same proportions all the way up. Gravity on its own would sort the gases by weight - that only happens higher up, in the heterosphere, where the mixing stops.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2022,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-002\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The boundary between the troposphere and the stratosphere is called the\",\"opts\":[\"Stratopause\",\"Tropopause\",\"Mesopause\"],\"ans\":1,\"exp\":\"Each boundary takes the name of the layer below it with \\\"-pause\\\" added. The top of the troposphere is therefore the tropopause; the stratopause caps the stratosphere at about 50 km.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Apr 2026 · OLODE 03\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-003\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The tropopause is\",\"opts\":[\"The boundary between the stratosphere and the mesosphere\",\"The layer separating the troposphere from the stratosphere\",\"The cloud-top layer\"],\"ans\":1,\"exp\":\"The tropopause is the lid of the troposphere - the thin transition layer where the normal fall of temperature with height stops and the stable stratosphere begins.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Mar 2025 · Regular 01\",\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-004\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The tropopause is the level at which\",\"opts\":[\"Temperature starts rising sharply with height\",\"The fall of temperature with height stops\",\"Pressure becomes zero\"],\"ans\":1,\"exp\":\"Through the troposphere the temperature falls with height. At the tropopause that fall stops and the temperature becomes nearly constant (and higher up in the stratosphere it rises). That change in lapse rate is how the tropopause is identified.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-005\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The height of the tropopause primarily depends on\",\"opts\":[\"Longitude only\",\"Latitude only\",\"Both latitude and longitude\"],\"ans\":1,\"exp\":\"The tropopause is highest over the warm equator (about 16-18 km) and lowest over the cold poles (about 8-10 km). A warmer surface gives a deeper troposphere, so the height changes with latitude (and season), not with longitude.\",\"seenIn\":[\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-006\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The height of the tropopause is lowest over the\",\"opts\":[\"Equator\",\"Mid-latitudes\",\"Poles\"],\"ans\":2,\"exp\":\"Cold polar air gives a shallow troposphere, so the tropopause sits at about 8-10 km over the poles against about 16-18 km over the equator.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Mar 2024 · Regular 01\",\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":3,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-007\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"In the ISA, the tropopause is at a height of\",\"opts\":[\"8 km\",\"11 km\",\"16 km\"],\"ans\":1,\"exp\":\"The ICAO Standard Atmosphere puts the tropopause at 11 km (36 090 ft), with a temperature of -56.5 °C. It is an average, mid-latitude value - the real tropopause is higher over the equator and lower over the poles.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Apr 2026 · OLODE 03\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-008\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"Over the equator, the tropopause is at about\",\"opts\":[\"16-18 km, and it is the coldest tropopause on earth\",\"11 km, at -56.5 °C\",\"8-10 km, and warmer than over the poles\"],\"ans\":0,\"exp\":\"The correct answer is: 16-18 km, and it is the coldest tropopause on earth.\",\"seenIn\":[\"May 2022 · Regular\",\"Apr 2024 · OLODE 03\",\"Aug 2025 · OLODE 06\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-009\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"Knowledge of the tropopause height is important to a pilot because\",\"opts\":[\"Weather is mainly confined below this level\",\"Clouds never form below this level\",\"All solar radiation is absorbed at this level\"],\"ans\":0,\"exp\":\"Almost all the water vapour, cloud and weather lives in the troposphere. The tropopause also marks where jet streams and clear-air turbulence are found, so its height tells you where the weather stops and where to watch for CAT.\",\"seenIn\":[\"Mar 2026 · Regular 01\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-010\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The lapse rate in the troposphere is produced by ______ and the inversion in the stratosphere by ______\",\"opts\":[\"Evaporation; condensation\",\"Terrestrial radiation heating the air from below; ozone absorbing solar ultraviolet\",\"Solar radiation; convection\"],\"ans\":1,\"exp\":\"The troposphere is heated from the bottom by the earth, so it is warmest at the surface and cools with height. The stratosphere is heated from within - ozone absorbs the sun's ultraviolet - so it warms with height.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-011\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"Nacreous clouds occur in the\",\"opts\":[\"Thermosphere\",\"Mesosphere\",\"Upper stratosphere\"],\"ans\":2,\"exp\":\"Nacreous (mother-of-pearl) clouds are thin iridescent clouds in the stratosphere, around 20-30 km, seen mostly in high latitudes. Do not confuse them with noctilucent clouds, which are higher still, in the mesosphere.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Sep 2024 · Regular 03\",\"Feb 2025 · OLODE 02\",\"May 2025 · OLODE 04\",\"Aug 2025 · OLODE 06\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":8,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-012\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"Noctilucent clouds occur in the\",\"opts\":[\"Thermosphere\",\"Mesosphere\",\"Stratosphere\"],\"ans\":1,\"exp\":\"Noctilucent clouds are the highest clouds of all, near the mesopause at about 80 km. They shine after sunset because at that height they are still lit by the sun.\",\"seenIn\":[\"Dec 2024 · Regular 04\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-013\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"Approximately half of the mass of the atmosphere lies below about\",\"opts\":[\"5.5-6 km (18 000-20 000 ft)\",\"11 km\",\"16 km\"],\"ans\":0,\"exp\":\"Pressure halves by about 18 000 ft (500 hPa is roughly 5.5 km). Since pressure is the weight of the air above, half the atmosphere's mass is below that level - and about three-quarters is inside the troposphere.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-014\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"Standard ISA conditions at mean sea level are\",\"opts\":[\"0 °C and 1000 hPa\",\"15 °C and 1013.25 hPa\",\"20 °C and 1010 hPa\"],\"ans\":1,\"exp\":\"ISA at MSL: temperature +15 °C, pressure 1013.25 hPa, density 1.225 kg/m3. Everything else in the ISA - and every altimeter - is built from these numbers.\",\"seenIn\":[\"May 2024 · OLODE\",\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-015\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"In the ISA, the temperature at 10 000 ft is about\",\"opts\":[\"+5 °C\",\"-5 °C\",\"-15 °C\"],\"ans\":1,\"exp\":\"ISA falls about 2 °C per 1000 ft (1.98). From +15 °C at MSL: 15 - 20 = -5 °C at 10 000 ft.\",\"seenIn\":[\"Jul 2023 · OLODE\",\"Sep 2024 · Regular 03\",\"Mar 2025 · Regular 01\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-016\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"In the ISA, the temperature at FL200 is\",\"opts\":[\"-15 °C\",\"-25 °C\",\"-35 °C\"],\"ans\":1,\"exp\":\"15 - (20 x 2) = -25 °C. Learn the pattern: every 5000 ft is 10 °C, so FL100 is -5, FL200 -25, FL300 -45.\",\"seenIn\":[\"2022 · Regular 03\",\"Apr 2025 · OLODE 03\",\"Dec 2025 · Regular 04\"],\"undated\":true,\"times\":3,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-017\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The OAT at FL200 is -35 °C. The ISA deviation is\",\"opts\":[\"ISA -10 °C\",\"ISA -15 °C\",\"ISA +5 °C\"],\"ans\":0,\"exp\":\"ISA at FL200 is -25 °C. Actual minus ISA = -35 - (-25) = -10, so the air is 10 °C colder than standard: ISA -10.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-018\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The observed temperature at 10 km is -40 °C. This is\",\"opts\":[\"10 °C warmer than ISA\",\"10 °C colder than ISA\",\"15 °C colder than ISA\"],\"ans\":0,\"exp\":\"ISA at 10 km = 15 - (6.5 x 10) = -50 °C. The actual -40 °C is 10 °C warmer than standard.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-019\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The ISA (average environmental) lapse rate in the troposphere is\",\"opts\":[\"1.5 °C per 1000 ft\",\"2 °C per 1000 ft (6.5 °C per km)\",\"3 °C per 1000 ft\"],\"ans\":1,\"exp\":\"The ISA lapse rate is 6.5 °C per km, which is 1.98 - call it 2 - °C per 1000 ft, up to the tropopause at 11 km. 3 °C per 1000 ft is the dry adiabatic rate, a different thing.\",\"seenIn\":[\"May 2022 · Regular\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Dec 2025 · Regular 04\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":5,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-020\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The temperature at FL160 is -22 °C. Using the ISA lapse rate, the temperature at FL090 is\",\"opts\":[\"-8 °C\",\"-36 °C\",\"-15 °C\"],\"ans\":0,\"exp\":\"FL160 to FL090 is 7000 ft lower. At 2 °C per 1000 ft that is 14 °C warmer: -22 + 14 = -8 °C. Going down, it gets warmer.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Feb 2025 · OLODE 02\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-021\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The temperature at FL140 is -12 °C. Using the ISA lapse rate, the temperature at FL110 is\",\"opts\":[\"-18 °C\",\"-6 °C\",\"-9 °C\"],\"ans\":1,\"exp\":\"3000 ft lower x 2 °C per 1000 ft = 6 °C warmer: -12 + 6 = -6 °C.\",\"seenIn\":[\"May 2024 · OLODE\",\"Jan 2025 · OLODE 01\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-022\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"In the ISA, a height of 18 000 ft corresponds to a pressure level of about\",\"opts\":[\"700 hPa\",\"600 hPa\",\"500 hPa\"],\"ans\":2,\"exp\":\"18 000 ft is roughly 500 hPa - half the sea-level pressure. Keep the set: 850 hPa about 5000 ft, 700 hPa about 10 000 ft, 500 hPa about 18 000 ft, 300 hPa about 30 000 ft.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Mar 2024 · Regular 01\",\"May 2024 · OLODE\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-023\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"In the ISA, the 700 hPa level corresponds approximately to\",\"opts\":[\"FL050\",\"FL100\",\"FL180\"],\"ans\":1,\"exp\":\"700 hPa sits at about 10 000 ft (roughly 3 km), i.e. about FL100.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-024\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"In the ISA, 24 000 ft corresponds approximately to\",\"opts\":[\"300 hPa\",\"400 hPa\",\"500 hPa\"],\"ans\":1,\"exp\":\"24 000 ft is about 400 hPa (ISA 393 hPa). Between the anchors 500 hPa at 18 000 ft and 300 hPa at 30 000 ft.\",\"seenIn\":[\"Mar 2022 · Regular\",\"May 2022 · Regular\",\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":3,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-025\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The maximum concentration of ozone in the atmosphere is found at a height of about\",\"opts\":[\"10-15 km\",\"20-25 km\",\"30-35 km\"],\"ans\":1,\"exp\":\"The ozone layer lies in the stratosphere with its maximum concentration around 20-25 km. Its absorption of the sun's ultraviolet is what warms the stratosphere with height.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-026\",\"topic\":\"Temperature & radiation\",\"stem\":\"Hot bodies like the sun radiate mainly\",\"opts\":[\"Long waves\",\"Short waves\",\"Both equally\"],\"ans\":1,\"exp\":\"The hotter the body, the shorter the wavelength of its strongest radiation. The sun (about 6000 K) sends short-wave radiation; the much cooler earth sends back long-wave (infrared) radiation.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Apr 2024 · OLODE 03\",\"Feb 2025 · OLODE 02\",\"Aug 2025 · OLODE 06\",\"Oct 2025 · OLODE 07\"],\"undated\":true,\"times\":5,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-027\",\"topic\":\"Temperature & radiation\",\"stem\":\"Wien's law states that the wavelength of maximum radiation is\",\"opts\":[\"Directly proportional to the absolute temperature\",\"Inversely proportional to the absolute temperature\",\"Independent of temperature\"],\"ans\":1,\"exp\":\"Wien: wavelength of peak emission = constant / T (absolute). Double the temperature and the peak wavelength halves. That is why the sun radiates short waves and the earth long waves.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Mar 2024 · Regular 01\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-028\",\"topic\":\"Temperature & radiation\",\"stem\":\"The greatest transfer of heat from the earth's surface to the atmosphere is by\",\"opts\":[\"Convection\",\"Radiation\",\"Latent heat (evaporation and condensation)\"],\"ans\":2,\"exp\":\"Water evaporated at the surface carries its latent heat up with it and releases it when it condenses into cloud. This latent-heat route accounts for about 77% of the non-radiative heat flow from surface to air; sensible heat carries the rest.\",\"seenIn\":[\"Mar 2026 · Regular 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-029\",\"topic\":\"Temperature & radiation\",\"stem\":\"Water vapour is ______ transparent to terrestrial (long-wave) radiation\",\"opts\":[\"Completely\",\"Partially\",\"Not at all\"],\"ans\":1,\"exp\":\"Water vapour lets short-wave sunlight through but absorbs much of the earth's long-wave radiation, except in a few \\\"window\\\" wavelengths. That partial absorption is the greenhouse effect - and why humid nights cool less than dry ones.\",\"seenIn\":[\"May 2024 · OLODE\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-030\",\"topic\":\"Temperature & radiation\",\"stem\":\"Cloudy nights are generally\",\"opts\":[\"Cold\",\"Normal\",\"Warm\"],\"ans\":2,\"exp\":\"Cloud absorbs the long-wave radiation escaping from the ground and sends much of it back down. The surface cannot cool as much, so cloudy nights stay warmer than clear ones - and fog and frost are less likely.\",\"seenIn\":[\"Nov 2024 · OLODE 08\",\"Oct 2025 · OLODE 07\",\"Mar 2026 · Regular 01\"],\"undated\":true,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-031\",\"topic\":\"Temperature & radiation\",\"stem\":\"The diurnal variation of temperature is greatest when the wind is\",\"opts\":[\"Strong\",\"Calm\",\"Gusty\"],\"ans\":1,\"exp\":\"With calm air the heating by day and cooling by night stay concentrated in a thin layer near the ground, so the range is large. A strong wind mixes the heat through a deep layer and flattens the range. Clear skies and dry land add to it; cloud, sea and wind reduce it.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Oct 2025 · OLODE 07\",\"Jan 2026 · OLODE 01\"],\"undated\":true,\"times\":3,\"years\":[2021,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-032\",\"topic\":\"Temperature & radiation\",\"stem\":\"What is meant by the diurnal variation of temperature?\",\"opts\":[\"The difference between the maximum and minimum temperature in 24 hours\",\"The change of temperature between summer and winter\",\"The difference between land and sea temperature\"],\"ans\":0,\"exp\":\"\\\"Diurnal\\\" means daily. The diurnal range is the day's maximum minus the night's minimum. The summer-winter difference is the annual range.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-033\",\"topic\":\"Temperature & radiation\",\"stem\":\"The minimum temperature of the day is normally reached\",\"opts\":[\"At midnight\",\"At sunrise\",\"About half to one hour after sunrise\"],\"ans\":2,\"exp\":\"The ground keeps losing heat until the incoming sunshine becomes stronger than the outgoing radiation, which happens a little after sunrise. So the coldest time is about 30 minutes to an hour after dawn - also when radiation fog is often thickest.\",\"seenIn\":[\"2022 · Regular 03\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"May 2025 · OLODE 04\",\"Oct 2025 · OLODE 07\",\"Apr 2026 · OLODE 03\"],\"undated\":true,\"times\":6,\"years\":[2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-034\",\"topic\":\"Temperature & radiation\",\"stem\":\"The maximum temperature of the day normally occurs at about\",\"opts\":[\"1200 hrs\",\"1300 hrs\",\"1400 hrs\"],\"ans\":2,\"exp\":\"The sun is highest at noon, but the ground keeps gaining more heat than it loses for another 2-3 hours. The maximum therefore comes in the early afternoon, around 1400 local time.\",\"seenIn\":[\"Mar 2026 · Regular 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-035\",\"topic\":\"Temperature & radiation\",\"stem\":\"Surface air temperature is measured (Stevenson screen) at a height above the ground of\",\"opts\":[\"1.0 m\",\"1.25 m\",\"2.0 m\"],\"ans\":1,\"exp\":\"In India the thermometers sit in a Stevenson screen with the bulbs 1.25 m above the ground - high enough to avoid the extreme ground temperature, shaded from direct sun and rain, and ventilated by louvres.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jul 2022 · OLODE 05\",\"Dec 2023 · Regular\",\"Apr 2024 · OLODE 03\",\"Sep 2024 · Regular 03\",\"Dec 2024 · Regular 04\",\"Jun 2025 · Regular 02\",\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":8,\"years\":[2021,2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-036\",\"topic\":\"Temperature & radiation\",\"stem\":\"The rate of fall of temperature with height is called the\",\"opts\":[\"Lapse rate\",\"Inversion\",\"Isothermal rate\"],\"ans\":0,\"exp\":\"A lapse rate is how fast temperature falls as you climb. If temperature stays constant with height the layer is isothermal; if it rises, that is an inversion.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-037\",\"topic\":\"Temperature & radiation\",\"stem\":\"An increase of temperature with height is called\",\"opts\":[\"Lapse rate\",\"Inversion\",\"Isothermal layer\"],\"ans\":1,\"exp\":\"Temperature rising with height is an inversion - a negative lapse rate. It is the most stable arrangement the atmosphere can have.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"2022 · Regular 03\",\"Sep 2023 · Regular 03\",\"Apr 2024 · OLODE 03\",\"Dec 2024 · Regular 04\",\"Feb 2025 · OLODE 02\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":7,\"years\":[2021,2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-038\",\"topic\":\"Temperature & radiation\",\"stem\":\"Under normal conditions in the troposphere, temperature\",\"opts\":[\"Increases with height\",\"Decreases with height\",\"Remains constant with height\"],\"ans\":1,\"exp\":\"The troposphere is heated from below by the earth, so normally it is warmest at the surface and cools as you go up - on average about 2 °C per 1000 ft.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-039\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Low pressure is associated with\",\"opts\":[\"Good weather\",\"Bad weather\",\"No particular weather\"],\"ans\":1,\"exp\":\"Air converges into a low and rises. Rising air cools, reaches saturation and builds cloud and precipitation - hence bad weather. A high does the opposite: sinking air warms and dries.\",\"seenIn\":[\"May 2022 · Regular\",\"Apr 2024 · OLODE 03\",\"May 2025 · OLODE 04\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-040\",\"topic\":\"Pressure & altimetry\",\"stem\":\"The vertical movement of air in a cyclone (low) is\",\"opts\":[\"Descending and subsiding\",\"Ascending and converging\",\"Ascending and diverging\"],\"ans\":1,\"exp\":\"At the surface air spirals in towards the low (convergence) and, having nowhere else to go, rises. That rising air is the source of the cloud and rain around a low.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-041\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Flying from low pressure to high pressure without changing the sub-scale, the altimeter will\",\"opts\":[\"Over-read\",\"Under-read\",\"Read correctly\"],\"ans\":1,\"exp\":\"Flying towards higher pressure, the altimeter sees more pressure and shows a lower height than you actually have - it under-reads, and you are higher than indicated. The dangerous case is the reverse: \\\"High to low, look out below.\\\"\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Mar 2024 · Regular 01\",\"Sep 2024 · Regular 03\",\"Mar 2025 · Regular 01\",\"Oct 2025 · OLODE 07\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":6,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-042\",\"topic\":\"Pressure & altimetry\",\"stem\":\"An altimeter on the ground reads the aerodrome elevation when the sub-scale is set to\",\"opts\":[\"QFE\",\"QNH\",\"QNE\"],\"ans\":1,\"exp\":\"QNH is the aerodrome pressure reduced to MSL using the ISA, so with QNH set the altimeter shows height above mean sea level - on the ground, the aerodrome elevation. With QFE set it would read zero.\",\"seenIn\":[\"2022 · Regular 03\",\"Dec 2023 · Regular\",\"May 2025 · OLODE 04\",\"Oct 2025 · OLODE 07\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":5,\"years\":[2022,2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-043\",\"topic\":\"Pressure & altimetry\",\"stem\":\"QNH is\",\"opts\":[\"QFE reduced to mean sea level using the ISA\",\"QFE reduced to mean sea level using the actual temperature\",\"The standard setting of 1013.25 hPa\"],\"ans\":0,\"exp\":\"QNH = aerodrome pressure brought down to MSL assuming ISA conditions. When the actual temperature is used instead, the result is QFF (the value on weather charts). 1013.25 hPa is the standard setting used for flight levels.\",\"seenIn\":[\"May 2022 · Regular\",\"Apr 2024 · OLODE 03\",\"Nov 2024 · OLODE 08\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-044\",\"topic\":\"Pressure & altimetry\",\"stem\":\"At an aerodrome well above mean sea level, the QNH compared with the QFE is\",\"opts\":[\"Lower\",\"Higher\",\"The same\"],\"ans\":1,\"exp\":\"QFE is the actual pressure at the aerodrome. QNH is that pressure reduced to sea level, and pressure increases as you go down, so QNH is higher - by about 1 hPa for every 27-30 ft of elevation.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-045\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Lines joining places of equal pressure are called\",\"opts\":[\"Isobars\",\"Isotherms\",\"Isohyets\"],\"ans\":0,\"exp\":\"Isobars join equal pressure, isotherms equal temperature, isohyets equal rainfall, isallobars equal pressure tendency. Closely spaced isobars mean strong wind.\",\"seenIn\":[\"May 2025 · OLODE 04\",\"Oct 2025 · OLODE 07\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-046\",\"topic\":\"Pressure & altimetry\",\"stem\":\"An isallobar is a line joining places of equal\",\"opts\":[\"Pressure\",\"Temperature tendency\",\"Pressure tendency\"],\"ans\":2,\"exp\":\"The correct answer is: Pressure tendency.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Apr 2024 · OLODE 03\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":3,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-047\",\"topic\":\"Pressure & altimetry\",\"stem\":\"On either side, perpendicular to a ______, the pressure rises\",\"opts\":[\"Trough\",\"Ridge\",\"Col\"],\"ans\":0,\"exp\":\"A trough is a line of lowest pressure running out from a low. Move away from it at right angles on either side and the pressure goes up. (Across a ridge, it falls.)\",\"seenIn\":[\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"May 2024 · OLODE\",\"Apr 2026 · OLODE 03\"],\"undated\":true,\"times\":4,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-048\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Pressure along a trough, compared with the surroundings, is\",\"opts\":[\"Higher\",\"Lower\",\"The same\"],\"ans\":1,\"exp\":\"A trough is an elongated extension of low pressure, so the pressure along its axis is lower than on either side.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-049\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Atmospheric pressure is due to\",\"opts\":[\"Wind\",\"Temperature\",\"The weight of the air above (gravity)\"],\"ans\":2,\"exp\":\"Pressure at any point is the weight of the column of air above it, pulled down by gravity. That is why it always falls as you climb - there is less air above you.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-050\",\"topic\":\"Pressure & altimetry\",\"stem\":\"The pressure gradient is\",\"opts\":[\"The change of pressure with horizontal distance\",\"The change of pressure with height\",\"The change of pressure with time\"],\"ans\":0,\"exp\":\"The horizontal pressure gradient is how quickly pressure changes across the ground, at right angles to the isobars. It drives the wind. Change with time is pressure tendency.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-051\",\"topic\":\"Pressure & altimetry\",\"stem\":\"A steep pressure gradient means\",\"opts\":[\"Isobars far apart and weak winds\",\"Isobars closely packed and strong winds\",\"Isobars closely packed and weak winds\"],\"ans\":1,\"exp\":\"Steep gradient = pressure changes quickly over a short distance = isobars crowded together = strong wind.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"May 2024 · OLODE\",\"Dec 2024 · Regular 04\",\"Mar 2025 · Regular 01\",\"May 2025 · OLODE 04\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":6,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-052\",\"topic\":\"Pressure & altimetry\",\"stem\":\"An altimeter measures the height of the aircraft above the\",\"opts\":[\"Mean sea level\",\"1013.25 hPa datum only\",\"Pressure datum set on its sub-scale\"],\"ans\":2,\"exp\":\"An altimeter is a barometer. It reads height above whatever pressure level you set: with QNH, height above MSL; with QFE, height above the aerodrome; with 1013.25, a flight level.\",\"seenIn\":[\"May 2024 · OLODE\",\"Apr 2026 · OLODE 03\"],\"undated\":true,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-053\",\"topic\":\"Pressure & altimetry\",\"stem\":\"If the QNH, QFE and QFF of an aerodrome are the same, the aerodrome is\",\"opts\":[\"In ISA conditions\",\"At MSL, but only if the temperature is ISA\",\"At mean sea level\"],\"ans\":2,\"exp\":\"QNH and QFF are both QFE corrected down to sea level. If the aerodrome is already at sea level there is nothing to correct, so all three are equal whatever the temperature.\",\"seenIn\":[\"May 2022 · Regular\",\"Dec 2023 · Regular\"],\"undated\":true,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-054\",\"topic\":\"Pressure & altimetry\",\"stem\":\"An aerodrome at mean sea level reports QNH 1022 hPa. Its QFF is\",\"opts\":[\"1022 hPa\",\"1013 hPa\",\"Cannot be determined\"],\"ans\":0,\"exp\":\"At an aerodrome at MSL, QFE, QNH and QFF are all the same value, because no height correction is needed.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Dec 2023 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-055\",\"topic\":\"Pressure & altimetry\",\"stem\":\"A pressure reported as Q1003 in a METAR can be anywhere in the range\",\"opts\":[\"1002.5 to 1003.5 hPa\",\"1003.0 to 1003.9 hPa\",\"1003.1 to 1003.5 hPa\"],\"ans\":1,\"exp\":\"QNH is rounded DOWN to the whole hectopascal, so 1003.0 up to 1003.9 all go out as Q1003. Rounding down keeps the altimeter error on the safe side.\",\"seenIn\":[\"2022 · Regular 03\",\"Dec 2023 · Regular\",\"Jan 2025 · OLODE 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":4,\"years\":[2022,2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-056\",\"topic\":\"Pressure & altimetry\",\"stem\":\"The group Q1003 in a METAR indicates\",\"opts\":[\"QFE\",\"QFF\",\"QNH\"],\"ans\":2,\"exp\":\"In a METAR, Q followed by four figures is the QNH in hectopascals. (A followed by four figures is the altimeter setting in inches, e.g. A2992.)\",\"seenIn\":[\"Jun 2023 · Regular\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-057\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Flight levels are measured with reference to a pressure setting of\",\"opts\":[\"1013.25 hPa\",\"1025.13 hPa\",\"QFE\"],\"ans\":0,\"exp\":\"Flight levels are pressure altitudes: every aircraft sets the standard 1013.25 hPa so that all are measured from the same datum and vertical separation holds.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-058\",\"topic\":\"Pressure & altimetry\",\"stem\":\"The rate of fall of pressure with height in a warm air mass, compared with a cold air mass, is\",\"opts\":[\"The same\",\"More rapid\",\"Less rapid\"],\"ans\":2,\"exp\":\"Warm air is less dense, so you must climb further to lose each hectopascal - pressure falls more slowly. That is why a pressure level is higher in warm air, and why an altimeter over-reads in cold air.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2022,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-059\",\"topic\":\"Pressure & altimetry\",\"stem\":\"A parked aircraft has its altimeter set. As a cold front passes and the pressure rises behind it, the altimeter reading will\",\"opts\":[\"Increase\",\"Decrease\",\"Remain unchanged\"],\"ans\":1,\"exp\":\"Pressure falls as a cold front approaches (the altimeter reads higher) and rises sharply after it passes (the altimeter reading drops). A rise in pressure always makes a fixed-setting altimeter show less height.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Nov 2024 · OLODE 08\",\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-060\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Over land in winter, a high pressure area generally gives\",\"opts\":[\"Clear skies with haze, mist or fog and poor visibility\",\"Widespread heavy rain\",\"Thunderstorms and squalls\"],\"ans\":0,\"exp\":\"Sinking air in a high is stable and dry above, with light winds. Smoke, dust and moisture get trapped under the subsidence inversion, so a winter high over land means clear skies but poor visibility, haze and fog.\",\"seenIn\":[\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-061\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Poor visibility is most often associated with\",\"opts\":[\"A high\",\"A low\",\"A col\"],\"ans\":0,\"exp\":\"Highs are stable: sinking air forms an inversion that traps haze, smoke and fog near the ground, and the light winds cannot clear it. Lows bring cloud and rain but usually cleaner air between showers.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-062\",\"topic\":\"Pressure & altimetry\",\"stem\":\"On a 300 hPa constant pressure chart, contours are normally drawn at an interval of\",\"opts\":[\"40 gpm\",\"60 gpm\",\"80 gpm\"],\"ans\":2,\"exp\":\"Contours on the 700 and 500 hPa charts are drawn every 40 geopotential metres; on the 300 and 200 hPa charts, every 80 gpm.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-063\",\"topic\":\"Density\",\"stem\":\"Near the surface, air density at the poles compared with the equator is\",\"opts\":[\"Higher\",\"Lower\",\"The same\"],\"ans\":0,\"exp\":\"Cold air is denser than warm air, so the cold polar surface air is denser than the warm equatorial air.\",\"seenIn\":[\"Oct 2025 · OLODE 07\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-064\",\"topic\":\"Density\",\"stem\":\"Above about 8 km, air density at the poles compared with the equator is\",\"opts\":[\"Higher\",\"Lower\",\"The same\"],\"ans\":1,\"exp\":\"The picture reverses aloft. The polar air is so dense that most of its mass is packed low down, so above about 8 km there is less air left over the poles than over the equator - density is lower there.\",\"seenIn\":[\"Jun 2025 · Regular 02\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-065\",\"topic\":\"Density\",\"stem\":\"When the density altitude increases, the air density\",\"opts\":[\"Increases\",\"Decreases\",\"Remains unchanged\"],\"ans\":1,\"exp\":\"A high density altitude means the air is as thin as it would be much higher up in the ISA. Less dense air gives less lift and less engine power - the hot, high aerodrome problem.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Mar 2025 · Regular 01\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-066\",\"topic\":\"Density\",\"stem\":\"Density altitude is\",\"opts\":[\"The ISA altitude at which the prevailing pressure occurs\",\"The ISA altitude at which the prevailing density occurs\",\"The height above the aerodrome\"],\"ans\":1,\"exp\":\"Density altitude is the height in the standard atmosphere that has the same density as the air you are actually in. The first option describes pressure altitude.\",\"seenIn\":[\"Dec 2024 · Regular 04\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-067\",\"topic\":\"Humidity\",\"stem\":\"The ratio (in %) of the amount of water vapour present in the air to the amount it can hold at the same temperature is called\",\"opts\":[\"Absolute humidity\",\"Relative humidity\",\"Specific humidity\"],\"ans\":1,\"exp\":\"Relative humidity compares what the air holds with what it could hold at that temperature. 100% means saturated.\",\"seenIn\":[\"Jun 2025 · Regular 02\",\"Mar 2026 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-068\",\"topic\":\"Humidity\",\"stem\":\"Relative humidity is defined as\",\"opts\":[\"The amount of water vapour present in the air\",\"The ratio of the actual vapour pressure to the saturation vapour pressure at the same temperature\",\"The maximum moisture the air can hold\"],\"ans\":1,\"exp\":\"RH = actual vapour pressure / saturation vapour pressure at the same temperature, as a percentage. It is a ratio, not an amount - the amount is absolute humidity.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Jan 2025 · OLODE 01\",\"Dec 2025 · Regular 04\"],\"undated\":true,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-069\",\"topic\":\"Humidity\",\"stem\":\"The actual amount (mass) of water vapour contained in a given volume of air is termed\",\"opts\":[\"Relative humidity\",\"Specific humidity\",\"Absolute humidity\"],\"ans\":2,\"exp\":\"Absolute humidity is grams of water vapour per cubic metre of air. Specific humidity is per kilogram of moist air; the humidity mixing ratio is per kilogram of dry air.\",\"seenIn\":[\"2022 · Regular 03\",\"Jun 2023 · Regular\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-070\",\"topic\":\"Humidity\",\"stem\":\"The temperature to which air must be cooled at constant pressure to become saturated is called the\",\"opts\":[\"Wet bulb temperature\",\"Dew point\",\"Lapse rate\"],\"ans\":1,\"exp\":\"Cool air without adding or removing water vapour and at the dew point it is saturated; cool it further and the vapour condenses - dew, fog or cloud.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jun 2023 · Regular\",\"Oct 2023 · OLODE\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Jan 2025 · OLODE 01\",\"Feb 2025 · OLODE 02\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":9,\"years\":[2021,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-071\",\"topic\":\"Humidity\",\"stem\":\"The lowest temperature to which air can be cooled by evaporating water into it until it is saturated is the\",\"opts\":[\"Wet bulb temperature\",\"Dew point\",\"Dry bulb temperature\"],\"ans\":0,\"exp\":\"A wet cloth on the thermometer bulb lets water evaporate, which takes heat from the bulb. The reading it settles at is the wet-bulb temperature. It lies between the dew point and the air temperature.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-072\",\"topic\":\"Humidity\",\"stem\":\"An air parcel is lifted until it becomes saturated. The temperature it has then reached is called its\",\"opts\":[\"Potential temperature\",\"Dew point\",\"Wet bulb temperature\"],\"ans\":1,\"exp\":\"Rising air cools until its temperature meets its dew point; there it is saturated and cloud forms. At the condensation level the parcel's temperature equals its dew point.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Mar 2025 · Regular 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-073\",\"topic\":\"Humidity\",\"stem\":\"Air temperature, wet bulb temperature and dew point are all equal when\",\"opts\":[\"The air is dry\",\"The relative humidity is 100%\",\"The pressure decreases\"],\"ans\":1,\"exp\":\"In saturated air no more water can evaporate, so the wet bulb cannot cool below the air temperature, and the air is already at its dew point - all three read the same.\",\"seenIn\":[\"May 2024 · OLODE\",\"Sep 2024 · Regular 03\",\"Apr 2025 · OLODE 03\",\"May 2026 · OLODE 04\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":5,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-074\",\"topic\":\"Humidity\",\"stem\":\"The amount of water vapour that air can hold depends mainly on its\",\"opts\":[\"Pressure\",\"Temperature\",\"Speed\"],\"ans\":1,\"exp\":\"Warm air can hold far more water vapour than cold air - roughly double for every 10 °C or so. That is why cooling moist air leads to saturation.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"May 2024 · OLODE\",\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-075\",\"topic\":\"Humidity\",\"stem\":\"If air is cooled while its water vapour content stays the same, its relative humidity\",\"opts\":[\"Increases\",\"Decreases\",\"Remains the same\"],\"ans\":0,\"exp\":\"The vapour present stays the same but the amount the air could hold falls as it cools, so the ratio - the RH - goes up, until it reaches 100% at the dew point.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Apr 2025 · OLODE 03\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":3,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-076\",\"topic\":\"Humidity\",\"stem\":\"The difference between the air temperature and the dew point is greater in\",\"opts\":[\"Moist air\",\"Dry air\",\"Saturated air\"],\"ans\":1,\"exp\":\"The dew-point spread shows how far the air is from saturation. Dry air must cool a long way to saturate, so its spread is large; in saturated air the spread is zero.\",\"seenIn\":[\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-077\",\"topic\":\"Humidity\",\"stem\":\"At the same sub-zero temperature, the saturation vapour pressure over ice compared with over supercooled water is\",\"opts\":[\"More\",\"Less\",\"The same\"],\"ans\":1,\"exp\":\"The saturation vapour pressure over ice is lower than over water. Air that is just saturated for the water droplets is supersaturated for ice crystals, so the crystals grow at the droplets' expense - the ice-crystal process that makes rain in cold clouds.\",\"seenIn\":[\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-078\",\"topic\":\"Humidity\",\"stem\":\"With the onset of a sea breeze there is a ______ in temperature and a ______ in relative humidity\",\"opts\":[\"Fall / Rise\",\"Rise / Fall\",\"Fall / Fall\"],\"ans\":0,\"exp\":\"The sea breeze brings in cooler, moist air from the sea: the temperature drops and the relative humidity climbs.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Jun 2025 · Regular 02\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-079\",\"topic\":\"Lapse rates & stability\",\"stem\":\"The dry adiabatic lapse rate (DALR) is\",\"opts\":[\"3 °C per 1000 ft (9.8 °C per km)\",\"2 °C per 1000 ft\",\"1.5 °C per 1000 ft\"],\"ans\":0,\"exp\":\"Unsaturated air cools at 9.8 °C per km (about 3 °C per 1000 ft) as it rises. Saturated air cools more slowly (about 1.5 °C per 1000 ft low down) because condensation releases latent heat. 2 °C per 1000 ft is the ISA lapse rate.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Nov 2024 · OLODE 08\",\"Mar 2025 · Regular 01\",\"May 2025 · OLODE 04\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":5,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-080\",\"topic\":\"Lapse rates & stability\",\"stem\":\"The surface temperature is 30 °C. Assuming the DALR, the temperature at 2 km is\",\"opts\":[\"18 °C\",\"10 °C\",\"42 °C\"],\"ans\":1,\"exp\":\"DALR is about 10 °C per km. 2 km x 10 = 20 °C cooler: 30 - 20 = 10 °C.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-081\",\"topic\":\"Lapse rates & stability\",\"stem\":\"If the ELR is greater than both the DALR and the SALR, the atmosphere is\",\"opts\":[\"Absolutely stable\",\"Conditionally unstable\",\"Absolutely unstable\"],\"ans\":2,\"exp\":\"A rising parcel, dry or saturated, cools more slowly than its surroundings, so it stays warmer and keeps rising. When the ELR exceeds both adiabatic rates the air is absolutely unstable.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-082\",\"topic\":\"Lapse rates & stability\",\"stem\":\"Dry (unsaturated) air is unstable when\",\"opts\":[\"ELR = DALR\",\"ELR > DALR\",\"ELR < DALR\"],\"ans\":1,\"exp\":\"If the environment cools faster with height than a rising dry parcel does, the parcel is always warmer than its surroundings and keeps going up - instability.\",\"seenIn\":[\"Jun 2025 · Regular 02\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-083\",\"topic\":\"Lapse rates & stability\",\"stem\":\"When DALR > ELR > SALR, the atmosphere is\",\"opts\":[\"Conditionally unstable\",\"Absolutely stable\",\"Absolutely unstable\"],\"ans\":0,\"exp\":\"Such air is stable while it stays unsaturated but becomes unstable once it is lifted to saturation. The condition is saturation - hence \\\"conditional\\\" instability, the usual set-up for towering cumulus.\",\"seenIn\":[\"May 2022 · Regular\",\"Oct 2023 · OLODE\",\"Mar 2024 · Regular 01\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":4,\"years\":[2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-084\",\"topic\":\"Lapse rates & stability\",\"stem\":\"A layer of air can be\",\"opts\":[\"Absolutely stable only\",\"Absolutely unstable only\",\"Conditionally unstable - unstable when saturated and stable when unsaturated\"],\"ans\":2,\"exp\":\"Stability depends on where the ELR lies against the two adiabatic rates. With the ELR between SALR and DALR, the same layer is stable for dry air and unstable for saturated air.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-085\",\"topic\":\"Lapse rates & stability\",\"stem\":\"The latent heat released during the adiabatic ascent of saturated air makes the air\",\"opts\":[\"Warmer than in a dry ascent\",\"Cooler than in a dry ascent\",\"Unaffected\"],\"ans\":0,\"exp\":\"Condensation gives back the latent heat, which offsets part of the expansion cooling. Saturated air therefore cools more slowly (SALR) and stays warmer than dry air lifted the same distance.\",\"seenIn\":[\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-086\",\"topic\":\"Lapse rates & stability\",\"stem\":\"An inversion in the atmosphere indicates\",\"opts\":[\"Stability\",\"Instability\",\"Neutrality\"],\"ans\":0,\"exp\":\"In an inversion a rising parcel immediately finds itself colder than the warmer air above, so it sinks back. An inversion is the most stable layer there is - a lid on convection.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-087\",\"topic\":\"Lapse rates & stability\",\"stem\":\"Temperature inversions are most common on\",\"opts\":[\"Summer afternoons\",\"Winter nights\",\"Monsoon afternoons\"],\"ans\":1,\"exp\":\"Long, clear, calm winter nights let the ground radiate its heat away, chilling the air next to it below the air above - a radiation inversion. That is also why winter mornings bring fog.\",\"seenIn\":[\"May 2026 · OLODE 04\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-088\",\"topic\":\"Lapse rates & stability\",\"stem\":\"Which of these indicates stable air?\",\"opts\":[\"A super-adiabatic lapse rate\",\"The dry adiabatic lapse rate\",\"A temperature inversion\"],\"ans\":2,\"exp\":\"Temperature increasing with height makes any lifted parcel colder than its surroundings, so it sinks back - stable. A super-adiabatic lapse rate is the most unstable case.\",\"seenIn\":[\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-089\",\"topic\":\"Lapse rates & stability\",\"stem\":\"Stable air is indicated by\",\"opts\":[\"Steady (continuous) precipitation\",\"Showers\",\"Cumuliform cloud with good visibility\"],\"ans\":0,\"exp\":\"Stable air lifted gently makes layer cloud and steady, continuous rain or drizzle with poor visibility. Showers and heaped cloud with good visibility are the marks of unstable air.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-090\",\"topic\":\"Lapse rates & stability\",\"stem\":\"Characteristics of a stable air mass include\",\"opts\":[\"Strong convection and turbulence\",\"Smooth air, poor visibility and stratiform cloud\",\"Rapid uplift and showers\"],\"ans\":1,\"exp\":\"Stable air resists vertical movement: smooth flying, layer (stratiform) cloud, steady light precipitation, and haze or fog trapped low down.\",\"seenIn\":[\"Jun 2025 · Regular 02\",\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-091\",\"topic\":\"Lapse rates & stability\",\"stem\":\"Altocumulus with cumuliform protuberances (castellanus / floccus) indicates\",\"opts\":[\"Stability\",\"Instability\",\"Neutrality\"],\"ans\":1,\"exp\":\"Turrets growing out of a medium-level layer show the air at that level is unstable - often a warning of thunderstorms later in the day.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Feb 2025 · OLODE 02\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2021,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-092\",\"topic\":\"Lapse rates & stability\",\"stem\":\"The large-scale downward movement of air is called\",\"opts\":[\"Convection\",\"Subsidence\",\"Advection\"],\"ans\":1,\"exp\":\"Subsidence is the slow sinking of air over a wide area, as in a high. Sinking air warms adiabatically and dries, which dissolves cloud.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"May 2024 · OLODE\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-093\",\"topic\":\"Lapse rates & stability\",\"stem\":\"The large deserts near 30 N and 30 S are primarily due to large-scale\",\"opts\":[\"Subsidence\",\"Convection\",\"Advection\"],\"ans\":0,\"exp\":\"The subtropical high-pressure belts sit near 30 degrees. Air sinks there, warming and drying as it descends, so clouds rarely form - hence the Sahara, Thar and Australian deserts.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-094\",\"topic\":\"Lapse rates & stability\",\"stem\":\"Convergence of air at the surface results in\",\"opts\":[\"Ascent of air\",\"Descent of air\",\"No vertical motion\"],\"ans\":0,\"exp\":\"Air piling in at the surface has to go somewhere, and the ground stops it going down - so it rises. Surface convergence means rising air, cloud and weather (lows, troughs, the ITCZ).\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-095\",\"topic\":\"Wind\",\"stem\":\"Geostrophic wind results from a balance between the\",\"opts\":[\"Gravity and friction\",\"Pressure gradient force and the Coriolis force\",\"Coriolis and centrifugal forces\"],\"ans\":1,\"exp\":\"Above the friction layer, with straight isobars, the pressure gradient force pushing towards low pressure is exactly balanced by the Coriolis force, and the wind blows parallel to the isobars.\",\"seenIn\":[\"2022 · Regular 03\",\"Apr 2024 · OLODE 03\",\"Nov 2024 · OLODE 08\",\"May 2025 · OLODE 04\",\"Apr 2026 · OLODE 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":6,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-096\",\"topic\":\"Wind\",\"stem\":\"The Coriolis force is greatest at the\",\"opts\":[\"Equator\",\"Mid-latitudes\",\"Poles\"],\"ans\":2,\"exp\":\"Coriolis force = 2 x omega x V x sin(latitude). Sin(latitude) is largest at 90 degrees, so it is greatest at the poles and zero at the equator.\",\"seenIn\":[\"Mar 2022 · Regular\",\"2022 · Regular 03\",\"Oct 2023 · OLODE\",\"Aug 2025 · OLODE 06\",\"Jan 2026 · OLODE 01\"],\"undated\":true,\"times\":5,\"years\":[2022,2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-097\",\"topic\":\"Wind\",\"stem\":\"The Coriolis force is least at the\",\"opts\":[\"Equator\",\"Mid-latitudes\",\"Poles\"],\"ans\":0,\"exp\":\"With sin(0) = 0, the Coriolis force vanishes at the equator. That is why the geostrophic idea fails near the equator and why tropical cyclones cannot form within about 5 degrees of it.\",\"seenIn\":[\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-098\",\"topic\":\"Wind\",\"stem\":\"In the Southern Hemisphere, if you stand with your back to the wind, the low pressure is on your\",\"opts\":[\"Left\",\"Right\",\"Front\"],\"ans\":1,\"exp\":\"Buys Ballot: back to the wind, low on the LEFT in the Northern Hemisphere and on the RIGHT in the Southern Hemisphere.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-099\",\"topic\":\"Wind\",\"stem\":\"In the Southern Hemisphere, flying from high pressure towards low pressure, the wind will be from the\",\"opts\":[\"Left, giving starboard drift\",\"Right, giving port drift\",\"Ahead\"],\"ans\":1,\"exp\":\"In the SH, with your back to the wind the low is on your right. Heading towards the low, the wind therefore blows across your track from the right and you drift to port. It is the mirror image of the Northern Hemisphere.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2021,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-100\",\"topic\":\"Wind\",\"stem\":\"In the Northern Hemisphere, flying towards an area of high pressure, you will experience\",\"opts\":[\"Port drift\",\"Starboard drift\",\"No drift\"],\"ans\":0,\"exp\":\"NH: back to the wind, low on the left. Flying from low towards high, the wind comes across from the right and you drift to port - and the altimeter under-reads. From high to low it is starboard drift.\",\"seenIn\":[\"May 2025 · OLODE 04\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-101\",\"topic\":\"Wind\",\"stem\":\"In the Northern Hemisphere, the wind around a low pressure system blows\",\"opts\":[\"Clockwise\",\"Anticlockwise\",\"Directly from high to low\"],\"ans\":1,\"exp\":\"NH: anticlockwise and inwards around a low, clockwise and outwards around a high. The SH is the reverse.\",\"seenIn\":[\"May 2024 · OLODE\",\"Dec 2025 · Regular 04\",\"Aug 2026 · OLODE 06\"],\"undated\":true,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-102\",\"topic\":\"Wind\",\"stem\":\"In the Southern Hemisphere, the wind around a low blows\",\"opts\":[\"Clockwise\",\"Anticlockwise\",\"Straight across the isobars to the centre\"],\"ans\":0,\"exp\":\"The Coriolis force acts to the left in the SH, so the circulation reverses: clockwise around lows, anticlockwise around highs.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-103\",\"topic\":\"Wind\",\"stem\":\"In the friction layer (Northern Hemisphere), the surface wind compared with the gradient wind\",\"opts\":[\"Veers and increases\",\"Backs and decreases\",\"Remains constant\"],\"ans\":1,\"exp\":\"Friction slows the surface wind; a slower wind has less Coriolis force, so the pressure gradient turns it towards low pressure. In the NH that is a backing. Climbing out of the friction layer (to about 2000 ft), the wind veers and strengthens.\",\"seenIn\":[\"2022 · Regular 03\",\"May 2024 · OLODE\",\"Sep 2024 · Regular 03\",\"Apr 2025 · OLODE 03\",\"May 2025 · OLODE 04\",\"Oct 2025 · OLODE 07\",\"Jan 2026 · OLODE 01\"],\"undated\":true,\"times\":7,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-104\",\"topic\":\"Wind\",\"stem\":\"The depth of the friction layer depends on\",\"opts\":[\"Wind speed, temperature and surface roughness\",\"Temperature and surface roughness\",\"Stability, wind speed and surface roughness\"],\"ans\":2,\"exp\":\"The rougher the ground and the stronger the wind, the higher friction effects reach; stable air resists vertical mixing and keeps the layer shallow. So the depth depends on roughness, wind speed and stability - deeper by day, shallower at night.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-105\",\"topic\":\"Wind\",\"stem\":\"For the same pressure gradient, the gradient wind around a high compared with the geostrophic wind is\",\"opts\":[\"Stronger\",\"Weaker\",\"The same\"],\"ans\":0,\"exp\":\"Around curved isobars the centrifugal effect is added. Around a high it adds to the pressure gradient, so the gradient wind is stronger than the geostrophic value; around a low it is weaker.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-106\",\"topic\":\"Wind\",\"stem\":\"A gale is a wind of\",\"opts\":[\"22-27 kt\",\"28-33 kt\",\"34 kt or more\"],\"ans\":2,\"exp\":\"Gale force starts at 34 kt (Beaufort force 8). In Indian cyclone classification 34-47 kt is a cyclonic storm.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Oct 2024 · OLODE 07\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-107\",\"topic\":\"Wind\",\"stem\":\"The lower level wind is 050/10 kt and the upper level wind is 230/05 kt. The thermal wind is\",\"opts\":[\"050/05 kt\",\"230/15 kt\",\"050/15 kt\"],\"ans\":1,\"exp\":\"Thermal wind = upper wind minus lower wind (as vectors). Subtracting 050/10 is the same as adding 230/10, and 230/05 + 230/10 = 230/15 kt.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-108\",\"topic\":\"Wind\",\"stem\":\"The upper wind is 240/05 kt and the lower wind is 060/10 kt. The thermal wind is\",\"opts\":[\"060/15 kt\",\"240/10 kt\",\"240/15 kt\"],\"ans\":2,\"exp\":\"Upper minus lower: minus 060/10 is plus 240/10, so 240/05 + 240/10 = 240/15 kt. When the two winds are opposite, add the speeds and take the direction of the upper wind.\",\"seenIn\":[\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-109\",\"topic\":\"Wind\",\"stem\":\"Wind shear is\",\"opts\":[\"A change of wind speed and/or direction over a short distance\",\"A steady strong wind\",\"Turbulence caused only by thermals\"],\"ans\":0,\"exp\":\"Wind shear is any change in wind speed or direction over a short distance, vertically or horizontally. Near the ground it changes your airspeed suddenly - the danger on approach and take-off.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Apr 2025 · OLODE 03\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2021,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-110\",\"topic\":\"Wind\",\"stem\":\"A surge is a sudden strengthening of the wind within the ______ air mass\",\"opts\":[\"Same\",\"Different\",\"Both\"],\"ans\":0,\"exp\":\"A surge is a pulse of stronger wind inside one air mass (common in a vigorous monsoon). A change of air mass would be a front.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Dec 2023 · Regular\",\"Nov 2024 · OLODE 08\"],\"undated\":false,\"times\":3,\"years\":[2021,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-111\",\"topic\":\"Local winds\",\"stem\":\"A wind blowing down a hillside at night is called\",\"opts\":[\"Anabatic\",\"Katabatic\",\"Fohn\"],\"ans\":1,\"exp\":\"At night the slope cools and chills the air on it; that denser air drains downhill - katabatic. By day the heated slope sends air uphill - anabatic.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Dec 2024 · Regular 04\",\"Jan 2025 · OLODE 01\",\"Jun 2025 · Regular 02\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-112\",\"topic\":\"Local winds\",\"stem\":\"A land breeze flows\",\"opts\":[\"From sea to land by day\",\"From land to sea by night\",\"From land to sea by day\"],\"ans\":1,\"exp\":\"At night the land cools faster than the sea, pressure becomes higher over the land, and air flows out to sea - the land breeze.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Oct 2024 · OLODE 07\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-113\",\"topic\":\"Local winds\",\"stem\":\"A sea breeze sets in by ______ and dies off at ______\",\"opts\":[\"Night / Day\",\"Day / Night\",\"Day and night\"],\"ans\":1,\"exp\":\"The land heats up faster than the sea by day, so cooler sea air moves in during the late morning and afternoon. It dies away in the evening as the land cools.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Jan 2025 · OLODE 01\",\"Oct 2025 · OLODE 07\"],\"undated\":true,\"times\":3,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-114\",\"topic\":\"Local winds\",\"stem\":\"Regarding land and sea breezes, which is correct?\",\"opts\":[\"The sea breeze is strongest at night\",\"The land breeze is weaker than the sea breeze and occurs at night\",\"Both occur during the day\"],\"ans\":1,\"exp\":\"The daytime land-sea temperature difference is larger than the night-time one, so the sea breeze (day) is stronger than the land breeze (night).\",\"seenIn\":[\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-115\",\"topic\":\"Local winds\",\"stem\":\"A sea breeze develops when\",\"opts\":[\"The land becomes warmer than the sea by day, with a light gradient wind\",\"The sea becomes warmer than the land at night\",\"The pressure gradient is steep\"],\"ans\":0,\"exp\":\"A sea breeze needs strong daytime heating of the land and a weak general wind that does not swamp the local circulation - clear, calm, sunny days.\",\"seenIn\":[\"2022 · Regular 03\",\"Mar 2025 · Regular 01\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-116\",\"topic\":\"Local winds\",\"stem\":\"Line squalls occur\",\"opts\":[\"Behind the cold front\",\"Ahead of the cold front\",\"At the warm front\"],\"ans\":1,\"exp\":\"A line squall is a band of thunderstorms that often runs ahead of an active cold front - sometimes 100-300 km ahead - with sudden strong gusts and a sharp veer.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Dec 2023 · Regular\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-117\",\"topic\":\"Local winds\",\"stem\":\"A line squall sometimes occurs 100-300 km ahead of a\",\"opts\":[\"Warm front\",\"Cold front\",\"Occluded front\"],\"ans\":1,\"exp\":\"The pre-frontal squall line runs parallel to, and ahead of, a fast-moving cold front. It can be more violent than the front itself.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":true,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-118\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Drizzle is typically associated with\",\"opts\":[\"Cumulus\",\"Stratus\",\"Cirrus\"],\"ans\":1,\"exp\":\"Drizzle is fine droplets from a shallow, low layer cloud - stratus (or thin stratocumulus). The cloud is too shallow for drops to grow big.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Jul 2022 · OLODE 05\",\"Jun 2023 · Regular\",\"Nov 2024 · OLODE 08\",\"Apr 2025 · OLODE 03\",\"May 2025 · OLODE 04\",\"Sep 2025 · Regular 03\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":8,\"years\":[2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-119\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Altostratus (AS) is\",\"opts\":[\"A low cloud of sheet type\",\"A medium cloud of sheet type\",\"A high cloud of sheet type\"],\"ans\":1,\"exp\":\"\\\"Alto\\\" means medium level; \\\"stratus\\\" means sheet or layer. AS is a grey medium-level sheet through which the sun appears as if through ground glass.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jun 2023 · Regular\",\"Dec 2024 · Regular 04\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2021,2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-120\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Medium-level clouds are\",\"opts\":[\"CU and CB\",\"AC and AS\",\"CI and CS\"],\"ans\":1,\"exp\":\"The \\\"alto\\\" clouds - altocumulus and altostratus - are the medium clouds. CI, CC and CS are high; CU and CB are clouds of vertical development.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Oct 2024 · OLODE 07\",\"Nov 2024 · OLODE 08\",\"Jan 2025 · OLODE 01\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":5,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-121\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Showers fall from\",\"opts\":[\"NS\",\"AC\",\"CB\"],\"ans\":2,\"exp\":\"Showers are short, heavy bursts from convective cloud - cumulonimbus (and large cumulus). NS gives continuous rain; AC gives little or none.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Oct 2023 · OLODE\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Sep 2024 · Regular 03\",\"Feb 2025 · OLODE 02\",\"Mar 2025 · Regular 01\",\"Aug 2025 · OLODE 06\",\"Dec 2025 · Regular 04\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":10,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-122\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Rain falling from a cloud but not reaching the ground is called\",\"opts\":[\"Virgo\",\"Virga\",\"Mirage\"],\"ans\":1,\"exp\":\"Virga are the trails of rain or snow that evaporate in dry air before reaching the ground. They can still mean downdraughts below the cloud.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"2022 · Regular 03\",\"Jun 2023 · Regular\",\"Jan 2025 · OLODE 01\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":5,\"years\":[2022,2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-123\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Clouds whose tops extend well above the freezing level are called\",\"opts\":[\"Warm clouds\",\"Cold clouds\",\"Moderate clouds\"],\"ans\":1,\"exp\":\"A cloud reaching above the 0 °C level contains ice crystals and supercooled water, and makes rain by the ice-crystal process - a cold cloud. One entirely below freezing level is a warm cloud.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Jun 2023 · Regular\",\"Nov 2024 · OLODE 08\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-124\",\"topic\":\"Clouds & precipitation\",\"stem\":\"The coalescence theory explains the occurrence of rainfall from\",\"opts\":[\"Warm clouds\",\"Cold clouds\",\"Both types of cloud\"],\"ans\":0,\"exp\":\"In warm clouds (no ice) raindrops grow by bigger droplets colliding with and absorbing smaller ones - coalescence. In cold clouds the ice-crystal (Bergeron) process does the work.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Dec 2023 · Regular\",\"Apr 2024 · OLODE 03\"],\"undated\":true,\"times\":3,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-125\",\"topic\":\"Clouds & precipitation\",\"stem\":\"The dark grey cloud giving continuous rain is\",\"opts\":[\"Altostratus\",\"Nimbostratus\",\"Stratus\"],\"ans\":1,\"exp\":\"Nimbostratus is the thick, dark, ragged-based rain cloud of the warm front, giving continuous moderate or heavy rain for hours.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Aug 2024 · OLODE\",\"Sep 2024 · Regular 03\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":6,\"years\":[2021,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-126\",\"topic\":\"Clouds & precipitation\",\"stem\":\"The word \\\"nimbus\\\" in a cloud name means the cloud is\",\"opts\":[\"Rain-bearing\",\"High\",\"Layered\"],\"ans\":0,\"exp\":\"Nimbus means rain cloud: nimbostratus is the layered rain cloud, cumulonimbus the heaped (shower and thunder) one.\",\"seenIn\":[\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-127\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Hail is most likely to fall from a cloud\",\"opts\":[\"Having layers\",\"Composed of ice crystals\",\"Having strong vertical development\"],\"ans\":2,\"exp\":\"Hailstones grow as strong updraughts carry them up and down through supercooled water again and again. That needs a deep cloud with violent vertical currents - the CB.\",\"seenIn\":[\"May 2024 · OLODE\",\"Jan 2025 · OLODE 01\",\"Jun 2025 · Regular 02\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-128\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Hail and heavy precipitation are associated with\",\"opts\":[\"Nimbostratus\",\"Altostratus\",\"Cumulonimbus\"],\"ans\":2,\"exp\":\"Only the cumulonimbus has the updraughts to grow hail. It is also the cloud of heavy showers, lightning, severe icing and turbulence.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Sep 2023 · Regular 03\",\"Apr 2024 · OLODE 03\",\"Jan 2025 · OLODE 01\",\"May 2025 · OLODE 04\",\"Dec 2025 · Regular 04\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":7,\"years\":[2021,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-129\",\"topic\":\"Clouds & precipitation\",\"stem\":\"The cloud least likely to give precipitation is\",\"opts\":[\"Cirrus\",\"Nimbostratus\",\"Cumulonimbus\"],\"ans\":0,\"exp\":\"Cirrus is a thin, high cloud of ice crystals; anything that falls from it evaporates long before reaching the ground.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Dec 2024 · Regular 04\",\"Feb 2025 · OLODE 02\",\"Apr 2026 · OLODE 03\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":6,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-130\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Precipitation from medium-level layer clouds is generally\",\"opts\":[\"Showers\",\"Continuous (steady) rain or snow\",\"Hail\"],\"ans\":1,\"exp\":\"Layer clouds come from gentle, widespread lifting, so their precipitation is steady and continuous. Showers and hail belong to convective clouds.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-131\",\"topic\":\"Clouds & precipitation\",\"stem\":\"A cumulonimbus with a distinct anvil is called\",\"opts\":[\"Castellanus\",\"Capillatus\",\"Uncinus\"],\"ans\":1,\"exp\":\"CB capillatus has a fibrous, glaciated top spreading into an anvil. Castellanus describes turreted AC or CC; uncinus is hooked cirrus.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-132\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Cumulonimbus clouds are mainly formed due to\",\"opts\":[\"Frontal lifting\",\"Radiation cooling\",\"Strong convective updraughts\"],\"ans\":2,\"exp\":\"A CB is the end product of deep convection: strong updraughts in unstable, moist air. Fronts and hills can trigger it, but the updraught is what builds it.\",\"seenIn\":[\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-133\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Strong updraughts with cumuliform cloud indicate\",\"opts\":[\"Stratus\",\"Altostratus\",\"Cumulonimbus\"],\"ans\":2,\"exp\":\"Strong updraughts in heaped (cumuliform) cloud mean vigorous convection - the development that ends in cumulonimbus.\",\"seenIn\":[\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-134\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Unstable air, a high moisture content and a very warm surface will lead to\",\"opts\":[\"Fog\",\"Thunderstorm (CB)\",\"Stratus\"],\"ans\":1,\"exp\":\"Those are the ingredients of a thunderstorm: a steep lapse rate, plenty of moisture, and surface heating as the trigger.\",\"seenIn\":[\"Apr 2025 · OLODE 03\",\"Jun 2025 · Regular 02\",\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":3,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-135\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Stable air forced up a slope forms\",\"opts\":[\"Cumulus\",\"Cumulonimbus\",\"Stratiform cloud\"],\"ans\":2,\"exp\":\"Stable air lifted over high ground cools to saturation but does not rise on its own, so it spreads out as layer (stratiform) cloud and hill fog on the windward side. Unstable air lifted the same way would build CU or CB.\",\"seenIn\":[\"May 2024 · OLODE\",\"Jan 2025 · OLODE 01\",\"Oct 2025 · OLODE 07\",\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":4,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-136\",\"topic\":\"Clouds & precipitation\",\"stem\":\"The lowest level below which condensation trails will not form is the\",\"opts\":[\"Mintra level\",\"Drytra level\",\"Maxtra level\"],\"ans\":0,\"exp\":\"Contrails form only in a band of cold air: below the MINTRA level (minimum trail level) it is too warm; above the MAXTRA level they no longer form.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Oct 2025 · OLODE 07\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-137\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Over coastal areas, rainfall is usually more\",\"opts\":[\"In the evening\",\"At night and in the early morning\",\"In the afternoon\"],\"ans\":1,\"exp\":\"At night the land breeze blowing out to sea converges with the sea air offshore, lifting it and setting off showers - so coastal areas often get their rain at night and in the early morning.\",\"seenIn\":[\"May 2022 · Regular\",\"Jan 2025 · OLODE 01\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-138\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Rainfall in the tropics is more in\",\"opts\":[\"Winter\",\"Summer\",\"Post-monsoon\"],\"ans\":1,\"exp\":\"Tropical rain is mostly convective, fed by strong heating and moist air - so it peaks in the summer (in India, the SW monsoon months).\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Jun 2025 · Regular 02\",\"Mar 2026 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-139\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Rainfall in the tropics is more in the\",\"opts\":[\"Morning\",\"Afternoon\",\"Night\"],\"ans\":1,\"exp\":\"Surface heating builds through the day, so convection and showers over land peak in the afternoon.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Dec 2024 · Regular 04\",\"May 2025 · OLODE 04\",\"Mar 2026 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":7,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-140\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Rainfall in the tropics is mostly associated with\",\"opts\":[\"Frontal activity\",\"Convective activity\",\"Orographic lifting only\"],\"ans\":1,\"exp\":\"In the tropics fronts are rare and heating is strong, so most rain comes from convection - showers and thunderstorms.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-141\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Over the plains, thunderstorms mostly occur in the\",\"opts\":[\"Afternoon\",\"Night\",\"Early morning\"],\"ans\":0,\"exp\":\"Over flat land the trigger is surface heating, which peaks in the afternoon. (Over the sea and in valleys, night and early-morning storms are more common.)\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Sep 2024 · Regular 03\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":5,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-142\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Rainfall in the temperate latitudes is more in\",\"opts\":[\"Winter\",\"Summer\",\"Spring\"],\"ans\":0,\"exp\":\"Temperate rain comes mostly from frontal depressions, which are most frequent and vigorous in winter.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Oct 2025 · OLODE 07\"],\"undated\":true,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-143\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Over J&K and the western Himalayas, rainfall is more in\",\"opts\":[\"Winter\",\"Summer\",\"Post-monsoon\"],\"ans\":0,\"exp\":\"Western disturbances - frontal systems from the Mediterranean - bring rain and snow to J&K and the western Himalayas mainly in winter.\",\"seenIn\":[\"May 2022 · Regular\",\"Mar 2025 · Regular 01\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-144\",\"topic\":\"Clouds & precipitation\",\"stem\":\"The rain-shadow area lies on the\",\"opts\":[\"Windward side of the mountains\",\"Leeward side of the mountains\",\"Equatorial side\"],\"ans\":1,\"exp\":\"Moist air drops its rain as it rises up the windward slope; descending the lee side it warms and dries, leaving a rain shadow - e.g. east of the Western Ghats.\",\"seenIn\":[\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-145\",\"topic\":\"Optical phenomena\",\"stem\":\"A halo is produced when light passes through\",\"opts\":[\"Water droplets\",\"Ice crystals\",\"Both\"],\"ans\":1,\"exp\":\"A halo is light refracted by ice crystals, giving a ring of about 22 degrees around the sun or moon, red on the inside.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-146\",\"topic\":\"Optical phenomena\",\"stem\":\"A halo is associated with which cloud?\",\"opts\":[\"Altocumulus\",\"Altostratus\",\"Cirrostratus\"],\"ans\":2,\"exp\":\"Halos form in thin ice-crystal cloud, typically cirrostratus. A halo in the sky often means a warm front is approaching.\",\"seenIn\":[\"Mar 2025 · Regular 01\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-147\",\"topic\":\"Optical phenomena\",\"stem\":\"To avoid icing, a pilot should prefer the cloud that shows which optical phenomenon?\",\"opts\":[\"Halo\",\"Corona\",\"Iridescence\"],\"ans\":0,\"exp\":\"A halo proves the cloud is made of ice crystals, which carry negligible icing risk. A corona or iridescence means supercooled water droplets - an icing cloud.\",\"seenIn\":[\"Dec 2023 · Regular\",\"May 2024 · OLODE\",\"Nov 2024 · OLODE 08\",\"Mar 2025 · Regular 01\"],\"undated\":true,\"times\":4,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-148\",\"topic\":\"Optical phenomena\",\"stem\":\"A corona is seen through\",\"opts\":[\"Cirrostratus\",\"Altostratus\",\"Cumulonimbus\"],\"ans\":1,\"exp\":\"A corona is a small coloured ring around the sun or moon made by diffraction through thin water-droplet cloud - altostratus or altocumulus. Cirrostratus (ice) gives a halo instead.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-149\",\"topic\":\"Optical phenomena\",\"stem\":\"The Aurora Australis occurs in the\",\"opts\":[\"Southern Hemisphere\",\"Northern Hemisphere\",\"Equatorial region\"],\"ans\":0,\"exp\":\"Australis means southern: the Southern Lights, seen in high southern latitudes. The Aurora Borealis is the Northern Lights.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-150\",\"topic\":\"Visibility & fog\",\"stem\":\"Fog is reported when visibility is reduced to\",\"opts\":[\"Below 5 km\",\"Below 1000 m\",\"Below 500 m\"],\"ans\":1,\"exp\":\"FG is reported when water droplets reduce the visibility to less than 1000 m. From 1000 m up to 5000 m with humid air it is mist (BR).\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Feb 2025 · OLODE 02\",\"Apr 2025 · OLODE 03\",\"Jun 2025 · Regular 02\",\"Sep 2025 · Regular 03\",\"Apr 2026 · OLODE 03\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":7,\"years\":[2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-151\",\"topic\":\"Visibility & fog\",\"stem\":\"Mist is reported when visibility is\",\"opts\":[\"Less than 1000 m\",\"1000 m to 5000 m\",\"More than 5000 m\"],\"ans\":1,\"exp\":\"BR (mist) is reported for visibility from 1000 m to 5000 m with high humidity. Below 1000 m it becomes fog; in dry air the same visibility would be haze.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Apr 2024 · OLODE 03\",\"Sep 2024 · Regular 03\",\"Oct 2024 · OLODE 07\",\"Mar 2025 · Regular 01\",\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":6,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-152\",\"topic\":\"Visibility & fog\",\"stem\":\"Warm, moist air moving over a cold surface causes\",\"opts\":[\"Radiation fog\",\"Advection fog\",\"Frontal fog\"],\"ans\":1,\"exp\":\"Advection means horizontal movement. Warm moist air carried over colder land or sea is cooled from below to its dew point - advection fog. Radiation fog needs no movement, just a clear night.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Sep 2023 · Regular 03\",\"Oct 2023 · OLODE\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Oct 2024 · OLODE 07\",\"Dec 2024 · Regular 04\",\"Jun 2025 · Regular 02\",\"Mar 2026 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":10,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-153\",\"topic\":\"Visibility & fog\",\"stem\":\"Advection fog forms\",\"opts\":[\"Only at night\",\"Only by day\",\"At any time of day or night\"],\"ans\":2,\"exp\":\"Advection fog depends on warm moist air moving over a cold surface, not on night-time cooling, so it can form - and persist - at any time, day or night, and with stronger winds than radiation fog.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jul 2022 · OLODE 05\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2021,2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-154\",\"topic\":\"Visibility & fog\",\"stem\":\"Radiation fog is common\",\"opts\":[\"Before a western disturbance\",\"After a western disturbance\",\"During the monsoon\"],\"ans\":1,\"exp\":\"After a WD passes, the skies clear, the winds fall light and the ground is still moist from its rain - perfect for radiation fog over north India on the winter nights that follow.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Apr 2025 · OLODE 03\",\"Sep 2025 · Regular 03\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-155\",\"topic\":\"Visibility & fog\",\"stem\":\"Radiation fog requires\",\"opts\":[\"Moisture, a cloudy sky and no wind\",\"Moisture, a clear sky and a light wind\",\"Moisture, a cloudy sky and a strong wind\"],\"ans\":1,\"exp\":\"A clear sky lets the ground radiate its heat away; moist air reaches its dew point; a light wind (about 2-8 kt) mixes the cooling through a shallow layer. Calm gives only dew, and a strong wind mixes too deep or lifts it into stratus.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Nov 2024 · OLODE 08\",\"Jan 2025 · OLODE 01\",\"Apr 2025 · OLODE 03\",\"Jun 2025 · Regular 02\",\"Jan 2026 · OLODE 01\"],\"undated\":true,\"times\":6,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-156\",\"topic\":\"Visibility & fog\",\"stem\":\"Radiation fog forms mainly\",\"opts\":[\"In the afternoon\",\"In the evening\",\"Around midnight to early morning\"],\"ans\":2,\"exp\":\"It builds through the night as the ground keeps cooling, and is usually thickest around dawn, just after the minimum temperature, before the sun burns it off.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"May 2025 · OLODE 04\",\"Jan 2026 · OLODE 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-157\",\"topic\":\"Visibility & fog\",\"stem\":\"Radiation fog is dissipated by\",\"opts\":[\"Insolation (heating by the sun)\",\"Strong winds\",\"Both\"],\"ans\":2,\"exp\":\"Sunshine warms the ground and air above the dew point, and an increase in wind mixes the fog with drier air above (often lifting it into low stratus). Either one clears it.\",\"seenIn\":[\"Dec 2023 · Regular\",\"May 2024 · OLODE\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-158\",\"topic\":\"Visibility & fog\",\"stem\":\"Hill fog is caused by\",\"opts\":[\"Radiation cooling of valleys\",\"Moist air being cooled as it is forced up the hills\",\"Warm air moving over a cold sea\"],\"ans\":1,\"exp\":\"Hill (orographic) fog is really low cloud: moist air forced up a slope cools adiabatically to its dew point and covers the high ground.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-159\",\"topic\":\"Visibility & fog\",\"stem\":\"When fog freezes on a parked aircraft it produces\",\"opts\":[\"Hoar frost\",\"Rime\",\"Clear ice\"],\"ans\":1,\"exp\":\"Supercooled fog droplets freeze on contact with the cold airframe as rime - white, opaque and rough.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Jan 2025 · OLODE 01\",\"Apr 2025 · OLODE 03\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":4,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-160\",\"topic\":\"Visibility & fog\",\"stem\":\"In the pre-monsoon season, visibility of around 10 km from Delhi to Kolkata is mainly reduced by\",\"opts\":[\"Fog\",\"Mist\",\"Dust haze\"],\"ans\":2,\"exp\":\"In the hot weather season gusty, dust-laden winds blow over the Gangetic plains during the day and the dust hangs in the air as haze over a large area. Fog belongs to winter.\",\"seenIn\":[\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-161\",\"topic\":\"Visibility & fog\",\"stem\":\"A warm front can produce fog when\",\"opts\":[\"Rain from the warm air falls into and saturates the cold air under the frontal surface\",\"The afternoon heating is strong\",\"The sky is clear\"],\"ans\":0,\"exp\":\"Frontal (pre-frontal) fog: rain falling from the warm air evaporates into the cold air below, raising its dew point until it saturates. It forms ahead of the warm front and can cover a wide area.\",\"seenIn\":[\"Jun 2025 · Regular 02\",\"Jul 2025 · OLODE 05\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-162\",\"topic\":\"Visibility & fog\",\"stem\":\"Meteorological visibility is the greatest distance at which\",\"opts\":[\"A dark object of suitable size near the ground can be seen and recognised against the horizon sky by day\",\"A runway light can be seen by a pilot on the approach\",\"An aircraft can see another aircraft in flight\"],\"ans\":0,\"exp\":\"Met visibility is defined on a black object against the sky by day (and on lights of known strength by night). The pilot's view of runway lights is RVR, a different measurement.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-163\",\"topic\":\"Visibility & fog\",\"stem\":\"In a METAR, visibility is reported in steps of 1000 m when the visibility is\",\"opts\":[\"0 to 800 m\",\"800 to 5000 m\",\"5000 m to 9999 m\"],\"ans\":2,\"exp\":\"Steps are 50 m below 800 m, 100 m from 800 to 5000 m, and 1000 m from 5000 m up to 9999 (which means 10 km or more).\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-164\",\"topic\":\"Visibility & fog\",\"stem\":\"CAVOK may be used when, among other conditions, the visibility is\",\"opts\":[\"9 km or more\",\"10 km or more\",\"5 km or more\"],\"ans\":1,\"exp\":\"CAVOK needs all three: visibility 10 km or more; no cloud below 1500 m (5000 ft) or the highest minimum sector altitude, whichever is greater, and no CB or TCU; and no significant weather.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"May 2022 · Regular\",\"Mar 2024 · Regular 01\",\"May 2024 · OLODE\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":5,\"years\":[2021,2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-165\",\"topic\":\"Visibility & fog\",\"stem\":\"In a METAR, the code BR means\",\"opts\":[\"Mist\",\"Haze\",\"Smoke\"],\"ans\":0,\"exp\":\"BR comes from the French \\\"brume\\\" - mist. Haze is HZ, smoke FU, fog FG.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-166\",\"topic\":\"Icing\",\"stem\":\"Glaze (clear) ice is formed by the freezing of ______ supercooled water droplets\",\"opts\":[\"Small\",\"Large\",\"Medium\"],\"ans\":1,\"exp\":\"Large droplets do not freeze instantly; they spread back over the surface before freezing, making a smooth, heavy, clear sheet that sticks hard. It is the most dangerous type.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Mar 2024 · Regular 01\",\"Oct 2025 · OLODE 07\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-167\",\"topic\":\"Icing\",\"stem\":\"Rime ice is formed by the freezing of ______ supercooled water droplets\",\"opts\":[\"Small\",\"Large\",\"Medium\"],\"ans\":0,\"exp\":\"Small droplets freeze the instant they hit, trapping air between them - so rime is white, opaque, light and brittle, and builds forward into the airflow.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Sep 2023 · Regular 03\",\"Apr 2024 · OLODE 03\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-168\",\"topic\":\"Icing\",\"stem\":\"Opaque rime ice is\",\"opts\":[\"Heavy and clear\",\"Light and porous\",\"Smooth and transparent\"],\"ans\":1,\"exp\":\"The air trapped between the tiny frozen droplets makes rime white, light and porous. That is also why it is easier to remove than glaze.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Nov 2024 · OLODE 08\",\"Dec 2024 · Regular 04\",\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":4,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-169\",\"topic\":\"Icing\",\"stem\":\"In clouds at temperatures below 0 °C an aircraft may encounter icing of the type\",\"opts\":[\"Only glazed\",\"Only rime\",\"Intermediate between these two\"],\"ans\":2,\"exp\":\"Real clouds contain a range of droplet sizes, so the ice that forms is usually a mixture of rime and glaze - the intermediate (mixed) type.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Apr 2024 · OLODE 03\",\"May 2024 · OLODE\",\"Aug 2025 · OLODE 06\",\"Dec 2025 · Regular 04\"],\"undated\":true,\"times\":5,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-170\",\"topic\":\"Icing\",\"stem\":\"In clouds, a mixture of rime and clear ice occurs when a wide range of drop sizes is present at temperatures between\",\"opts\":[\"0 °C and -10 °C only\",\"0 °C and -40 °C\",\"Below -40 °C only\"],\"ans\":1,\"exp\":\"Supercooled drops can exist anywhere from 0 °C down to about -40 °C. With a mix of large and small drops you get a mixture of the two ice types.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jun 2025 · Regular 02\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2021,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-171\",\"topic\":\"Icing\",\"stem\":\"In AC clouds, ______ icing is possible in mountainous areas\",\"opts\":[\"Light\",\"Moderate\",\"Severe\"],\"ans\":2,\"exp\":\"Over mountains, forced lifting adds a lot of supercooled water to altocumulus (such as the lenticular clouds of mountain waves), so the icing there can be severe.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Oct 2024 · OLODE 07\",\"Dec 2024 · Regular 04\",\"Oct 2025 · OLODE 07\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":6,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-172\",\"topic\":\"Icing\",\"stem\":\"In CB, icing may range from light to severe up to the -20 °C level. Below this temperature, severe icing is\",\"opts\":[\"Not significant\",\"Significant\",\"Maximum\"],\"ans\":0,\"exp\":\"Colder than about -20 °C most of the water in the cloud has frozen into ice crystals, which do not stick, so severe icing becomes unlikely.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Dec 2024 · Regular 04\",\"Jan 2025 · OLODE 01\",\"Apr 2025 · OLODE 03\",\"Jun 2025 · Regular 02\"],\"undated\":true,\"times\":5,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-173\",\"topic\":\"Icing\",\"stem\":\"Airframe icing becomes progressively less likely below about\",\"opts\":[\"0 °C\",\"-20 °C\",\"-40 °C\"],\"ans\":1,\"exp\":\"Below about -20 °C the proportion of supercooled droplets falls rapidly as they freeze into ice crystals, so the chance of icing drops off.\",\"seenIn\":[\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-174\",\"topic\":\"Icing\",\"stem\":\"Aircraft icing is most favoured in cloud at temperatures between\",\"opts\":[\"-20 °C and -40 °C\",\"0 °C and -20 °C\",\"Below -40 °C\"],\"ans\":1,\"exp\":\"Supercooled water is most plentiful between 0 and -20 °C, so that is where most icing happens. Below -40 °C water cannot stay liquid.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Jun 2025 · Regular 02\",\"Dec 2025 · Regular 04\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-175\",\"topic\":\"Icing\",\"stem\":\"In towering cumulus (TCU), icing may range from light to severe at least up to the\",\"opts\":[\"-40 °C level\",\"-30 °C level\",\"-20 °C level\"],\"ans\":2,\"exp\":\"The strong updraughts in TCU carry plenty of supercooled water up to at least the -20 °C level, so the icing risk extends that high.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"May 2024 · OLODE\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-176\",\"topic\":\"Icing\",\"stem\":\"Liquid water content is an important factor in icing. Maximum ice formation in clouds may be expected around the level where the maximum water concentration is, about the\",\"opts\":[\"-25 °C level\",\"-20 °C level\",\"-15 °C level\"],\"ans\":0,\"exp\":\"Maximum supercooled liquid water concentration is found around the -25 °C level, and the heaviest ice formation in cloud is expected there too.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Jul 2022 · OLODE 05\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check could not confirm this answer from the official sources we hold; treat it with care and confirm with your instructor.\"},{\"id\":\"CPLMET-177\",\"topic\":\"Icing\",\"stem\":\"The type of ice that poses the most serious aviation hazard is\",\"opts\":[\"Rime\",\"Hoar frost\",\"Glaze (clear ice)\"],\"ans\":2,\"exp\":\"Glaze is heavy, hard, sticks firmly, is hard to see and to shed, and spreads back over the wing, badly spoiling the aerofoil.\",\"seenIn\":[\"Aug 2024 · OLODE\",\"Nov 2024 · OLODE 08\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-178\",\"topic\":\"Icing\",\"stem\":\"Icing ______ the stalling speed appreciably\",\"opts\":[\"Decreases\",\"Increases\",\"Does not affect\"],\"ans\":1,\"exp\":\"Ice destroys the smooth wing profile (less lift, more drag) and adds weight, so the aircraft stalls at a higher speed - sometimes with little warning.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Oct 2023 · OLODE\",\"May 2024 · OLODE\",\"Sep 2025 · Regular 03\",\"May 2026 · OLODE 04\"],\"undated\":true,\"times\":5,\"years\":[2021,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-179\",\"topic\":\"Icing\",\"stem\":\"______ forms in moist, cloudless air on an aircraft surface below 0 °C, by the sublimation of water vapour into feathery ice crystals\",\"opts\":[\"Rime\",\"Glaze\",\"Hoar frost\"],\"ans\":2,\"exp\":\"Hoar frost is vapour turning directly into ice on a surface below freezing - on a parked aircraft on a clear night, or on one descending from cold levels into moist air.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Sep 2024 · Regular 03\",\"Jan 2025 · OLODE 01\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-180\",\"topic\":\"Icing\",\"stem\":\"Heavy (severe) airframe icing is most likely in\",\"opts\":[\"Cirrus\",\"Stratus\",\"Cumulonimbus\"],\"ans\":2,\"exp\":\"The CB carries large supercooled drops high above the freezing level in strong updraughts - the recipe for severe clear icing.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Nov 2024 · OLODE 08\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-181\",\"topic\":\"Icing\",\"stem\":\"Ci, Cs and Cc clouds consist mostly of ice crystals. The icing hazard in them is therefore\",\"opts\":[\"Maximum\",\"Medium\",\"Negligible\"],\"ans\":2,\"exp\":\"Ice crystals bounce off the airframe instead of freezing onto it. With almost no supercooled water, the high clouds carry negligible icing risk.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\"],\"undated\":true,\"times\":3,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-182\",\"topic\":\"Icing\",\"stem\":\"Freezing rain (FZRA) and freezing fog (FZFG) occur ______ a warm front\",\"opts\":[\"Ahead of\",\"During\",\"After\"],\"ans\":0,\"exp\":\"Ahead of a warm front, rain from the warm air above falls into the sub-zero cold air underneath, becoming supercooled and freezing on impact.\",\"seenIn\":[\"2022 · Regular 03\",\"Jun 2023 · Regular\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":4,\"years\":[2022,2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-183\",\"topic\":\"Icing\",\"stem\":\"Freezing rain is most likely when\",\"opts\":[\"A warm front is approaching\",\"A cold front has passed\",\"A thunderstorm is nearby\"],\"ans\":0,\"exp\":\"Freezing rain needs warm air aloft over a sub-zero layer near the ground - the structure found ahead of a warm front in winter.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"May 2024 · OLODE\"],\"undated\":false,\"times\":3,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-184\",\"topic\":\"Icing\",\"stem\":\"Ice pellets on the ground are evidence that\",\"opts\":[\"A cold front has passed\",\"There may be freezing rain at a higher level\",\"There are thunderstorms in the area\"],\"ans\":1,\"exp\":\"Ice pellets are raindrops that fell through a cold layer and froze on the way down. So above you there is warm air with rain falling into sub-zero air - freezing rain is likely higher up.\",\"seenIn\":[\"2022 · Regular 03\",\"Dec 2023 · Regular\",\"May 2024 · OLODE\",\"Feb 2025 · OLODE 02\",\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":6,\"years\":[2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-185\",\"topic\":\"Thunderstorms\",\"stem\":\"The conditions necessary for the formation of a thunderstorm are\",\"opts\":[\"Stable atmosphere, dry air and cooling\",\"Steep lapse rate, adequate supply of moisture and a trigger action\",\"Weak lapse rate and no moisture\"],\"ans\":1,\"exp\":\"Three ingredients: instability (a steep lapse rate), plenty of moisture to release latent heat, and a trigger to start the lifting - heating, a front, hills or convergence.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Jul 2022 · OLODE 05\",\"Dec 2023 · Regular\",\"May 2024 · OLODE\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":5,\"years\":[2022,2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-186\",\"topic\":\"Thunderstorms\",\"stem\":\"A mature thunderstorm has strong\",\"opts\":[\"Updraughts only\",\"Downdraughts only\",\"Updraughts and downdraughts both\"],\"ans\":2,\"exp\":\"The mature stage starts when rain begins to fall. Falling rain drags air down beside the updraughts, so both exist together - the most violent, turbulent stage.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Jun 2025 · Regular 02\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-187\",\"topic\":\"Thunderstorms\",\"stem\":\"Rain starting to fall from a thunderstorm indicates the\",\"opts\":[\"Developing (cumulus) stage\",\"Mature stage\",\"Dissipating stage\"],\"ans\":1,\"exp\":\"The start of precipitation at the surface marks the beginning of the mature stage.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-188\",\"topic\":\"Thunderstorms\",\"stem\":\"A thunderstorm in the dissipating stage is characterised by\",\"opts\":[\"Updraughts only\",\"Downdraughts\",\"Updraughts and downdraughts\"],\"ans\":1,\"exp\":\"In the dissipating stage the downdraughts spread through the whole cell and cut off the supply of warm moist air; the storm rains itself out.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-189\",\"topic\":\"Thunderstorms\",\"stem\":\"The most severe activity of a single-cell cumulonimbus occurs during the\",\"opts\":[\"Cumulus stage\",\"Mature stage\",\"Dissipating stage\"],\"ans\":1,\"exp\":\"Heavy rain, hail, lightning, gust fronts and the worst turbulence all come in the mature stage, when updraughts and downdraughts work side by side.\",\"seenIn\":[\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-190\",\"topic\":\"Thunderstorms\",\"stem\":\"The diameter of a microburst is\",\"opts\":[\"Less than 4 km\",\"Less than 6 km\",\"More than 10 km\"],\"ans\":0,\"exp\":\"A microburst is a violent downburst less than 4 km across, lasting only a few minutes - small enough to catch an aircraft on final approach.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Mar 2024 · Regular 01\",\"Oct 2024 · OLODE 07\",\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\",\"Dec 2025 · Regular 04\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":7,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-191\",\"topic\":\"Thunderstorms\",\"stem\":\"The diameter of a macroburst is\",\"opts\":[\"Less than 4 km\",\"4 km or more\",\"More than 8 km only\"],\"ans\":1,\"exp\":\"A downburst 4 km or more across is a macroburst; under 4 km it is a microburst.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jul 2022 · OLODE 05\",\"Apr 2024 · OLODE 03\",\"Aug 2024 · OLODE\",\"Sep 2024 · Regular 03\",\"Dec 2024 · Regular 04\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":7,\"years\":[2021,2022,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-192\",\"topic\":\"Thunderstorms\",\"stem\":\"Norwesters normally occur during the\",\"opts\":[\"Mornings\",\"Afternoons and evenings\",\"Nights\"],\"ans\":1,\"exp\":\"Norwesters are heat-triggered: they build with the afternoon heating over east and north-east India and strike in the late afternoon and evening.\",\"seenIn\":[\"2022 · Regular 03\",\"Mar 2024 · Regular 01\",\"May 2024 · OLODE\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-193\",\"topic\":\"Thunderstorms\",\"stem\":\"Norwesters mainly affect\",\"opts\":[\"North-west India\",\"Bengal, Bihar, Odisha and Assam\",\"Central India\"],\"ans\":1,\"exp\":\"The Norwester (Kal Baisakhi) is the pre-monsoon squally thunderstorm of east and north-east India - West Bengal, Bihar, Odisha, Jharkhand and Assam.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Mar 2024 · Regular 01\",\"Dec 2025 · Regular 04\"],\"undated\":true,\"times\":3,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-194\",\"topic\":\"Thunderstorms\",\"stem\":\"Norwesters occur during\",\"opts\":[\"January-February\",\"March-May\",\"June-September\"],\"ans\":1,\"exp\":\"They belong to the hot weather (pre-monsoon) season, March to May.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-195\",\"topic\":\"Thunderstorms\",\"stem\":\"Norwesters are\",\"opts\":[\"Western disturbances affecting NW India\",\"Severe thunderstorms over NE India during the hot weather period\",\"Severe thunderstorms over the peninsula during the hot weather period\"],\"ans\":1,\"exp\":\"Named after the direction they usually come from, Norwesters are violent pre-monsoon thunderstorms with squalls and hail over east and north-east India.\",\"seenIn\":[\"Dec 2024 · Regular 04\",\"Apr 2026 · OLODE 03\"],\"undated\":true,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-196\",\"topic\":\"Thunderstorms\",\"stem\":\"The most hazardous cloud for aviation is\",\"opts\":[\"CB\",\"CU\",\"NS\"],\"ans\":0,\"exp\":\"The CB brings everything at once: severe turbulence, severe icing, hail, lightning, microbursts and wind shear. Avoid it; never fly through it.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Aug 2025 · OLODE 06\",\"Oct 2025 · OLODE 07\",\"Jan 2026 · OLODE 01\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":5,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-197\",\"topic\":\"Thunderstorms\",\"stem\":\"Dust storms over north-west India usually occur during the\",\"opts\":[\"Post-monsoon\",\"Winter\",\"Pre-monsoon\"],\"ans\":2,\"exp\":\"The hot, dry pre-monsoon months, with strong surface heating and gusty winds, raise dust storms (andhis) over Rajasthan, Punjab and the plains.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-198\",\"topic\":\"Thunderstorms\",\"stem\":\"Dust storms over NW India in the hot weather season are commonly associated with\",\"opts\":[\"Western disturbances\",\"The south-west monsoon\",\"The trade winds\"],\"ans\":0,\"exp\":\"In the hot weather season, western disturbances passing across the north set off thunderstorms and dust storms over Punjab and Rajasthan.\",\"seenIn\":[\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-199\",\"topic\":\"Thunderstorms\",\"stem\":\"Thunderstorm weather in the pre-monsoon season is typically\",\"opts\":[\"Drizzle\",\"CB with heavy turbulence\",\"Stratus, cold, with no showers\"],\"ans\":1,\"exp\":\"Pre-monsoon storms are heat-driven cumulonimbus - Norwesters, andhis and hailstorms - with severe turbulence and squalls.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-200\",\"topic\":\"Thunderstorms\",\"stem\":\"Turbulence near a cumulonimbus is experienced\",\"opts\":[\"Only 5 NM outside the CB\",\"Inside the CB and outside it as well\",\"Only inside the CB\"],\"ans\":1,\"exp\":\"Turbulence is not confined to the cloud: gust fronts, downdraughts and shear extend well outside it - under the anvil and ahead of the storm. Keep a wide margin.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-201\",\"topic\":\"Air masses & fronts\",\"stem\":\"At a warm front, the warm air\",\"opts\":[\"Slides beneath the cold air\",\"Rides up over the cold air\",\"Mixes evenly with the cold air\"],\"ans\":1,\"exp\":\"At a warm front the advancing warm air is lighter, so it climbs gently up over the wedge of retreating cold air - producing the long sequence Ci, Cs, As, Ns.\",\"seenIn\":[\"2022 · Regular 03\",\"Jun 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Sep 2024 · Regular 03\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":5,\"years\":[2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-202\",\"topic\":\"Air masses & fronts\",\"stem\":\"If a warm air mass overtakes a cold air mass, it is called a\",\"opts\":[\"Cold front\",\"Warm front\",\"Occluded front\"],\"ans\":1,\"exp\":\"The front is named after the air that is advancing: warm air replacing cold air is a warm front.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\"],\"undated\":true,\"times\":3,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-203\",\"topic\":\"Air masses & fronts\",\"stem\":\"A warm front is defined as\",\"opts\":[\"Cold air advancing under warm air\",\"Warm air advancing over retreating cold air, with a gentle slope\",\"A stationary boundary\"],\"ans\":1,\"exp\":\"Warm air replaces cold air along a shallow slope of about 1 in 150, which is why its cloud and rain spread far ahead of the surface front.\",\"seenIn\":[\"Jun 2025 · Regular 02\",\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-204\",\"topic\":\"Air masses & fronts\",\"stem\":\"A cold front moves at ______ the speed of a warm front\",\"opts\":[\"The same as\",\"About double\",\"About half\"],\"ans\":1,\"exp\":\"The dense cold air pushes forward quickly; a cold front typically travels about twice as fast as a warm front, which is why it eventually catches up and forms an occlusion.\",\"seenIn\":[\"Sep 2024 · Regular 03\",\"Jan 2025 · OLODE 01\",\"Jul 2025 · OLODE 05\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-205\",\"topic\":\"Air masses & fronts\",\"stem\":\"Compared with a warm front, a cold front has\",\"opts\":[\"A steeper slope and moves faster\",\"A gentler slope and moves slower\",\"A steeper slope and moves slower\"],\"ans\":0,\"exp\":\"Cold front slope about 1:50 to 1:80 against 1:150 for a warm front, and about double the speed. Steep and fast gives a narrow band of violent weather; shallow and slow gives wide, long-lasting weather.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Mar 2024 · Regular 01\",\"Jul 2025 · OLODE 05\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-206\",\"topic\":\"Air masses & fronts\",\"stem\":\"Which front generally moves the fastest?\",\"opts\":[\"Warm front\",\"Cold front\",\"Stationary front\"],\"ans\":1,\"exp\":\"Cold fronts move at about twice the speed of warm fronts; a stationary front hardly moves at all.\",\"seenIn\":[\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-207\",\"topic\":\"Air masses & fronts\",\"stem\":\"Ahead of a warm front, the surface wind\",\"opts\":[\"Backs and weakens\",\"Veers and strengthens\",\"Backs and strengthens\"],\"ans\":2,\"exp\":\"As a warm front approaches the pressure falls and the gradient tightens, so the wind backs and freshens; at the front it veers.\",\"seenIn\":[\"Dec 2024 · Regular 04\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-208\",\"topic\":\"Air masses & fronts\",\"stem\":\"During the passage of a cold front (NH), the wind\",\"opts\":[\"Suddenly becomes squally and veers\",\"Backs and weakens\",\"Does not change\"],\"ans\":0,\"exp\":\"At a cold front the wind veers sharply, often with violent gusts and squalls, the temperature drops and the pressure starts to rise.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jul 2022 · OLODE 05\",\"May 2024 · OLODE\",\"Feb 2025 · OLODE 02\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":5,\"years\":[2021,2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-209\",\"topic\":\"Air masses & fronts\",\"stem\":\"After the passage of a cold front\",\"opts\":[\"Precipitation ceases quickly and visibility improves\",\"Continuous rain lasts for many hours\",\"Fog forms and persists\"],\"ans\":0,\"exp\":\"Cold-front weather is a narrow band. Once it has passed, the rain stops, the cold air brings good visibility, and scattered showers may follow.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-210\",\"topic\":\"Air masses & fronts\",\"stem\":\"In a warm occlusion\",\"opts\":[\"The warm air is lifted off the surface and the overtaking cold air rides over the colder air ahead\",\"The overtaking cold air undercuts both air masses\",\"No lifting takes place\"],\"ans\":0,\"exp\":\"In any occlusion the warm sector air is lifted off the ground. In a warm occlusion the air behind the cold front is less cold than the air ahead, so it rides up over it.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Jan 2025 · OLODE 01\",\"Mar 2025 · Regular 01\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":6,\"years\":[2021,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-211\",\"topic\":\"Air masses & fronts\",\"stem\":\"If the advancing cold air is colder than the cool air ahead of the warm front, it undercuts and lifts both. This is a\",\"opts\":[\"Warm occlusion\",\"Cold occlusion\",\"Stationary front\"],\"ans\":1,\"exp\":\"In a cold occlusion the coldest air is the overtaking air behind the cold front, so it wedges under everything ahead of it.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Dec 2024 · Regular 04\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":3,\"years\":[2022,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-212\",\"topic\":\"Air masses & fronts\",\"stem\":\"An air mass acquires its characteristics from the\",\"opts\":[\"Upper winds\",\"Latitude alone\",\"Underlying surface\"],\"ans\":2,\"exp\":\"An air mass takes its temperature and moisture from the land or sea it sits over in its source region - hot or cold, dry or moist.\",\"seenIn\":[\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-213\",\"topic\":\"Air masses & fronts\",\"stem\":\"An air mass originating over land in the polar region is\",\"opts\":[\"Warm and dry\",\"Warm and moist\",\"Cold and dry\"],\"ans\":2,\"exp\":\"Polar = cold, continental (land) = dry: polar continental air is cold and dry.\",\"seenIn\":[\"Apr 2025 · OLODE 03\",\"Oct 2025 · OLODE 07\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-214\",\"topic\":\"Air masses & fronts\",\"stem\":\"An air mass originating over the sea in high latitudes is\",\"opts\":[\"Polar maritime\",\"Tropical maritime\",\"Polar continental\"],\"ans\":0,\"exp\":\"High latitude = polar; over the sea = maritime. Polar maritime air is cool and moist.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-215\",\"topic\":\"Air masses & fronts\",\"stem\":\"An air mass originating over the sea in low latitudes is\",\"opts\":[\"Warm and moist\",\"Cold and dry\",\"Warm and dry\"],\"ans\":0,\"exp\":\"Low latitude = tropical (warm); over the sea = maritime (moist). Tropical maritime air is warm and moist.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2021,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-216\",\"topic\":\"Air masses & fronts\",\"stem\":\"A WD with two or more closed isobars at 2 hPa interval is termed a\",\"opts\":[\"Trough in the westerlies\",\"Western depression\",\"Western cyclone\"],\"ans\":1,\"exp\":\"When a western disturbance deepens enough to show two or more closed isobars at 2 hPa spacing, it is called a western depression.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Dec 2023 · Regular\",\"Apr 2025 · OLODE 03\",\"Aug 2025 · OLODE 06\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":5,\"years\":[2021,2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-217\",\"topic\":\"Air masses & fronts\",\"stem\":\"The maximum number of western disturbances occur in\",\"opts\":[\"Summer\",\"Monsoon\",\"Winter\"],\"ans\":2,\"exp\":\"WDs travel east with the subtropical westerlies, which lie over north India in winter - five to seven a month then.\",\"seenIn\":[\"Dec 2024 · Regular 04\",\"May 2026 · OLODE 04\"],\"undated\":true,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-218\",\"topic\":\"Air masses & fronts\",\"stem\":\"Fronts are characteristic of\",\"opts\":[\"Tropical depressions\",\"Extra-tropical depressions\",\"Heat lows\"],\"ans\":1,\"exp\":\"Fronts need two contrasting air masses, which meet along the polar front in mid-latitudes. Extra-tropical depressions form on it; tropical depressions and heat lows form in a single air mass and have no fronts.\",\"seenIn\":[\"Apr 2025 · OLODE 03\",\"May 2025 · OLODE 04\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-219\",\"topic\":\"Air masses & fronts\",\"stem\":\"A stationary (quasi-stationary) front is one that\",\"opts\":[\"Shows little or no movement\",\"Moves at twice the speed of a cold front\",\"Always produces thunderstorms\"],\"ans\":0,\"exp\":\"When the winds on both sides blow nearly parallel to the front, it hardly moves. Its weather can sit over one area for days.\",\"seenIn\":[\"Apr 2025 · OLODE 03\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-220\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"Lenticular clouds indicate the presence of\",\"opts\":[\"A warm front\",\"A cold front\",\"Mountain waves\"],\"ans\":2,\"exp\":\"Lens-shaped clouds that stay still over or downwind of a ridge mark the crests of standing mountain waves. Ragged edges mean turbulence.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jul 2022 · OLODE 05\",\"Jul 2023 · OLODE\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"May 2024 · OLODE\",\"Feb 2025 · OLODE 02\",\"Jun 2025 · Regular 02\",\"Jul 2025 · OLODE 05\",\"Oct 2025 · OLODE 07\",\"Apr 2026 · OLODE 03\"],\"undated\":true,\"times\":12,\"years\":[2021,2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-221\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"For mountain waves to form, there should be ______ air below the ridge (with less stable air above)\",\"opts\":[\"Stable\",\"Unstable\",\"Indifferent\"],\"ans\":0,\"exp\":\"A stable layer near ridge level makes the air bounce after crossing the ridge, like a spring, setting up the waves; less stable air above lets them extend upwards. Unstable air would just give convection.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Dec 2023 · Regular\",\"Jan 2025 · OLODE 01\",\"Mar 2025 · Regular 01\",\"Jun 2025 · Regular 02\",\"Oct 2025 · OLODE 07\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":7,\"years\":[2022,2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-222\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"Conditions for mountain waves include\",\"opts\":[\"Stable air and strong winds blowing across the mountains\",\"Unstable air and weak winds\",\"Calm conditions only\"],\"ans\":0,\"exp\":\"Needed: a wind of adequate strength blowing within about 30 degrees of the perpendicular to the ridge, increasing with height, and stable air near ridge level.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"May 2025 · OLODE 04\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2021,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-223\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"For mountain waves to form, the airflow across the ridge should be within ______ of the perpendicular to the ridge\",\"opts\":[\"30 degrees\",\"45 degrees\",\"60 degrees\"],\"ans\":0,\"exp\":\"The flow must hit the ridge nearly head-on - within about 30 degrees of the perpendicular. Wind blowing along the ridge does not set up waves.\",\"seenIn\":[\"Dec 2024 · Regular 04\",\"Apr 2025 · OLODE 03\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-224\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"For mountain waves to form, the wind speed for large mountains should be at least\",\"opts\":[\"15 m/s\",\"10 m/s\",\"7 m/s\"],\"ans\":0,\"exp\":\"At ridge level about 15 m/s (around 30 kt) is needed over large mountain ranges, and about 7 m/s over small ones.\",\"seenIn\":[\"2022 · Regular 03\",\"Jun 2023 · Regular\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\"],\"undated\":true,\"times\":4,\"years\":[2022,2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-225\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"For mountain waves to form, the wind speed for small mountains should be at least\",\"opts\":[\"5 m/s\",\"7 m/s\",\"10 m/s\"],\"ans\":1,\"exp\":\"Small hills need about 7 m/s (around 15 kt) at ridge level; large ranges about 15 m/s.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Dec 2024 · Regular 04\",\"Jan 2025 · OLODE 01\",\"May 2025 · OLODE 04\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-226\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"The worst turbulence is encountered near\",\"opts\":[\"Rotor clouds\",\"Lenticular clouds\",\"Cap clouds\"],\"ans\":0,\"exp\":\"The rotor zone under the wave crests holds the most violent turbulence of a mountain wave - comparable to a violent thunderstorm, with up- and down-gusts.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-227\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"Rotor clouds are associated with\",\"opts\":[\"Sea breezes\",\"Mountain waves\",\"Warm fronts\"],\"ans\":1,\"exp\":\"Rotor (roll) clouds form downwind of a ridge, under the crests of strong mountain waves, and mark the worst turbulence in the wave system.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-228\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"Taking off behind a heavy aircraft that has just departed, to avoid its wingtip vortices you should\",\"opts\":[\"Take off behind and below its flight path\",\"Lift off before its rotation point and stay above its flight path\",\"Follow the same flight path\"],\"ans\":1,\"exp\":\"Vortices start when the heavy aircraft's nose wheel lifts off and then sink, levelling off 500-1000 ft below its flight path. Lift off before that point and climb above its path and you stay out of them.\",\"seenIn\":[\"Dec 2023 · Regular\",\"May 2024 · OLODE\",\"Feb 2025 · OLODE 02\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-229\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"On a summer day, turbulence caused by solar heating is most marked\",\"opts\":[\"Soon after sunrise\",\"In the early afternoon\",\"At dawn\"],\"ans\":1,\"exp\":\"Thermal turbulence follows the heating of the ground, which peaks in the early afternoon - the bumpiest time for low-level flying on a hot day.\",\"seenIn\":[\"Dec 2023 · Regular\",\"May 2024 · OLODE\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-230\",\"topic\":\"Jet streams & upper winds\",\"stem\":\"A jet stream can be recognised by\",\"opts\":[\"High-level dust\",\"High pressure\",\"Streaks of cirrus\"],\"ans\":2,\"exp\":\"Long bands of cirrus lying along the flow, often sharp-edged on the cold (poleward) side, mark a jet stream - and the zone where clear-air turbulence may be found.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Oct 2024 · OLODE 07\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":5,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-231\",\"topic\":\"Jet streams & upper winds\",\"stem\":\"The tropical jet stream is\",\"opts\":[\"Westerly\",\"Easterly\",\"Northerly\"],\"ans\":1,\"exp\":\"The tropical easterly jet blows from the east at about 14-16 km over south India and Africa in the summer monsoon. The subtropical jet is westerly.\",\"seenIn\":[\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-232\",\"topic\":\"Jet streams & upper winds\",\"stem\":\"An aircraft flying from Delhi to Kolkata at 10 km in the pre-monsoon season will experience\",\"opts\":[\"Easterly winds\",\"Westerly winds\",\"Southerly winds\"],\"ans\":1,\"exp\":\"Until the monsoon sets in, the subtropical westerly jet still lies over north India, so the upper winds are strong westerlies - a tailwind towards Kolkata.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Sep 2023 · Regular 03\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-233\",\"topic\":\"Jet streams & upper winds\",\"stem\":\"An aircraft flying from Delhi to Kolkata at 10 km in winter will experience\",\"opts\":[\"Easterly winds\",\"Northerly winds\",\"Westerly winds\"],\"ans\":2,\"exp\":\"In winter the subtropical westerly jet sits over north India at about 12 km, around 27 N, with westerlies of 80-100 kt or more.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Dec 2024 · Regular 04\",\"Feb 2025 · OLODE 02\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-234\",\"topic\":\"Jet streams & upper winds\",\"stem\":\"An aircraft flying in winter from Chennai to Kolkata at 12 km will experience\",\"opts\":[\"Easterly winds\",\"Westerly winds\",\"Northerly winds\"],\"ans\":1,\"exp\":\"In winter the westerlies above about 10 000 ft spread south to the tip of the peninsula and strengthen with height, so at 12 km the wind is westerly even over south India.\",\"seenIn\":[\"2022 · Regular 03\",\"Aug 2024 · OLODE\",\"Nov 2024 · OLODE 08\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-235\",\"topic\":\"Jet streams & upper winds\",\"stem\":\"An aircraft flying from Mumbai to Ahmedabad at 3 km during the monsoon will experience\",\"opts\":[\"North-easterly winds\",\"South-easterly winds\",\"South-westerly winds\"],\"ans\":2,\"exp\":\"At low and medium levels the monsoon current over the west coast blows from the south-west off the Arabian Sea.\",\"seenIn\":[\"May 2025 · OLODE 04\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-236\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"A tropical cyclonic storm has an outer storm area of about\",\"opts\":[\"More than 400 km\",\"More than 700 km\",\"More than 900 km\"],\"ans\":0,\"exp\":\"A mature tropical cyclone has an eye of about 30-65 km, an inner storm area of about 50-150 km and an outer storm area reaching about 400 km, with gales and spiral cloud bands.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-237\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"In a depression, the wind speed is\",\"opts\":[\"Less than 17 kt\",\"17-27 kt\",\"34-47 kt\"],\"ans\":1,\"exp\":\"Indian classification: low below 17 kt, depression 17-27 kt, deep depression 28-33 kt, cyclonic storm 34-47 kt, severe cyclonic storm 48-63 kt.\",\"seenIn\":[\"2022 · Regular 03\",\"Jun 2023 · Regular\",\"Dec 2024 · Regular 04\"],\"undated\":true,\"times\":3,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-238\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"During re-curvature, the maximum weather in a monsoon depression occurs in the\",\"opts\":[\"SE sector\",\"SW sector\",\"NE sector\"],\"ans\":2,\"exp\":\"Normally the worst weather is in the SW sector of a monsoon depression. When it re-curves, the rain belt shifts to the north-east sector.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Apr 2024 · OLODE 03\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-239\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"Cyclonic storms form over the Indian seas during the\",\"opts\":[\"SW monsoon\",\"Winter season\",\"Pre-monsoon and post-monsoon\"],\"ans\":2,\"exp\":\"Cyclones need warm sea, moist air and little vertical wind shear. The strong shear of the monsoon suppresses them, so the peak seasons are April-May and October-November.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Sep 2024 · Regular 03\",\"Mar 2025 · Regular 01\",\"Jan 2026 · OLODE 01\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":6,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-240\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"Cyclonic storms cross the Tamil Nadu coast in\",\"opts\":[\"October-November\",\"July-August\",\"February-May\"],\"ans\":0,\"exp\":\"Post-monsoon storms form over the Bay of Bengal and move west-north-west, crossing the Tamil Nadu and Andhra coasts in October-November - Tamil Nadu's main rainy season.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Dec 2023 · Regular\",\"Jun 2025 · Regular 02\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":4,\"years\":[2022,2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-241\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"Cyclonic storms in the Indian region are less intense because\",\"opts\":[\"They have a very short travel over the sea\",\"The sea surface temperatures are not high\",\"India is close to the equator\"],\"ans\":0,\"exp\":\"A cyclone feeds on the warm sea. Over the narrow Bay of Bengal and Arabian Sea it reaches land after a short sea track, before it can grow as big as the Pacific typhoons.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Mar 2024 · Regular 01\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-242\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"Tropical revolving storms over the Indian seas form in the latitude belt of\",\"opts\":[\"The equatorial region\",\"5-15 N\",\"0-5 N\"],\"ans\":1,\"exp\":\"Within about 5 degrees of the equator the Coriolis force is too weak to start the rotation, so TRS form in the 5-15 degree belt.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Oct 2023 · OLODE\",\"Apr 2024 · OLODE 03\",\"Dec 2024 · Regular 04\",\"Mar 2025 · Regular 01\",\"Jun 2025 · Regular 02\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":7,\"years\":[2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-243\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"In a mature tropical cyclone, the eye is characterised by\",\"opts\":[\"Moderate weather\",\"Stormy weather\",\"Calm wind, little cloud and practically no rain\"],\"ans\":2,\"exp\":\"Air sinks in the eye, warming and drying, so it has light winds and broken or no cloud - right in the middle of the storm.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-244\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"The most dangerous part of a tropical cyclone is the\",\"opts\":[\"Eye\",\"Eye wall\",\"Outer cloud bands\"],\"ans\":1,\"exp\":\"The wall of cumulonimbus ringing the eye has the strongest winds, the heaviest rain and the worst turbulence. The calm eye is surrounded by the most violent weather in the storm.\",\"seenIn\":[\"Dec 2025 · Regular 04\",\"Jan 2026 · OLODE 01\"],\"undated\":true,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-245\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"The weather in a well-developed cyclonic storm is\",\"opts\":[\"Clear sky and calm winds\",\"Strong winds, heavy rain and poor visibility\",\"Dry weather only\"],\"ans\":1,\"exp\":\"Outside the eye a cyclonic storm brings gale to hurricane force winds, torrential rain, low cloud and very poor visibility - stormy weather.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-246\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"A monsoon depression moves faster over\",\"opts\":[\"Plains\",\"Sea\",\"Rivers\"],\"ans\":0,\"exp\":\"Monsoon depressions travel faster over the plains than over hills or sea.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Feb 2025 · OLODE 02\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check could not confirm this answer from the official sources we hold; treat it with care and confirm with your instructor.\"},{\"id\":\"CPLMET-247\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"A non-frontal thermal depression is generally formed due to\",\"opts\":[\"Surface heating\",\"Cold air intrusion\",\"Frontal activity\"],\"ans\":0,\"exp\":\"Strong heating of the land warms the air, which expands and rises, lowering the surface pressure - a heat (thermal) low, like the summer low over Pakistan and NW India.\",\"seenIn\":[\"May 2025 · OLODE 04\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-248\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"Surge and shear line are features of a ______ monsoon\",\"opts\":[\"Weak\",\"Retreating\",\"Vigorous\"],\"ans\":2,\"exp\":\"Surges (pulses of stronger wind) and shear lines appear when the monsoon current is strong - a vigorous monsoon.\",\"seenIn\":[\"Sep 2025 · Regular 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-249\",\"topic\":\"General circulation\",\"stem\":\"Rising air creates calms (doldrums) in the equatorial region, called\",\"opts\":[\"ITCZ\",\"Horse latitudes\",\"Equatorial doldrums\"],\"ans\":2,\"exp\":\"Along the equatorial low the air mostly rises, so surface winds are light and variable - the doldrums. The horse latitudes are the calms of the subtropical highs near 30 degrees.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check found that more than one option can be argued for, as worded in the recall. The key gives the answer most references support.\"},{\"id\":\"CPLMET-250\",\"topic\":\"General circulation\",\"stem\":\"The horse latitudes are\",\"opts\":[\"The equatorial low-pressure belt\",\"The subtropical high-pressure belts around 30 N and S\",\"The polar highs\"],\"ans\":1,\"exp\":\"Under the subtropical highs the air sinks and the winds are light. Sailing ships were becalmed there - hence the name.\",\"seenIn\":[\"May 2024 · OLODE\",\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-251\",\"topic\":\"General circulation\",\"stem\":\"The trade winds are\",\"opts\":[\"The westerlies of the mid-latitudes\",\"Easterly winds blowing from the subtropical highs towards the ITCZ\",\"The polar easterlies\"],\"ans\":1,\"exp\":\"Air flows from the subtropical highs towards the equatorial low and is turned by the Coriolis force: NE trades in the Northern Hemisphere, SE trades in the Southern, meeting at the ITCZ.\",\"seenIn\":[\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-252\",\"topic\":\"General circulation\",\"stem\":\"The zonal westerlies are\",\"opts\":[\"The easterly trade winds\",\"The prevailing westerly winds of the mid-latitudes\",\"The monsoon flow\"],\"ans\":1,\"exp\":\"Between about 30 and 60 degrees, and through the upper troposphere, the general flow is from the west - the zonal westerlies, strongest in the jet streams.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-253\",\"topic\":\"Indian climatology\",\"stem\":\"A break in the monsoon occurs when the axis of the monsoon trough is along the\",\"opts\":[\"Gangetic plains\",\"Foothills of the Himalayas\",\"Bay of Bengal\"],\"ans\":1,\"exp\":\"Normally the trough runs along the Gangetic plains (Ganganagar-Allahabad-Kolkata). When it shifts north to the Himalayan foothills, rain stops over most of the country - a break.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Jun 2023 · Regular\",\"May 2024 · OLODE\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-254\",\"topic\":\"Indian climatology\",\"stem\":\"During a break in the monsoon, more rain occurs over the\",\"opts\":[\"Coastal areas\",\"Plateau region\",\"Himalayan foothills\"],\"ans\":2,\"exp\":\"With the trough lying along the foothills, the rain is concentrated there (and floods the rivers coming out of the hills) while the plains stay dry.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Mar 2025 · Regular 01\",\"Jul 2025 · OLODE 05\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":4,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-255\",\"topic\":\"Indian climatology\",\"stem\":\"During an active (normal) monsoon, the axis of the monsoon trough lies along the\",\"opts\":[\"Gangetic plains\",\"Himalayan foothills\",\"Southern peninsula\"],\"ans\":0,\"exp\":\"In its normal position the trough runs from Ganganagar through Allahabad and Kolkata to the head of the Bay, and rain is widespread across the country.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Dec 2024 · Regular 04\",\"Jan 2025 · OLODE 01\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-256\",\"topic\":\"Indian climatology\",\"stem\":\"The monsoon advances with\",\"opts\":[\"The Bay of Bengal current only\",\"The Arabian Sea current only\",\"Both the Bay of Bengal and Arabian Sea currents\"],\"ans\":2,\"exp\":\"The SW monsoon arrives in two branches: the Arabian Sea branch onto the west coast and the Bay of Bengal branch into the north-east and the Gangetic plains. They meet over central and north India.\",\"seenIn\":[\"May 2025 · OLODE 04\",\"Sep 2025 · Regular 03\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-257\",\"topic\":\"Indian climatology\",\"stem\":\"During the monsoon season, the seasonal low pressure lies over\",\"opts\":[\"Bay of Bengal\",\"NE India\",\"Pakistan\"],\"ans\":2,\"exp\":\"The monsoon heat low is centred over Pakistan and NW India, with the monsoon trough extending from it to the head of the Bay of Bengal.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Mar 2025 · Regular 01\",\"Mar 2026 · Regular 01\"],\"undated\":true,\"times\":3,\"years\":[2021,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-258\",\"topic\":\"Indian climatology\",\"stem\":\"Peninsular discontinuity occurs during the\",\"opts\":[\"Monsoon\",\"NE monsoon\",\"Pre-monsoon\"],\"ans\":2,\"exp\":\"The correct answer is: Pre-monsoon.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Oct 2023 · OLODE\",\"Nov 2024 · OLODE 08\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":4,\"years\":[2021,2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-259\",\"topic\":\"Indian climatology\",\"stem\":\"The monsoon (SW monsoon) period in India is\",\"opts\":[\"March-May\",\"June-September\",\"October-November\"],\"ans\":1,\"exp\":\"IMD seasons: winter January-February, pre-monsoon (hot weather) March-May, SW monsoon June-September, post-monsoon October-November.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Oct 2025 · OLODE 07\",\"Dec 2025 · Regular 04\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-260\",\"topic\":\"Indian climatology\",\"stem\":\"The post-monsoon period in India is\",\"opts\":[\"March-May\",\"June-September\",\"October-November\"],\"ans\":2,\"exp\":\"October-November, also called the retreating monsoon or NE monsoon season - Tamil Nadu's main rainy season.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Apr 2024 · OLODE 03\",\"Dec 2024 · Regular 04\",\"Feb 2025 · OLODE 02\",\"Aug 2025 · OLODE 06\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":6,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-261\",\"topic\":\"Indian climatology\",\"stem\":\"The pre-monsoon (hot weather) period in India is\",\"opts\":[\"January-February\",\"March-May\",\"June-September\"],\"ans\":1,\"exp\":\"March to May: rising temperatures, dust storms in the north-west, Norwesters in the east.\",\"seenIn\":[\"2022 · Regular 03\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-262\",\"topic\":\"Indian climatology\",\"stem\":\"Low temperatures and low humidity are the characteristic of\",\"opts\":[\"Summer\",\"Monsoon\",\"Winter\"],\"ans\":2,\"exp\":\"In winter north India is fed cold, dry continental air - clear skies, low humidity and low temperatures, broken only by western disturbances.\",\"seenIn\":[\"Mar 2022 · Regular\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2022,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-263\",\"topic\":\"Indian climatology\",\"stem\":\"India's greatest share of annual rainfall comes from the\",\"opts\":[\"Maritime tropical air of the winter\",\"NE monsoon\",\"SW monsoon\"],\"ans\":2,\"exp\":\"Most of India receives the bulk of its annual rainfall - roughly three-quarters - from the SW monsoon, June to September.\",\"seenIn\":[\"Dec 2023 · Regular\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-264\",\"topic\":\"Indian climatology\",\"stem\":\"During the post-monsoon season, the pressure gradient over India is generally\",\"opts\":[\"Steep\",\"Weak\",\"Very steep\"],\"ans\":1,\"exp\":\"In October-November one isobar can surround the whole country - the pressure field is flat, so surface winds are light and variable.\",\"seenIn\":[\"Dec 2024 · Regular 04\",\"Jun 2025 · Regular 02\",\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-265\",\"topic\":\"Indian climatology\",\"stem\":\"The strongest winds along the west coast of India occur during the\",\"opts\":[\"SW monsoon\",\"Winter\",\"Post-monsoon\"],\"ans\":0,\"exp\":\"A vigorous monsoon brings a steep pressure gradient and strong south-westerly winds along the west coast, especially in June-July.\",\"seenIn\":[\"May 2024 · OLODE\",\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-266\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"The validity of a TREND (landing) forecast is\",\"opts\":[\"1 hr\",\"2 hr\",\"3 hr\"],\"ans\":1,\"exp\":\"A TREND forecast appended to a METAR or SPECI is valid for 2 hours from the time of the report.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Sep 2023 · Regular 03\",\"May 2024 · OLODE\",\"Apr 2025 · OLODE 03\",\"Mar 2026 · Regular 01\"],\"undated\":true,\"times\":5,\"years\":[2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-267\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"A wind shear warning is issued for observed or expected wind shear between the runway level and\",\"opts\":[\"500 m\",\"Above 500 m\",\"300 m\"],\"ans\":0,\"exp\":\"Wind shear warnings cover the layer from runway level up to about 500 m (1600 ft) - the approach and climb-out zone.\",\"seenIn\":[\"Apr 2025 · OLODE 03\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-268\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"TAFs issued in India are valid for\",\"opts\":[\"At least 9 hours and at most 30 hours\",\"Exactly 2 hours\",\"48 hours\"],\"ans\":0,\"exp\":\"TAF validity runs from 9 hours (issued every 3 hours) up to a maximum of 30 hours for the longer TAFs (issued every 6 hours). Two hours is a TREND.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"May 2024 · OLODE\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":5,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-269\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"METAR and TAF are\",\"opts\":[\"Both forecasts\",\"Both actual observations\",\"METAR the actual weather, TAF a forecast\"],\"ans\":2,\"exp\":\"A METAR reports what the weather IS at the aerodrome at the time of observation; a TAF forecasts what it WILL be over its validity period.\",\"seenIn\":[\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-270\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"In a METAR, the cloud height is found in the\",\"opts\":[\"Wind group\",\"Visibility group\",\"Cloud group\"],\"ans\":2,\"exp\":\"Each cloud group gives the amount and the height of the base in hundreds of feet, e.g. BKN012 = 5-7 oktas based at 1200 ft.\",\"seenIn\":[\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-271\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"In a METAR, the time is reported in\",\"opts\":[\"Local time\",\"UTC\",\"IST\"],\"ans\":1,\"exp\":\"All aviation met reports use UTC, shown as day and time with a Z (e.g. 210400Z). IST is UTC + 5:30.\",\"seenIn\":[\"May 2025 · OLODE 04\",\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-272\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"SIGMET is NOT issued for\",\"opts\":[\"Thunderstorms\",\"Rain\",\"Severe icing\"],\"ans\":1,\"exp\":\"SIGMET warns aircraft in flight of hazardous phenomena - thunderstorms, severe turbulence, severe icing, mountain waves, volcanic ash, tropical cyclones. Ordinary rain is not one of them.\",\"seenIn\":[\"Jun 2025 · Regular 02\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-273\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"In India, SIGMET is provided by\",\"opts\":[\"DGCA\",\"IMD\",\"AAI\"],\"ans\":1,\"exp\":\"SIGMETs are issued by the Meteorological Watch Offices, which in India are run by the India Meteorological Department.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-274\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"An aerodrome warning for strong surface wind is issued when the wind is expected to reach\",\"opts\":[\"20 kt\",\"30 kt\",\"40 kt\"],\"ans\":1,\"exp\":\"An aerodrome warning is issued for surface winds of 30 kt or more (and for a direction change of 45 degrees with winds of 20 kt), with a lower threshold (17 kt) at aerodromes used by light aircraft. Aerodrome warnings are for aircraft on the ground; SIGMET is for aircraft in flight.\",\"seenIn\":[\"Dec 2025 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check could not confirm this answer from the official sources we hold; treat it with care and confirm with your instructor.\"},{\"id\":\"CPLMET-275\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"A SPECI is issued when\",\"opts\":[\"Any one of the criteria for change is met\",\"Any two of the criteria are met\",\"All the criteria are met\"],\"ans\":0,\"exp\":\"A special report goes out as soon as any single specified change occurs - in visibility, cloud, wind or weather. Contrast CAVOK, which needs all three of its conditions.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-276\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"In a METAR, the group 1200 +SHRA means\",\"opts\":[\"Visibility 1200 m, heavy showers of rain\",\"Visibility 12 km, heavy rain\",\"RVR 1200 m, moderate showers of rain\"],\"ans\":0,\"exp\":\"Four figures after the wind are the visibility in metres: 1200 = 1.2 km. + means heavy, SH showers, RA rain.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-277\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"In a station model, cloud-base height code 2 represents a base of\",\"opts\":[\"0-99 m\",\"100-199 m\",\"200-299 m\"],\"ans\":1,\"exp\":\"The height-of-base code steps are 0 = 0-49 m, 1 = 50-99 m, 2 = 100-199 m, 3 = 200-299 m, 4 = 300-599 m.\",\"seenIn\":[\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-278\",\"topic\":\"Visibility & fog\",\"stem\":\"Visibility is poor in a warm front\",\"opts\":[\"Ahead\",\"Ahead & during\",\"After & during\"],\"ans\":1,\"exp\":\"Ahead of a warm front the steady rain from As and Ns lowers the visibility, and frontal fog forms as the rain saturates the cold air underneath. At the front itself the cloud base is at its lowest, the rain heaviest, and the visibility at its worst. It improves once the front has passed.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Dec 2023 · Regular\",\"Jun 2025 · Regular 02\",\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-279\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"Flying through a mountain wave system, the severe turbulence is found\",\"opts\":[\"Along the rotor cloud, on the leeward side of the ridge\",\"Only above the lenticular clouds\",\"Only on the windward slope\"],\"ans\":0,\"exp\":\"The rotor is a rolling eddy that forms downwind of the ridge, under the wave. The air in and along the rotor cloud is violently turbulent, like the inside of a thunderstorm. Treat the whole rotor zone on the lee side as a no-go area.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Jul 2023 · OLODE\",\"Sep 2024 · Regular 03\",\"Jan 2025 · OLODE 01\",\"Feb 2025 · OLODE 02\",\"Mar 2025 · Regular 01\",\"Sep 2025 · Regular 03\",\"Jan 2026 · OLODE 01\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":9,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-280\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"In a mountain wave, rotor clouds form\",\"opts\":[\"On the leeward side of the ridge\",\"On the windward side of the ridge\",\"Over the top of the ridge\"],\"ans\":0,\"exp\":\"Rotor (roll) clouds form downwind of the ridge on the leeward side, under the wave crests. The strongest rotor is usually in the first wave downwind. Cap cloud sits on the ridge itself, and lenticulars sit higher up in the wave crests.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-281\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"For mountain waves and lenticular clouds, the air at higher levels above the stable layer, on the leeward side, is\",\"opts\":[\"Stable\",\"Unstable (less stable)\",\"Indifferent\"],\"ans\":1,\"exp\":\"The wave needs a stable layer at about ridge height, which acts like a spring. The air above it on the leeward side is less stable, and that lets the wave grow upward and the lenticular clouds form in its crests.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Sep 2024 · Regular 03\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-282\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The troposphere is deepest over the\",\"opts\":[\"Poles\",\"Equator\",\"Mid-latitudes\"],\"ans\":1,\"exp\":\"Strong surface heating and convection over the equator push the tropopause up to about 16-18 km, against about 8 km over the poles. So the troposphere is deepest over the equator.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":2,\"years\":[2021,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-283\",\"topic\":\"Wind\",\"stem\":\"The thermal wind is\",\"opts\":[\"A wind caused by thermals\",\"A warm leeward downslope wind\",\"The vector to add to the lower geostrophic wind to obtain the upper geostrophic wind\"],\"ans\":2,\"exp\":\"The thermal wind is not a real wind. It is the vector difference between the geostrophic winds at two levels: add it to the lower wind to get the upper wind. It blows parallel to the isotherms with cold air on its left in the northern hemisphere.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-284\",\"topic\":\"Lapse rates & stability\",\"stem\":\"Dry air having a temp of 35°C on surface when forced to rise adiabatically by 1 km would attain a temp of\",\"opts\":[\"29°C\",\"25°C\",\"45°C\"],\"ans\":1,\"exp\":\"Dry air cools at the dry adiabatic lapse rate of about 9.8 °C per km, so 35 °C at the surface becomes about 25 °C after a 1 km climb.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2021,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-285\",\"topic\":\"Thunderstorms\",\"stem\":\"Over the sea TS are more frequent\",\"opts\":[\"afternoon\",\"night\",\"early morning\"],\"ans\":1,\"exp\":\"Over the sea, thunderstorms are most frequent at night: the sea stays warm while the air above cools by radiation, which steepens the lapse rate. Over land the peak comes in the afternoon.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"2022 · Regular 03\",\"Apr 2024 · OLODE 03\",\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":4,\"years\":[2021,2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-286\",\"topic\":\"Indian climatology\",\"stem\":\"The rainfall over India during monsoon depends on\",\"opts\":[\"Low over Pakistan\",\"Depression over Bay of Bengal\",\"The position of the axis of Monsoon Trough\"],\"ans\":2,\"exp\":\"Where the monsoon trough lies decides where the rain falls. Along the Gangetic plains it gives a normal, active monsoon; shifted to the Himalayan foothills it gives a break.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-287\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"Temperature +2.5°C is reported as\",\"opts\":[\"02\",\"03\",\"2.5°C\"],\"ans\":1,\"exp\":\"METAR temperatures are rounded to whole degrees, with an exact .5 rounded up. So +2.5 °C becomes 03.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2021,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-288\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"Visibility is reported in steps of 50 m when visibility is\",\"opts\":[\"800 m to 5000 m\",\"0 to 800 m\",\"5000 m to 10 km\"],\"ans\":1,\"exp\":\"Visibility steps in a METAR: 50 m below 800 m, 100 m from 800 to 5000 m, and 1000 m from 5000 m up to 9999. Fine steps where it matters most for landing.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-289\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The tropical tropopause over India is at about\",\"opts\":[\"20–21 km\",\"14–15 km\",\"16–16.5 km\"],\"ans\":2,\"exp\":\"Over India the tropical tropopause is high and cold, at about 16-16.5 km. It extends from the equator to about 35-40 degrees latitude, where it breaks and gives way to the lower polar tropopause.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-290\",\"topic\":\"Pressure & altimetry\",\"stem\":\"The relationship between height and pressure is used in the construction of the\",\"opts\":[\"Altimeter\",\"Airspeed indicator\",\"Vertical speed indicator\"],\"ans\":0,\"exp\":\"The altimeter is a barometer calibrated in feet: it uses the standard relationship between pressure and height to turn the pressure it senses into a height.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jul 2022 · OLODE 05\",\"Sep 2024 · Regular 03\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":4,\"years\":[2021,2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-291\",\"topic\":\"Indian climatology\",\"stem\":\"During break monsoon sometimes the surface winds over East UP and Bihar are\",\"opts\":[\"very strong\",\"weak\",\"normal\"],\"ans\":0,\"exp\":\"During a break, the monsoon trough shifts to the Himalayan foothills. The pressure gradient over east UP and Bihar can then tighten, and the surface winds there can at times be very strong.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jul 2022 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2021,2022],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check could not confirm this answer from the official sources we hold; treat it with care and confirm with your instructor.\"},{\"id\":\"CPLMET-292\",\"topic\":\"General circulation\",\"stem\":\"A part of the sinking air over the subtropical highs flows towards the equator, turning west (in the northern hemisphere) due to the Coriolis force. This surface air is called\",\"opts\":[\"Trade winds\",\"Westerlies\",\"Doldrums\"],\"ans\":0,\"exp\":\"Air sinking at the subtropical highs flows back towards the equator at the surface. Coriolis turns it west, so it becomes the NE trade wind in the northern hemisphere and the SE trade wind in the southern.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Sep 2023 · Regular 03\",\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":3,\"years\":[2021,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-293\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"In a METAR or SPECI, the group BKN100 means\",\"opts\":[\"Broken cloud, base 100 m\",\"Broken cloud, base 10,000 ft\",\"Broken cloud, base 1000 ft\"],\"ans\":1,\"exp\":\"Cloud heights in METAR and SPECI are in hundreds of feet above aerodrome level: BKN100 = 5 to 7 oktas based at 10,000 ft. BKN019 would be 1900 ft.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2021,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-294\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Flying near fair-weather cumulus, you can expect\",\"opts\":[\"Turbulence below the cloud base and smooth air above the cloud tops\",\"Smooth air below the cloud base\",\"Severe icing and thunderstorms\"],\"ans\":0,\"exp\":\"Fair-weather cumulus sits on top of thermals. Below the base the rising and sinking air makes it bumpy; above the tops the air is usually smooth. That is why pilots climb above a cumulus layer.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2021,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-295\",\"topic\":\"Air masses & fronts\",\"stem\":\"CI, CS, AS, NS, ST in sequence are associated with the front\",\"opts\":[\"Warm\",\"Cold\",\"Occluded\"],\"ans\":0,\"exp\":\"A warm front announces itself from far ahead: first Ci, then Cs, As, Ns and finally St as the frontal surface comes down to the ground.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"2022 · Regular 03\",\"Oct 2023 · OLODE\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":4,\"years\":[2021,2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-296\",\"topic\":\"Thunderstorms\",\"stem\":\"Generally the severest activity of a, heat type, TS is for\",\"opts\":[\"2 hrs\",\"30 to 45 min\",\"3 to 4 hr\"],\"ans\":1,\"exp\":\"The correct answer is: 30 to 45 min.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Jul 2022 · OLODE 05\",\"Sep 2023 · Regular 03\",\"Sep 2024 · Regular 03\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":5,\"years\":[2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-297\",\"topic\":\"Humidity\",\"stem\":\"The humidity mixing ratio, when unsaturated air is lifted adiabatically\",\"opts\":[\"Decreases\",\"Remains constant\",\"Increases\"],\"ans\":1,\"exp\":\"The mixing ratio is the mass of water vapour per mass of dry air. Lifting or cooling a parcel adds or removes neither, so the mixing ratio stays constant until condensation starts.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-298\",\"topic\":\"Temperature & radiation\",\"stem\":\"A fresh snow surface reflects about ____ of incident solar radiation\",\"opts\":[\"75%\",\"80%\",\"90%\"],\"ans\":1,\"exp\":\"A fresh snow surface reflects about 80% of the incoming solar radiation: its albedo is very high, which is why snow-covered ground stays cold by day.\",\"seenIn\":[\"Mar 2022 · Regular\",\"2022 · Regular 03\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":3,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-299\",\"topic\":\"Pressure & altimetry\",\"stem\":\"An altimeter is which kind of barometer?\",\"opts\":[\"Aneroid\",\"Mercury\",\"Alcohol\"],\"ans\":0,\"exp\":\"The aircraft altimeter is an aneroid barometer: a sealed, partly evacuated capsule expands and contracts with pressure, and the movement drives the pointers.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Jul 2022 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-300\",\"topic\":\"Density\",\"stem\":\"For a given pressure and temperature, moist air has a ____ density than dry air\",\"opts\":[\"Higher\",\"Lower\",\"Same\"],\"ans\":1,\"exp\":\"Water vapour (molecular weight 18) is lighter than dry air (about 29). Replacing some air with vapour lowers the density, so humid air gives poorer take-off performance.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Jul 2025 · OLODE 05\"],\"undated\":true,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-301\",\"topic\":\"Wind\",\"stem\":\"Vertical wind shear is typically measured in\",\"opts\":[\"Knots per 100 ft\",\"Knots per 1000 ft\",\"Metres per second only\"],\"ans\":0,\"exp\":\"Vertical wind shear - the change of wind with height - is quoted in knots per 100 ft. Horizontal wind shear uses knots per 1000 ft.\",\"seenIn\":[\"Mar 2022 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-302\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The lowest layer of the atmosphere is the\",\"opts\":[\"Troposphere\",\"Tropopause\",\"Stratosphere\"],\"ans\":0,\"exp\":\"The troposphere is the lowest layer, from the surface to the tropopause. Almost all the weather and water vapour are found in it.\",\"seenIn\":[\"May 2022 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-303\",\"topic\":\"Air masses & fronts\",\"stem\":\"WDs approach India as\",\"opts\":[\"Cols\",\"Occluded Fronts\",\"Highs\"],\"ans\":1,\"exp\":\"Western disturbances reach India as occluded fronts. They start as frontal depressions far to the west and are usually occluded by the time they arrive, often showing only as an upper-air trough.\",\"seenIn\":[\"May 2022 · Regular\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-304\",\"topic\":\"Air masses & fronts\",\"stem\":\"Fog occurs in Cold Front\",\"opts\":[\"Ahead\",\"During\",\"After\"],\"ans\":0,\"exp\":\"With a cold front, fog and poor visibility are found ahead of the front; behind it the fresh, cold air brings good visibility.\",\"seenIn\":[\"May 2022 · Regular\",\"Sep 2023 · Regular 03\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-305\",\"topic\":\"Local winds\",\"stem\":\"The Chinook is\",\"opts\":[\"A hot, dusty north-easterly wind of central Asia\",\"An oppressive, hot, sand-laden southerly wind\",\"A warm, dry westerly wind on the leeward (eastern) side of the Rocky Mountains\"],\"ans\":2,\"exp\":\"The Chinook is the Rocky Mountains' Föhn: air that has dropped its moisture on the windward side descends the lee slopes and warms at the dry adiabatic rate, arriving warm and dry.\",\"seenIn\":[\"May 2022 · Regular\",\"Nov 2024 · OLODE 08\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":3,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-306\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"Carbon dioxide and water vapour in the atmosphere are known as\",\"opts\":[\"Greenhouse gases\",\"Noble gases\",\"Inert gases\"],\"ans\":0,\"exp\":\"Water vapour, carbon dioxide and methane absorb the earth's long-wave radiation and re-radiate part of it downwards. This greenhouse effect heats the troposphere from below and gives it its lapse rate.\",\"seenIn\":[\"Jul 2022 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-307\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"By volume, the proportion of CO₂ in the atmosphere is about\",\"opts\":[\"3%\",\"0.3%\",\"0.03%\"],\"ans\":2,\"exp\":\"Carbon dioxide is a tiny fraction of the atmosphere - about 0.03 % by volume - yet it is an important greenhouse gas.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-308\",\"topic\":\"Pressure & altimetry\",\"stem\":\"In the ISA, the 200 hPa level corresponds to approximately\",\"opts\":[\"20 000 ft\",\"30 000 ft\",\"40 000 ft\"],\"ans\":2,\"exp\":\"Useful ISA pairs: 700 hPa ≈ 10,000 ft, 500 hPa ≈ 18,000 ft, 300 hPa ≈ 30,000 ft, 200 hPa ≈ 40,000 ft.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Jul 2023 · OLODE\"],\"undated\":false,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-309\",\"topic\":\"Temperature & radiation\",\"stem\":\"The total energy radiated by a black body is proportional to\",\"opts\":[\"T²\",\"T³\",\"T⁴\"],\"ans\":2,\"exp\":\"Stefan's law: the energy a black body radiates is proportional to the fourth power of its absolute temperature. Double the temperature and the radiation rises sixteen-fold.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Sep 2023 · Regular 03\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-310\",\"topic\":\"Temperature & radiation\",\"stem\":\"The diurnal variation of temperature is least on a day that is\",\"opts\":[\"Clear\",\"Partly cloudy\",\"Overcast\"],\"ans\":2,\"exp\":\"Cloud blocks the sun by day and traps the earth's radiation by night. An overcast day therefore shows the smallest difference between the maximum and minimum temperatures.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Feb 2025 · OLODE 02\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-311\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"RVR is reported when the visibility falls below\",\"opts\":[\"500 m\",\"1000 m\",\"1500 m\"],\"ans\":2,\"exp\":\"RVR is reported once the visibility (or the RVR itself) falls below 1500 m, because that is where it starts to matter for approach and landing minima.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Oct 2024 · OLODE 07\"],\"undated\":true,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-312\",\"topic\":\"Visibility & fog\",\"stem\":\"Advection fog can form over\",\"opts\":[\"Over sea only\",\"Over land only\",\"Both over land and sea\"],\"ans\":2,\"exp\":\"Advection fog needs only warm, moist air moving over a colder surface - cold sea or cold land. It forms over both, and at any time of day or night.\",\"seenIn\":[\"Jul 2022 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-313\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"Cloud base is measured by\",\"opts\":[\"Hygrograph\",\"Ceilometer / Ceilograph / Ceiling Balloon\",\"Anemograph\"],\"ans\":1,\"exp\":\"Cloud base is measured with a ceilometer (a laser or light-beam instrument), a ceilograph, or a ceiling balloon timed as it rises to the base.\",\"seenIn\":[\"Jul 2022 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-314\",\"topic\":\"Thunderstorms\",\"stem\":\"In the cumulus (developing) stage of a thunderstorm, the vertical currents are\",\"opts\":[\"Updraughts throughout\",\"Downdraughts throughout\",\"Updraughts and downdraughts side by side\"],\"ans\":0,\"exp\":\"In the cumulus stage, latent heat keeps the cloud warmer than its surroundings, so the whole cloud rises in updraughts. Downdraughts appear only with the rain in the mature stage.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"2022 · Regular 03\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-315\",\"topic\":\"Lapse rates & stability\",\"stem\":\"If DALR = 9.8 °C/km and ELR = 6.8 °C/km, dry (unsaturated) air is\",\"opts\":[\"Stable\",\"Unstable\",\"Indifferent\"],\"ans\":0,\"exp\":\"Stability of dry air is judged against the DALR. An ELR of 6.8 °C/km is less than the DALR of 9.8 °C/km, so a displaced dry parcel is always colder than its surroundings and sinks back - the air is stable.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-316\",\"topic\":\"Clouds & precipitation\",\"stem\":\"A day is called Rainy day when rainfall in 24 hr is ____________. mm or more\",\"opts\":[\"1.5\",\"2\",\"2.5\"],\"ans\":2,\"exp\":\"In India a \\\"rainy day\\\" is one with 2.5 mm or more of rain in 24 hours.\",\"seenIn\":[\"Jul 2022 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-317\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"In the Bay of Bengal during the months of Jul, august, Monsoon Depression form\",\"opts\":[\"Over Head bay\",\"Central Bay\",\"South Bay\"],\"ans\":0,\"exp\":\"In July and August, monsoon depressions over the Bay of Bengal mostly form over the head (north) of the Bay, then move west-north-west across central India.\",\"seenIn\":[\"Jul 2022 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-318\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"Eye of a CS is surrounded by\",\"opts\":[\"Shelf Clouds\",\"Wall Clouds\",\"Rotor Clouds\"],\"ans\":1,\"exp\":\"The calm eye of a cyclonic storm is ringed by the wall cloud - a wall of towering CB with the strongest winds and heaviest rain of the whole storm.\",\"seenIn\":[\"Jul 2022 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-319\",\"topic\":\"Indian climatology\",\"stem\":\"Peninsular discontinuity occurs along\",\"opts\":[\"West Coast\",\"East Coast\",\"Central peninsula\"],\"ans\":2,\"exp\":\"Peninsular discontinuity is a trough line running north-south along the central peninsula in the pre-monsoon season, where the winds from the Arabian Sea and the Bay of Bengal meet.\",\"seenIn\":[\"Jul 2022 · OLODE 05\",\"Mar 2025 · Regular 01\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-320\",\"topic\":\"Wind\",\"stem\":\"Lines of constant wind speed on a chart are called\",\"opts\":[\"Isobars\",\"Isotachs\",\"Isogons\"],\"ans\":1,\"exp\":\"Isotachs are lines joining places of equal wind speed. Isobars join equal pressure; isogonals join equal magnetic variation.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-321\",\"topic\":\"Lapse rates & stability\",\"stem\":\"In the actual atmosphere, the lapse rate can\",\"opts\":[\"Assume any value\",\"Only fall up to 8 km\",\"Only rise up to 50 km\"],\"ans\":0,\"exp\":\"The real lapse rate at any place and time can take any value: positive, zero (isothermal) or negative (an inversion). Only the ISA fixes it at 2 °C per 1000 ft.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Sep 2024 · Regular 03\",\"Feb 2025 · OLODE 02\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-322\",\"topic\":\"Lapse rates & stability\",\"stem\":\"In an isothermal layer, the temperature\",\"opts\":[\"Remains constant with height\",\"Increases with height\",\"Decreases with height\"],\"ans\":0,\"exp\":\"Isothermal means equal temperature: through the layer the temperature neither falls nor rises with height. Such a layer is stable, like an inversion, only less strongly.\",\"seenIn\":[\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-323\",\"topic\":\"Density\",\"stem\":\"Compared with a sunny day, the runway length required on a rainy day is\",\"opts\":[\"More\",\"Less\",\"Same\"],\"ans\":0,\"exp\":\"Rain means a warm, humid, low-pressure day with a wet runway: lower air density cuts engine and wing performance, and the wet surface lengthens the stop. Both push the runway length required up.\",\"seenIn\":[\"Oct 2023 · OLODE\"],\"undated\":true,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check could not confirm this answer from the official sources we hold; treat it with care and confirm with your instructor.\"},{\"id\":\"CPLMET-324\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"Average life of a monsoon depression is\",\"opts\":[\"2 to 3 days\",\"8 to 9 days\",\"3 - 5 days\"],\"ans\":2,\"exp\":\"A monsoon depression typically lasts three to five days, moving west-north-west from the Bay of Bengal across central India and giving heavy rain along its south-west sector.\",\"seenIn\":[\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-325\",\"topic\":\"Jet streams & upper winds\",\"stem\":\"The arbitrary lower limit of jet core velocity has been assigned by WMO as\",\"opts\":[\"60 kt\",\"60 m/s\",\"70 m/s\"],\"ans\":0,\"exp\":\"By WMO convention, a wind qualifies as a jet stream only when its core speed reaches at least 60 kt.\",\"seenIn\":[\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-326\",\"topic\":\"Icing\",\"stem\":\"Hoar frost occurs on airframe in clear air when the temperature of airframe is\",\"opts\":[\"below the frost point\",\"frost point\",\"just above the frost point\"],\"ans\":0,\"exp\":\"Hoar frost forms in clear, moist air when the airframe is colder than the frost point: water vapour turns straight to ice (sublimation) on the cold skin, as after a descent from cold altitude into humid air.\",\"seenIn\":[\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-327\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Very heavy precipitation as showers over a short period is called\",\"opts\":[\"Flash floods\",\"Cloud Burst\",\"Orographic Rain\"],\"ans\":1,\"exp\":\"A cloudburst is an extreme shower - a very large amount of rain in a very short time, usually from a vigorous CB over hilly terrain. Flash floods are what often follows it.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Sep 2024 · Regular 03\"],\"undated\":true,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-328\",\"topic\":\"Temperature & radiation\",\"stem\":\"The warmer the earth's surface, the ____ its nocturnal (long-wave) radiation\",\"opts\":[\"More intense\",\"Weaker\",\"Unchanged\"],\"ans\":0,\"exp\":\"Every body radiates according to its temperature, so a warmer surface sends out more long-wave radiation at night. That is why the hottest days can be followed by rapid cooling under a clear sky.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"May 2025 · OLODE 04\"],\"undated\":true,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-329\",\"topic\":\"Temperature & radiation\",\"stem\":\"Solar radiation received per unit area is called\",\"opts\":[\"Insolation\",\"Convection\",\"Conduction\"],\"ans\":0,\"exp\":\"Insolation (incoming solar radiation) is the solar energy received per unit area of the earth's surface. It depends on the sun's elevation, the length of the day and the transparency of the atmosphere.\",\"seenIn\":[\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-330\",\"topic\":\"Icing\",\"stem\":\"As, NS consist of supercooled water drops and ice crystals in varying proportion ______ icing is possible\",\"opts\":[\"Maximum\",\"Light or moderate\",\"Negligible\"],\"ans\":1,\"exp\":\"The correct answer is: Light or moderate.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-331\",\"topic\":\"Air masses & fronts\",\"stem\":\"The transition zone between two different air masses is called a\",\"opts\":[\"Front\",\"Col\",\"Ridge\"],\"ans\":0,\"exp\":\"A front is the boundary zone where two air masses of different temperature and humidity meet - the polar front, for example, separates polar from tropical air. It is named warm or cold by which air is replacing the other.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-332\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"A METAR contains the cloud group FEW025CB. The base of the CB is\",\"opts\":[\"2500 m\",\"3000 ft\",\"2500 ft\"],\"ans\":2,\"exp\":\"Cloud bases in a METAR are given in hundreds of feet above the aerodrome: 025 = 2500 ft. FEW means 1 to 2 oktas, and CB is named because it is significant convective cloud.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-333\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"Supplemental oxygen is required when flying above about\",\"opts\":[\"5000 ft\",\"7000 ft\",\"10 000 ft\"],\"ans\":2,\"exp\":\"Above about 10,000 ft the oxygen partial pressure is low enough that judgement and night vision start to suffer, so supplemental oxygen is needed above that level.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-334\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"In the Jet Standard Atmosphere, the assumed lapse rate is\",\"opts\":[\"2°C/1000 ft\",\"2°C/km\",\"5°C/km\"],\"ans\":0,\"exp\":\"The Jet Standard Atmosphere assumes a lapse rate of 2 °C per 1000 ft with no tropopause, so it keeps cooling at the same rate all the way up. It is used for jet performance data.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-335\",\"topic\":\"Lapse rates & stability\",\"stem\":\"The stratosphere is\",\"opts\":[\"Unstable\",\"Neutral\",\"Stable\"],\"ans\":2,\"exp\":\"Temperature in the lower stratosphere stays constant and then rises with height. That inversion makes the stratosphere very stable, which is why convective cloud stops at the tropopause.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-336\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"QNH 1002.6 hPa is reported as\",\"opts\":[\"Q1002\",\"Q1003\",\"Q1002.6\"],\"ans\":0,\"exp\":\"Unlike temperature, QNH in a METAR is not rounded: it is truncated to the whole hectopascal below. So 1002.6 hPa is reported as Q1002.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-337\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"Average Life of a tropical cyclone in India is\",\"opts\":[\"10 days\",\"6-8 days\",\"3 - 4 Days\"],\"ans\":2,\"exp\":\"A tropical cyclone over the Indian seas typically lives for three to four days, weakening quickly once it crosses the coast and loses its supply of warm, moist air.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-338\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"In TRS the central pressure is about\",\"opts\":[\"1002-1010 hPa\",\"1000 - 900 hpa\",\"1010-1020 hPa\"],\"ans\":1,\"exp\":\"The central pressure of a tropical revolving storm is very low, typically between about 1000 and 900 hPa. The deeper the centre, the stronger the winds around the eye.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-339\",\"topic\":\"Air masses & fronts\",\"stem\":\"When cold air advances and replaces warm air at the surface, the front is a\",\"opts\":[\"Warm front\",\"Cold front\",\"Stationary front\"],\"ans\":1,\"exp\":\"Fronts are named after the air that is doing the replacing. Cold air pushing in under and replacing warm air makes a cold front; warm air replacing cold makes a warm front.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-340\",\"topic\":\"Icing\",\"stem\":\"______ occurs in AS, NS, AC and towering CU or CB between 0°C and −20°C, in warm front below 0°C, especially if the aircraft has rapidly descended from a colder region\",\"opts\":[\"Glazed\",\"Rime\",\"Mixture of Rime and Clear ice\"],\"ans\":2,\"exp\":\"Where a wide range of drop sizes is present - in As, Ns, Ac and towering Cu or Cb between 0 and -20 °C, and below 0 °C at a warm front - small drops freeze as rime and large ones as clear ice, so the two mix.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-341\",\"topic\":\"Jet streams & upper winds\",\"stem\":\"Most CAT occurs on the ______ of a jet stream and in the vicinity of upper level frontal zones where temperature contrasts are strong.\",\"opts\":[\"Fringes\",\"Within the core\",\"Axis\"],\"ans\":0,\"exp\":\"Clear air turbulence near a jet stream is worst on its fringes - especially the cold (polar) side and near upper frontal zones - where the wind shear is strongest. The core itself is often smooth.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-342\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"SIGMET is valid for\",\"opts\":[\"4 hr\",\"8 hr\",\"9 hr\"],\"ans\":0,\"exp\":\"A SIGMET is valid for up to 4 hours. It warns of hazardous en-route weather such as thunderstorms, severe turbulence or icing, and is reissued if the hazard persists.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-343\",\"topic\":\"Thunderstorms\",\"stem\":\"The life of Mesoscale Convective Complex TS is\",\"opts\":[\"6 to 24 hr\",\"3-4 hr\",\"2-3 hr\"],\"ans\":0,\"exp\":\"A mesoscale convective complex is a large, organised cluster of thunderstorms, far longer-lived than a single cell: typically 6 to 24 hours.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-344\",\"topic\":\"Humidity\",\"stem\":\"The difference between TT and TdTd is 3°C. The atmosphere is\",\"opts\":[\"Very Dry\",\"Moist\",\"Saturated\"],\"ans\":1,\"exp\":\"A spread of only 3 °C between the temperature and the dew point means the air is close to saturation - moist. The smaller the spread, the closer you are to cloud, mist or fog.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-345\",\"topic\":\"Temperature & radiation\",\"stem\":\"ALBEDO is the\",\"opts\":[\"Radiation received by the earth\",\"Amount of heat stored\",\"Reflecting power of a surface\"],\"ans\":2,\"exp\":\"Albedo is the reflecting power of a surface - the fraction of incoming solar radiation it reflects. Fresh snow has a high albedo; dark soil and the sea have a low one.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-346\",\"topic\":\"Wind\",\"stem\":\"A change in wind speed from 10 kt to 30 kt and back to 15 kt is a\",\"opts\":[\"Gust\",\"Squall\",\"Gale\"],\"ans\":0,\"exp\":\"A gust is a short, sudden rise in wind speed that dies away again within seconds, like 10 kt to 30 kt and back to 15 kt. A squall lasts minutes.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check could not confirm this answer from the official sources we hold; treat it with care and confirm with your instructor.\"},{\"id\":\"CPLMET-347\",\"topic\":\"Visibility & fog\",\"stem\":\"Radiation fog forms over North India mainly during\",\"opts\":[\"May–June\",\"December–February\",\"October–November\"],\"ans\":1,\"exp\":\"Radiation fog over north India is a winter feature, mainly December to February, when long clear nights, light winds and moisture left by western disturbances combine.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-348\",\"topic\":\"Temperature & radiation\",\"stem\":\"The temperature at FL110 is -5 °C. Using the ISA lapse rate, the temperature at FL50 is\",\"opts\":[\"-17 °C\",\"+7 °C\",\"+1 °C\"],\"ans\":1,\"exp\":\"Descending 6000 ft at 2 °C per 1000 ft warms the air by 12 °C: -5 + 12 = +7 °C. Going down, add; going up, subtract.\",\"seenIn\":[\"May 2024 · OLODE\",\"Nov 2024 · OLODE 08\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-349\",\"topic\":\"Visibility & fog\",\"stem\":\"The pressure system most favourable for fog formation is\",\"opts\":[\"Lows and cols\",\"Highs and troughs\",\"Highs and cols\"],\"ans\":2,\"exp\":\"Fog needs light winds and, for radiation fog, clear skies - the conditions of a high or a col. In a low the winds and cloud usually keep fog away.\",\"seenIn\":[\"May 2024 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-350\",\"topic\":\"Wind\",\"stem\":\"A wind speed of 90 km/h is about\",\"opts\":[\"49 kt\",\"90 kt\",\"167 kt\"],\"ans\":0,\"exp\":\"One knot is 1.852 km/h, so 90 ÷ 1.852 ≈ 48.6 kt. A quick check: knots are roughly half of km/h.\",\"seenIn\":[\"May 2024 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-351\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The average height of the tropopause at latitude 50° is about\",\"opts\":[\"8 km\",\"11 km\",\"14 km\"],\"ans\":1,\"exp\":\"In middle latitudes the tropopause sits at about 11 km, between the equatorial 16-18 km and the polar 8 km - which is also the height the ISA uses.\",\"seenIn\":[\"Aug 2024 · OLODE\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-352\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"Most of the atmospheric water vapour is found\",\"opts\":[\"In the stratosphere\",\"Up to 30 000 ft\",\"In the lower troposphere\"],\"ans\":2,\"exp\":\"Warm air holds far more water vapour than cold air, and the air is warmest near the surface, so the vapour is concentrated in the lower troposphere. The stratosphere is almost dry.\",\"seenIn\":[\"Sep 2024 · Regular 03\",\"May 2025 · OLODE 04\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check found that more than one option can be argued for, as worded in the recall. The key gives the answer most references support.\"},{\"id\":\"CPLMET-353\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"Tropical revolving storms form over\",\"opts\":[\"Warm seas\",\"Large land masses\",\"High mountain ranges\"],\"ans\":0,\"exp\":\"A tropical revolving storm feeds on the latent heat of moist air rising from warm water - it needs a sea surface temperature of about 26-27 °C. Over land its fuel is cut off and it weakens.\",\"seenIn\":[\"Sep 2024 · Regular 03\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-354\",\"topic\":\"Density\",\"stem\":\"Pressure altitude and density altitude are the same when the temperature is\",\"opts\":[\"0 °C\",\"The ISA standard temperature for that level\",\"Below freezing\"],\"ans\":1,\"exp\":\"Density altitude is pressure altitude corrected for non-standard temperature. When the actual temperature equals ISA, there is nothing to correct and the two are the same.\",\"seenIn\":[\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-355\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"In the lower part of the stratosphere the temperature\",\"opts\":[\"Is almost constant\",\"Decreases with altitude\",\"Increases with altitude\"],\"ans\":0,\"exp\":\"In the lower stratosphere the temperature stays almost constant with height (isothermal), before it starts to rise with height higher up because ozone absorbs solar ultraviolet.\",\"seenIn\":[\"Sep 2024 · Regular 03\",\"Jun 2025 · Regular 02\"],\"undated\":true,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-356\",\"topic\":\"Visibility & fog\",\"stem\":\"Radiation fog is essentially a ____ phenomenon\",\"opts\":[\"Nocturnal\",\"Dusk\",\"Daytime\"],\"ans\":0,\"exp\":\"Radiation fog forms when the ground cools by radiation on a clear night, so it is essentially a night-time phenomenon, thickest around dawn and burning off after sunrise.\",\"seenIn\":[\"Sep 2024 · Regular 03\",\"Mar 2025 · Regular 01\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-357\",\"topic\":\"Temperature & radiation\",\"stem\":\"Above 8 km, the lower temperatures are found over the\",\"opts\":[\"Equator\",\"Mid-latitudes\",\"Poles\"],\"ans\":0,\"exp\":\"The correct answer is: Equator.\",\"seenIn\":[\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-358\",\"topic\":\"Air masses & fronts\",\"stem\":\"CB, Roll-type clouds, SC, AC with embedded CB are associated with\",\"opts\":[\"Cold Front\",\"Warm front\",\"Stationary front\"],\"ans\":0,\"exp\":\"A cold front lifts warm air sharply, giving CB, roll clouds and Sc or Ac with embedded CB along a narrow band. Layered cloud from Ci down to Ns belongs to the warm front.\",\"seenIn\":[\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-359\",\"topic\":\"Indian climatology\",\"stem\":\"The monsoon current over the West Coast of India is\",\"opts\":[\"SWly\",\"SEly\",\"NEly\"],\"ans\":0,\"exp\":\"The monsoon current strikes the west coast of India from the south-west - the SW monsoon - bringing heavy orographic rain on the Western Ghats.\",\"seenIn\":[\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-360\",\"topic\":\"Indian climatology\",\"stem\":\"During vigorous monsoon period the pressure gradient over west coast is\",\"opts\":[\"Weak\",\"Steep\",\"Normal\"],\"ans\":1,\"exp\":\"In a vigorous monsoon the pressure gradient over the west coast steepens, strengthening the south-westerly current and the rain along the coast.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-361\",\"topic\":\"Thunderstorms\",\"stem\":\"Andhi (blinding storms) occur generally over\",\"opts\":[\"S India\",\"N India\",\"NE India\"],\"ans\":1,\"exp\":\"Andhis are the blinding dust storms of north India in the hot weather season, raised by the strong gusts of dry thunderstorms.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"May 2025 · OLODE 04\",\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-362\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"For detecting precipitation a Radar wavelength in the range ______ is suitable\",\"opts\":[\"30 to 200 mm\",\"400–500 mm\",\"600–700 mm\"],\"ans\":0,\"exp\":\"Weather radars that detect precipitation work at wavelengths of about 30 to 200 mm (the X, C and S bands): long enough to pass through cloud, short enough to be reflected by raindrops.\",\"seenIn\":[\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-363\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"A tropical Cyclone moves ______.. in a day\",\"opts\":[\"300 - 500 km\",\"500-700 km\",\"700-900 km\"],\"ans\":0,\"exp\":\"A tropical cyclone typically moves about 300-500 km in a day - roughly 12-20 km/h - so it gives a day or two of warning before landfall.\",\"seenIn\":[\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-364\",\"topic\":\"Visibility & fog\",\"stem\":\"The instrument used to measure visibility is the\",\"opts\":[\"Visiometer\",\"Transmissometer\",\"Ceilometer\"],\"ans\":1,\"exp\":\"Visibility at aerodromes is measured with a transmissometer, which measures how much of a light beam survives a known path length. A ceilometer measures cloud base.\",\"seenIn\":[\"Nov 2024 · OLODE 08\",\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-365\",\"topic\":\"Indian climatology\",\"stem\":\"A WD originate over\",\"opts\":[\"Baluchistan\",\"Caspian sea\",\"Mediterranean, Caspian and Black Seas\"],\"ans\":2,\"exp\":\"Western disturbances are born as depressions over the Mediterranean, Caspian and Black Sea region and travel east to north India in the westerlies, mainly in winter.\",\"seenIn\":[\"Nov 2024 · OLODE 08\",\"May 2025 · OLODE 04\"],\"undated\":true,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-366\",\"topic\":\"Temperature & radiation\",\"stem\":\"Flying at FL100 in air 10 °C warmer than ISA, the outside air temperature is about\",\"opts\":[\"-5 °C\",\"+5 °C\",\"+25 °C\"],\"ans\":1,\"exp\":\"ISA at FL100 is 15 - 20 = -5 °C. Add the 10 °C deviation: -5 + 10 = +5 °C.\",\"seenIn\":[\"Nov 2024 · OLODE 08\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-367\",\"topic\":\"Wind\",\"stem\":\"Surge is also\",\"opts\":[\"Velocity Divergence\",\"Velocity Convergence\",\"Like ITCZ\"],\"ans\":1,\"exp\":\"A surge is a strengthening of the wind within the same air mass, and the faster air running into the slower air ahead produces velocity convergence - which lifts the air and enhances rain.\",\"seenIn\":[\"Nov 2024 · OLODE 08\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-368\",\"topic\":\"Air masses & fronts\",\"stem\":\"Widespread, continuous precipitation is typical\",\"opts\":[\"Ahead of a warm front\",\"Behind a cold front\",\"In the centre of a high\"],\"ans\":0,\"exp\":\"At a warm front the warm air rises gently over the cold air across a wide area, producing layered cloud and steady rain over a broad belt ahead of the surface front. A cold front gives a narrow band of showers.\",\"seenIn\":[\"Nov 2024 · OLODE 08\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-369\",\"topic\":\"Lapse rates & stability\",\"stem\":\"SALR approaches DALR\",\"opts\":[\"At -15 °C\",\"At -40 °C\",\"At +15 °C\"],\"ans\":1,\"exp\":\"Saturated air cools more slowly than dry air because condensation releases latent heat. At very low temperatures the air holds almost no water vapour, so there is little heat to release and the SALR approaches the DALR - at about -40 °C.\",\"seenIn\":[\"Nov 2024 · OLODE 08\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-370\",\"topic\":\"Local winds\",\"stem\":\"Anabatic wind occurs\",\"opts\":[\"At night\",\"At any time\",\"During the day\"],\"ans\":2,\"exp\":\"An anabatic wind is warm air flowing up a slope heated by the sun, so it blows by day. Its night-time opposite, flowing down the slope, is the katabatic wind.\",\"seenIn\":[\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-371\",\"topic\":\"Indian climatology\",\"stem\":\"During Summer season, the WDs cause TS activity over Punjab & Rajasthan and track of WD is\",\"opts\":[\"No WD\",\"NE Part\",\"Northern most part of country\"],\"ans\":2,\"exp\":\"In summer, western disturbances pass across the northernmost part of India and trigger thunderstorms and dust storms over Punjab and Rajasthan.\",\"seenIn\":[\"2022 · Regular 03\",\"Dec 2024 · Regular 04\",\"Feb 2025 · OLODE 02\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check could not confirm this answer from the official sources we hold; treat it with care and confirm with your instructor.\"},{\"id\":\"CPLMET-372\",\"topic\":\"Air masses & fronts\",\"stem\":\"Extra Tropical Storms originate in\",\"opts\":[\"Equatorial Front\",\"Tropical Front\",\"Polar Front\"],\"ans\":2,\"exp\":\"Extra-tropical depressions form on the polar front, where cold polar air meets warm tropical air in the middle latitudes.\",\"seenIn\":[\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-373\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"CAVOK is issued when: (i) Vis 10 km or more; (ii) No cloud below 1500m or below highest MSA; (iii) No CB.\",\"opts\":[\"Any one condition\",\"Any two conditions\",\"All the three conditions\"],\"ans\":2,\"exp\":\"CAVOK needs all three at once: visibility 10 km or more, no cloud of operational significance (below 1500 m or the highest MSA, whichever is higher) and no CB or TCU, and no significant weather.\",\"seenIn\":[\"Dec 2024 · Regular 04\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-374\",\"topic\":\"Pressure & altimetry\",\"stem\":\"After landing (QNH 993 hPa) the altimeter is still set to 1013.2 hPa and reads 1200 ft. The aerodrome elevation is about\",\"opts\":[\"660 ft\",\"1200 ft\",\"2280 ft\"],\"ans\":0,\"exp\":\"Setting 1013 instead of 993 is 20 hPa too high, and at about 27 ft per hPa the altimeter over-reads by about 540 ft. So the elevation is about 1200 - 540 = 660 ft.\",\"seenIn\":[\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-375\",\"topic\":\"Pressure & altimetry\",\"stem\":\"An altimeter set to 1013 hPa reads 3600 ft. Reset to the local QNH of 991 hPa, it would read about\",\"opts\":[\"2922 ft\",\"3006 ft\",\"4194 ft\"],\"ans\":1,\"exp\":\"Lowering the sub-scale by 22 hPa lowers the reading by about 22 × 27 ≈ 594 ft: 3600 - 594 ≈ 3006 ft. Lower setting, lower reading.\",\"seenIn\":[\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-376\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"Nitrogen makes up about ______ of the atmosphere by volume\",\"opts\":[\"78 %\",\"72 %\",\"91 %\"],\"ans\":0,\"exp\":\"Dry air is about 78 % nitrogen, 21 % oxygen and 0.93 % argon, with a tiny amount of carbon dioxide and trace gases.\",\"seenIn\":[\"Dec 2024 · Regular 04\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-377\",\"topic\":\"Wind\",\"stem\":\"Around a low-pressure area, the surface winds\",\"opts\":[\"Converge\",\"Diverge\",\"Blow straight\"],\"ans\":0,\"exp\":\"Friction slows the surface wind so Coriolis turns it less, and it blows across the isobars in towards the low. The air converges at the centre and rises - which is why lows bring cloud and rain.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-378\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Flying Delhi→Calcutta at a constant indicated altitude and drifting to starboard, the true altitude compared with the indicated altitude will be\",\"opts\":[\"Lower\",\"Same\",\"Higher\"],\"ans\":0,\"exp\":\"The correct answer is: Lower.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Feb 2025 · OLODE 02\",\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-379\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Atmospheric pressure is measured with a\",\"opts\":[\"Barometer\",\"Anemograph\",\"Ceilometer\"],\"ans\":0,\"exp\":\"A barometer measures pressure (a barograph records it continuously). An anemograph records wind and a ceilometer measures cloud base.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-380\",\"topic\":\"Air masses & fronts\",\"stem\":\"The well developed extra tropical cyclonic storm is composed of two main frontal systems and an occluded front, which varies in extent\",\"opts\":[\"A stationary Front followed by a warm front\",\"A low with a warm front radiating out Southwards followed by a cold front .\",\"A warm front and an occluded front\"],\"ans\":1,\"exp\":\"A mature extra-tropical depression is a low with a warm front running out from it, followed by a cold front, the two joining in an occlusion near the centre as the cold front catches up.\",\"seenIn\":[\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-381\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"SIG Weather Charts are issued ______ times a day\",\"opts\":[\"Two\",\"Three\",\"Four\"],\"ans\":2,\"exp\":\"Significant weather charts are prepared four times a day, for fixed validity times, so a pilot can always pick the chart nearest the time of the flight.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-382\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The atmosphere is heated mainly by\",\"opts\":[\"Solar radiation directly\",\"Heat from the earth's surface\",\"Radiation from space\"],\"ans\":1,\"exp\":\"Air is almost transparent to incoming sunlight. The sun heats the ground, and the ground then heats the air in contact with it by conduction, convection and its own long-wave radiation - so the atmosphere is heated from below.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-383\",\"topic\":\"Jet streams & upper winds\",\"stem\":\"The TJ is located over Indian, approximately at a height of\",\"opts\":[\"15-16 km\",\"12-13 km\",\"11-12 km\"],\"ans\":0,\"exp\":\"The tropical easterly jet sits over India in the summer monsoon at about 15-16 km, close to the high tropical tropopause - well above the westerly jets of winter.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-384\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"CO₂ and water vapour keep the atmosphere\",\"opts\":[\"Warm\",\"Cold\",\"No effect\"],\"ans\":0,\"exp\":\"Carbon dioxide and water vapour let sunlight through but absorb the long-wave radiation the earth sends back and re-radiate part of it downwards - the greenhouse effect that keeps the lower atmosphere warm.\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-385\",\"topic\":\"Wind\",\"stem\":\"In the NH the thermal wind blows parallel to the ____ with the lower values (cold) on its left\",\"opts\":[\"Isobars\",\"Isotherms\",\"Isallobars\"],\"ans\":1,\"exp\":\"The thermal wind is the change of wind with height caused by the horizontal temperature difference, and it blows along the isotherms with the colder air on its left in the northern hemisphere.\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-386\",\"topic\":\"Wind\",\"stem\":\"The winds in the upper troposphere in the equatorial regions are\",\"opts\":[\"Westerlies\",\"Easterlies\",\"Northerlies\"],\"ans\":1,\"exp\":\"The correct answer is: Easterlies.\",\"seenIn\":[\"Apr 2025 · OLODE 03\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-387\",\"topic\":\"Pressure & altimetry\",\"stem\":\"QNH is 1009 hPa but the altimeter sub-scale is set to 1013 hPa. Compared with the true altitude, the altimeter reads\",\"opts\":[\"Higher\",\"Lower\",\"The same\"],\"ans\":0,\"exp\":\"The sub-scale is 4 hPa higher than QNH, and each hPa of excess setting adds about 27 ft to the reading, so the altimeter over-reads by roughly 110 ft - the aircraft is lower than the altimeter says.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-388\",\"topic\":\"Wind\",\"stem\":\"Lines joining places of equal wind speed are called\",\"opts\":[\"Isotachs\",\"Isotherms\",\"Isallobars\"],\"ans\":0,\"exp\":\"Isotachs join points of equal wind speed and are drawn on upper-air charts to show where the jet streams are. Isotherms join equal temperature and isallobars equal pressure tendency.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-389\",\"topic\":\"Visibility & fog\",\"stem\":\"If the wind over a radiation fog strengthens (for example from 5 kt to 13 kt), the fog is most likely to\",\"opts\":[\"Lift to form low stratus\",\"Become thicker at the surface\",\"Turn into advection fog\"],\"ans\":0,\"exp\":\"Radiation fog needs a light wind. A stronger wind mixes the cold surface layer with warmer air above, so the fog lifts off the ground and becomes a sheet of low stratus rather than simply clearing.\",\"seenIn\":[\"2022 · Regular 03\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-390\",\"topic\":\"Wind\",\"stem\":\"A marked low-level inversion just above the aerodrome warns a departing pilot to expect\",\"opts\":[\"Wind shear while climbing through it\",\"Severe icing\",\"Heavy precipitation\"],\"ans\":0,\"exp\":\"Under a night inversion the surface wind is light while the wind above is much stronger and from a different direction, so an aircraft climbing through the inversion meets a sudden change of wind - wind shear.\",\"seenIn\":[\"Mar 2025 · Regular 01\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-391\",\"topic\":\"Lapse rates & stability\",\"stem\":\"The surface temperature is 15 °C and the temperature at 1000 m is 13 °C. The air is\",\"opts\":[\"Absolutely stable\",\"Absolutely unstable\",\"Conditionally unstable\"],\"ans\":0,\"exp\":\"The temperature falls only 2 °C in 1000 m, an ELR of 2 °C per km. That is less than even the SALR (about 6 °C per km), so a rising parcel, dry or saturated, is always colder than its surroundings - absolutely stable.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-392\",\"topic\":\"Pressure & altimetry\",\"stem\":\"In the ISA, the 250 hPa level is at approximately\",\"opts\":[\"FL340\",\"FL300\",\"FL390\"],\"ans\":0,\"exp\":\"Standard pressure levels: 500 hPa is about FL180, 300 hPa about FL300, 250 hPa about FL340 and 200 hPa about FL390.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-393\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"In a METAR, the wind group 00000KT means\",\"opts\":[\"Calm - no wind\",\"Wind variable in direction\",\"Wind not measured\"],\"ans\":0,\"exp\":\"When there is no wind the group is coded 00000KT. A wind whose direction cannot be defined is coded VRB in place of the direction.\",\"seenIn\":[\"2022 · Regular 03\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-394\",\"topic\":\"Wind\",\"stem\":\"The Intertropical Convergence Zone (ITCZ) is where\",\"opts\":[\"The north-east and south-east trade winds converge\",\"The polar easterlies meet the westerlies\",\"The subtropical highs are centred\"],\"ans\":0,\"exp\":\"The ITCZ lies between the air masses either side of the heat equator. There the NE trades of the northern hemisphere meet the SE trades of the southern hemisphere, and the converging air rises in towering cloud.\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-395\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Cloud is dissipated mainly by\",\"opts\":[\"Subsidence\",\"Convection\",\"Orographic lifting\"],\"ans\":0,\"exp\":\"Descending air is compressed and warms adiabatically, so its relative humidity falls and the cloud droplets evaporate. Convection and orographic lifting do the opposite - they cool the air and build cloud.\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-396\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The troposphere contains about ______ of the mass of the atmosphere\",\"opts\":[\"75 %\",\"25 %\",\"50 %\"],\"ans\":0,\"exp\":\"Air is compressed by the weight above it, so it is densest near the surface: about three-quarters of the atmosphere by mass, and nearly all its water vapour, lies in the troposphere.\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-397\",\"topic\":\"Visibility & fog\",\"stem\":\"Early-morning radiation fog is most likely when, the evening before,\",\"opts\":[\"The temperature and dew point are close together\",\"The air is very dry\",\"A strong wind is blowing\"],\"ans\":0,\"exp\":\"Fog forms when the air cools to its dew point. If the evening spread between temperature and dew point is already small, a night of clear-sky cooling is enough to close it by dawn.\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-398\",\"topic\":\"Air masses & fronts\",\"stem\":\"An air mass is\",\"opts\":[\"A large body of air whose temperature and humidity are nearly uniform horizontally\",\"A narrow zone separating warm and cold air\",\"A column of rising air in a thunderstorm\"],\"ans\":0,\"exp\":\"An air mass takes on the temperature and moisture of the surface it lingers over, and stays nearly uniform across hundreds of kilometres. The boundary between two air masses is a front.\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-399\",\"topic\":\"Wind\",\"stem\":\"For the same pressure gradient, the gradient wind around a low compared with the geostrophic wind is\",\"opts\":[\"Weaker\",\"Stronger\",\"The same\"],\"ans\":0,\"exp\":\"Around a low, part of the inward pressure force is used to curve the flow, so less Coriolis force - and therefore less speed - is needed to balance it: the gradient wind is weaker than geostrophic. Around a high it is the reverse.\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-400\",\"topic\":\"Temperature & radiation\",\"stem\":\"Intense radiation is emitted by\",\"opts\":[\"Hot bodies\",\"Cold bodies\",\"Only stars\"],\"ans\":0,\"exp\":\"The hotter a body, the more energy it radiates - the total rises with the fourth power of its absolute temperature - so intense radiation comes from hot bodies such as the sun.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-401\",\"topic\":\"Wind\",\"stem\":\"In the Northern Hemisphere, due to the earth's rotation, winds are deflected to the\",\"opts\":[\"Left\",\"Right\",\"Towards the equator\"],\"ans\":1,\"exp\":\"The earth turning beneath moving air makes the air appear to turn - to the right in the northern hemisphere and to the left in the southern. This apparent force is the Coriolis force.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-402\",\"topic\":\"Jet streams & upper winds\",\"stem\":\"Wind speed along the axis of a jet stream is always\",\"opts\":[\"Same everywhere\",\"Uniform\",\"Not uniform\"],\"ans\":2,\"exp\":\"A jet stream is not a uniform tube of wind. The speed varies along its axis, with stronger segments (jet streaks) separated by weaker stretches.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-403\",\"topic\":\"Visibility & fog\",\"stem\":\"Fog is essentially ____ cloud on the ground\",\"opts\":[\"Stratocumulus\",\"Stratus\",\"Nimbostratus\"],\"ans\":1,\"exp\":\"Fog is simply stratus whose base is on the ground: a layer of tiny water droplets formed by cooling of moist air near the surface.\",\"seenIn\":[\"May 2025 · OLODE 04\",\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-404\",\"topic\":\"Indian climatology\",\"stem\":\"Norwesters originates over\",\"opts\":[\"Chota-Nagpur hills\",\"Deccan Plato\",\"Khasi hills\"],\"ans\":0,\"exp\":\"Norwesters are the violent pre-monsoon thunderstorms of north-east India. They generally form over the Chota Nagpur plateau and move south-east over West Bengal and Bangladesh.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check could not confirm this answer from the official sources we hold; treat it with care and confirm with your instructor.\"},{\"id\":\"CPLMET-405\",\"topic\":\"Icing\",\"stem\":\"Glazed ice is formed by freezing of ______ supercooled water droplets on airframe when aircraft is flying through clouds\",\"opts\":[\"Small\",\"Large\",\"Medium\"],\"ans\":1,\"exp\":\"Large supercooled drops do not freeze at once on impact. They spread back over the surface before freezing, forming a clear, heavy and hard-to-shed glaze. Small drops freeze instantly as rime.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-406\",\"topic\":\"Temperature & radiation\",\"stem\":\"Between MSL and 20 km, the lowest temperature in the ISA is\",\"opts\":[\"−273°C\",\"−44.7°C\",\"−56.5°C\"],\"ans\":2,\"exp\":\"The ISA temperature falls at 2 °C per 1000 ft from +15 °C at sea level to -56.5 °C at the tropopause (11 km), and then stays at -56.5 °C up to 20 km. So -56.5 °C is the lowest ISA temperature below 20 km.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-407\",\"topic\":\"Air masses & fronts\",\"stem\":\"The airmass which originates over equatorial region is\",\"opts\":[\"Warm and dry\",\"Warm and Moist\",\"Cold and dry\"],\"ans\":1,\"exp\":\"Air that forms over the equatorial oceans takes on the heat and moisture of the warm sea surface, so an equatorial air mass is warm and moist.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-408\",\"topic\":\"Pressure & altimetry\",\"stem\":\"In the ISA, the 850 hPa level corresponds to approximately\",\"opts\":[\"7 000 ft\",\"5 000 ft\",\"10 000 ft\"],\"ans\":1,\"exp\":\"Standard pressure levels: 850 hPa is about 5000 ft, 700 hPa about 10,000 ft and 500 hPa about 18,000 ft.\",\"seenIn\":[\"Jun 2025 · Regular 02\",\"Aug 2025 · OLODE 06\"],\"undated\":true,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-409\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Near MSL, an increase of 1000 ft corresponds to a pressure decrease of about\",\"opts\":[\"3 hPa\",\"33 hPa\",\"100 hPa\"],\"ans\":1,\"exp\":\"Near sea level pressure falls by about 1 hPa for every 27-30 ft, so 1000 ft of height is worth about 33 hPa.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-410\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The atmospheric layer characterised by a temperature inversion and great stability is the\",\"opts\":[\"Troposphere\",\"Tropopause\",\"Stratosphere\"],\"ans\":2,\"exp\":\"In the stratosphere the temperature is constant or rises with height (an inversion), so a rising parcel is always colder than its surroundings - the layer is very stable and there is little vertical motion or weather.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-411\",\"topic\":\"Density\",\"stem\":\"Air is less dense in\",\"opts\":[\"High altitudes\",\"Warm air\",\"All of these\"],\"ans\":2,\"exp\":\"Density falls as altitude rises (lower pressure), as the air warms (it expands) and as humidity rises (water vapour is lighter than the nitrogen and oxygen it replaces). All of these give less dense air.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-412\",\"topic\":\"Air masses & fronts\",\"stem\":\"On approach of a Warm Front temperature\",\"opts\":[\"Fall\",\"Rise\",\"Remain same\"],\"ans\":2,\"exp\":\"Ahead of a warm front the cold air stays in place under the sloping frontal surface, so the surface temperature changes little as the front approaches. The marked rise comes after the front has passed, when the warm sector air arrives.\",\"seenIn\":[\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-413\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"cyclonic storms are confined almost entirely to the\",\"opts\":[\"Latitudes near the equator\",\"Tropic latitudes\",\"Polar latitudes\"],\"ans\":1,\"exp\":\"Cyclonic storms need a warm sea surface and enough Coriolis force to start a rotation, so they are confined almost entirely to the tropical latitudes - not right at the equator, where the Coriolis force is too weak.\",\"seenIn\":[\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-414\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"A tropical revolving storm gets its energy mainly from\",\"opts\":[\"Latent heat released as water vapour from the warm ocean condenses\",\"Direct heating of the air by the sun\",\"The very low pressure inside the storm\"],\"ans\":0,\"exp\":\"Air over a warm ocean picks up huge amounts of water vapour. As it rises in the storm the vapour condenses and releases its latent heat, warming the core and driving the circulation. Cut off from the sea over land, the storm weakens.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-415\",\"topic\":\"Visibility & fog\",\"stem\":\"Advection fog lifts to form low stratus when the wind speed is\",\"opts\":[\"Greater than about 15 kt\",\"Less than 5 kt\",\"Calm\"],\"ans\":0,\"exp\":\"Advection fog needs a wind to carry the moist air over the cold surface, but a wind stronger than about 15 kt mixes the layer enough to lift the fog off the surface as a sheet of stratus.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-416\",\"topic\":\"Wind\",\"stem\":\"Wind is caused by\",\"opts\":[\"Differences in pressure\",\"The Coriolis force\",\"Friction with the surface\"],\"ans\":0,\"exp\":\"Air moves from high to low pressure under the pressure gradient force. Coriolis only turns moving air and friction only slows it - neither can start it moving.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-417\",\"topic\":\"Temperature & radiation\",\"stem\":\"The rate at which temperature falls with increase of height is called the\",\"opts\":[\"Lapse rate\",\"Inversion\",\"Isothermal layer\"],\"ans\":0,\"exp\":\"The fall of temperature with height is the lapse rate. A layer where temperature rises with height is an inversion, and one where it stays constant is isothermal.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-418\",\"topic\":\"Lapse rates & stability\",\"stem\":\"The stability of the atmosphere at any time is determined by its\",\"opts\":[\"ELR\",\"DALR\",\"SALR\"],\"ans\":0,\"exp\":\"The DALR and SALR are the rates at which a rising parcel cools, and they barely change. What changes from day to day is the actual temperature structure - the ELR. Comparing it with the parcel rates tells you whether the air is stable or unstable.\",\"seenIn\":[\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-419\",\"topic\":\"Thunderstorms\",\"stem\":\"In a METAR, +TSRA is associated with which cloud?\",\"opts\":[\"CB\",\"NS\",\"AS\"],\"ans\":0,\"exp\":\"TS is a thunderstorm and +RA heavy rain. A thunderstorm comes only from a cumulonimbus, so +TSRA means a CB overhead or nearby giving heavy rain.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-420\",\"topic\":\"Humidity\",\"stem\":\"Relative humidity depends on\",\"opts\":[\"Moisture content and temperature of the air\",\"Temperature of the air only\",\"Moisture content and pressure of the air\"],\"ans\":0,\"exp\":\"Relative humidity compares the water vapour actually present with the most the air could hold at its temperature. Add moisture and it rises; warm the air and it falls, because warm air can hold more.\",\"seenIn\":[\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-421\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Two aircraft at the same indicated altitude (1013.2 hPa set), one over a cold air mass and one over a warm air mass. Which has the greater true altitude?\",\"opts\":[\"The one over the warm air mass\",\"The one over the cold air mass\",\"Both are at the same true altitude\"],\"ans\":0,\"exp\":\"Cold air is dense, so pressure falls quickly with height and the aircraft sits lower than its altimeter says. Over warm air the pressure levels are spread further apart, so the same indicated altitude is genuinely higher. Same reading, two different true altitudes.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-422\",\"topic\":\"Pressure & altimetry\",\"stem\":\"The isobars on a surface weather chart join places of equal\",\"opts\":[\"QFE\",\"QFF\",\"QNH\"],\"ans\":1,\"exp\":\"A surface analysis chart is drawn in QFF - aerodrome pressure reduced to mean sea level using the actual conditions of the day. QNH is the equivalent reduced using ISA, which is why the two differ.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-423\",\"topic\":\"Optical phenomena\",\"stem\":\"A corona is associated with which cloud?\",\"opts\":[\"Altostratus (AS)\",\"Altocumulus (AC)\",\"Cirrocumulus (CC)\"],\"ans\":1,\"exp\":\"A corona is a small coloured ring close around the sun or moon, made by diffraction through WATER droplets - so the cloud is altocumulus or altostratus and carries an icing risk. A halo is the large ring made by ice crystals.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check found that more than one option can be argued for, as worded in the recall. The key gives the answer most references support.\"},{\"id\":\"CPLMET-424\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Surface temperature is 16 °C and the dew point is 6 °C. With a DALR of 3 °C/1000 ft and a dew-point lapse rate of 0.3 °C/1000 ft, the cloud base is about\",\"opts\":[\"4000 ft\",\"3000 ft\",\"5000 ft\"],\"ans\":0,\"exp\":\"The temperature and the dew point close on each other at 3 - 0.3 = 2.7 °C per 1000 ft. The 10 °C spread therefore closes after about 10 ÷ 2.7 = 3.7, or roughly 3,700 ft - nearest to 4000 ft. That level is the lifting condensation level, which is the cloud base.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-425\",\"topic\":\"Air masses & fronts\",\"stem\":\"Ahead of an approaching warm front in the northern hemisphere, the surface wind\",\"opts\":[\"Backs and strengthens\",\"Veers and strengthens\",\"Backs and weakens\"],\"ans\":0,\"exp\":\"As the front approaches, pressure falls and the wind backs - turns anticlockwise - and strengthens. It veers AFTER the front has passed. Ahead: backs; after: veers.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-426\",\"topic\":\"Wind\",\"stem\":\"On a clear night, a marked low-level inversion produces\",\"opts\":[\"Wind shear at the top of the inversion\",\"A steady wind at all levels\",\"Strong gusts at the surface\"],\"ans\":0,\"exp\":\"Surface cooling stops the vertical mixing, so below the inversion the wind is light and from a different direction, while above it the wind is much stronger. An aircraft climbing or descending through that boundary meets a sudden change of wind - wind shear.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-427\",\"topic\":\"Pressure & altimetry\",\"stem\":\"QNH is 1008 hPa and the aerodrome elevation is 1200 ft. On the ground with 1013 hPa set, the altimeter reads about\",\"opts\":[\"1335 ft\",\"1200 ft\",\"1065 ft\"],\"ans\":0,\"exp\":\"The sub-scale is 5 hPa above QNH, and near the ground 1 hPa is worth about 27 ft, so the altimeter over-reads by roughly 135 ft: 1200 + 135 = about 1335 ft. Setting a higher sub-scale always gives a higher reading.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-428\",\"topic\":\"Pressure & altimetry\",\"stem\":\"QNH is 1000 hPa and QFE is 980 hPa. The aerodrome elevation is about\",\"opts\":[\"540 ft\",\"600 ft\",\"160 ft\"],\"ans\":0,\"exp\":\"QNH minus QFE is the pressure difference between mean sea level and the aerodrome: 20 hPa. At about 27 ft per hPa that is 20 x 27 = 540 ft of elevation.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check found that more than one option can be argued for, as worded in the recall. The key gives the answer most references support.\"},{\"id\":\"CPLMET-429\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Compared with altostratus, nimbostratus\",\"opts\":[\"Has a lower base and gives continuous rain or snow\",\"Has a higher base and gives no precipitation\",\"Is a high cloud made of ice crystals\"],\"ans\":0,\"exp\":\"Nimbostratus is the dark grey rain cloud - thick enough to blot out the sun, extending through the medium and low levels, giving continuous rain or snow. Altostratus is the thinner, lighter grey sheet above it, through which the sun shows as if through ground glass.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-430\",\"topic\":\"Visibility & fog\",\"stem\":\"Visibility falls to between 1000 m and 2000 m because of water droplets suspended in the air. This is reported as\",\"opts\":[\"Fog\",\"Haze\",\"Mist\"],\"ans\":2,\"exp\":\"Mist is a suspension of water droplets giving a visibility of 1000 m or more but not more than 5000 m, with the relative humidity close to 100%. Below 1000 m the same droplets are called fog. Haze is dry - dust and smoke particles, not water.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-431\",\"topic\":\"Indian climatology\",\"stem\":\"In a westward-moving monsoon depression, the heaviest rain is expected in the\",\"opts\":[\"NE quadrant\",\"NW quadrant\",\"SW quadrant\"],\"ans\":2,\"exp\":\"The worst weather of a monsoon depression sits in its SW sector, where the rain is steady and heavy in a belt about 400 km wide; elsewhere it is scanty. Only when the depression re-curves does the rain belt shift to the N-NE sector.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-432\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"Dry bulb and dew point at an aerodrome are -0.5 °C and -9.0 °C. In the METAR they are reported as\",\"opts\":[\"-0.5/-9.0\",\"M0.5/M9.0\",\"M00/M09\"],\"ans\":2,\"exp\":\"METAR carries temperature and dew point as two whole degrees separated by a solidus, with no decimals and no sign symbol - a temperature below zero is prefixed M. A sub-zero value that rounds to zero is written M00, which is how the report shows the air is below freezing.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-433\",\"topic\":\"Wind\",\"stem\":\"Squalls are distinguished from gusts by their\",\"opts\":[\"Longer duration\",\"Shorter duration\",\"Lower wind speeds\"],\"ans\":0,\"exp\":\"The difference is duration. A gust is a rapid fluctuation lasting a few seconds; a squall is a sudden increase of at least 16 kt that reaches 22 kt or more and lasts at least one minute, usually with a temperature drop and precipitation.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-434\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"In a METAR, when the sky is clear and the visibility is 10 km or more, the visibility, cloud and weather groups can be replaced by\",\"opts\":[\"SKC\",\"NOSIG\",\"CAVOK\"],\"ans\":2,\"exp\":\"CAVOK - Ceiling And Visibility OK - replaces the visibility, RVR, weather and cloud groups together. It needs all three conditions at once: visibility 10 km or more, no cloud below 1500 m (or below the highest minimum sector altitude) and no CB, and no significant weather.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-435\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"METAR VIDP 270300Z 30020KT 0500 R28/1200 R10/1100 R27/1000 FG FEW200 10/10 Q1009 BECMG 1500 BR. The visibility reported is\",\"opts\":[\"1200 m\",\"1100 m\",\"500 m\"],\"ans\":2,\"exp\":\"The visibility group is the bare four-figure group that follows the wind: 0500, so 500 metres. The groups beginning R are RVR for particular runways (R28/1200 is runway 28), which is a measured range along the runway, not the aerodrome visibility.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-436\",\"topic\":\"Humidity\",\"stem\":\"The humidity mixing ratio is the ratio of the\",\"opts\":[\"Mass of water vapour to the mass of dry air\",\"Mass of water vapour to the volume of dry air\",\"Volume of water vapour to the volume of dry air\"],\"ans\":0,\"exp\":\"Mixing ratio compares two masses - the mass of water vapour against the mass of the dry air it is mixed with, usually in grams per kilogram. Because it is a ratio of masses it does not change when the parcel expands or is lifted, which is why it is a useful way of tracking moisture.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-437\",\"topic\":\"Pressure & altimetry\",\"stem\":\"A rapid fall of pressure over a station during the last 6 hours is generally associated with\",\"opts\":[\"Clear weather\",\"The approach of a cyclonic storm\",\"The formation of fog\"],\"ans\":1,\"exp\":\"Pressure tendency is a forecasting tool: a steep, sustained fall means a low is deepening or approaching, and the steeper the fall the stronger the system. Lines joining equal pressure change are isallobars, and the region of greatest fall is the isallobaric low.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-438\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"A SPECI is issued when the visibility improves to or deteriorates past\",\"opts\":[\"700 m\",\"1400 m\",\"3000 m\"],\"ans\":2,\"exp\":\"The visibility criteria for a SPECI are the fixed steps 800 m, 1500 m, 3000 m and 5000 m - the values that matter operationally. Of the three offered, only 3000 m is one of them. On an improvement the SPECI is issued after the better conditions have held for 10 minutes.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-439\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"The eye of a very severe cyclonic storm is associated with\",\"opts\":[\"Torrential rain\",\"The strongest winds of the storm\",\"Light wind and fair weather\"],\"ans\":2,\"exp\":\"The eye is a region of subsiding air, so it is nearly calm with little or no cloud. The violence is in the eye wall that surrounds it, where the strongest winds and the heaviest rain are found - which is why an aircraft or ship gets a deceptive lull before the second, opposite-direction onslaught.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-440\",\"topic\":\"Indian climatology\",\"stem\":\"Which of the following does NOT prevail during a break in the monsoon?\",\"opts\":[\"The monsoon trough lies along the foothills of the Himalayas\",\"Low-level easterlies over northern India are absent\",\"A monsoon depression lies over the Odisha coast\"],\"ans\":2,\"exp\":\"In a break the monsoon trough shifts north to the Himalayan foothills, the plains turn dry and the low-level easterly flow over north India dies away. A monsoon depression sitting on the Odisha coast is the opposite - that is an ACTIVE monsoon situation feeding heavy rain into central India.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-441\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Normally, the pressure at a station at 1600 hours local time, compared with 1000 hours local time, is\",\"opts\":[\"Greater\",\"Less\",\"The same\"],\"ans\":1,\"exp\":\"Pressure has a twice-daily (semi-diurnal) swing with maxima near 1000 and 2200 and minima near 0400 and 1600 local time. So 1600 sits at a minimum and 1000 at a maximum, and the afternoon value is the lower of the two. The swing is largest in the tropics.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-442\",\"topic\":\"Indian climatology\",\"stem\":\"Tamil Nadu gets most of its rain during\",\"opts\":[\"January\",\"July\",\"October\"],\"ans\":2,\"exp\":\"Tamil Nadu is on the lee side of the Western Ghats during the south-west monsoon, so July is comparatively dry there. Its rain comes with the north-east (retreating) monsoon, when the flow reverses and picks up moisture crossing the Bay of Bengal - October and November are the wettest months.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-443\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"When moist air blows steadily across a mountain range, the cloud and precipitation are\",\"opts\":[\"Greater on the leeward side\",\"Greatest over the crest\",\"Greater on the windward side\"],\"ans\":2,\"exp\":\"The air is forced to rise on the windward slope, cools at the adiabatic lapse rate, reaches saturation and forms orographic cloud and rain there. Having dropped its moisture it descends the far side and warms, which is why the leeward side is comparatively dry - the rain shadow.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-444\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The height of the tropopause varies with latitude. It\",\"opts\":[\"Increases with increasing latitude\",\"Decreases with increasing latitude\",\"Stays the same at all latitudes\"],\"ans\":1,\"exp\":\"A warm surface gives a deep troposphere. Over the hot equator the tropopause is pushed up to about 16-18 km; over the cold poles it sits at only about 8-10 km. So as you go polewards - increasing latitude - the tropopause gets lower.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-445\",\"topic\":\"Temperature & radiation\",\"stem\":\"During a clear, calm night the surface temperature will ______, the relative humidity will ______ and the dew point will ______\",\"opts\":[\"Fall, rise, rise\",\"Fall, rise, remain about the same\",\"Fall, fall, remain about the same\"],\"ans\":1,\"exp\":\"The ground loses heat by radiation, so the temperature falls. No moisture is added or removed, so the dew point - which depends on the moisture content - stays about the same. As the air temperature falls towards that unchanged dew point the relative humidity rises, which is why radiation fog forms in the early morning.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-446\",\"topic\":\"Pressure & altimetry\",\"stem\":\"In the ISA, the 300 hPa level is at approximately\",\"opts\":[\"10 000 ft\",\"18 000 ft\",\"30 000 ft\"],\"ans\":2,\"exp\":\"Working the standard atmosphere down from 1013.25 hPa, the 300 hPa surface comes out at about 30 065 ft, so 30 000 ft is the figure to carry. It is a useful one to know because the 300 hPa chart is the standard upper-wind chart for jet cruising levels.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-447\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Near the earth s surface, a climb of 1000 ft corresponds to a pressure decrease of about\",\"opts\":[\"3 hPa\",\"33 hPa\",\"100 hPa\"],\"ans\":1,\"exp\":\"Near sea level 1 hPa is worth about 30 ft, so 1000 ft costs roughly 1000/30 = 33 hPa. The relationship is not constant - higher up the air is less dense and 1 hPa covers far more height - which is why altimetry corrections are always quoted for low level.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-448\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Which of these instruments measures pressure?\",\"opts\":[\"Anemograph\",\"Barometer\",\"Hygrograph\"],\"ans\":1,\"exp\":\"A barometer measures atmospheric pressure (the recording form is a barograph). An anemograph records wind speed and direction, and a hygrograph records humidity - the prefixes give them away: anemo- wind, hygro- moisture, baro- weight or pressure.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-449\",\"topic\":\"Air masses & fronts\",\"stem\":\"When a cold air mass advances and replaces a warm air mass, the boundary is called a\",\"opts\":[\"Cold front\",\"Warm front\",\"Polar front\"],\"ans\":0,\"exp\":\"A front is named after the air mass that is doing the advancing. Cold air pushing in under warm air and displacing it is a cold front; warm air riding up over retreating cold air is a warm front. The polar front is the name of a particular boundary - between polar and tropical air - not of this motion.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-450\",\"topic\":\"Thunderstorms\",\"stem\":\"The most severe weather - destructive winds, large hail and tornadoes - is generally associated with\",\"opts\":[\"Slow-moving warm fronts\",\"Squall lines\",\"Fast-moving occluded fronts\"],\"ans\":1,\"exp\":\"When thunderstorms organise into a line along or ahead of a cold front they form a squall line, and these are far more violent than isolated air-mass storms: the cells feed each other, the gust front is continuous, and this is the structure that produces destructive surface winds, giant hail and tornadoes.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-451\",\"topic\":\"Air masses & fronts\",\"stem\":\"An air mass that is being cooled from below becomes\",\"opts\":[\"More stable, favouring fog and stratus\",\"Less stable, favouring cumulus and showers\",\"Unaffected in its stability\"],\"ans\":0,\"exp\":\"Cooling the bottom of an air mass reduces the temperature difference between the surface and the air above it, so the lapse rate becomes smaller and the air more stable. A stable, moist air mass cannot convect - so its moisture shows up as fog, mist or a sheet of stratus rather than as cumulus.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-452\",\"topic\":\"Humidity\",\"stem\":\"At the same sub-zero temperature, the saturation vapour pressure over water compared with that over ice is\",\"opts\":[\"Less\",\"Greater\",\"The same\"],\"ans\":1,\"exp\":\"It takes less energy for a molecule to escape liquid water than to escape the ice lattice, so at the same sub-zero temperature the saturation vapour pressure over water is the higher of the two. That difference drives the Bergeron process: in a cloud holding both, the ice crystals grow at the expense of the supercooled droplets.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-453\",\"topic\":\"Jet streams & upper winds\",\"stem\":\"The tropical easterly jet stream over India is\",\"opts\":[\"A winter feature lying over the Himalayas\",\"A monsoon feature with its axis near 13 °N\",\"Present throughout the year over the Bay of Bengal\"],\"ans\":1,\"exp\":\"The tropical easterly jet appears with the summer monsoon and is weak or absent in winter. Its axis runs near 13 °N - about the latitude of Chennai - at roughly 15 km, averaging 60-80 kt. It is found only over Asia and Africa, and the subtropical westerly jet takes over from it in winter.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-454\",\"topic\":\"Wind\",\"stem\":\"What prevents air from flowing directly from a high pressure area to a low pressure area?\",\"opts\":[\"Coriolis force\",\"Surface friction\",\"Pressure gradient force\"],\"ans\":0,\"exp\":\"The pressure gradient force is what starts the air moving from high to low. As soon as it moves, the Coriolis force deflects it - to the right in the northern hemisphere - until the flow ends up running along the isobars rather than across them. Friction only modifies this near the surface.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-455\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"In the ISA, the temperature at 17 km is\",\"opts\":[\"-56.5 °C\",\"-35.5 °C\",\"+15 °C\"],\"ans\":0,\"exp\":\"In the ICAO Standard Atmosphere the temperature falls to -56.5 °C at the 11 km tropopause and is then held CONSTANT at that value up to 20 km. 17 km lies inside that isothermal layer, so the temperature is still -56.5 °C.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-456\",\"topic\":\"Pressure & altimetry\",\"stem\":\"A region lying between two lows and two highs is called a\",\"opts\":[\"Depression\",\"Secondary low\",\"Col\"],\"ans\":2,\"exp\":\"A col is the slack saddle in the middle of that arrangement. The pressure gradient there is weak, so the winds are light and variable - which makes a col a favourite place for fog to form, and in summer for thunderstorms.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-457\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Semi-diurnal pressure changes are most pronounced in the\",\"opts\":[\"Polar regions\",\"Middle latitudes\",\"Tropics\"],\"ans\":2,\"exp\":\"The twice-daily pressure wave is largest near the equator, where it reaches about 3 hPa, and shrinks polewards where travelling weather systems swamp it. That is why the tropical maxima near 1000 and 2200, and minima near 0400 and 1600 local time, stand out so clearly.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-458\",\"topic\":\"Humidity\",\"stem\":\"When the air is saturated, the spread between the free air temperature and the dew point is\",\"opts\":[\"Large\",\"Least\",\"Unchanged from its usual value\"],\"ans\":1,\"exp\":\"The spread is the gap between the air temperature and the dew point, and it measures how close the air is to saturation. At saturation the air has been cooled right down to its dew point, so the two are equal and the spread is zero - the least it can be.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-459\",\"topic\":\"Lapse rates & stability\",\"stem\":\"An inversion is a ______ lapse rate\",\"opts\":[\"Positive\",\"Negative\",\"Neutral\"],\"ans\":1,\"exp\":\"A positive lapse rate is the normal case, temperature falling with height; zero is isothermal. When temperature RISES with height the lapse rate is negative, and that is an inversion. Inversions are very stable - they cap convection and trap haze, smoke and moisture below them.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-460\",\"topic\":\"Air masses & fronts\",\"stem\":\"An air mass that formed over a land area in a polar region is\",\"opts\":[\"Warm and dry\",\"Warm and moist\",\"Cold and dry\"],\"ans\":2,\"exp\":\"An air mass takes its character from its source region. Polar means cold, continental means dry, so continental polar air is cold and dry. Maritime polar would be cold and moist, and a tropical source gives the warm versions of each.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-461\",\"topic\":\"Jet streams & upper winds\",\"stem\":\"The tropical easterly jet (TJ) is\",\"opts\":[\"Westerly\",\"Easterly\",\"Southerly\"],\"ans\":1,\"exp\":\"The name carries the answer: the tropical easterly jet blows from the east. It is a monsoon feature with its axis near 13 °N at about 15 km over India, and in winter it is replaced by the subtropical WESTERLY jet.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-462\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"Tropical revolving storms form over the Indian seas mainly between latitudes\",\"opts\":[\"The equator and 5 °\",\"5 ° and 15 °\",\"Beyond 30 °\"],\"ans\":1,\"exp\":\"A tropical revolving storm needs the Coriolis force to start it turning, and Coriolis is zero at the equator, so nothing forms within about 5 ° of it. It also needs a sea surface above about 26 °C, which rules out the higher latitudes. The productive belt is roughly 5 ° to 15 ° from the equator.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-463\",\"topic\":\"Indian climatology\",\"stem\":\"The pressure gradient over the west coast of India is steepest during the\",\"opts\":[\"Pre-monsoon\",\"Winter\",\"SW monsoon\"],\"ans\":2,\"exp\":\"During the south-west monsoon the seasonal low over north-west India and the high over the southern Indian Ocean set up a strong gradient across the coast, and that is what drives the steady, strong monsoon westerlies onto it. In winter the gradient over that coast is weak.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-464\",\"topic\":\"General circulation\",\"stem\":\"Air moving polewards piles up in the subtropics and forms a surface high pressure belt called the\",\"opts\":[\"Subtropical high\",\"Polar high\",\"Equatorial high\"],\"ans\":0,\"exp\":\"Air rising at the equator moves polewards aloft, cools, converges and subsides near 30 ° latitude. That subsidence builds the subtropical high pressure belt at the surface - the horse latitudes - and from it the trade winds flow back towards the equator while the westerlies flow polewards.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-465\",\"topic\":\"Temperature & radiation\",\"stem\":\"The temperature at FL110 is -12 °C. Using the ISA lapse rate, the temperature at FL140 will be\",\"opts\":[\"-6 °C\",\"-18 °C\",\"-9 °C\"],\"ans\":1,\"exp\":\"The ISA lapse rate is 2 °C per 1000 ft. FL140 is 3000 ft higher than FL110, so the temperature falls by 3 x 2 = 6 °C, and -12 - 6 = -18 °C. Climbing always makes it colder, which rules out -6 and -9 before any arithmetic.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-466\",\"topic\":\"Visibility & fog\",\"stem\":\"Radiation fog forms because of\",\"opts\":[\"Advection of cold air over a warm surface\",\"Heating of the earth during the day\",\"Radiational cooling of the earth at night\"],\"ans\":2,\"exp\":\"On a clear night the ground radiates its heat away to space, cools, and chills the shallow layer of air touching it until that air reaches its dew point. It is a night-time land phenomenon, which is exactly why it burns off through the morning as the sun warms the surface again.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-467\",\"topic\":\"Density\",\"stem\":\"In the ISA, the air density at mean sea level is\",\"opts\":[\"1.225 kg/m3\",\"1.013 kg/m3\",\"0.905 kg/m3\"],\"ans\":0,\"exp\":\"The ICAO Standard Atmosphere fixes sea level at 15 °C, 1013.25 hPa and a density of 1.225 kg/m3. Density falls off with height much as pressure does, roughly halving by 22 000 ft, and it is density rather than pressure alone that decides engine power, lift and true airspeed.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"topic\",\"optionsWritten\":false},{\"id\":\"CPLMET-468\",\"topic\":\"Clouds & precipitation\",\"stem\":\"The high-level clouds are\",\"opts\":[\"Ci, Cs and Cc\",\"As, Ac and Ns\",\"St, Sc and Cu\"],\"ans\":0,\"exp\":\"The correct answer is: Ci, Cs and Cc.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"topic\",\"optionsWritten\":false},{\"id\":\"CPLMET-469\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"The temperature of the tropopause over the equator is about\",\"opts\":[\"-40 °C\",\"-56.5 °C\",\"-75 to -80 °C\"],\"ans\":2,\"exp\":\"The equatorial troposphere is very deep, so air goes on cooling all the way to 16-18 km and arrives far colder than anywhere else, about -75 to -80 °C. The -56.5 °C figure is the ISA, mid-latitude tropopause. This is why the coldest air at cruising levels is found over the tropics, not over the poles.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"topic\",\"optionsWritten\":false},{\"id\":\"CPLMET-470\",\"topic\":\"Humidity\",\"stem\":\"The difference between the air temperature and the dew point at a station is 3 °C. The air is\",\"opts\":[\"Very dry\",\"Close to saturation\",\"Exactly saturated\"],\"ans\":1,\"exp\":\"The spread between temperature and dew point measures how far the air is from saturation. A spread of only 3 °C means very little further cooling is needed before condensation starts, so the air is moist and close to saturation. A spread of zero would mean it is saturated already.\",\"seenIn\":[],\"undated\":true,\"times\":0,\"years\":[],\"kind\":\"topic\",\"optionsWritten\":false},{\"id\":\"CPLMET-471\",\"topic\":\"The atmosphere & ISA\",\"stem\":\"About 90% of the water vapour in the atmosphere is contained in the\",\"opts\":[\"Troposphere\",\"Stratosphere\",\"Mesosphere\"],\"ans\":0,\"exp\":\"Water vapour is evaporated from the surface and carried up by convection, and the air can hold less of it the colder it gets. So it is concentrated in the lowest layer - above about 30 000 ft there is very little left. That is why effectively all cloud and weather is a tropospheric business.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-472\",\"topic\":\"Tropical systems & cyclones\",\"stem\":\"A tropical revolving storm draws its energy mainly from\",\"opts\":[\"Latent heat released as water vapour condenses\",\"The equatorial jet stream\",\"Friction between the sea and the air\"],\"ans\":0,\"exp\":\"The storm is a heat engine. Warm sea above about 26 °C evaporates huge quantities of water; as that vapour is carried up and condenses it releases latent heat, which warms the core, lowers the surface pressure further and drives more inflow. Cut it off from the warm sea - by landfall - and it dies quickly.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-473\",\"topic\":\"Pressure & altimetry\",\"stem\":\"Thermal lows form over\",\"opts\":[\"Land areas strongly heated in summer\",\"Cold ocean currents\",\"High ground in winter\"],\"ans\":0,\"exp\":\"A thermal low is made by heating, not by fronts: the ground warms, the air above it expands and rises, and the surface pressure falls. That is the origin of the seasonal low over north-west India and Pakistan in summer, which is the engine that pulls in the south-west monsoon.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-474\",\"topic\":\"Air masses & fronts\",\"stem\":\"At a stationary front, the winds on either side blow\",\"opts\":[\"Parallel to the front, in opposite directions\",\"At right angles to the front, towards it\",\"Parallel to the front, in the same direction\"],\"ans\":0,\"exp\":\"A front stays put when neither air mass can displace the other. That happens when the flow on each side runs ALONG the boundary rather than across it, in opposing directions, so neither pushes it. The polar front is the classic example.\",\"seenIn\":[\"Mar 2022 · Regular\",\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-475\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Snow reaching the ground most commonly falls from\",\"opts\":[\"Nimbostratus\",\"Stratus\",\"Cirrus\"],\"ans\":0,\"exp\":\"Nimbostratus is the deep, layered rain-and-snow cloud - thick enough and cold enough through its depth for ice crystals to grow to a size that reaches the ground. Stratus is too thin and gives only drizzle, and cirrus is far too high, its crystals evaporating long before they arrive.\",\"seenIn\":[\"May 2022 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-476\",\"topic\":\"Lapse rates & stability\",\"stem\":\"The stability of the atmosphere at a given time is determined from the\",\"opts\":[\"DALR\",\"SALR\",\"ELR compared with the adiabatic lapse rates\"],\"ans\":2,\"exp\":\"DALR and SALR are fixed properties of a rising parcel. The Environmental Lapse Rate is what the atmosphere is actually doing at that moment, so stability is judged by comparing the ELR against them: ELR less than SALR is absolutely stable, greater than DALR is absolutely unstable, and in between is conditionally unstable.\",\"seenIn\":[\"May 2022 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-477\",\"topic\":\"Icing\",\"stem\":\"Hoar frost forms on an airframe parked in clear air when the temperature of the airframe is\",\"opts\":[\"Below the frost point\",\"At the dew point\",\"Above the frost point\"],\"ans\":0,\"exp\":\"The frost point is the temperature at which air becomes saturated with respect to ICE. Cool a surface below it and water vapour turns straight into ice crystals on that surface - deposition, with no liquid stage. It needs no cloud and no precipitation, only a cold enough surface in clear air.\",\"seenIn\":[\"May 2022 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-478\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"A SPECI is issued when the mean surface wind speed has changed by\",\"opts\":[\"5 kt or more\",\"10 kt or more\",\"20 kt or more\"],\"ans\":1,\"exp\":\"The correct answer is: 10 kt or more.\",\"seenIn\":[\"Jul 2022 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-479\",\"topic\":\"Wind\",\"stem\":\"Wind is caused primarily by\",\"opts\":[\"A difference of pressure between two places\",\"A difference of temperature alone\",\"The rotation of the earth\"],\"ans\":0,\"exp\":\"Air moves because of a pressure gradient - that is the only force that starts it. Temperature differences matter because they CREATE the pressure differences, and the earth rotation (Coriolis) only deflects air that is already moving. No pressure gradient, no wind.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"May 2024 · OLODE\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-480\",\"topic\":\"Pressure & altimetry\",\"stem\":\"An aircraft is at an aerodrome where the pressure is 30 hPa above the QNH datum. The elevation of the aerodrome is about\",\"opts\":[\"300 ft\",\"900 ft\",\"3000 ft\"],\"ans\":1,\"exp\":\"The correct answer is: 900 ft.\",\"seenIn\":[\"Jul 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-481\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"A heavy aircraft crosses your track at the same level from left to right. To avoid its wake turbulence you should\",\"opts\":[\"Reduce speed to Va and hold your altitude\",\"Climb above its flight path\",\"Descend below its flight path\"],\"ans\":1,\"exp\":\"Wingtip vortices sink below the path of the aircraft that made them, typically 500-1000 ft, and then drift downwind. So the safe air is ABOVE the generating aircraft track. Descending through the vortex core is the one thing that puts you into it.\",\"seenIn\":[\"Mar 2022 · Regular\",\"May 2022 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-482\",\"topic\":\"Pressure & altimetry\",\"stem\":\"At a constant indicated altitude, an altimeter will under-read the true altitude when the aircraft flies into an area of\",\"opts\":[\"Higher temperature\",\"Lower temperature\",\"Lower pressure\"],\"ans\":0,\"exp\":\"Warm air is less dense, so the pressure levels spread apart and each one lies higher than the standard atmosphere says. The altimeter goes on reading the standard height for that pressure, so the aircraft is actually HIGHER than indicated - the altimeter under-reads. The dangerous case is the reverse: from high to low, look out below.\",\"seenIn\":[\"Mar 2022 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLMET-483\",\"topic\":\"Humidity\",\"stem\":\"The relative humidity of a sample of air depends on\",\"opts\":[\"Its temperature and how much water vapour it holds\",\"Its pressure alone\",\"Its density alone\"],\"ans\":0,\"exp\":\"Relative humidity compares the water vapour actually present with the most the air could hold at that temperature. So it moves with BOTH: add moisture and it rises, and warm the air - which raises the amount it could hold - and it falls, even though nothing has been taken out.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"rebuilt\",\"optionsWritten\":false},{\"id\":\"CPLMET-484\",\"topic\":\"Clouds & precipitation\",\"stem\":\"Cloud is most likely to be dissipated by\",\"opts\":[\"A fall in temperature\",\"Subsidence and warming of the air\",\"An increase in relative humidity\"],\"ans\":1,\"exp\":\"Cloud is water that has condensed because the air was cooled to saturation. Reverse that and the cloud evaporates: sinking air is compressed and warms, so its relative humidity falls and the droplets return to vapour. This is why subsiding air in a high gives clear skies.\",\"seenIn\":[\"May 2024 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"rebuilt\",\"optionsWritten\":false},{\"id\":\"CPLMET-485\",\"topic\":\"Visibility & fog\",\"stem\":\"Advection fog is lifted into low stratus by\",\"opts\":[\"A strengthening wind\",\"A falling temperature\",\"An increase in humidity\"],\"ans\":0,\"exp\":\"Fog needs the cooling to stay in a shallow layer near the surface. As the wind strengthens - beyond roughly 15 kt - turbulence mixes that cooling through a deeper layer, so the condensation level rises off the ground and the fog becomes a sheet of low stratus instead.\",\"seenIn\":[\"May 2024 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"rebuilt\",\"optionsWritten\":false},{\"id\":\"CPLMET-486\",\"topic\":\"Air masses & fronts\",\"stem\":\"A cold air mass moving over a warm surface becomes\",\"opts\":[\"More stable, with fog or stratus\",\"Unstable, with cumulus and showers\",\"Unchanged\"],\"ans\":1,\"exp\":\"Heating an air mass from below steepens its lapse rate and makes it unstable. The warmed surface air rises, and if there is enough moisture it forms cumulus and showers. The opposite case - warm air over a cold surface - is stabilised, and gives fog or stratus instead.\",\"seenIn\":[\"May 2024 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"rebuilt\",\"optionsWritten\":false},{\"id\":\"CPLMET-487\",\"topic\":\"Temperature & radiation\",\"stem\":\"The seasons are caused by\",\"opts\":[\"The tilt of the earth axis as it orbits the sun\",\"The changing distance between earth and sun\",\"Changes in the output of the sun\"],\"ans\":0,\"exp\":\"The earth axis is tilted about 23.5 ° and keeps pointing the same way all year. So each hemisphere is tilted towards the sun for part of the orbit - longer days and a higher sun, giving summer - and away from it for the other part. The earth is actually closest to the sun in January, which shows distance is not the cause.\",\"seenIn\":[\"May 2024 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"rebuilt\",\"optionsWritten\":false},{\"id\":\"CPLMET-488\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"The wingtip vortices of a large aircraft, once formed, tend to\",\"opts\":[\"Sink below its flight path and drift downwind\",\"Rise above its flight path\",\"Stay exactly on its flight path\"],\"ans\":0,\"exp\":\"The pair of vortices descends at a few hundred feet a minute and levels off roughly 500-1000 ft below the path of the aircraft that made them. Near the ground they cannot keep sinking, so they move outwards along the surface and then drift with the wind. Both parts matter: stay above the path, and think about where the wind is taking them.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":0,\"years\":[2023,2024],\"kind\":\"topic\",\"optionsWritten\":false},{\"id\":\"CPLMET-489\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"The wingtip vortices of an aircraft are strongest when it is\",\"opts\":[\"Heavy, clean and slow\",\"Light, in the landing configuration and fast\",\"Heavy, with full flap and fast\"],\"ans\":0,\"exp\":\"The correct answer is: Heavy, clean and slow.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":0,\"years\":[2024],\"kind\":\"topic\",\"optionsWritten\":false},{\"id\":\"CPLMET-490\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"Landing behind a heavy aircraft that has just landed on the same runway, you should aim to touch down\",\"opts\":[\"Beyond its touchdown point\",\"Short of its touchdown point\",\"At exactly its touchdown point\"],\"ans\":0,\"exp\":\"The heavy aircraft stops making vortices at the point where its wheels touch and the wing stops lifting. The air beyond that point is therefore clear, and the vortices lie behind it. Touching down beyond its touchdown point keeps you out of them; landing short puts you straight into them.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":0,\"years\":[2024],\"kind\":\"topic\",\"optionsWritten\":false},{\"id\":\"CPLMET-491\",\"topic\":\"Mountain waves & turbulence\",\"stem\":\"In a light crosswind, the vortex that is the greater hazard on the runway is the\",\"opts\":[\"Upwind vortex, which can be held over the runway\",\"Downwind vortex, which always clears fastest\",\"Neither - both clear immediately\"],\"ans\":0,\"exp\":\"Once the vortices reach the ground they move outwards at a few knots. A light crosswind of about that speed cancels the outward movement of the UPWIND vortex, so instead of clearing the runway it sits on it. The downwind one is carried away quickly. A light crosswind is therefore worse than a strong one.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":0,\"years\":[2024],\"kind\":\"topic\",\"optionsWritten\":false},{\"id\":\"CPLMET-492\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"On a station model, the air temperature (TT) is plotted\",\"opts\":[\"Upper left of the station circle\",\"Lower left of the station circle\",\"Upper right of the station circle\"],\"ans\":0,\"exp\":\"The station model has fixed positions: temperature upper left, dew point lower left directly below it, and the sea level pressure upper right. Present weather goes between the temperature and the dew point, to the left of the circle. The positions never change, which is what makes the model readable at a glance.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":0,\"years\":[2024],\"kind\":\"topic\",\"optionsWritten\":false},{\"id\":\"CPLMET-493\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"On a station model, the dew point (TdTd) is plotted\",\"opts\":[\"Upper left of the station circle\",\"Lower left of the station circle\",\"Directly below the station circle\"],\"ans\":1,\"exp\":\"Dew point sits lower left, immediately under the temperature at upper left. Keeping the two in the same column is deliberate - it lets a forecaster read the spread between them, and so how close that station is to saturation, without doing any arithmetic.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":0,\"years\":[2024],\"kind\":\"topic\",\"optionsWritten\":false},{\"id\":\"CPLMET-494\",\"topic\":\"Reports, forecasts & warnings\",\"stem\":\"On a station model, the sea level pressure (PPP) is shown as\",\"opts\":[\"The full value in hPa\",\"The last three digits, in tenths of a hPa\",\"The pressure change in 3 hours\"],\"ans\":1,\"exp\":\"Only the last three digits are plotted, in tenths of a hPa, with the leading 9 or 10 left off. So 148 means 1014.8 hPa and 987 means 998.7 hPa. The rule of thumb is to prefix 10 when the group is below about 500 and 9 when it is above.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":0,\"years\":[2023],\"kind\":\"topic\",\"optionsWritten\":false},{\"id\":\"CPLMET-495\",\"topic\":\"Indian climatology\",\"stem\":\"The south-west monsoon has normally withdrawn from almost all of India by\",\"opts\":[\"15 August\",\"15 October\",\"15 December\"],\"ans\":1,\"exp\":\"Withdrawal begins from Rajasthan around 01 September and from north-west India by about 15 September, and the monsoon has left almost the whole country by 15 October. It is then replaced by the north-east monsoon, which is what brings Tamil Nadu its main rain in October and November.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":0,\"years\":[2024],\"kind\":\"topic\",\"optionsWritten\":false},{\"id\":\"CPLMET-496\",\"topic\":\"Wind\",\"stem\":\"The thermal wind in a layer is\",\"opts\":[\"The wind that must be added to the geostrophic wind at the bottom of the layer to give the geostrophic wind at the top\",\"The wind produced directly by the heating of the ground\",\"The average wind through the layer\"],\"ans\":0,\"exp\":\"Thermal wind is a difference, not a wind you can feel. It is the vector that turns the lower-level geostrophic wind into the upper-level one, and its size depends on the horizontal TEMPERATURE gradient through the layer. That is why the subtropical westerly jet exists: a standing equator-to-pole temperature gradient makes a westerly thermal wind that builds with height.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":0,\"years\":[2024],\"kind\":\"topic\",\"optionsWritten\":false}]},{\"slug\":\"cpl-air-regulations\",\"subjectId\":\"air-regulations\",\"title\":\"CPL Air Regulations\",\"short\":\"Air Regulations\",\"published\":true,\"checked\":\"17 Oct 2026\",\"sittings\":[\"Feb 2021\",\"May 2022\",\"Aug 2022\",\"2022 · Regular 03\",\"Dec 2022 · Session 04\",\"Jul 2023 · OLODE\",\"Aug 2023 · OLODE\",\"Sep 2023 · Regular 03\",\"Oct 2023 · FC 07\",\"Nov 2023 · OLODE 08\",\"Dec 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\",\"May 2024 · OLODE 04\",\"Jun 2024 · Regular\",\"Sep 2024 · Session 03\",\"Oct 2024 · OLODE 07\",\"Nov 2024 · OLODE 08\",\"Dec 2024 · Regular 04\",\"Jan 2025 · OLODE 01\",\"Feb 2025 · OLODE 02\",\"Mar 2025 · Regular 01\",\"Apr 2025 · Regular 01\",\"May 2025 · OLODE 04\",\"Jul 2025 · OLODE 05\",\"Sep 2025 · Regular 03\",\"Oct 2025 · OLODE 07\",\"Jan 2026 · OLODE 01\",\"Apr 2026 · OLODE 03\",\"May 2026 · OLODE 04\",\"Jun 2026 · Regular 02\",\"Jul 2026 · OLODE 05\",\"Aug 2026 · OLODE 06\",\"Sep 2026 · Regular 03\"],\"firstYear\":2021,\"lastYear\":2026,\"questions\":[{\"id\":\"CPLREG-001\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Where is the headquarters of ICAO?\",\"opts\":[\"Montreal, Canada\",\"Paris, France\",\"Chicago, USA\"],\"ans\":0,\"exp\":\"ICAO sits in Montreal. Chicago is where the Convention was signed in 1944, and Paris is where the 1919 convention that came before it was signed - two classic distractors.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Jan 2025 · OLODE 01\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":3,\"years\":[2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-002\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"The Convention on International Civil Aviation (Chicago Convention) was signed in\",\"opts\":[\"1944\",\"1945\",\"1943\"],\"ans\":0,\"exp\":\"Signed at Chicago on 7 December 1944. It created ICAO and still forms the legal base of international civil aviation.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Jan 2024 · Regular (Day 2)\",\"May 2025 · OLODE 04\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-003\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"The Chicago Convention of 1944 replaced which earlier convention on air navigation?\",\"opts\":[\"Paris Convention, 1919\",\"Warsaw Convention, 1929\",\"Tokyo Convention, 1963\"],\"ans\":0,\"exp\":\"The Paris Convention of 1919 regulated aerial navigation and set up ICAN. Chicago 1944 replaced it and ICAO took over from ICAN. Warsaw deals with carriers' liability, and Tokyo came 19 years after Chicago.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-004\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Which convention gives the aircraft commander the power to impose reasonable measures, including restraint, on a person who commits an offence on board?\",\"opts\":[\"Tokyo Convention, 1963\",\"Warsaw Convention, 1929\",\"Chicago Convention, 1944\"],\"ans\":0,\"exp\":\"The Tokyo Convention (1963) covers offences and certain other acts committed on board aircraft. It is the one that gives the commander authority to restrain an offender and to disembark him.\",\"seenIn\":[\"Feb 2021\",\"Jun 2024 · Regular\",\"Jul 2025 · OLODE 05\",\"Apr 2026 · OLODE 03\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":5,\"years\":[2021,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-005\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Which convention deals with unlawful acts against the safety of civil aviation, such as sabotage?\",\"opts\":[\"Tokyo Convention\",\"Montreal Convention (1971)\",\"Warsaw Convention\"],\"ans\":1,\"exp\":\"Montreal 1971 covers acts of violence on board, destroying or damaging an aircraft, damaging navigation facilities and giving false information. Tokyo covers offences on board; Warsaw covers carriage by air.\",\"seenIn\":[\"Feb 2025 · OLODE 02\",\"Jun 2026 · Regular 02\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-006\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Which convention unified the rules for the international carriage of passengers, baggage and cargo by air?\",\"opts\":[\"Chicago Convention\",\"Tokyo Convention\",\"Warsaw Convention\"],\"ans\":2,\"exp\":\"The Warsaw Convention of 1929 - the Convention for the Unification of Certain Rules Relating to International Carriage by Air. It sets the air carrier's liability to passengers and shippers.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Feb 2025 · OLODE 02\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-007\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"The ICAO body of 19 members, appointed by the Council to deal with air navigation matters, is correctly called the\",\"opts\":[\"Air Navigation Committee\",\"Air Navigation Commission\",\"Air Navigation Council\"],\"ans\":1,\"exp\":\"It is the Air Navigation Commission (ANC). The Council is ICAO's governing body, and the word \\\"committee\\\" belongs to other bodies such as the Air Transport Committee and the Legal Committee.\",\"seenIn\":[\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-008\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Cabotage means\",\"opts\":[\"Carriage of passengers or cargo for remuneration between two points within the same State\",\"Flying over a State without landing\",\"Landing in another State for non-traffic purposes\"],\"ans\":0,\"exp\":\"Cabotage is domestic air service. Under Article 7 of the Chicago Convention each State may refuse foreign aircraft permission to carry traffic for hire between two points inside its own territory. Overflight and technical stops are the first and second freedoms.\",\"seenIn\":[\"2022 · Regular 03\",\"May 2024 · OLODE 04\",\"Nov 2024 · OLODE 08\",\"Apr 2025 · Regular 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":5,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-009\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"The common mark used by aircraft of an international operating agency is assigned by\",\"opts\":[\"The State of Registry\",\"ICAO\",\"The International Telecommunication Union (ITU)\"],\"ans\":1,\"exp\":\"ICAO assigns the common mark to the common mark registering authority, choosing from the radio call-sign symbols the ITU has allotted to ICAO. The individual registration mark is then given by that registering authority.\",\"seenIn\":[\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-010\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"An aircraft flying over the territory of another Contracting State must comply with the rules of the air of\",\"opts\":[\"The State of Registry\",\"The State of the Operator\",\"The State being overflown\"],\"ans\":2,\"exp\":\"The rules of the air follow the aircraft wherever it goes, but only so far as they do not conflict with the rules of the State that has jurisdiction over the territory overflown. Over someone else's country, their rules apply.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-011\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"SARPs stands for\",\"opts\":[\"Standards and Recommended Practices\",\"Standard Aviation Rules and Procedures\",\"Safety and Airworthiness Regulations for Pilots\"],\"ans\":0,\"exp\":\"SARPs are the Standards and Recommended Practices adopted by the ICAO Council and published as the Annexes to the Chicago Convention. A State that cannot comply with a Standard must notify ICAO of the difference.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-012\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"ICAO Annex 1 deals with\",\"opts\":[\"Personnel Licensing\",\"Rules of the Air\",\"Air Traffic Services\"],\"ans\":0,\"exp\":\"Annex 1 is Personnel Licensing. Rules of the Air is Annex 2 and Air Traffic Services is Annex 11.\",\"seenIn\":[\"Apr 2026 · OLODE 03\",\"Jun 2026 · Regular 02\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":3,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-013\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"ICAO Annex 8 deals with\",\"opts\":[\"Airworthiness of Aircraft\",\"Personnel Licensing\",\"Aircraft Nationality and Registration Marks\"],\"ans\":0,\"exp\":\"Annex 8 is Airworthiness of Aircraft. Personnel Licensing is Annex 1, and Nationality and Registration Marks is Annex 7.\",\"seenIn\":[\"Aug 2022\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2022,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-014\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Air Traffic Services are the subject of which ICAO Annex?\",\"opts\":[\"Annex 11\",\"Annex 14\",\"Annex 17\"],\"ans\":0,\"exp\":\"Annex 11 is Air Traffic Services. Annex 14 is Aerodromes and Annex 17 is Security.\",\"seenIn\":[\"Jan 2026 · OLODE 01\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-015\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Which Annex to the Chicago Convention contains the standards for the operation of aircraft, including commercial air transport?\",\"opts\":[\"Annex 10\",\"Annex 11\",\"Annex 6\"],\"ans\":2,\"exp\":\"Annex 6, Operation of Aircraft, in three parts - Part I covers international commercial air transport with aeroplanes. Annex 10 is telecommunications and Annex 11 is air traffic services.\",\"seenIn\":[\"May 2025 · OLODE 04\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-016\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"The safe transport of dangerous goods by air is covered by\",\"opts\":[\"Annex 18\",\"Annex 17\",\"Annex 16\"],\"ans\":0,\"exp\":\"Annex 18 is The Safe Transport of Dangerous Goods by Air. Annex 17 is Security and Annex 16 is Environmental Protection.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Nov 2024 · OLODE 08\",\"Feb 2025 · OLODE 02\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-017\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"ICAO Doc 4444 is\",\"opts\":[\"PANS-OPS\",\"PANS-ATM\",\"Annex 11\"],\"ans\":1,\"exp\":\"Doc 4444 is the Procedures for Air Navigation Services - Air Traffic Management (PANS-ATM). PANS-OPS is Doc 8168, and Annex 11 is a separate document containing the ATS Standards.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Jan 2025 · OLODE 01\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-018\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"ICAO Doc 8168 is\",\"opts\":[\"PANS-OPS (Aircraft Operations)\",\"PANS-ATM (Air Traffic Management)\",\"The Manual of Radiotelephony\"],\"ans\":0,\"exp\":\"Doc 8168 is PANS-OPS - Procedures for Air Navigation Services, Aircraft Operations. Volume I is flight procedures for pilots; Volume II is the construction of procedures for designers.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-019\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"ICAO Doc 7030 contains the\",\"opts\":[\"Regional Supplementary Procedures\",\"Manual of Radiotelephony\",\"Procedures for Air Navigation Services - Aircraft Operations\"],\"ans\":0,\"exp\":\"Doc 7030 holds the Regional Supplementary Procedures (SUPPs) - procedures that apply in a particular ICAO region on top of the worldwide PANS. Annex 2 refers you to it, for example, for regional contingency procedures.\",\"seenIn\":[\"Jul 2026 · OLODE 05\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-020\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Under Article 36 of the Chicago Convention, each Contracting State may\",\"opts\":[\"Prohibit or regulate the use of photographic apparatus in aircraft over its territory\",\"Refuse all foreign aircraft the right of overflight\",\"Require every aircraft to carry a flight engineer\"],\"ans\":0,\"exp\":\"Article 36 lets each State prohibit or regulate the use of cameras in aircraft over its territory. In India the matching rule is in the Aircraft Rules - photography from an aircraft in flight needs written permission.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-021\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Under the Aircraft Rules, a photograph at a Government aerodrome or from an aircraft in flight may be taken only\",\"opts\":[\"With written permission from the DGCA or an officer authorised under the rule\",\"Freely, except over a military airfield\",\"With verbal permission from the pilot-in-command\"],\"ans\":0,\"exp\":\"Rule 13 says no person shall take, or cause to be taken, a photograph at a Government aerodrome or from an aircraft in flight except under a written permission granted by the Director-General or one of the officers named in the rule.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-022\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"As per Rule 39C of the Aircraft Rules, a Student Pilot's Licence is valid for\",\"opts\":[\"10 years\",\"5 years\",\"2 years\"],\"ans\":1,\"exp\":\"The SPL is valid for five years. The 2023 amendment to Rule 39C raised the CPL and ATPL to ten years (the PPL was already ten) but left the Student Pilot's Licence at five.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-023\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"The minimum age for the issue of a Private Pilot's Licence is\",\"opts\":[\"16 years\",\"17 years\",\"18 years\"],\"ans\":1,\"exp\":\"PPL 17 years. For comparison: SPL 16, CPL 18, ATPL 21.\",\"seenIn\":[\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-024\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"Type ratings shall be established\",\"opts\":[\"For any type of aircraft whenever considered necessary by the Licensing Authority\",\"All the answers are correct\",\"Only for aircraft certificated for operation with a minimum crew of at least two pilots\"],\"ans\":0,\"exp\":\"The authority may require a type rating for any type it considers necessary. Aircraft certificated for a minimum crew of two pilots always need one, but the word \\\"only\\\" makes that option wrong - so \\\"all correct\\\" is wrong too.\",\"seenIn\":[\"2022 · Regular 03\",\"Dec 2022 · Session 04\",\"Apr 2026 · OLODE 03\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2022,2026],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check could not confirm this answer from the official sources we hold; treat it with care and confirm with your instructor.\"},{\"id\":\"CPLREG-025\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"A licence holder shall not exercise the privileges of the licence without a fresh medical examination after a sickness or injury causing incapacity for\",\"opts\":[\"7 days or more\",\"15 days or more\",\"30 days or more\"],\"ans\":1,\"exp\":\"Fifteen days or more of incapacity for the licensed work means a fresh medical before flying again. The same applies to any injury likely to affect your efficiency, whatever its length.\",\"seenIn\":[\"May 2022\",\"Nov 2023 · OLODE 08\",\"Sep 2024 · Session 03\",\"Jan 2025 · OLODE 01\",\"Oct 2025 · OLODE 07\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":6,\"years\":[2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-026\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"An aeroplane with a passenger seating capacity of 10 to 50 must carry at least\",\"opts\":[\"1 cabin crew member\",\"2 cabin crew members\",\"No cabin crew\"],\"ans\":0,\"exp\":\"Rule 38B: an aeroplane with 10 to 50 seats needs one cabin crew member. Cabin crew are counted on the seats installed, not on the passengers carried that day.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-027\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"An aeroplane with a passenger seating capacity of 84 must carry at least\",\"opts\":[\"1 cabin crew member\",\"2 cabin crew members\",\"3 cabin crew members\"],\"ans\":1,\"exp\":\"More than 50 seats needs two cabin crew, plus one more for each unit (or part) of 50 seats above 99. Eighty-four seats is above 50 but not above 99, so the answer is two.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-028\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"Under the Aircraft Rules, \\\"petroleum in bulk\\\" means petroleum carried in a receptacle\",\"opts\":[\"Of exactly 900 litres capacity\",\"Of less than 900 litres capacity\",\"Exceeding 900 litres capacity\"],\"ans\":2,\"exp\":\"The definition in Rule 3 is petroleum in a receptacle exceeding 900 litres in capacity.\",\"seenIn\":[\"Dec 2024 · Regular 04\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-029\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"Which set of documents must be carried on board an Indian-registered aircraft?\",\"opts\":[\"The Certificate of Registration, the Certificate of Airworthiness and the licences of the flight crew\",\"Only the Certificate of Airworthiness\",\"Only the pilot's licence and personal logbook\"],\"ans\":0,\"exp\":\"Among others, the aircraft must carry its Certificate of Registration, Certificate of Airworthiness and the licences of each flight crew member, plus (as applicable) the operator's permit, radio licence, journey logbook, MEL and flight manual.\",\"seenIn\":[\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-030\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"\\\"Flight time\\\" for an aeroplane is\",\"opts\":[\"From engine start to engine shutdown\",\"From take-off to landing\",\"From the moment the aeroplane first moves for the purpose of taking off until it finally comes to rest at the end of the flight\"],\"ans\":2,\"exp\":\"Flight time starts at the first movement for take-off and ends when the aeroplane comes to rest after the flight. It is the same as \\\"block to block\\\" or \\\"chock to chock\\\" time - not airborne time, and not engine-running time.\",\"seenIn\":[\"Apr 2026 · OLODE 03\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-031\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"Under the current flight duty time rules for a two-pilot crew, a flight duty period of up to 11 hours with up to 8 hours of flight time allows a maximum of\",\"opts\":[\"4 landings\",\"6 landings\",\"8 landings\"],\"ans\":1,\"exp\":\"The current FDTL table pairs flight time, flight duty period and landings: up to 8 hours of flight time within an 11-hour FDP permits 6 landings. Longer duty periods bring fewer permitted landings.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Oct 2025 · OLODE 07\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-032\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"In India, VFR flights (unless exempted by ATC) may be operated only between\",\"opts\":[\"20 minutes before sunrise and 20 minutes after sunset\",\"20 minutes before sunrise and 20 minutes before sunset\",\"10 minutes before sunrise and 20 minutes before sunset\"],\"ans\":0,\"exp\":\"VFR flights shall not operate between 20 minutes after sunset and 20 minutes before sunrise, except when exempted by ATC. Local and flying-club training flights may be cleared at night in VMC.\",\"seenIn\":[\"Feb 2025 · OLODE 02\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-033\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"In India, VFR flights shall not be operated above\",\"opts\":[\"FL150\",\"FL200\",\"FL245\"],\"ans\":0,\"exp\":\"AIP India: VFR flights shall not be operated above FL150, nor at transonic or supersonic speeds. The ICAO figure in Annex 2 is FL200 - the Indian limit is lower, and the Indian limit is what applies.\",\"seenIn\":[\"Feb 2025 · OLODE 02\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-034\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"An Air Defence Clearance (ADC) is NOT required for\",\"opts\":[\"Military flights\",\"Local flights within 5 NM of the aerodrome reference point and up to 1000 ft AGL, where ATS is available\",\"Any flight below FL150\"],\"ans\":1,\"exp\":\"Local flights, including flying-club flights, within a 5 NM radius of the ARP and up to 1000 ft AGL at an aerodrome with ATS are exempt. Every other flight in or into an ADIZ - civil or military - needs an ADC before take-off.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Jan 2024 · Regular (Day 2)\",\"May 2024 · OLODE 04\",\"Jul 2025 · OLODE 05\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":5,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-035\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"MEL stands for\",\"opts\":[\"Minimum Equipment List\",\"Master Equipment Log\",\"Maximum Equipment Limit\"],\"ans\":0,\"exp\":\"The Minimum Equipment List, part of the Operations Manual and approved by the DGCA, tells the pilot-in-command whether a flight may begin or continue with a particular item unserviceable.\",\"seenIn\":[\"Oct 2025 · OLODE 07\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-036\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"The Minimum Equipment List of an Indian operator is\",\"opts\":[\"Prepared by the operator in its Operations Manual and approved by the DGCA\",\"Written by the pilot-in-command before each flight\",\"Issued by ICAO for each aircraft type\"],\"ans\":0,\"exp\":\"The operator includes the MEL in its Operations Manual and the DGCA approves it. The manufacturer's master list (MMEL) is the starting point; the MEL can be as restrictive as the MMEL or more so, never less.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-037\",\"topic\":\"Rules of the air & signals\",\"stem\":\"Except for take-off and landing, a VFR flight over a congested area shall not be flown lower than\",\"opts\":[\"300 m (1000 ft) above the highest obstacle within 600 m of the aircraft\",\"150 m (500 ft) above the ground\",\"450 m (1500 ft) above the highest obstacle within 8 km\"],\"ans\":0,\"exp\":\"Over cities, towns, settlements or an open-air crowd: 1000 ft above the highest obstacle within 600 m. Elsewhere the minimum is 500 ft above ground or water.\",\"seenIn\":[\"Jul 2023 · OLODE\",\"Nov 2024 · OLODE 08\",\"Jan 2025 · OLODE 01\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-038\",\"topic\":\"Rules of the air & signals\",\"stem\":\"Where no minimum IFR altitude has been established, an IFR flight over high terrain or mountainous areas shall be flown at least\",\"opts\":[\"600 m (2000 ft) above the highest obstacle within 8 km of the estimated position\",\"300 m (1000 ft) above the highest obstacle within 8 km of the estimated position\",\"600 m (2000 ft) above the highest obstacle within 5 km of the estimated position\"],\"ans\":0,\"exp\":\"Over high terrain or mountains: 2000 ft above the highest obstacle within 8 km of the estimated position. Elsewhere the figure is 1000 ft, still within 8 km.\",\"seenIn\":[\"Nov 2023 · OLODE 08\",\"Jan 2024 · Regular (Day 2)\",\"May 2024 · OLODE 04\",\"Nov 2024 · OLODE 08\",\"May 2025 · OLODE 04\",\"Apr 2026 · OLODE 03\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":7,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-039\",\"topic\":\"Rules of the air & signals\",\"stem\":\"Below 3050 m (10,000 ft) AMSL (and above 900 m / 3000 ft), the VMC minima for flight in Class B to G airspace are\",\"opts\":[\"5 km flight visibility, 1500 m horizontally and 300 m (1000 ft) vertically from cloud\",\"8 km flight visibility, 1500 m horizontally and 300 m vertically from cloud\",\"1500 m flight visibility and clear of cloud\"],\"ans\":0,\"exp\":\"The correct answer is: 5 km flight visibility, 1500 m horizontally and 300 m (1000 ft) vertically from cloud.\",\"seenIn\":[\"Feb 2021\",\"2022 · Regular 03\",\"Sep 2023 · Regular 03\",\"Nov 2024 · OLODE 08\",\"Feb 2025 · OLODE 02\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":6,\"years\":[2021,2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-040\",\"topic\":\"Rules of the air & signals\",\"stem\":\"Without an ATC clearance, a VFR flight shall not take off or land at an aerodrome within a control zone when the ceiling is less than ___ or the ground visibility is less than ___\",\"opts\":[\"450 m (1500 ft) / 5 km\",\"300 m (1000 ft) / 3 km\",\"600 m (2000 ft) / 8 km\"],\"ans\":0,\"exp\":\"Ceiling below 1500 ft or ground visibility below 5 km - no VFR take-off, landing or entry into the traffic pattern at a control-zone aerodrome without an ATC clearance.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-041\",\"topic\":\"Rules of the air & signals\",\"stem\":\"Instrument meteorological conditions (IMC) are\",\"opts\":[\"Conditions expressed in visibility, distance from cloud and ceiling, less than the minima specified for VMC\",\"Any conditions in which the aircraft is flying in cloud\",\"Any conditions in which the ceiling is below 1000 ft\"],\"ans\":0,\"exp\":\"IMC is simply \\\"worse than the VMC minima\\\", measured in visibility, distance from cloud and ceiling. Being in cloud is one example of IMC, not the definition.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-042\",\"topic\":\"Rules of the air & signals\",\"stem\":\"When the weather is VMC, the decision to fly under IFR rather than VFR normally rests with\",\"opts\":[\"ATC\",\"The operator\",\"The pilot-in-command, unless the ATS authority requires IFR\"],\"ans\":2,\"exp\":\"A pilot may elect to fly IFR in VMC, or may be required to by the appropriate ATS authority. So the choice - including a change from VFR to IFR - is the commander's, unless the airspace rules demand IFR.\",\"seenIn\":[\"Apr 2026 · OLODE 03\",\"Jun 2026 · Regular 02\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-043\",\"topic\":\"Rules of the air & signals\",\"stem\":\"On an IFR flight plan in VMC, the weather deteriorates to IMC. The pilot should\",\"opts\":[\"Continue in accordance with the IFR flight plan and clearance\",\"Land at the nearest aerodrome\",\"Cancel IFR and continue under VFR\"],\"ans\":0,\"exp\":\"An IFR flight is cleared and protected for flight in IMC, so nothing changes - carry on with the clearance. Cancelling IFR to continue VFR into IMC would be the one thing you may not do.\",\"seenIn\":[\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-044\",\"topic\":\"Rules of the air & signals\",\"stem\":\"An aircraft suffering radio communication failure while in VMC shall\",\"opts\":[\"Continue to fly in VMC, land at the nearest suitable aerodrome and report its arrival to ATC by the quickest means\",\"Continue according to the current flight plan to destination\",\"Return to the departure aerodrome\"],\"ans\":0,\"exp\":\"In VMC: stay VMC, land at the nearest suitable aerodrome and report the arrival by the most expeditious means. Continuing the flight plan is the IMC procedure, used only when VMC cannot be kept.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"May 2024 · OLODE 04\",\"Jan 2025 · OLODE 01\",\"Feb 2025 · OLODE 02\",\"Jan 2026 · OLODE 01\",\"Apr 2026 · OLODE 03\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":7,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-045\",\"topic\":\"Rules of the air & signals\",\"stem\":\"An IFR flight with radio communication failure in IMC, in airspace where radar is not used, shall maintain its last assigned speed and level (or minimum flight altitude if higher) for\",\"opts\":[\"20 minutes after failing to report over a compulsory reporting point\",\"7 minutes after failing to report over a compulsory reporting point\",\"30 minutes after the last contact\"],\"ans\":0,\"exp\":\"Twenty minutes in non-radar airspace, then adjust level and speed to the filed flight plan. Where radar is used, the period is 7 minutes.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-046\",\"topic\":\"Rules of the air & signals\",\"stem\":\"You are radar vectored off your flight plan route and then lose radio communication. You should rejoin the route\",\"opts\":[\"In the most direct manner possible, no later than the next significant point\",\"With an intercept angle of at least 30 degrees\",\"With an intercept angle of at least 45 degrees\"],\"ans\":0,\"exp\":\"After losing communication while being vectored, go back to the flight plan route by the most direct means, no later than the next significant point, respecting the minimum flight altitude. No intercept angle is specified.\",\"seenIn\":[\"Sep 2024 · Session 03\",\"Feb 2025 · OLODE 02\",\"Apr 2026 · OLODE 03\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":5,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-047\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A steady red light from the aerodrome control tower to an aircraft in flight means\",\"opts\":[\"Give way to other aircraft and continue circling\",\"Aerodrome unsafe, do not land\",\"Return for landing\"],\"ans\":0,\"exp\":\"Steady red in flight = give way and keep circling. Red flashes mean the aerodrome is unsafe; green flashes mean return for landing.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-048\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A steady green light from the tower to an aircraft on the ground means\",\"opts\":[\"Cleared for take-off\",\"Cleared to taxi\",\"Return to starting point on the aerodrome\"],\"ans\":0,\"exp\":\"On the ground, steady green = cleared for take-off. Cleared to taxi is a series of green flashes, and return to starting point is a series of white flashes.\",\"seenIn\":[\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-049\",\"topic\":\"Rules of the air & signals\",\"stem\":\"By day or night, an intercepting aircraft rocking its wings and flashing its navigation lights from slightly above and ahead of you means\",\"opts\":[\"You have been intercepted - follow me\",\"You may proceed\",\"Land at this aerodrome\"],\"ans\":0,\"exp\":\"Series 1 of the interception signals: rocking the aircraft and flashing the navigation lights at irregular intervals means \\\"you have been intercepted, follow me\\\". You reply by rocking your own aircraft and following.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-050\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A marshaller asks the pilot to set the brakes by\",\"opts\":[\"Raising the hand just above shoulder height with open palm, then closing the hand into a fist\",\"Holding the arms down, palms facing inwards, moving them inwards from the extended position\",\"Crossing both arms above the head\"],\"ans\":0,\"exp\":\"Set brakes: open palm at shoulder height, then close it into a fist, and wait for the crew's thumbs-up. Arms moving inward is the chocks-inserted signal, and wands crossed above the head is emergency stop.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Apr 2025 · Regular 01\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-051\",\"topic\":\"Rules of the air & signals\",\"stem\":\"The marshalling signal for \\\"affirmative / all clear\\\" is\",\"opts\":[\"Right arm raised to head level with wand pointing up, or hand displayed with thumbs up\",\"Both arms extended sideways with palms down\",\"Wands crossed above the head\"],\"ans\":0,\"exp\":\"All clear: right arm up to head level with the wand pointing up, or a thumbs-up, with the left arm at the side. Crossed wands above the head means emergency stop.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-052\",\"topic\":\"Rules of the air & signals\",\"stem\":\"At an aerodrome, flashing runway or taxiway lights mean\",\"opts\":[\"Vacate the runway and observe the tower for a light signal\",\"The aerodrome is closed - land elsewhere\",\"Cleared to land\"],\"ans\":0,\"exp\":\"When radio or normal light signals cannot be used, flashing runway or taxiway lights tell everyone on them to vacate the runway and watch the tower for a light signal.\",\"seenIn\":[\"Oct 2023 · FC 07\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-053\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A flight plan shall be submitted\",\"opts\":[\"Only for IFR flights\",\"Before operating any flight, or portion of a flight, that is to be provided with air traffic control service\",\"Only for international flights\"],\"ans\":1,\"exp\":\"Any flight - VFR or IFR, domestic or international - that will receive ATC service needs a flight plan first. The rule also covers IFR flights in advisory airspace and flights crossing international borders.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-054\",\"topic\":\"Rules of the air & signals\",\"stem\":\"On an IFR flight, an emergency forces you to deviate from your ATC clearance. You must\",\"opts\":[\"Notify the appropriate ATC unit of the action taken as soon as circumstances permit\",\"Obtain an amended clearance before taking any action\",\"Cancel the IFR flight plan\"],\"ans\":0,\"exp\":\"In an emergency needing immediate action you act first, then tell ATC as soon as circumstances permit, saying the action was taken under emergency authority.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-055\",\"topic\":\"Rules of the air & signals\",\"stem\":\"An aircraft may deviate from its ATC clearance without first obtaining a new one\",\"opts\":[\"When an emergency arises that needs immediate action by the pilot-in-command\",\"Whenever the pilot wishes, without reason\",\"Only when the weather is good\"],\"ans\":0,\"exp\":\"A controlled flight keeps to its clearance unless it gets a new one - the only exception is an emergency that needs immediate action. After that, ATC must be told as soon as possible.\",\"seenIn\":[\"Apr 2025 · Regular 01\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-056\",\"topic\":\"Rules of the air & signals\",\"stem\":\"Runway designation numbers are based on the runway direction measured from\",\"opts\":[\"True north\",\"Magnetic north\",\"Grid north\"],\"ans\":1,\"exp\":\"The two-digit designator is the magnetic direction of the runway (approach direction) to the nearest ten degrees. So runway 27 lies about 270 degrees magnetic.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Jan 2024 · Regular (Day 2)\",\"Jan 2025 · OLODE 01\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-057\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"An airspace in which IFR and VFR flights are permitted, all flights receive ATC service and all flights are separated from each other is\",\"opts\":[\"Class A\",\"Class B\",\"Class C\"],\"ans\":1,\"exp\":\"Class B: IFR and VFR, everyone separated from everyone. Class A allows IFR only. In Class C, VFR flights are not separated from each other - they only get traffic information on other VFR.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-058\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"In Class C airspace\",\"opts\":[\"IFR is separated from IFR and from VFR; VFR is separated from IFR and receives traffic information on other VFR\",\"All flights are separated from each other\",\"IFR is separated from IFR only\"],\"ans\":0,\"exp\":\"Class C: IFR separated from all traffic; VFR separated from IFR only, and given traffic information about other VFR. \\\"IFR separated from IFR only\\\" is Class D.\",\"seenIn\":[\"Apr 2026 · OLODE 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-059\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"In Class F airspace\",\"opts\":[\"Participating IFR flights receive an air traffic advisory service, and all flights receive flight information service if requested\",\"All flights are separated by ATC\",\"Only IFR flights are permitted\"],\"ans\":0,\"exp\":\"Class F is uncontrolled. IFR flights taking part get advisory service, and every flight can have flight information service on request - but nobody is separated by ATC.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-060\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"A VFR flight may operate without continuous two-way radio communication in\",\"opts\":[\"Class E airspace\",\"Class A airspace\",\"Class C airspace\"],\"ans\":0,\"exp\":\"In Class E (and F and G), VFR flights do not need continuous two-way radio. Classes A to D need it for every flight - and Class A does not allow VFR at all.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-061\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"ATC separates ALL flights, IFR and VFR, from each other in\",\"opts\":[\"Class A and Class B\",\"Class C and Class D\",\"Class E and Class F\"],\"ans\":0,\"exp\":\"All flights are separated from each other only in Class A (IFR only) and Class B (IFR and VFR). From Class C down, at least some pairs of flights receive traffic information instead of separation.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-062\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"In Class D, E, F and G airspace below 3050 m (10,000 ft) AMSL, aircraft are limited to\",\"opts\":[\"250 kt IAS\",\"250 kt TAS\",\"No speed limit\"],\"ans\":0,\"exp\":\"The speed limit is 250 kt IAS below 10,000 ft AMSL. In Class C it applies to VFR flights; in Classes D to G it applies to IFR and VFR alike. It is indicated airspeed, not true.\",\"seenIn\":[\"May 2025 · OLODE 04\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-063\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"A control area normally established at the confluence of ATS routes in the vicinity of one or more major aerodromes is a\",\"opts\":[\"Control zone (CTZ)\",\"Terminal control area (TMA)\",\"Aerodrome traffic zone (ATZ)\"],\"ans\":1,\"exp\":\"That is the definition of a terminal control area. A control zone starts from the surface around an aerodrome; a TMA is a control area, so it starts from a specified limit above the earth.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-064\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"A control area is a controlled airspace extending upwards from a specified limit above the\",\"opts\":[\"Earth\",\"Mean sea level\",\"Transition altitude\"],\"ans\":0,\"exp\":\"The definition says \\\"a specified limit above the earth\\\". The control zone is the one that extends upwards from the surface of the earth.\",\"seenIn\":[\"Apr 2025 · Regular 01\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-065\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"Which of the following is an ATS unit?\",\"opts\":[\"A flight information centre\",\"An area control centre\",\"Both of these\"],\"ans\":2,\"exp\":\"\\\"ATS unit\\\" is a generic term that covers ATC units (area control centre, approach control office, aerodrome control tower), flight information centres and ATS reporting offices.\",\"seenIn\":[\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-066\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"The ATC service provided to traffic on the manoeuvring area of an aerodrome is\",\"opts\":[\"Flight information service\",\"Aerodrome control service\",\"Air traffic advisory service\"],\"ans\":1,\"exp\":\"Aerodrome control service is the ATC service for aerodrome traffic - everything on the manoeuvring area and aircraft in the vicinity of the aerodrome.\",\"seenIn\":[\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-067\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"Essential traffic is\",\"opts\":[\"Controlled traffic to which ATC separation applies but which, in relation to a particular flight, is not or will not be separated by the minima\",\"Any traffic within 5 NM of the aircraft\",\"Uncontrolled VFR traffic near an aerodrome\"],\"ans\":0,\"exp\":\"Essential traffic is controlled traffic that should be separated but, in relation to your flight, is not or will not be. Because of that, ATC must pass it to you as essential traffic information.\",\"seenIn\":[\"Jul 2025 · OLODE 05\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-068\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"A clearance limit is\",\"opts\":[\"The point to which an aircraft is granted an ATC clearance\",\"The time after which a clearance lapses\",\"The lowest level to which an aircraft may be cleared\"],\"ans\":0,\"exp\":\"The clearance limit is a point - the fix, reporting point or aerodrome up to which you are cleared. The time after which a clearance lapses is its expiry time.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-069\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"Your IFR clearance includes \\\"clearance expires at 0920\\\". This means\",\"opts\":[\"If you are not airborne by 0920 the clearance is cancelled and a new one is needed\",\"Take-off is expected at 0920\",\"You must return to the ramp at 0920 and file a new flight plan\"],\"ans\":0,\"exp\":\"The expiry time is the time after which the clearance is automatically cancelled if the flight has not started. Miss it and you need a new clearance - you do not need a new flight plan.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Jan 2025 · OLODE 01\",\"Apr 2026 · OLODE 03\",\"Jun 2026 · Regular 02\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":5,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-070\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"A position report contains, in order\",\"opts\":[\"Aircraft identification, position, time, level, next position and time over, ensuing significant point\",\"Position, time, level, fuel remaining\",\"Aircraft identification, aircraft type, position\"],\"ans\":0,\"exp\":\"Identification, position, time, flight level or altitude, next position with its time, then the ensuing significant point. Type and fuel are not part of it.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Sep 2024 · Session 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2022,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-071\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"After radar vectoring, ATC instructs \\\"resume own navigation\\\". This means\",\"opts\":[\"The pilot takes back responsibility for his own navigation\",\"ATC will continue to vector the aircraft\",\"The aircraft is no longer under air traffic control\"],\"ans\":0,\"exp\":\"Vectoring has ended and the pilot navigates again, usually back to the route. The flight is still controlled. If the vectors took you off your route, ATC will also give you your position.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Oct 2024 · OLODE 07\",\"Jan 2025 · OLODE 01\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-072\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"An aircraft known or believed to be the subject of unlawful interference places the rescue services in the\",\"opts\":[\"Alert phase (ALERFA)\",\"Uncertainty phase (INCERFA)\",\"Distress phase (DETRESFA)\"],\"ans\":0,\"exp\":\"Unlawful interference is one of the triggers for the alert phase, along with failing to land within 5 minutes of the expected time after being cleared to land.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-073\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"Item 9 of the ICAO flight plan contains\",\"opts\":[\"The departure aerodrome\",\"The number and type of aircraft and the wake turbulence category\",\"The cruising level\"],\"ans\":1,\"exp\":\"Item 9: number of aircraft (if more than one), type designator and wake turbulence category. The departure aerodrome is Item 13 and the cruising level is part of Item 15.\",\"seenIn\":[\"Nov 2023 · OLODE 08\",\"Sep 2024 · Session 03\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-074\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"An aircraft cleared for an immediate take-off shall\",\"opts\":[\"Taxi out onto the runway and take off in one continuous movement\",\"Take off within 30 seconds of the clearance\",\"Complete its checks on the runway and then take off\"],\"ans\":0,\"exp\":\"An immediate take-off clearance may be given before the aircraft enters the runway. Once you accept it, you line up and take off in one continuous movement - so accept it only if you are ready.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"May 2024 · OLODE 04\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-075\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"An aircraft is given the correct time by the aerodrome controller\",\"opts\":[\"On initial contact\",\"Prior to taxiing for take-off\",\"After take-off\"],\"ans\":1,\"exp\":\"Before taxiing for take-off the aircraft is given, in order: runway, surface wind, QNH, air temperature (turbine aircraft), visibility or RVR if relevant, and the correct time.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Feb 2025 · OLODE 02\",\"May 2026 · OLODE 04\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":4,\"years\":[2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-076\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"An aircraft is \\\"HEAVY\\\" for wake turbulence purposes when its maximum certificated take-off mass is\",\"opts\":[\"7000 kg or more\",\"136,000 kg or more\",\"570,000 kg or more\"],\"ans\":1,\"exp\":\"HEAVY is 136,000 kg or more; MEDIUM is between 7000 kg and 136,000 kg; LIGHT is 7000 kg or less.\",\"seenIn\":[\"2022 · Regular 03\",\"Jul 2023 · OLODE\",\"May 2024 · OLODE 04\",\"Nov 2024 · OLODE 08\",\"Jan 2025 · OLODE 01\",\"May 2025 · OLODE 04\",\"Oct 2025 · OLODE 07\",\"May 2026 · OLODE 04\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":9,\"years\":[2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-077\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"Two departures follow the same track and the preceding aircraft is 40 kt or more faster than the following one. The minimum separation between take-offs is\",\"opts\":[\"2 minutes\",\"1 minute\",\"5 minutes\"],\"ans\":0,\"exp\":\"The correct answer is: 2 minutes.\",\"seenIn\":[\"Apr 2026 · OLODE 03\",\"May 2026 · OLODE 04\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":3,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-078\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"The wake turbulence separation for a MEDIUM aircraft taking off behind a HEAVY aircraft on the same runway is\",\"opts\":[\"1 minute\",\"3 minutes\",\"2 minutes\"],\"ans\":2,\"exp\":\"Two minutes for a LIGHT or MEDIUM taking off behind a HEAVY from the same runway. It rises to 3 minutes if the follower departs from an intermediate part of the runway.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-079\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"The wake turbulence separation for a LIGHT aircraft taking off behind a MEDIUM aircraft on the same runway is\",\"opts\":[\"1 minute\",\"3 minutes\",\"2 minutes\"],\"ans\":2,\"exp\":\"Two minutes - the same figure as LIGHT or MEDIUM behind HEAVY. From an intermediate part of the runway it becomes 3 minutes.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-080\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"Taking off behind a heavy jet, the best way to avoid its wake vortices is to\",\"opts\":[\"Lift off before its lift-off point and climb above its flight path\",\"Lift off after its lift-off point and stay below its flight path\",\"Take off immediately behind it\"],\"ans\":0,\"exp\":\"Vortices start where the heavy lifts off and then sink. Get airborne before that point and stay above its climb path, and you stay out of them.\",\"seenIn\":[\"Jul 2025 · OLODE 05\",\"Apr 2026 · OLODE 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-081\",\"topic\":\"Transponder & emergencies\",\"stem\":\"The transponder code for unlawful interference is\",\"opts\":[\"7500\",\"7600\",\"7700\"],\"ans\":0,\"exp\":\"7500 unlawful interference, 7600 radio failure, 7700 emergency. If ATC asks you to confirm 7500, you may confirm it or simply not reply - either tells them it was not selected by mistake.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Apr 2025 · Regular 01\",\"May 2025 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-082\",\"topic\":\"Transponder & emergencies\",\"stem\":\"On losing two-way radio communication, the transponder is set to\",\"opts\":[\"Mode A 7500\",\"Mode A 7600 with Mode C\",\"Mode A 7700\"],\"ans\":1,\"exp\":\"Radio failure is 7600, keeping Mode C on so ATC still sees your level. ATC can then check how far the failure goes by asking you to squawk IDENT or change code.\",\"seenIn\":[\"Feb 2021\",\"May 2024 · OLODE 04\",\"Jun 2024 · Regular\",\"Nov 2024 · OLODE 08\",\"Jan 2025 · OLODE 01\",\"May 2025 · OLODE 04\",\"Jul 2025 · OLODE 05\",\"Oct 2025 · OLODE 07\",\"Apr 2026 · OLODE 03\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":11,\"years\":[2021,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-083\",\"topic\":\"Transponder & emergencies\",\"stem\":\"The transponder code for a general emergency is\",\"opts\":[\"7700\",\"7600\",\"7500\"],\"ans\":0,\"exp\":\"Squawk 7700 for an emergency unless ATC has already given you a code to use - and you may still select 7700 if you think it is the best course of action.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-084\",\"topic\":\"Transponder & emergencies\",\"stem\":\"Which of these is NOT a valid transponder code?\",\"opts\":[\"7777\",\"5678\",\"7500\"],\"ans\":1,\"exp\":\"Transponder codes are octal - every digit runs from 0 to 7, so the range is 0000 to 7777. Any code containing an 8 or a 9 cannot be set.\",\"seenIn\":[\"Jan 2026 · OLODE 01\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-085\",\"topic\":\"Transponder & emergencies\",\"stem\":\"A pilot shall operate the transponder on the Mode A code\",\"opts\":[\"Assigned by the ATC unit in contact\",\"Of his own choice\",\"2000 at all times\"],\"ans\":0,\"exp\":\"First the code the ATC unit gives you; failing that, the code set by regional agreement; and only in the absence of both, code 2000.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-086\",\"topic\":\"Transponder & emergencies\",\"stem\":\"In the absence of any ATC instruction or regional agreement, the transponder is set to\",\"opts\":[\"Mode A 2000 with Mode C\",\"Mode A 7000\",\"Mode A 7600\"],\"ans\":0,\"exp\":\"Code 2000 is the default - for example when entering an FIR where no code has been given. 7000 is a European VFR convention, not the ICAO default, and 7600 means radio failure.\",\"seenIn\":[\"Jul 2025 · OLODE 05\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-087\",\"topic\":\"Transponder & emergencies\",\"stem\":\"When acknowledging a mode or code setting instruction, the pilot shall\",\"opts\":[\"Say ROGER\",\"Say WILCO\",\"Read back the mode and code to be set\"],\"ans\":2,\"exp\":\"SSR codes are on the list of items that must always be read back, like clearances, runway instructions and altimeter settings. ROGER or WILCO alone is not enough.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Nov 2023 · OLODE 08\",\"Jun 2024 · Regular\",\"Jan 2025 · OLODE 01\",\"Oct 2025 · OLODE 07\",\"Jul 2026 · OLODE 05\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":7,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-088\",\"topic\":\"Transponder & emergencies\",\"stem\":\"An aircraft subject to unlawful interference cannot notify ATS and no regional procedure applies. In airspace with a 1000 ft vertical separation minimum, it should fly at a level that differs from the normal IFR cruising levels by\",\"opts\":[\"Nothing - it keeps its assigned level\",\"150 m (500 ft)\",\"300 m (1000 ft)\"],\"ans\":1,\"exp\":\"Offset 500 ft from the normal IFR levels where 1000 ft separation is applied (such as RVSM above FL290), and 1000 ft where 2000 ft separation is applied. You then sit halfway between other traffic.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Oct 2025 · OLODE 07\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-089\",\"topic\":\"Communications & phraseology\",\"stem\":\"A distress message is preceded by the radiotelephony distress signal\",\"opts\":[\"MAYDAY, preferably spoken three times\",\"PAN PAN, preferably spoken three times\",\"DISTRESS, spoken three times\"],\"ans\":0,\"exp\":\"Distress = MAYDAY, preferably three times, sent on the frequency in use. PAN PAN is the urgency signal, for a situation that is serious but not in grave and imminent danger.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"May 2025 · OLODE 04\",\"Jul 2026 · OLODE 05\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-090\",\"topic\":\"Communications & phraseology\",\"stem\":\"The radiotelephony urgency signal is\",\"opts\":[\"PAN PAN\",\"MAYDAY\",\"SECURITE\"],\"ans\":0,\"exp\":\"PAN PAN, preferably spoken three times, pronounced like the French word \\\"panne\\\". MAYDAY is distress; SECURITE is a safety signal from marine radio, not the aviation urgency call.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Jan 2025 · OLODE 01\",\"Apr 2025 · Regular 01\",\"May 2025 · OLODE 04\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":5,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-091\",\"topic\":\"Communications & phraseology\",\"stem\":\"The international aeronautical VHF emergency frequency is\",\"opts\":[\"121.5 MHz\",\"123.45 MHz\",\"118.1 MHz\"],\"ans\":0,\"exp\":\"The correct answer is: 121.5 MHz.\",\"seenIn\":[\"Nov 2023 · OLODE 08\",\"Jul 2025 · OLODE 05\",\"Apr 2026 · OLODE 03\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-092\",\"topic\":\"Communications & phraseology\",\"stem\":\"Which of these is an international HF distress frequency, used for voice contact with ships?\",\"opts\":[\"3062 kHz\",\"2182 kHz\",\"2346 kHz\"],\"ans\":1,\"exp\":\"2182 kHz is the maritime distress frequency, and many ships can also be reached on 4125 kHz and 121.5 MHz. The recognised distress list is 121.5 MHz, 243.0 MHz and 2182 kHz.\",\"seenIn\":[\"Oct 2025 · OLODE 07\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-093\",\"topic\":\"Communications & phraseology\",\"stem\":\"On the readability scale, \\\"readability 3\\\" means\",\"opts\":[\"Readable now and then\",\"Readable but with difficulty\",\"Perfectly readable\"],\"ans\":1,\"exp\":\"The scale runs 1 unreadable, 2 readable now and then, 3 readable but with difficulty, 4 readable, 5 perfectly readable.\",\"seenIn\":[\"Feb 2021\",\"Dec 2022 · Session 04\",\"Jan 2025 · OLODE 01\",\"Oct 2025 · OLODE 07\",\"Apr 2026 · OLODE 03\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":6,\"years\":[2021,2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-094\",\"topic\":\"Communications & phraseology\",\"stem\":\"An altitude of 3500 ft is transmitted in radiotelephony as\",\"opts\":[\"Three five zero zero\",\"Three thousand five hundred\",\"Thirty-five hundred\"],\"ans\":1,\"exp\":\"For altitude, cloud height, visibility and RVR, whole thousands and hundreds are spoken as THOUSAND and HUNDRED: \\\"three thousand five hundred\\\". Digit by digit is used for flight levels and squawk codes.\",\"seenIn\":[\"May 2022\",\"2022 · Regular 03\",\"Aug 2023 · OLODE\",\"Jan 2025 · OLODE 01\",\"May 2026 · OLODE 04\",\"Jun 2026 · Regular 02\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":7,\"years\":[2022,2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-095\",\"topic\":\"Communications & phraseology\",\"stem\":\"Having made an error in a transmission, the correct word to use is\",\"opts\":[\"REPEAT\",\"CORRECTION\",\"DISREGARD\"],\"ans\":1,\"exp\":\"CORRECTION means \\\"an error has been made in this transmission; the correct version is...\\\". DISREGARD cancels a transmission and REPEAT is not used in this sense.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-096\",\"topic\":\"Communications & phraseology\",\"stem\":\"RNAV stands for\",\"opts\":[\"Area navigation\",\"Radio navigation\",\"Route navigation\"],\"ans\":0,\"exp\":\"Area navigation: navigation on any desired path within ground-based or space-based aid coverage, or within the limits of self-contained aids, or a combination.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-097\",\"topic\":\"Communications & phraseology\",\"stem\":\"AFIS stands for\",\"opts\":[\"Aerodrome forecast information service\",\"Aerodrome flight information service\",\"Automatic flight information service\"],\"ans\":1,\"exp\":\"Aerodrome flight information service - flight information and alerting at an aerodrome that has no control tower. Do not confuse it with ATIS, the automatic information broadcast.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-098\",\"topic\":\"Communications & phraseology\",\"stem\":\"In ICAO terminology, STAR stands for\",\"opts\":[\"Standard instrument arrival\",\"Standard terminal radar\",\"Surveillance and tracking arrival route\"],\"ans\":0,\"exp\":\"A STAR is a published IFR arrival route linking an en-route significant point to a point where an instrument approach can begin. Some countries say \\\"standard terminal arrival route\\\"; the ICAO term is standard instrument arrival.\",\"seenIn\":[\"Aug 2022\",\"Jul 2023 · OLODE\",\"Feb 2025 · OLODE 02\",\"Oct 2025 · OLODE 07\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":5,\"years\":[2022,2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-099\",\"topic\":\"Communications & phraseology\",\"stem\":\"DER stands for\",\"opts\":[\"Departure end of runway\",\"Designated emergency runway\",\"Distance to end of runway\"],\"ans\":0,\"exp\":\"The departure end of the runway is the end of the area declared suitable for take-off. The instrument departure procedure starts there.\",\"seenIn\":[\"2022 · Regular 03\",\"Nov 2024 · OLODE 08\",\"Oct 2025 · OLODE 07\",\"Apr 2026 · OLODE 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":5,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-100\",\"topic\":\"Communications & phraseology\",\"stem\":\"RVR stands for\",\"opts\":[\"Runway visual range\",\"Runway visibility report\",\"Reported visual range\"],\"ans\":0,\"exp\":\"Runway visual range: the distance over which a pilot on the runway centre line can see the runway markings or lights. With DA/H, it is how precision approach minima are stated.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-101\",\"topic\":\"Altimetry\",\"stem\":\"The transition altitude at an aerodrome is specified by\",\"opts\":[\"The State in which the aerodrome is located\",\"The pilot-in-command\",\"The ATC unit on duty\"],\"ans\":0,\"exp\":\"The State specifies a transition altitude for each aerodrome and publishes it. In India no transition altitude is less than 4000 ft.\",\"seenIn\":[\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-102\",\"topic\":\"Altimetry\",\"stem\":\"The transition layer is\",\"opts\":[\"The airspace between the transition altitude and the transition level\",\"The airspace above the transition level\",\"The airspace below the transition altitude\"],\"ans\":0,\"exp\":\"Transition altitude at the bottom, transition level at the top, transition layer in between.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-103\",\"topic\":\"Altimetry\",\"stem\":\"The transition level\",\"opts\":[\"Is published for the aerodrome in the ENR section of the AIP\",\"Is the lowest flight level available for use above the transition altitude\",\"Is calculated and declared for an approach by the pilot-in-command\"],\"ans\":1,\"exp\":\"By definition, the transition level is the lowest usable flight level above the transition altitude. ATC decides it and passes it on - the pilot does not calculate it.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-104\",\"topic\":\"Altimetry\",\"stem\":\"At or below the transition altitude, vertical position is expressed as\",\"opts\":[\"Altitude, with QNH set\",\"Flight level, with 1013.2 hPa set\",\"Height, with QNH set\"],\"ans\":0,\"exp\":\"At or below the transition altitude: altitude on QNH. Above it: flight levels on 1013.2 hPa. Height is measured on QFE, not QNH.\",\"seenIn\":[\"Nov 2024 · OLODE 08\",\"Feb 2025 · OLODE 02\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-105\",\"topic\":\"Altimetry\",\"stem\":\"During descent, the altimeter is changed from 1013.2 hPa to QNH when passing the\",\"opts\":[\"Transition altitude\",\"Transition level\",\"Middle of the transition layer\"],\"ans\":1,\"exp\":\"Climbing: change to 1013.2 at the transition altitude. Descending: change to QNH at the transition level. In both cases the change happens at the first boundary you meet.\",\"seenIn\":[\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-106\",\"topic\":\"Instrument procedures\",\"stem\":\"The initial approach segment of an instrument approach begins at the\",\"opts\":[\"Final approach fix (FAF)\",\"Initial approach fix (IAF)\",\"Point of descent through the transition altitude\"],\"ans\":1,\"exp\":\"The initial segment runs from the IAF to the intermediate fix. The FAF is where the final segment begins.\",\"seenIn\":[\"Feb 2025 · OLODE 02\",\"Jan 2026 · OLODE 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-107\",\"topic\":\"Instrument procedures\",\"stem\":\"An instrument approach procedure can have up to how many segments?\",\"opts\":[\"3\",\"4\",\"5\"],\"ans\":2,\"exp\":\"Up to five: arrival, initial, intermediate, final and missed approach. Not every procedure has all five.\",\"seenIn\":[\"Jul 2025 · OLODE 05\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-108\",\"topic\":\"Instrument procedures\",\"stem\":\"The segment in which the aircraft is aligned with the runway and descends to land is the\",\"opts\":[\"Initial approach segment\",\"Intermediate approach segment\",\"Final approach segment\"],\"ans\":2,\"exp\":\"The final approach segment runs from the FAF (or FAP) to the MAPt - the part where you are lined up and descending to land. The intermediate segment is where speed and configuration are set up for it.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-109\",\"topic\":\"Instrument procedures\",\"stem\":\"The minimum sector altitude (MSA) based on a navigation facility applies within\",\"opts\":[\"15 NM\",\"25 NM\",\"30 NM\"],\"ans\":1,\"exp\":\"The MSA gives at least 1000 ft obstacle clearance within 25 NM (46 km) of the navigation aid, IAF or IF.\",\"seenIn\":[\"2022 · Regular 03\",\"Jun 2024 · Regular\",\"Oct 2024 · OLODE 07\",\"Jan 2025 · OLODE 01\",\"May 2026 · OLODE 04\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":6,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-110\",\"topic\":\"Instrument procedures\",\"stem\":\"The minimum obstacle clearance in the primary area of the initial approach segment is\",\"opts\":[\"300 m (1000 ft)\",\"150 m (500 ft)\",\"600 m (2000 ft)\"],\"ans\":0,\"exp\":\"300 m (1000 ft) in the initial segment, reducing to zero at the outer edge of the secondary area. It then reduces from 300 m to 150 m through the intermediate segment.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Oct 2024 · OLODE 07\",\"May 2026 · OLODE 04\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":4,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-111\",\"topic\":\"Instrument procedures\",\"stem\":\"The minimum obstacle clearance in the primary area of the intermediate approach segment\",\"opts\":[\"Is 150 m throughout\",\"Is 300 m throughout\",\"Reduces from 300 m to 150 m\"],\"ans\":2,\"exp\":\"The intermediate segment is the transition: its MOC reduces from 300 m (984 ft) to 150 m (492 ft).\",\"seenIn\":[\"Sep 2024 · Session 03\",\"Jan 2025 · OLODE 01\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-112\",\"topic\":\"Instrument procedures\",\"stem\":\"On an omnidirectional departure, turns are not started until the aircraft reaches a height above aerodrome elevation of at least\",\"opts\":[\"120 m (394 ft)\",\"150 m (500 ft)\",\"300 m (1000 ft)\"],\"ans\":0,\"exp\":\"Climb straight ahead on the runway centre line to 120 m (394 ft) before turning, and not sooner than 600 m from the start of the runway. Helicopters may turn at 90 m (295 ft).\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-113\",\"topic\":\"Instrument procedures\",\"stem\":\"The minimum obstacle clearance at the departure end of the runway (DER) is\",\"opts\":[\"Zero\",\"35 ft\",\"50 ft\"],\"ans\":0,\"exp\":\"Obstacle clearance is zero at the DER and grows at 0.8 % of the distance flown - the difference between the 3.3 % design gradient and the 2.5 % obstacle surface.\",\"seenIn\":[\"May 2026 · OLODE 04\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-114\",\"topic\":\"Instrument procedures\",\"stem\":\"A turn away from a designated track, followed by a turn in the opposite direction to intercept and follow the reciprocal of that track, is a\",\"opts\":[\"Procedure turn\",\"Racetrack procedure\",\"Base turn\"],\"ans\":0,\"exp\":\"That is the definition of a procedure turn. A racetrack uses two 180-degree turns in the same direction; a base turn has no opposite-direction turn.\",\"seenIn\":[\"May 2025 · OLODE 04\",\"Apr 2026 · OLODE 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-115\",\"topic\":\"Instrument procedures\",\"stem\":\"For a non-precision approach, a straight-in approach is acceptable if the angle between the final approach track and the runway centre line is\",\"opts\":[\"30 degrees or less\",\"40 degrees or less\",\"20 degrees or less\"],\"ans\":0,\"exp\":\"Thirty degrees or less. Beyond that, or if the descent gradient is too steep, the procedure becomes a circling approach.\",\"seenIn\":[\"Nov 2023 · OLODE 08\",\"May 2024 · OLODE 04\",\"Jul 2025 · OLODE 05\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-116\",\"topic\":\"Instrument procedures\",\"stem\":\"Aircraft approach categories are based on\",\"opts\":[\"1.3 x the stalling speed in clean configuration at minimum certified landing mass\",\"1.3 x the stalling speed in the landing configuration at minimum certified landing mass\",\"1.3 x the stalling speed in the landing configuration at maximum certified landing mass\"],\"ans\":2,\"exp\":\"Vat = 1.3 x Vso (or 1.23 x Vs1g, whichever is higher), in the landing configuration at maximum certificated landing mass.\",\"seenIn\":[\"Feb 2021\",\"Apr 2025 · Regular 01\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2021,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-117\",\"topic\":\"Instrument procedures\",\"stem\":\"The threshold speed (Vat) range for approach Category B is\",\"opts\":[\"Less than 91 kt\",\"91 to 120 kt\",\"121 to 140 kt\"],\"ans\":1,\"exp\":\"A below 91 kt, B 91-120, C 121-140, D 141-165, E 166-210 kt.\",\"seenIn\":[\"2022 · Regular 03\",\"Jul 2025 · OLODE 05\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-118\",\"topic\":\"Instrument procedures\",\"stem\":\"The threshold speed (Vat) range for approach Category A is\",\"opts\":[\"Less than 91 kt\",\"91 to 120 kt\",\"121 to 140 kt\"],\"ans\":0,\"exp\":\"Category A is below 91 kt at the threshold - light training aircraft live here.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-119\",\"topic\":\"Instrument procedures\",\"stem\":\"For a non-precision approach, the MDA/H is\",\"opts\":[\"Always 200 ft\",\"At or above the OCA/H\",\"Always 350 ft\"],\"ans\":1,\"exp\":\"The OCA/H is the lowest level at which the obstacle clearance criteria are met, so the MDA/H is set at or above it and is never a fixed figure.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Jan 2025 · OLODE 01\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-120\",\"topic\":\"Instrument procedures\",\"stem\":\"For Category A and B aircraft, the maximum descent gradient in the final approach segment is\",\"opts\":[\"3.0 %\",\"5 %\",\"6.5 %\"],\"ans\":2,\"exp\":\"Optimum 5.2 % (3 degrees); maximum 6.5 % for Categories A and B and 6.1 % for C to E.\",\"seenIn\":[\"2022 · Regular 03\",\"May 2024 · OLODE 04\",\"Dec 2024 · Regular 04\",\"Sep 2025 · Regular 03\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":5,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-121\",\"topic\":\"Instrument procedures\",\"stem\":\"On a non-precision approach, the missed approach is started\",\"opts\":[\"At the missed approach point (MAPt)\",\"At the final approach fix\",\"At the outer marker\"],\"ans\":0,\"exp\":\"On a non-precision approach, if the required visual reference is not established at the MAPt, go around at once. On a precision approach you go around at the DA/H.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Apr 2026 · OLODE 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-122\",\"topic\":\"Instrument procedures\",\"stem\":\"The obstacle clearance height (OCH) for a precision approach is\",\"opts\":[\"The lowest height above the relevant threshold elevation used in establishing compliance with the obstacle clearance criteria\",\"The height at which the aircraft must be established on the glide path\",\"A fixed height of 200 ft\"],\"ans\":0,\"exp\":\"OCA/H is the lowest altitude or height that meets the obstacle clearance criteria. OCA is referenced to mean sea level; OCH to the threshold (or aerodrome) elevation. The DA/H is set at or above it.\",\"seenIn\":[\"Dec 2024 · Regular 04\",\"Oct 2025 · OLODE 07\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-123\",\"topic\":\"Instrument procedures\",\"stem\":\"An instrument approach procedure is\",\"opts\":[\"A series of predetermined manoeuvres by reference to flight instruments, with specified protection from obstacles\",\"Any approach that needs two trained pilots\",\"An approach flown only with an ILS localizer and glide path\"],\"ans\":0,\"exp\":\"A set of predetermined manoeuvres, flown on instruments with obstacle protection, from the IAF (or an arrival route) to a point from which a landing can be completed - or to a hold or en-route clearance if not.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-124\",\"topic\":\"Instrument procedures\",\"stem\":\"A visual approach is\",\"opts\":[\"An approach by an IFR flight when part or all of an instrument approach is not completed and the approach is flown by visual reference to terrain\",\"Any approach flown by a VFR flight\",\"An ILS approach flown in good weather\"],\"ans\":0,\"exp\":\"A visual approach is an IFR flight choosing to finish its approach visually. A VFR flight simply lands under VFR - that is not a \\\"visual approach\\\" in the ATC sense.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Apr 2025 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-125\",\"topic\":\"Instrument procedures\",\"stem\":\"On a precision approach, the pilot shall not continue below the\",\"opts\":[\"MSA\",\"MDA\",\"DA/DH\"],\"ans\":2,\"exp\":\"Precision approaches and APV use a decision altitude or height; non-precision approaches use an MDA/H. At the DA/H, without the required visual reference, you go around.\",\"seenIn\":[\"Sep 2024 · Session 03\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-126\",\"topic\":\"Instrument procedures\",\"stem\":\"A surveillance radar approach (SRA) is a\",\"opts\":[\"Precision approach\",\"Non-precision approach\",\"Visual approach\"],\"ans\":1,\"exp\":\"An SRA gives azimuth guidance and advisory heights only - no glide path - so it is a non-precision approach. PAR is the radar approach that counts as precision.\",\"seenIn\":[\"Feb 2025 · OLODE 02\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-127\",\"topic\":\"Instrument procedures\",\"stem\":\"Aerodrome operating minima for a precision approach are expressed as\",\"opts\":[\"Visibility or RVR, and DA/H\",\"Ceiling only\",\"MSA and visibility\"],\"ans\":0,\"exp\":\"For precision approaches: visibility or RVR plus a decision altitude or height. For a non-precision approach it is visibility or RVR with an MDA/H, and sometimes a ceiling.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Feb 2025 · OLODE 02\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-128\",\"topic\":\"Aeronautical information\",\"stem\":\"In India, NOTAMs for military-controlled airfields used by domestic flights are issued in Series\",\"opts\":[\"A\",\"B\",\"D\"],\"ans\":2,\"exp\":\"Series D covers changes at military-controlled airfields used by domestic flights. Series A is international distribution; B is for information valid more than 30 minutes but less than 2 hours.\",\"seenIn\":[\"Feb 2025 · OLODE 02\",\"Jan 2026 · OLODE 01\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-129\",\"topic\":\"Aeronautical information\",\"stem\":\"In India, a NOTAM whose information is valid for less than 2 hours is issued in Series\",\"opts\":[\"A\",\"B\",\"D\"],\"ans\":1,\"exp\":\"Series B carries information valid for more than 30 minutes but less than 2 hours. Series A is for information of international importance lasting more than 2 hours.\",\"seenIn\":[\"Jan 2026 · OLODE 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-130\",\"topic\":\"Human performance\",\"stem\":\"Hyperventilation is\",\"opts\":[\"Breathing in excess of the body's needs (over-breathing)\",\"Breathing too slowly for the body's needs\",\"Normal breathing at high altitude\"],\"ans\":0,\"exp\":\"Hyperventilation is over-breathing: ventilating the lungs more than the body needs. The usual cause is anxiety or stress, and good training is the best defence.\",\"seenIn\":[\"Nov 2024 · OLODE 08\",\"Jan 2025 · OLODE 01\",\"Oct 2025 · OLODE 07\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-131\",\"topic\":\"Human performance\",\"stem\":\"Hyperventilation results in\",\"opts\":[\"Too much carbon dioxide in the blood\",\"Too little carbon dioxide in the blood\",\"No change in the blood's carbon dioxide\"],\"ans\":1,\"exp\":\"Over-breathing washes carbon dioxide out of the blood and the blood becomes alkaline. Breathing into a paper bag brings the CO2 level back up, and the brain slows the breathing.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Apr 2026 · OLODE 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-132\",\"topic\":\"Human performance\",\"stem\":\"The risk of hypoxia increases\",\"opts\":[\"As altitude decreases\",\"As altitude increases\",\"With an increase in humidity\"],\"ans\":1,\"exp\":\"Higher means lower air pressure, so lower oxygen partial pressure, even though the air is still about 21 % oxygen. The higher you go, the faster hypoxia sets in.\",\"seenIn\":[\"Apr 2025 · Regular 01\",\"Jun 2026 · Regular 02\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-133\",\"topic\":\"Human performance\",\"stem\":\"Hypoxia is\",\"opts\":[\"A lack of both oxygen and carbon dioxide\",\"A deficiency of oxygen in the body tissues, enough to impair their function\",\"An excess of nitrogen in the blood\"],\"ans\":1,\"exp\":\"Hypoxia is oxygen deprivation of the body's tissues, the brain first. For pilots the main cause is breathing air at low pressure at altitude. Excess nitrogen coming out of solution is decompression sickness.\",\"seenIn\":[\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-134\",\"topic\":\"Human performance\",\"stem\":\"A dangerous early symptom of hypoxia, because the pilot feels fine, is\",\"opts\":[\"Euphoria\",\"Cyanosis\",\"Convulsions\"],\"ans\":0,\"exp\":\"Hypoxia may start with a feeling of well-being - euphoria - so the pilot is often the last person to suspect anything. Cyanosis and convulsions come later.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"May 2026 · OLODE 04\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":3,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-135\",\"topic\":\"Human performance\",\"stem\":\"Oxygen is carried in the blood mainly by\",\"opts\":[\"Plasma\",\"White blood cells\",\"Haemoglobin in the red blood cells\"],\"ans\":2,\"exp\":\"Oxygen binds to haemoglobin in the red cells as blood passes the alveoli. That is also why carbon monoxide is so dangerous: it grabs haemoglobin far more readily than oxygen does.\",\"seenIn\":[\"Feb 2021\",\"2022 · Regular 03\",\"Dec 2022 · Session 04\",\"Nov 2023 · OLODE 08\",\"Sep 2024 · Session 03\",\"Jan 2025 · OLODE 01\",\"Jul 2025 · OLODE 05\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":8,\"years\":[2021,2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-136\",\"topic\":\"Human performance\",\"stem\":\"The two physiologically important gases in breathing are\",\"opts\":[\"Oxygen and nitrogen\",\"Oxygen and carbon dioxide\",\"Nitrogen and carbon dioxide\"],\"ans\":1,\"exp\":\"The body takes in oxygen and gives off carbon dioxide, and the CO2 level drives breathing. Nitrogen matters in decompression sickness, not in normal gas exchange.\",\"seenIn\":[\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-137\",\"topic\":\"Human performance\",\"stem\":\"After a rapid decompression at high altitude, the crew's first actions are to\",\"opts\":[\"Put on oxygen masks, then begin an emergency descent\",\"Stay at the same level and assess the damage\",\"Climb above the weather\"],\"ans\":0,\"exp\":\"Oxygen first - time of useful consciousness may be only seconds. Then an emergency descent to about 10,000 ft, where everyone can breathe without supplementary oxygen.\",\"seenIn\":[\"Apr 2026 · OLODE 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-138\",\"topic\":\"Human performance\",\"stem\":\"Decompression sickness is caused by\",\"opts\":[\"Nitrogen coming out of solution as bubbles in the body\",\"Oxygen bubbles forming in the blood\",\"Carbon monoxide in the blood\"],\"ans\":0,\"exp\":\"Henry's law: nitrogen dissolved in the body at higher pressure comes out as bubbles when the pressure drops quickly - the bends, the chokes and nervous-system symptoms.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Sep 2024 · Session 03\",\"Nov 2024 · OLODE 08\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":4,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-139\",\"topic\":\"Human performance\",\"stem\":\"Decompression sickness can occur even at low altitude if the pilot has\",\"opts\":[\"Been scuba diving with compressed air shortly before the flight\",\"Eaten a heavy meal\",\"Slept less than 8 hours\"],\"ans\":0,\"exp\":\"Diving with compressed air loads the body with extra nitrogen. Fly soon afterwards and even a modest drop in pressure can release it as bubbles - hence the rule not to fly for 24 hours after diving to 30 ft or more.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-140\",\"topic\":\"Human performance\",\"stem\":\"Which statement about carbon monoxide is true?\",\"opts\":[\"It is always present in the lungs\",\"Mixed with oxygen it has no physiological effect\",\"It is present in cigarette smoke\"],\"ans\":2,\"exp\":\"Cigarette smoke contains carbon monoxide, which binds to haemoglobin over 200 times more readily than oxygen. Every cigarette takes part of your oxygen-carrying capacity out of use for hours.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Oct 2025 · OLODE 07\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-141\",\"topic\":\"Human performance\",\"stem\":\"Smoking a packet of cigarettes a day reduces the blood's capacity to carry oxygen by about\",\"opts\":[\"1-2 %\",\"5-8 %\",\"20-25 %\"],\"ans\":1,\"exp\":\"A pack a day takes away about 5-8 % of oxygen-carrying capacity, because carbon monoxide ties up haemoglobin. It also raises the risk of carbon monoxide poisoning.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-142\",\"topic\":\"Human performance\",\"stem\":\"A smoker may experience symptoms of hypoxia at a lower altitude than a non-smoker - at about\",\"opts\":[\"7,000 ft\",\"10,000 ft\",\"14,000 ft\"],\"ans\":0,\"exp\":\"A non-smoker typically meets hypoxia symptoms around 10,000 ft; a smoker can meet them around 7,000 ft - a 3,000 ft penalty.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Jun 2026 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-143\",\"topic\":\"Human performance\",\"stem\":\"Which is true about the SHEL model?\",\"opts\":[\"All components are equally important, as error arises from mismatches between them\",\"Hardware is the hub, so the other components should be matched to the best hardware\",\"Liveware is the hub, so the non-human components should be adapted and matched to it\"],\"ans\":2,\"exp\":\"The human (liveware) sits at the centre of the SHEL model. Software, hardware, environment and other people are matched to the human - not the other way round.\",\"seenIn\":[\"Oct 2025 · OLODE 07\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-144\",\"topic\":\"Human performance\",\"stem\":\"Spatial disorientation mainly involves the\",\"opts\":[\"Vestibular system of the inner ear\",\"Sense of smell\",\"Sense of hearing\"],\"ans\":0,\"exp\":\"The vestibular apparatus of the inner ear tells you which way is up. Without a visual horizon it is easily fooled, and that is spatial disorientation.\",\"seenIn\":[\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-145\",\"topic\":\"Human performance\",\"stem\":\"The composition of dry air in the lower atmosphere is about\",\"opts\":[\"78 % nitrogen, 21 % oxygen, 0.93 % argon\",\"25 % oxygen, 50 % nitrogen, 20 % argon\",\"80 % oxygen, 18 % nitrogen, 1 % argon\"],\"ans\":0,\"exp\":\"Nitrogen 78.08 %, oxygen 20.95 %, argon 0.93 %, then traces of carbon dioxide and other gases. Water vapour varies and is counted separately.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Oct 2025 · OLODE 07\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-146\",\"topic\":\"Human performance\",\"stem\":\"The percentage of oxygen in the atmosphere at 35,000 ft is about\",\"opts\":[\"21 %\",\"5 %\",\"50 %\"],\"ans\":0,\"exp\":\"The percentage stays about 21 % throughout the lower atmosphere. What falls with height is the pressure, so each breath contains less oxygen.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Jan 2025 · OLODE 01\",\"May 2025 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-147\",\"topic\":\"Human performance\",\"stem\":\"As altitude increases\",\"opts\":[\"The percentage of oxygen in the air falls\",\"The percentage of oxygen stays about 21 %, but air density and oxygen partial pressure fall\",\"Air density increases\"],\"ans\":1,\"exp\":\"The mix stays the same - about 21 % oxygen - but the air gets thinner, so the partial pressure of oxygen falls. That drop in partial pressure is what causes altitude hypoxia.\",\"seenIn\":[\"Apr 2025 · Regular 01\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-148\",\"topic\":\"Human performance\",\"stem\":\"Atmospheric pressure is about half its sea-level value at\",\"opts\":[\"10,000 ft\",\"18,000 ft\",\"25,000 ft\"],\"ans\":1,\"exp\":\"About 18,000 ft for half, and about 36,000 ft for a quarter. The oxygen available falls in the same proportion.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Oct 2023 · FC 07\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-149\",\"topic\":\"Human performance\",\"stem\":\"The ISA temperature lapse rate in the troposphere is\",\"opts\":[\"1.98 °C per 1000 ft\",\"3 °C per 1000 ft\",\"1 °C per 1000 ft\"],\"ans\":0,\"exp\":\"1.98 °C per 1000 ft (6.5 °C per km) up to the tropopause at 36,090 ft, where the temperature settles at -56.5 °C.\",\"seenIn\":[\"Feb 2025 · OLODE 02\",\"Oct 2025 · OLODE 07\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-150\",\"topic\":\"Human performance\",\"stem\":\"The amount of water vapour in the atmosphere, as altitude increases,\",\"opts\":[\"Decreases\",\"Increases\",\"Stays the same\"],\"ans\":0,\"exp\":\"Almost all water vapour is in the lowest few kilometres, because cold air holds far less. Air at cruise levels is very dry, which is why dehydration is a real issue on long flights.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-151\",\"topic\":\"Human performance\",\"stem\":\"FL150 expressed in metres is about\",\"opts\":[\"4572 m\",\"4000 m\",\"5000 m\"],\"ans\":0,\"exp\":\"FL150 is 15,000 ft, and 15,000 x 0.3048 = 4572 m.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-152\",\"topic\":\"Human performance\",\"stem\":\"Breathing is controlled by the\",\"opts\":[\"Medulla of the brain\",\"Heart\",\"Lungs themselves\"],\"ans\":0,\"exp\":\"The respiratory centre is in the medulla. It works automatically, driven mainly by the level of carbon dioxide in the blood, and you can override it only to a limited extent.\",\"seenIn\":[\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-153\",\"topic\":\"Human performance\",\"stem\":\"Hail is associated with which cloud?\",\"opts\":[\"Cumulonimbus (Cb)\",\"Stratus (St)\",\"Nimbostratus (Ns)\"],\"ans\":0,\"exp\":\"The correct answer is: Cumulonimbus (Cb).\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Dec 2024 · Regular 04\",\"May 2025 · OLODE 04\",\"Oct 2025 · OLODE 07\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":5,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-154\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Which convention deals with the unlawful seizure of aircraft (hijacking)?\",\"opts\":[\"Tokyo Convention, 1963\",\"Hague Convention, 1970\",\"Warsaw Convention, 1929\"],\"ans\":1,\"exp\":\"The Hague Convention of 1970 defines unlawful seizure of aircraft in flight and requires States to extradite or prosecute hijackers. Tokyo deals with offences on board generally; Warsaw with carrier liability.\",\"seenIn\":[\"Aug 2022\",\"Jan 2024 · Regular (Day 2)\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":3,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-155\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"ICAO Standards and Recommended Practices are published as\",\"opts\":[\"The Annexes to the Chicago Convention\",\"The PANS documents\",\"The Regional Supplementary Procedures\"],\"ans\":0,\"exp\":\"SARPs are the 19 Annexes. The PANS (such as Doc 4444 and Doc 8168) and the Regional Supplementary Procedures (Doc 7030) sit below them in the ICAO publication hierarchy.\",\"seenIn\":[\"Sep 2024 · Session 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-156\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"The first freedom of the air is the right to\",\"opts\":[\"Fly across the territory of another State without landing\",\"Carry traffic between two foreign States\",\"Land in another State for non-traffic purposes\"],\"ans\":0,\"exp\":\"First freedom: overfly another State without landing. Second: land there for non-traffic purposes, such as refuelling. Together they are the two technical freedoms.\",\"seenIn\":[\"Feb 2021\",\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2021,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-157\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"The second freedom of the air is the right to\",\"opts\":[\"Land in another State for non-traffic purposes, without loading or unloading passengers or cargo\",\"Fly over another State without landing\",\"Carry passengers from your own State to another State\"],\"ans\":0,\"exp\":\"A technical stop - for fuel or maintenance, for example - with no passengers or cargo put down or picked up. Carrying passengers from your own State to another is the third freedom.\",\"seenIn\":[\"2022 · Regular 03\",\"Nov 2024 · OLODE 08\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-158\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"The fifth freedom of the air is the right to\",\"opts\":[\"Pick up traffic in a second State and carry it to a third State, on a service that begins or ends in your own State\",\"Overfly a State without landing\",\"Carry traffic between two points inside another State\"],\"ans\":0,\"exp\":\"Fifth freedom: pick up in State B and deliver to State C on a service linked to your home State A. Carrying traffic between two points inside another State is cabotage.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-159\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Under Article 1 of the Chicago Convention, every State has\",\"opts\":[\"Complete and exclusive sovereignty over the airspace above its territory\",\"Shared sovereignty with ICAO over its airspace\",\"Sovereignty only up to FL245\"],\"ans\":0,\"exp\":\"Complete and exclusive sovereignty over the airspace above its territory - the founding principle of air law. Territory means the land areas and the adjacent territorial waters.\",\"seenIn\":[\"Apr 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-160\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"The Montreal Protocol of 1988 extended the Montreal Convention to cover\",\"opts\":[\"Acts of violence at airports serving international civil aviation\",\"Carriage of passengers and baggage\",\"The marking of plastic explosives\"],\"ans\":0,\"exp\":\"The 1988 Protocol brought violence at international airports and the destruction of airport facilities under the 1971 Montreal regime. Marking of plastic explosives is the separate Montreal Convention of 1991.\",\"seenIn\":[\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-161\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"How many regional offices does ICAO have?\",\"opts\":[\"12\",\"8\",\"7\"],\"ans\":2,\"exp\":\"Seven regional offices serve nine air navigation regions. The Asia and Pacific office, which covers India, is in Bangkok.\",\"seenIn\":[\"Apr 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-162\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Aircraft nationality and registration marks are covered by ICAO\",\"opts\":[\"Annex 14\",\"Annex 7\",\"Annex 1\"],\"ans\":1,\"exp\":\"Annex 7 is Aircraft Nationality and Registration Marks. Annex 14 is Aerodromes and Annex 1 is Personnel Licensing.\",\"seenIn\":[\"Apr 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-163\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"ICAO Doc 7910 lists\",\"opts\":[\"Four-letter location indicators\",\"Aircraft type designators\",\"Regional supplementary procedures\"],\"ans\":0,\"exp\":\"Doc 7910 is Location Indicators - the four-letter codes such as VIDP and VABB. Aircraft type designators are in Doc 8643, and regional procedures are in Doc 7030.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-164\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"The right of aircraft on NON-scheduled flights to fly into or across another State and to make stops for non-traffic purposes without prior permission applies to\",\"opts\":[\"Aircraft of scheduled air services only\",\"Aircraft not engaged in scheduled international air services\",\"Military aircraft only\"],\"ans\":1,\"exp\":\"Article 5 gives non-scheduled flights the first two freedoms without prior permission, although the State overflown may require them to land. A scheduled international service needs that State's permission.\",\"seenIn\":[\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-165\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"A State that cannot comply with an ICAO Standard must\",\"opts\":[\"Notify ICAO of the difference\",\"Leave ICAO\",\"Wait for the next ICAO Assembly before acting\"],\"ans\":0,\"exp\":\"A State that finds it impracticable to comply with a Standard must notify ICAO immediately of the difference. ICAO then informs the other States, and the difference is also published in the State's AIP.\",\"seenIn\":[\"2022 · Regular 03\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-166\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Schedule II of the Aircraft Rules, 1937 deals with\",\"opts\":[\"Flying over prohibited areas\",\"Personnel licences\",\"Registration of aircraft\"],\"ans\":1,\"exp\":\"The correct answer is: Personnel licences.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-167\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"The nationality mark of an Indian civil aircraft is\",\"opts\":[\"VT\",\"IN\",\"VU\"],\"ans\":0,\"exp\":\"Indian civil aircraft carry the nationality mark VT, followed by the three-letter registration mark - VT-ABC, for example.\",\"seenIn\":[\"Oct 2023 · FC 07\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-168\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"Which letter group may NOT be used as a registration mark, because it could be confused with a radio signal?\",\"opts\":[\"TTT\",\"VT-ABC\",\"VT-KLM\"],\"ans\":0,\"exp\":\"Registration marks may not use combinations that could be mistaken for distress, urgency or safety signals - SOS, XXX, PAN or TTT - or for Q-code groups.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-169\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"In India, the regulation and oversight of security against acts of unlawful interference is the responsibility of\",\"opts\":[\"The Bureau of Civil Aviation Security (BCAS)\",\"The Aircraft Accident Investigation Bureau (AAIB)\",\"The Directorate of Flight Training\"],\"ans\":0,\"exp\":\"The BCAS, headed by a Director General appointed by the Central Government, is responsible for regulating and overseeing civil aviation security in India.\",\"seenIn\":[\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-170\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"In India, the AIP is published by\",\"opts\":[\"The DGCA\",\"The Airports Authority of India (AAI)\",\"The Ministry of Defence\"],\"ans\":1,\"exp\":\"The AAI provides the aeronautical information service and publishes the AIP. Aeronautical Information Circulars (AICs) come from the DGCA - a favourite trap.\",\"seenIn\":[\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-171\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"DGCA Civil Aviation Requirements (CAR) Section 7 deals with\",\"opts\":[\"Flight crew standards, training and licensing\",\"Airworthiness\",\"Aerodrome standards\"],\"ans\":0,\"exp\":\"Section 7 is Flight Crew Standards, Training and Licensing - where the medical, FDTL and RTR requirements sit. Airworthiness is Section 2.\",\"seenIn\":[\"Feb 2025 · OLODE 02\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-172\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"The minimum age at which a person may have sole control of an aircraft in motion (and hold a Student Pilot's Licence) is\",\"opts\":[\"14 years\",\"16 years\",\"18 years\"],\"ans\":1,\"exp\":\"Nobody under 16 may have sole control of an aircraft in motion, and the SPL minimum age is also 16. PPL is 17, CPL 18 and ATPL 21.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Nov 2024 · OLODE 08\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-173\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"The minimum age for the issue of a Commercial Pilot's Licence is\",\"opts\":[\"17 years\",\"18 years\",\"21 years\"],\"ans\":1,\"exp\":\"Eighteen years for the CPL. The PPL minimum is 17 and the ATPL minimum is 21.\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-174\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"The minimum age for the issue of an Airline Transport Pilot's Licence is\",\"opts\":[\"18 years\",\"21 years\",\"23 years\"],\"ans\":1,\"exp\":\"ATPL 21 years - the highest of the pilot licences. The CPL is 18.\",\"seenIn\":[\"Nov 2024 · OLODE 08\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-175\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"No person may act as pilot-in-command or co-pilot in commercial air transport after reaching the age of\",\"opts\":[\"60 years\",\"65 years\",\"70 years\"],\"ans\":1,\"exp\":\"Sixty-five is the hard ceiling. Between 60 and 65, a pilot may fly commercial air transport only in a multi-crew aircraft with the other pilot under 60.\",\"seenIn\":[\"Oct 2023 · FC 07\",\"Apr 2025 · Regular 01\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-176\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"Following the 2023 amendment to Rule 39C, a Commercial Pilot's Licence is valid for\",\"opts\":[\"2 years\",\"5 years\",\"10 years\"],\"ans\":2,\"exp\":\"GSR 733(E) of 10 October 2023 raised the CPL and ATPL from five to ten years. Much of the older study material still says five - it is out of date.\",\"seenIn\":[\"Jun 2024 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-177\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"A Private Pilot's Licence is valid for\",\"opts\":[\"5 years\",\"10 years\",\"2 years\"],\"ans\":1,\"exp\":\"The PPL is valid for ten years under Rule 39C. Its medical assessment is valid for 24 months.\",\"seenIn\":[\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-178\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"The medical assessment for a Private Pilot's Licence is valid for\",\"opts\":[\"12 months\",\"24 months\",\"6 months\"],\"ans\":1,\"exp\":\"The PPL medical is valid for 24 months under Rule 39C. The CPL and ATPL medical is 12 months.\",\"seenIn\":[\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-179\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"For a CPL or ATPL holder under 40, the medical assessment is valid for\",\"opts\":[\"6 months\",\"12 months\",\"24 months\"],\"ans\":1,\"exp\":\"Twelve months for CPL and ATPL holders under 40 - both the Aircraft Rules and the medical CAR agree on this.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-180\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"How many classes of medical assessment does the DGCA issue?\",\"opts\":[\"Two\",\"Three\",\"Four\"],\"ans\":1,\"exp\":\"Three. Class 1 is for CPL, ATPL and PPL with instrument rating privileges; Class 2 for PPL and student licences; Class 3 for air traffic controllers.\",\"seenIn\":[\"Apr 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-181\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"A pilot assessed at English Language Proficiency Level 4 must be re-evaluated every\",\"opts\":[\"3 years\",\"6 years\",\"1 year\"],\"ans\":0,\"exp\":\"Level 4 (Operational) is re-evaluated every 3 years and Level 5 every 6 years. Level 6 (Expert) needs no re-evaluation.\",\"seenIn\":[\"Dec 2024 · Regular 04\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-182\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"A prisoner may be carried on an aircraft only\",\"opts\":[\"With a written permit from the DGCA (or an officer authorised under the rule)\",\"With the permission of the pilot-in-command\",\"Without any permission, if escorted by police\"],\"ans\":0,\"exp\":\"Rule 24B: no prisoner may be taken on board except under a written permit from the Director-General or one of the officers the rule names, and subject to its conditions.\",\"seenIn\":[\"Nov 2024 · OLODE 08\",\"Dec 2024 · Regular 04\",\"Feb 2025 · OLODE 02\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":4,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-183\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"Separate sheets of printed paper (leaflets) may be dropped from an aircraft only with the prior written permission of the\",\"opts\":[\"DGCA\",\"District Magistrate or Commissioner of Police\",\"Aerodrome operator\"],\"ans\":1,\"exp\":\"Rule 26 allows leaflets or flower petals to be dropped only with the prior written permission of the District Magistrate or Commissioner of Police, from a suitable aircraft, observing the minimum safe heights.\",\"seenIn\":[\"2022 · Regular 03\",\"Oct 2024 · OLODE 07\",\"Jul 2025 · OLODE 05\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-184\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"Discretionary fuel is carried at the discretion of the\",\"opts\":[\"Pilot-in-command\",\"DGCA\",\"Air traffic controller\"],\"ans\":0,\"exp\":\"Discretionary fuel is the extra fuel the pilot-in-command decides to carry on top of the planned minimum.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-185\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"For a turbine-engined aeroplane, final reserve fuel is the fuel to fly for\",\"opts\":[\"30 minutes at holding speed at 1500 ft above aerodrome elevation in standard conditions\",\"45 minutes at cruise speed\",\"2 hours at normal cruise consumption\"],\"ans\":0,\"exp\":\"Turbine: 30 minutes holding at 450 m (1500 ft) above the aerodrome in standard conditions. For reciprocating-engine aeroplanes it is 45 minutes.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-186\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"A reciprocating-engine aeroplane flying to an isolated aerodrome (no destination alternate available) must carry reserve fuel for\",\"opts\":[\"45 minutes plus 15 % of the planned cruise time, or 2 hours, whichever is less\",\"30 minutes at 1500 ft\",\"Destination plus 45 minutes only\"],\"ans\":0,\"exp\":\"For an isolated aerodrome: 45 minutes plus 15 % of the time planned at cruising level, or two hours, whichever is less - final reserve included. A turbine aeroplane carries two hours at normal cruise consumption instead.\",\"seenIn\":[\"Aug 2022\",\"Dec 2022 · Session 04\",\"Jan 2025 · OLODE 01\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-187\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"After donating blood, an active pilot should not fly for at least\",\"opts\":[\"12 hours\",\"24 hours\",\"48 hours\"],\"ans\":2,\"exp\":\"Active pilots should avoid donating blood; if they do, they should wait at least 48 hours before flying. Plasma recovers in hours, but the red cell mass takes weeks.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-188\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"After scuba diving with compressed air, a pilot should not fly within\",\"opts\":[\"4 hours\",\"12 hours\",\"24 hours\"],\"ans\":2,\"exp\":\"As a general rule, do not fly within 24 hours of diving - and certainly not the same day. Nitrogen absorbed on the dive can come out as bubbles at even a modest cabin altitude.\",\"seenIn\":[\"2022 · Regular 03\",\"Dec 2022 · Session 04\",\"Nov 2024 · OLODE 08\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-189\",\"topic\":\"Rules of the air & signals\",\"stem\":\"An aircraft is overtaking another if it approaches from the rear on a line forming an angle with the other's plane of symmetry of less than\",\"opts\":[\"50 degrees\",\"70 degrees\",\"60 degrees\"],\"ans\":1,\"exp\":\"Less than 70 degrees - close enough behind that at night it could see neither of the other aircraft's wing-tip navigation lights. The aircraft being overtaken has right of way, and the overtaking aircraft alters heading to the right.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-190\",\"topic\":\"Rules of the air & signals\",\"stem\":\"An IFR flight in IMC suffers a total radio communication failure. It should\",\"opts\":[\"Continue according to the current flight plan, as the rules for this case prescribe\",\"Land at the nearest suitable aerodrome and report to ATS\",\"Try to contact another aircraft for relay and hold until contact is made\"],\"ans\":0,\"exp\":\"In IMC you keep to the plan: hold the last assigned level and speed for the set time, follow the route to the destination aid, and land within 30 minutes of your ETA or EAT. \\\"Land at the nearest aerodrome\\\" is the VMC answer.\",\"seenIn\":[\"May 2022\",\"Jul 2023 · OLODE\",\"Dec 2023 · Regular\",\"Sep 2024 · Session 03\",\"Jan 2025 · OLODE 01\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":6,\"years\":[2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-191\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A black letter \\\"C\\\" displayed vertically against a yellow background indicates\",\"opts\":[\"The location of the control tower\",\"The location of the air traffic services reporting office\",\"Rest-room facilities for visiting pilots\"],\"ans\":1,\"exp\":\"The yellow \\\"C\\\" marks the ATS reporting office - where a visiting pilot reports.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-192\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A series of red flashes from the tower to an aircraft in flight means\",\"opts\":[\"Return for landing\",\"Aerodrome unsafe, do not land\",\"Give way and continue circling\"],\"ans\":1,\"exp\":\"Red flashes in flight: aerodrome unsafe, do not land. Steady red means give way and keep circling; green flashes mean return for landing.\",\"seenIn\":[\"2022 · Regular 03\",\"Dec 2023 · Regular\",\"Oct 2024 · OLODE 07\",\"Apr 2025 · Regular 01\"],\"undated\":false,\"times\":4,\"years\":[2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-193\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A series of red flashes from the tower to an aircraft on the ground means\",\"opts\":[\"Stop\",\"Taxi clear of the landing area in use\",\"Return to starting point on the aerodrome\"],\"ans\":1,\"exp\":\"On the ground: red flashes = taxi clear of the landing area in use. Steady red = stop. White flashes = return to starting point.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Dec 2024 · Regular 04\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-194\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A series of green flashes from the tower to an aircraft on the ground means\",\"opts\":[\"Cleared for take-off\",\"Cleared to taxi\",\"Return to starting point\"],\"ans\":1,\"exp\":\"On the ground, green flashes = cleared to taxi and steady green = cleared for take-off. The same green flashes to an aircraft in flight mean \\\"return for landing\\\".\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-195\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A series of green flashes from the tower to an aircraft in flight means\",\"opts\":[\"Cleared to land\",\"Return for landing\",\"Land at this aerodrome and proceed to apron\"],\"ans\":1,\"exp\":\"In flight: green flashes = return for landing; steady green = cleared to land; white flashes = land at this aerodrome and proceed to the apron.\",\"seenIn\":[\"Aug 2022\",\"Nov 2024 · OLODE 08\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-196\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A red pyrotechnic (red flare) fired to an aircraft in flight means\",\"opts\":[\"Notwithstanding any previous instructions, do not land for the time being\",\"Land immediately\",\"Return to the departure aerodrome\"],\"ans\":0,\"exp\":\"A red flare overrides everything you have been told: do not land for the time being.\",\"seenIn\":[\"Nov 2024 · OLODE 08\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-197\",\"topic\":\"Rules of the air & signals\",\"stem\":\"In daylight, an aircraft on the ground acknowledges a tower light signal by\",\"opts\":[\"Moving its ailerons or rudder\",\"Switching its navigation lights off and on once\",\"Rocking its wings\"],\"ans\":0,\"exp\":\"On the ground by day: move the ailerons or rudder. At night: flash the landing lights (or navigation lights) on and off twice. In flight by day: rock the wings.\",\"seenIn\":[\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-198\",\"topic\":\"Rules of the air & signals\",\"stem\":\"Two power-driven aeroplanes are converging at about the same level. Which gives way?\",\"opts\":[\"The one that has the other on its right\",\"The one that has the other on its left\",\"The faster one\"],\"ans\":0,\"exp\":\"The aircraft that has the other on its right gives way. So a single-engine aircraft that sees a multi-engine aircraft converging from its left has right of way - the number of engines does not matter.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Oct 2024 · OLODE 07\",\"Nov 2024 · OLODE 08\",\"May 2025 · OLODE 04\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-199\",\"topic\":\"Rules of the air & signals\",\"stem\":\"Crosses of a single contrasting colour, yellow or white, displayed horizontally on a runway or taxiway indicate\",\"opts\":[\"An area unfit for the movement of aircraft\",\"Glider flying in progress\",\"A closed aerodrome for helicopters only\"],\"ans\":0,\"exp\":\"Crosses on a runway or taxiway, or on part of one, mark an area unfit for the movement of aircraft.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"May 2024 · OLODE 04\",\"Nov 2024 · OLODE 08\"],\"undated\":false,\"times\":3,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-200\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A horizontal red square panel with yellow diagonals in the signal area means\",\"opts\":[\"Landing is prohibited, and the prohibition is liable to be prolonged\",\"Special precautions are needed when landing\",\"Gliders are flying\"],\"ans\":0,\"exp\":\"Red panel with yellow diagonals (both) = landings prohibited for some time. With only ONE yellow diagonal = special precautions needed because of the bad state of the manoeuvring area.\",\"seenIn\":[\"Sep 2024 · Session 03\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-201\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A white dumb-bell with a black bar across each circular end, in the signal area, means\",\"opts\":[\"Land and take off on runways only; other manoeuvres need not be confined to runways and taxiways\",\"Land, take off and taxi on runways and taxiways only\",\"Use taxiways only\"],\"ans\":0,\"exp\":\"The plain dumb-bell means land, take off and taxi on runways and taxiways only. Adding the black bars relaxes it: only landing and take-off must be on runways.\",\"seenIn\":[\"Feb 2021\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2021,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-202\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A double white cross displayed horizontally in the signal area indicates\",\"opts\":[\"Glider flights are being performed\",\"The area is unfit for movement\",\"Right-hand circuit in force\"],\"ans\":0,\"exp\":\"A double white cross means gliders are using the aerodrome.\",\"seenIn\":[\"Feb 2025 · OLODE 02\",\"May 2025 · OLODE 04\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-203\",\"topic\":\"Rules of the air & signals\",\"stem\":\"By day or night, a series of projectiles fired from the ground at 10-second intervals, bursting red and green, warns an aircraft that\",\"opts\":[\"It is flying in, or about to enter, a restricted, prohibited or danger area\",\"A military exercise is complete\",\"It must land at the nearest aerodrome\"],\"ans\":0,\"exp\":\"Red and green stars every 10 seconds tell an unauthorised aircraft it is in, or about to enter, a restricted, prohibited or danger area and must take remedial action.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-204\",\"topic\":\"Rules of the air & signals\",\"stem\":\"The marshalling signal \\\"cut engines\\\" is\",\"opts\":[\"Arm and wand extended at shoulder level, then drawn across the throat in a slicing motion\",\"Both arms crossed above the head\",\"Arms moved downwards in a patting gesture\"],\"ans\":0,\"exp\":\"Cut engines: a slicing motion across the throat. Crossed wands above the head is emergency stop; patting downwards is slow down.\",\"seenIn\":[\"Nov 2023 · OLODE 08\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-205\",\"topic\":\"Rules of the air & signals\",\"stem\":\"At and above 3050 m (10,000 ft) AMSL, the minimum flight visibility for VMC is\",\"opts\":[\"5 km\",\"8 km\",\"1500 m\"],\"ans\":1,\"exp\":\"Eight km at and above 10,000 ft AMSL (or FL100 where the transition altitude is lower), with 1500 m horizontal and 1000 ft vertical clearance from cloud. Below 10,000 ft it is 5 km.\",\"seenIn\":[\"Nov 2024 · OLODE 08\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-206\",\"topic\":\"Rules of the air & signals\",\"stem\":\"In Class F or G airspace at or below 900 m (3000 ft) AMSL (or 1000 ft above terrain), the VMC minima are\",\"opts\":[\"5 km flight visibility, clear of cloud and with the surface in sight\",\"8 km flight visibility, 1500 m from cloud\",\"1500 m flight visibility and 1000 ft below cloud\"],\"ans\":0,\"exp\":\"Low down in uncontrolled airspace: 5 km visibility, clear of cloud and in sight of the surface. The ATS authority may allow a lower visibility (not below 1500 m) for slow aircraft.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-207\",\"topic\":\"Rules of the air & signals\",\"stem\":\"Over terrain that is NOT high or mountainous, and where no minimum IFR altitude is established, an IFR flight shall be at least\",\"opts\":[\"300 m (1000 ft) above the highest obstacle within 8 km of its estimated position\",\"150 m (500 ft) above the highest obstacle within 5 km\",\"600 m (2000 ft) above the highest obstacle within 8 km\"],\"ans\":0,\"exp\":\"Elsewhere: 1000 ft above the highest obstacle within 8 km. Over high or mountainous terrain the figure doubles to 2000 ft, still within 8 km.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Nov 2024 · OLODE 08\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-208\",\"topic\":\"Rules of the air & signals\",\"stem\":\"An IFR flight that encounters VMC shall not cancel its IFR flight unless\",\"opts\":[\"It expects to continue for a reasonable time in uninterrupted VMC\",\"ATC orders it to\",\"It is below FL100\"],\"ans\":0,\"exp\":\"Only cancel IFR if you expect uninterrupted VMC for a reasonable period. Cancelling and then running back into cloud is exactly what the rule prevents.\",\"seenIn\":[\"Sep 2024 · Session 03\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-209\",\"topic\":\"Rules of the air & signals\",\"stem\":\"If the average true airspeed at cruising level varies from the flight plan by ___ or more, ATS must be informed\",\"opts\":[\"2 %\",\"3 %\",\"5 %\"],\"ans\":2,\"exp\":\"A TAS change of plus or minus 5 % must be reported. A time estimate in error by more than 3 minutes must also be revised.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-210\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A revised estimate must be passed to ATS when the estimate for the next reporting point, FIR boundary or destination is in error by more than\",\"opts\":[\"3 minutes\",\"5 minutes\",\"10 minutes\"],\"ans\":0,\"exp\":\"More than 3 minutes (or another period the ATS authority prescribes) - pass a revised estimate as soon as possible.\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-211\",\"topic\":\"Rules of the air & signals\",\"stem\":\"An IFR flight with radio failure in IMC should land, if possible, within\",\"opts\":[\"15 minutes of the ETA or EAT\",\"30 minutes after the ETA or the last acknowledged EAT, whichever is later\",\"45 minutes of the ETA\"],\"ans\":1,\"exp\":\"The last step of the IMC radio failure procedure: complete a normal instrument approach and land, if possible, within 30 minutes after the ETA or the last acknowledged EAT, whichever is later.\",\"seenIn\":[\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-212\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A controlled flight shall make position reports\",\"opts\":[\"Over each designated compulsory reporting point, and elsewhere when ATC requests\",\"Only at the discretion of the commander\",\"Only when passing an on-request reporting point\"],\"ans\":0,\"exp\":\"Report the time and level over every compulsory reporting point, plus any extra points ATC asks for.\",\"seenIn\":[\"Feb 2025 · OLODE 02\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-213\",\"topic\":\"Rules of the air & signals\",\"stem\":\"The general rules of Annex 2 apply to\",\"opts\":[\"IFR flights only\",\"VFR flights only\",\"Both VFR and IFR flights\"],\"ans\":2,\"exp\":\"Every flight complies with the general rules, and in addition with either the VFR or the IFR.\",\"seenIn\":[\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-214\",\"topic\":\"Rules of the air & signals\",\"stem\":\"A special VFR flight may be conducted\",\"opts\":[\"At any time\",\"At the pilot's discretion\",\"Only when cleared by ATC, within a control zone\"],\"ans\":2,\"exp\":\"Special VFR is a VFR flight cleared by ATC to operate within a control zone in conditions below VMC. No clearance, no special VFR.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-215\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"The lateral limit of a control zone (CTR) shall extend at least ___ from the centre of the aerodrome in the directions from which approaches may be made\",\"opts\":[\"25 NM\",\"10 NM\",\"5 NM\"],\"ans\":2,\"exp\":\"At least 9.3 km (5 NM). A control zone may include two or more aerodromes that are close together.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-216\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"A flight information region (FIR) is airspace of defined dimensions within which\",\"opts\":[\"Flight information service and alerting service are provided\",\"Air traffic control service is provided to all flights\",\"Only military flights operate\"],\"ans\":0,\"exp\":\"FIR = flight information and alerting service. These are the minimum services, available everywhere; ATC comes on top of them only in controlled airspace.\",\"seenIn\":[\"Feb 2025 · OLODE 02\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-217\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"Flight information service is a service provided to\",\"opts\":[\"Give advice and information useful for the safe and efficient conduct of flights\",\"Separate all aircraft\",\"Control aircraft on the manoeuvring area\"],\"ans\":0,\"exp\":\"FIS gives advice and information - weather, facilities, known traffic and hazards. It does not separate aircraft; that is ATC.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-218\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"Approach control service is air traffic control service for\",\"opts\":[\"Arriving or departing controlled flights\",\"Aircraft on the apron only\",\"En-route traffic above FL245\"],\"ans\":0,\"exp\":\"Approach control handles arriving and departing controlled flights. The tower handles aerodrome traffic; area control handles en-route traffic.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-219\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"\\\"Radar contact\\\" means\",\"opts\":[\"The radar position of the aircraft is seen and identified on the situation display\",\"The pilot can see the radar antenna\",\"Radar service has been terminated\"],\"ans\":0,\"exp\":\"Radar contact: the controller sees your radar position and has identified it. From then on, surveillance services can be provided.\",\"seenIn\":[\"Feb 2025 · OLODE 02\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-220\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"ATIS broadcast information shall be updated\",\"opts\":[\"On receipt of any official weather, whatever its content\",\"Every 30 minutes if below VFR, otherwise hourly\",\"Immediately a significant change occurs\"],\"ans\":2,\"exp\":\"The ATIS is updated as soon as a significant change occurs, and each new broadcast gets the next code letter so pilots can confirm they have the current one.\",\"seenIn\":[\"2022 · Regular 03\",\"Dec 2022 · Session 04\",\"Nov 2024 · OLODE 08\",\"Jan 2025 · OLODE 01\",\"Apr 2025 · Regular 01\"],\"undated\":false,\"times\":5,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-221\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"In Item 15 of the flight plan, the cruising speed is entered as\",\"opts\":[\"Indicated airspeed\",\"True airspeed (or Mach number where prescribed)\",\"Ground speed\"],\"ans\":1,\"exp\":\"Item 15 cruising speed is true airspeed, in knots (N0450) or km/h (K0830), or true Mach number where the ATS authority prescribes it.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-222\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"Item 7 of the ICAO flight plan contains the\",\"opts\":[\"Aircraft identification\",\"Aircraft type\",\"Flight rules\"],\"ans\":0,\"exp\":\"Item 7 is the aircraft identification - the call sign, or the registration. Flight rules are Item 8 and aircraft type is Item 9.\",\"seenIn\":[\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-223\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"A departing aircraft is given the QNH\",\"opts\":[\"After landing\",\"Prior to taxiing for take-off\",\"Only on request\"],\"ans\":1,\"exp\":\"Before taxiing for take-off, ATC passes the runway, surface wind, QNH, temperature (turbine aircraft), visibility or RVR if relevant, and the correct time.\",\"seenIn\":[\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-224\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"A blind transmission is\",\"opts\":[\"A transmission made where two-way communication cannot be established but the called station is believed able to receive it\",\"A transmission sent to all stations at once\",\"A transmission without a call sign\"],\"ans\":0,\"exp\":\"You make a blind transmission when you cannot hear the ground but believe they can hear you - for example after a receiver failure.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-225\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"Distress messages concern\",\"opts\":[\"Aircraft threatened by grave and imminent danger and requiring immediate assistance\",\"The safety of an aircraft, with no immediate assistance needed\",\"Routine flight safety information\"],\"ans\":0,\"exp\":\"Distress is grave and imminent danger needing immediate help. A safety concern that does not need immediate assistance is urgency.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-226\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"The priority indicator for AFTN messages concerning NOTAMs is\",\"opts\":[\"SS\",\"DD\",\"GG\"],\"ans\":2,\"exp\":\"AIS messages, including those concerning NOTAMs and SNOWTAMs, carry priority indicator GG. SS is distress and DD is urgency.\",\"seenIn\":[\"Apr 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-227\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"In India, a NOTAM containing information of international importance, valid for more than 2 hours, is issued in Series\",\"opts\":[\"A\",\"B\",\"G\"],\"ans\":0,\"exp\":\"Series A: international distribution, duration more than 2 hours. Series B covers 30 minutes to 2 hours.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-228\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"A landing aircraft will not normally be permitted to cross the runway threshold until the preceding departing aircraft\",\"opts\":[\"Has crossed the end of the runway in use or has started a turn\",\"Has reached 1000 ft\",\"Has been handed over to approach control\"],\"ans\":0,\"exp\":\"The runway must be clear: the departing aircraft has crossed the end of the runway or started a turn, or all preceding landing aircraft have cleared the runway.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-229\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"The movement area of an aerodrome consists of\",\"opts\":[\"The manoeuvring area and the aprons\",\"The runways only\",\"The runways and taxiways only\"],\"ans\":0,\"exp\":\"Movement area = manoeuvring area (runways and taxiways) plus aprons. The manoeuvring area excludes the aprons.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-230\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"The transition level to be used near an aerodrome is established by\",\"opts\":[\"The pilot-in-command\",\"The appropriate ATS unit\",\"The State of Registry\"],\"ans\":1,\"exp\":\"The ATS unit sets the transition level from the QNH and passes it to aircraft. The transition altitude, by contrast, is published by the State.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Dec 2024 · Regular 04\",\"Apr 2025 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-231\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"In India, no transition altitude is lower than\",\"opts\":[\"3000 ft\",\"4000 ft\",\"6000 ft\"],\"ans\":1,\"exp\":\"AIP India states that no transition altitude is less than 4000 ft.\",\"seenIn\":[\"Jul 2025 · OLODE 05\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-232\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"Aerodrome lights not needed for navigation may be switched off, provided they can be brought back into operation\",\"opts\":[\"At least 30 minutes before the expected arrival of an aircraft\",\"At least one hour before the expected arrival of an aircraft\",\"Within 5 minutes of a request\"],\"ans\":1,\"exp\":\"Lights may be switched off only if they can be back in operation at least one hour before an aircraft is expected.\",\"seenIn\":[\"Apr 2025 · Regular 01\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-233\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"In RVSM airspace, the vertical separation minimum between FL290 and FL410 inclusive is\",\"opts\":[\"500 ft\",\"1000 ft\",\"2000 ft\"],\"ans\":1,\"exp\":\"RVSM applies 300 m (1000 ft) between FL290 and FL410 inclusive, for RVSM-approved aircraft. Outside RVSM, 2000 ft applies at and above FL290.\",\"seenIn\":[\"2022 · Regular 03\",\"May 2024 · OLODE 04\",\"Nov 2024 · OLODE 08\",\"Jan 2025 · OLODE 01\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":5,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-234\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"The vertical separation minimum below FL290 is\",\"opts\":[\"500 ft\",\"1000 ft\",\"2000 ft\"],\"ans\":1,\"exp\":\"Below FL290: 1000 ft. At or above FL290: 2000 ft - reduced to 1000 ft only for RVSM aircraft in RVSM airspace.\",\"seenIn\":[\"Sep 2024 · Session 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-235\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"In RVSM airspace, an IFR flight on a magnetic track of 350 degrees should cruise at\",\"opts\":[\"FL410\",\"FL400\",\"FL405\"],\"ans\":1,\"exp\":\"Tracks 180-359 use even levels (FL300, 320 ... 400); tracks 000-179 use odd levels (FL290, 310 ... 410). FL405 is not an IFR cruising level.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-236\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"The basic time separation between aircraft at the same level on the same track is\",\"opts\":[\"5 minutes\",\"10 minutes\",\"15 minutes\"],\"ans\":2,\"exp\":\"Fifteen minutes. It drops to 10 minutes if navigation aids allow frequent fixing, and to 5 minutes if the leader is 20 kt or more faster (under set conditions).\",\"seenIn\":[\"Nov 2024 · OLODE 08\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-237\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"If navigation aids permit frequent determination of position and speed, the time separation for aircraft at the same level on the same track may be\",\"opts\":[\"5 minutes\",\"10 minutes\",\"15 minutes\"],\"ans\":1,\"exp\":\"Ten minutes with frequent position and speed checks, instead of the basic 15.\",\"seenIn\":[\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-238\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"Two aircraft at the same level on the same track: the preceding aircraft is 20 kt or more faster (for example, both departed from the same aerodrome). The minimum separation is\",\"opts\":[\"15 minutes\",\"10 minutes\",\"5 minutes\"],\"ans\":2,\"exp\":\"Five minutes when the leader keeps a true airspeed 20 kt or more faster, in the listed cases. With 40 kt or more it can be 3 minutes.\",\"seenIn\":[\"Apr 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-239\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"Departing aircraft that will fly tracks diverging by at least 45 degrees immediately after take-off need a separation of\",\"opts\":[\"1 minute\",\"2 minutes\",\"5 minutes\"],\"ans\":0,\"exp\":\"One minute, because lateral separation starts immediately after take-off. On the same track the figures are 5 minutes, or 2 minutes if the leader is 40 kt faster.\",\"seenIn\":[\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-240\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"The wake turbulence separation for a MEDIUM aircraft landing behind a HEAVY is\",\"opts\":[\"2 minutes\",\"3 minutes\",\"5 minutes\"],\"ans\":0,\"exp\":\"Arrivals: MEDIUM behind HEAVY - 2 minutes; LIGHT behind HEAVY or MEDIUM - 3 minutes.\",\"seenIn\":[\"Apr 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-241\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"The standard horizontal radar separation minimum is\",\"opts\":[\"3 NM\",\"5 NM\",\"10 NM\"],\"ans\":1,\"exp\":\"5 NM (9.3 km). Where the radar allows, it may be reduced to 3 NM, and to 2.5 NM on the same final approach track within 10 NM of the runway end.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-242\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"The radar wake turbulence separation for a MEDIUM aircraft following directly behind a HEAVY is\",\"opts\":[\"4 NM\",\"5 NM\",\"6 NM\"],\"ans\":1,\"exp\":\"5 NM. HEAVY behind HEAVY is 4 NM, LIGHT behind HEAVY 6 NM, and LIGHT behind MEDIUM 5 NM.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-243\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"For independent parallel approaches, the no transgression zone (NTZ) must be at least\",\"opts\":[\"300 m wide\",\"610 m wide\",\"1035 m wide\"],\"ans\":1,\"exp\":\"At least 610 m (2000 ft) wide, equidistant between the extended runway centre lines, and shown on the controller's display.\",\"seenIn\":[\"Feb 2021\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2021,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-244\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"When vectored to intercept the ILS localizer, the final vector should give an intercept angle of\",\"opts\":[\"Not more than 20 degrees\",\"Not more than 30 degrees\",\"Not more than 45 degrees\"],\"ans\":1,\"exp\":\"Not more than 30 degrees, with at least 1 NM of straight and level flight before the intercept.\",\"seenIn\":[\"Aug 2022\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-245\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"An aircraft with a maximum certificated take-off mass of 6700 kg is in which wake turbulence category?\",\"opts\":[\"LIGHT\",\"MEDIUM\",\"HEAVY\"],\"ans\":0,\"exp\":\"LIGHT is 7000 kg or less, so 6700 kg is LIGHT. MEDIUM is above 7000 kg and below 136,000 kg.\",\"seenIn\":[\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-246\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"The MEDIUM wake turbulence category covers maximum certificated take-off masses of\",\"opts\":[\"2000 to 7000 kg\",\"More than 7000 kg but less than 136,000 kg\",\"136,000 kg or more\"],\"ans\":1,\"exp\":\"MEDIUM: above 7000 kg and below 136,000 kg. At 136,000 kg exactly you are HEAVY.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-247\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"An aircraft cleared to leave a level is considered to have vacated it when its Mode C shows a change of more than\",\"opts\":[\"100 ft\",\"200 ft\",\"300 ft\"],\"ans\":2,\"exp\":\"More than 90 m (300 ft) in the expected direction from the previous level. The same 300 ft test applies to \\\"passed a level\\\".\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-248\",\"topic\":\"Transponder & emergencies\",\"stem\":\"An aircraft carrying a serviceable transponder shall operate it\",\"opts\":[\"At all times during flight\",\"Only in controlled airspace\",\"Only when ATC asks\"],\"ans\":0,\"exp\":\"Operate it at all times in flight, whether or not SSR is used where you are - with Mode C on so other aircraft's ACAS can see you too.\",\"seenIn\":[\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-249\",\"topic\":\"Transponder & emergencies\",\"stem\":\"A radar controller instructs \\\"fly heading 030\\\". The pilot flies\",\"opts\":[\"030 degrees magnetic, with no correction for wind\",\"030 degrees true\",\"A heading that makes the track 030\"],\"ans\":0,\"exp\":\"A radar vector is a magnetic heading. You fly the heading as given; the controller watches the track and adjusts for wind. Pilots do not correct radar vectors for wind.\",\"seenIn\":[\"Feb 2021\",\"Sep 2023 · Regular 03\",\"Oct 2024 · OLODE 07\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":4,\"years\":[2021,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-250\",\"topic\":\"Instrument procedures\",\"stem\":\"The threshold speed (Vat) range for approach Category D is\",\"opts\":[\"121 to 140 kt\",\"141 to 165 kt\",\"166 to 210 kt\"],\"ans\":1,\"exp\":\"D is 141-165 kt. C is 121-140 kt and E is 166-210 kt.\",\"seenIn\":[\"Jun 2024 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-251\",\"topic\":\"Instrument procedures\",\"stem\":\"On a precision approach, the final approach segment begins at the\",\"opts\":[\"Final approach point (FAP)\",\"Initial approach fix\",\"Outer marker, always\"],\"ans\":0,\"exp\":\"On a precision approach the final segment starts at the FAP - where the intermediate altitude meets the glide path. The FAF belongs to non-precision approaches.\",\"seenIn\":[\"Jun 2024 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-252\",\"topic\":\"Instrument procedures\",\"stem\":\"The missed approach procedure is normally based on a minimum climb gradient of\",\"opts\":[\"2.5 %\",\"3.3 %\",\"5 %\"],\"ans\":0,\"exp\":\"A 2.5 % missed approach gradient. The 3.3 % figure is the departure procedure design gradient.\",\"seenIn\":[\"Feb 2021\",\"Sep 2023 · Regular 03\",\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2021,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-253\",\"topic\":\"Instrument procedures\",\"stem\":\"A straight departure is one in which the initial departure track is within ___ of the runway centre line\",\"opts\":[\"15 degrees\",\"30 degrees\",\"45 degrees\"],\"ans\":0,\"exp\":\"Within 15 degrees of runway alignment. A turn of more than 15 degrees makes it a turning departure.\",\"seenIn\":[\"Nov 2023 · OLODE 08\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-254\",\"topic\":\"Instrument procedures\",\"stem\":\"A racetrack procedure consists of\",\"opts\":[\"A 180-degree turn from the facility onto an outbound track for 1, 2 or 3 minutes, then a 180-degree turn in the same direction to the inbound track\",\"A 45-degree turn away from the track and a 180-degree turn back\",\"A turn made between the end of the outbound track and the start of the final track\"],\"ans\":0,\"exp\":\"Two 180-degree turns in the same direction, with a timed (or DME-limited) outbound leg in between. The 45/180 manoeuvre is a procedure turn; the last option describes a base turn.\",\"seenIn\":[\"2022 · Regular 03\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-255\",\"topic\":\"Instrument procedures\",\"stem\":\"A turn executed during the initial approach between the end of the outbound track and the beginning of the intermediate or final approach track is a\",\"opts\":[\"Procedure turn\",\"Base turn\",\"Racetrack\"],\"ans\":1,\"exp\":\"That is a base turn. The outbound and inbound tracks of a base turn are not reciprocal - that is what separates it from a procedure turn.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-256\",\"topic\":\"Instrument procedures\",\"stem\":\"The OCH is referenced to the aerodrome elevation, rather than the threshold elevation, when the threshold is\",\"opts\":[\"More than 2 m (7 ft) below the aerodrome elevation\",\"Above the aerodrome elevation\",\"More than 50 ft above the aerodrome elevation\"],\"ans\":0,\"exp\":\"OCH is normally measured from the threshold, but if the threshold is more than 2 m (7 ft) below the aerodrome elevation, the aerodrome elevation is used.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-257\",\"topic\":\"Instrument procedures\",\"stem\":\"The optimum glide path / final approach angle is\",\"opts\":[\"2 degrees\",\"3 degrees\",\"5 degrees\"],\"ans\":1,\"exp\":\"Three degrees - a 5.2 % descent gradient, about 318 ft per NM. That is also why a 3-degree glide path meets the intermediate altitude 3-10 NM out.\",\"seenIn\":[\"Sep 2024 · Session 03\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-258\",\"topic\":\"Instrument procedures\",\"stem\":\"The initial phase of the missed approach ends at the\",\"opts\":[\"Start of climb (SOC)\",\"Missed approach point\",\"Point where 50 m obstacle clearance is obtained\"],\"ans\":0,\"exp\":\"Initial phase: MAPt to SOC. Intermediate phase: SOC to where 50 m (164 ft) of obstacle clearance is reached. Final phase: from there onward.\",\"seenIn\":[\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-259\",\"topic\":\"Instrument procedures\",\"stem\":\"In a standard holding pattern, turns are made to the\",\"opts\":[\"Left\",\"Right\",\"Side depending on the wind\"],\"ans\":1,\"exp\":\"Standard holding uses right turns. A left-hand hold must be published or instructed.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-260\",\"topic\":\"Instrument procedures\",\"stem\":\"Which of these is a precision approach aid?\",\"opts\":[\"VOR\",\"NDB\",\"ILS\"],\"ans\":2,\"exp\":\"The conventional precision approaches are ILS, MLS and PAR. VOR and NDB approaches are non-precision.\",\"seenIn\":[\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-261\",\"topic\":\"Instrument procedures\",\"stem\":\"RNP stands for\",\"opts\":[\"Required navigation performance\",\"Radio navigation procedure\",\"Route navigation point\"],\"ans\":0,\"exp\":\"Required navigation performance: a statement of the navigation performance needed to operate in a defined airspace.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-262\",\"topic\":\"Instrument procedures\",\"stem\":\"RNP 4 represents a navigation accuracy of\",\"opts\":[\"Within 4 NM for at least 95 % of the flying time\",\"Within 4 km at all times\",\"Within 0.4 NM for at least 95 % of the flying time\"],\"ans\":0,\"exp\":\"Plus or minus 7.4 km (4 NM) for at least 95 % of the total flying time.\",\"seenIn\":[\"Apr 2025 · Regular 01\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-263\",\"topic\":\"Instrument procedures\",\"stem\":\"PANS stands for\",\"opts\":[\"Procedures for Air Navigation Services\",\"Pilot Air Navigation Standards\",\"Procedures for Aircraft Navigation Safety\"],\"ans\":0,\"exp\":\"Procedures for Air Navigation Services, for example PANS-ATM (Doc 4444) and PANS-OPS (Doc 8168).\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-264\",\"topic\":\"Communications & phraseology\",\"stem\":\"In the SHEL model, the letters stand for\",\"opts\":[\"Software, Hardware, Environment, Liveware\",\"Safety, Health, Environment, Leadership\",\"Systems, Human, Error, Limits\"],\"ans\":0,\"exp\":\"Software (procedures, manuals, checklists), Hardware (the machine), Environment, and Liveware (the human, at the centre).\",\"seenIn\":[\"Feb 2021\",\"Sep 2024 · Session 03\",\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":3,\"years\":[2021,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-265\",\"topic\":\"Communications & phraseology\",\"stem\":\"TORA (take-off run available) is\",\"opts\":[\"The length of runway declared available and suitable for the ground run of an aeroplane taking off\",\"TORA plus the clearway\",\"TORA plus the stopway\"],\"ans\":0,\"exp\":\"TORA is the runway available for the ground run. TODA adds the clearway; ASDA adds the stopway.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-266\",\"topic\":\"Communications & phraseology\",\"stem\":\"In the ground-to-air code used by rescue units, \\\"LLL\\\" means\",\"opts\":[\"Operation completed\",\"We have found all personnel\",\"Nothing found - will continue to search\"],\"ans\":0,\"exp\":\"LLL = operation completed. LL = found all personnel; NN = nothing found, will continue.\",\"seenIn\":[\"Jun 2024 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-267\",\"topic\":\"Communications & phraseology\",\"stem\":\"In the ground-to-air code used by survivors, \\\"X\\\" means\",\"opts\":[\"Require medical assistance\",\"Require assistance\",\"No / negative\"],\"ans\":0,\"exp\":\"X = require medical assistance; V = require assistance; N = no; Y = yes; an arrow = proceeding in this direction. Symbols should be at least 2.5 m (8 ft) long.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Oct 2023 · FC 07\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-268\",\"topic\":\"Aeronautical information\",\"stem\":\"Taxiway markings are\",\"opts\":[\"White\",\"Yellow\",\"Red\"],\"ans\":1,\"exp\":\"Taxiway, runway turn-pad and stand markings are yellow; runway markings are white. In India, apron safety lines are red.\",\"seenIn\":[\"Jun 2024 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-269\",\"topic\":\"Aeronautical information\",\"stem\":\"Taxiway edge lights are\",\"opts\":[\"Fixed blue lights\",\"Fixed green lights\",\"Fixed yellow lights\"],\"ans\":0,\"exp\":\"Taxiway edge lights show blue and taxiway centre-line lights green. Runway edge lights are white; threshold lights green; runway end lights red.\",\"seenIn\":[\"Oct 2024 · OLODE 07\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-270\",\"topic\":\"Aeronautical information\",\"stem\":\"Runway threshold lights are\",\"opts\":[\"Blue\",\"Green\",\"Red\"],\"ans\":1,\"exp\":\"Fixed unidirectional green lights, showing green towards the approach. Runway end lights are red.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-271\",\"topic\":\"Aeronautical information\",\"stem\":\"A land aerodrome beacon shows\",\"opts\":[\"Green flashes alternating with white flashes\",\"Yellow flashes alternating with white flashes\",\"Red flashes only\"],\"ans\":0,\"exp\":\"A land aerodrome beacon shows green flashes alternating with white (or white only), 20-30 flashes a minute. A water aerodrome beacon uses yellow.\",\"seenIn\":[\"Oct 2023 · FC 07\",\"Jun 2024 · Regular\",\"Nov 2024 · OLODE 08\",\"Jul 2025 · OLODE 05\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-272\",\"topic\":\"Human performance\",\"stem\":\"A normal blood pressure for a healthy young adult is about\",\"opts\":[\"120/80 mmHg\",\"160/100 mmHg\",\"90/50 mmHg\"],\"ans\":0,\"exp\":\"About 120 over 80: systolic 120 mmHg as the heart contracts, diastolic 80 mmHg as it relaxes and refills.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Apr 2025 · Regular 01\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-273\",\"topic\":\"Human performance\",\"stem\":\"A normal resting pulse rate for an adult is about\",\"opts\":[\"30-50 beats per minute\",\"60-80 beats per minute\",\"110-150 beats per minute\"],\"ans\":1,\"exp\":\"About 60 to 80 beats per minute; the usual reference value is 72. At rest the heart then pumps about 5 litres a minute.\",\"seenIn\":[\"Feb 2025 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-274\",\"topic\":\"Human performance\",\"stem\":\"On final approach in bad weather you feel dizzy, with tingling in the hands and a rapid heart rate. These are most likely symptoms of\",\"opts\":[\"Hypoxia\",\"Hyperventilation\",\"Decompression sickness\"],\"ans\":1,\"exp\":\"Anxiety-driven over-breathing gives dizziness, tingling, and a racing heart. At low altitude hypoxia is unlikely, so assume hyperventilation and slow your breathing down.\",\"seenIn\":[\"Feb 2021\",\"Nov 2024 · OLODE 08\",\"Jan 2025 · OLODE 01\",\"Apr 2025 · Regular 01\",\"May 2025 · OLODE 04\",\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":6,\"years\":[2021,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-275\",\"topic\":\"Human performance\",\"stem\":\"Which of these is NOT a symptom of hyperventilation?\",\"opts\":[\"Dizziness\",\"Tingling\",\"A decrease in heart rate\"],\"ans\":2,\"exp\":\"Hyperventilation speeds the heart up - it does not slow it. Dizziness and tingling are classic symptoms.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Jan 2025 · OLODE 01\",\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":3,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-276\",\"topic\":\"Human performance\",\"stem\":\"The most common cause of hyperventilation in pilots at low altitude is\",\"opts\":[\"Anxiety or stress\",\"Too much oxygen\",\"Cold temperatures\"],\"ans\":0,\"exp\":\"Anxiety, fear and stress. A thorough briefing calms passengers, and good training prevents it in pilots.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Apr 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-277\",\"topic\":\"Human performance\",\"stem\":\"A pilot suspects hyperventilation during descent. The correct action is to\",\"opts\":[\"Consciously slow the breathing rate to about 10-12 breaths a minute, without breathing deeply\",\"Breathe faster to get more oxygen\",\"Climb immediately\"],\"ans\":0,\"exp\":\"First check the oxygen in case it is hypoxia. If the symptoms persist, slow the breathing to 10-12 breaths a minute and avoid deep breaths.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-278\",\"topic\":\"Human performance\",\"stem\":\"Sudden pain in the joints (such as the knees) after flight at high altitude is a symptom of\",\"opts\":[\"Decompression sickness (the bends)\",\"Barotrauma\",\"Hypoxia\"],\"ans\":0,\"exp\":\"Joint pain is the bends - nitrogen coming out of solution in the tissues. Other forms are the chokes, skin manifestations and nervous-system symptoms.\",\"seenIn\":[\"Aug 2022\",\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-279\",\"topic\":\"Human performance\",\"stem\":\"Time of useful consciousness (TUC) is\",\"opts\":[\"The time during which a pilot can still take proper corrective and protective action after the oxygen supply is interrupted\",\"The time until the pilot loses consciousness\",\"The time taken to don an oxygen mask\"],\"ans\":0,\"exp\":\"TUC is useful time, not time to unconsciousness. After it ends, a pilot may still be awake for a few seconds but can no longer act effectively - so the mask goes on first.\",\"seenIn\":[\"Aug 2022\",\"Oct 2024 · OLODE 07\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-280\",\"topic\":\"Human performance\",\"stem\":\"At about 35,000 ft, time of useful consciousness is approximately\",\"opts\":[\"30 to 60 seconds\",\"3 to 5 minutes\",\"10 minutes\"],\"ans\":0,\"exp\":\"About 33-54 seconds at 35,000 ft, roughly halved at 40,000 ft - and halved again by a rapid decompression.\",\"seenIn\":[\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-281\",\"topic\":\"Human performance\",\"stem\":\"After an explosive decompression, the cabin may\",\"opts\":[\"Fill with fog (mist), dust and debris\",\"Become warmer\",\"Show no visible change\"],\"ans\":0,\"exp\":\"The sudden drop in pressure and temperature forms fog, and dust and debris fly about. The crew may be briefly dazed, which slows donning the masks.\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-282\",\"topic\":\"Human performance\",\"stem\":\"Haze on the approach may cause the pilot to\",\"opts\":[\"Feel too high and fly a shallower approach than normal\",\"Feel too low and fly a steeper approach\",\"See the runway correctly\"],\"ans\":0,\"exp\":\"Haze makes the runway look further away, so the pilot thinks he is high, reduces the descent and flies shallow - and risks landing short.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Feb 2025 · OLODE 02\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-283\",\"topic\":\"Human performance\",\"stem\":\"Ear barotrauma is most likely when\",\"opts\":[\"Descending with a cold (blocked Eustachian tube)\",\"Climbing in good health\",\"Cruising at a constant altitude\"],\"ans\":0,\"exp\":\"On descent the middle ear must take air in through the Eustachian tube. A cold blocks it, so descent is the dangerous direction. Do not fly if you cannot clear your ears.\",\"seenIn\":[\"Feb 2021\",\"Jun 2024 · Regular\",\"Jan 2025 · OLODE 01\",\"Oct 2025 · OLODE 07\",\"Apr 2026 · OLODE 03\"],\"undated\":false,\"times\":5,\"years\":[2021,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-284\",\"topic\":\"Human performance\",\"stem\":\"Night vision and vision in dim light depend mainly on the\",\"opts\":[\"Rods, in the periphery of the retina\",\"Cones, in the centre of the retina\",\"Lens\"],\"ans\":0,\"exp\":\"Rods sit in the periphery, see only black and white, and work in low light; cones are central and give colour and detail by day. At night, look slightly off-centre.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Dec 2024 · Regular 04\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-285\",\"topic\":\"Human performance\",\"stem\":\"Dalton's law states that\",\"opts\":[\"The total pressure of a gas mixture equals the sum of the partial pressures of its gases\",\"Gas volume is inversely proportional to pressure\",\"The amount of gas dissolved in a liquid is proportional to its partial pressure\"],\"ans\":0,\"exp\":\"Dalton: total pressure = sum of partial pressures. This is why oxygen falls with altitude even though it stays at 21 %. The other options are Boyle's law and Henry's law.\",\"seenIn\":[\"Nov 2024 · OLODE 08\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-286\",\"topic\":\"Human performance\",\"stem\":\"Which are types of hypoxia?\",\"opts\":[\"Stagnant hypoxia only\",\"Anaemic hypoxia only\",\"Both stagnant and anaemic hypoxia\"],\"ans\":2,\"exp\":\"There are four types: hypoxic (altitude), anaemic (reduced oxygen-carrying capacity), stagnant or ischaemic (poor blood flow) and histotoxic (cells cannot use the oxygen).\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Jan 2025 · OLODE 01\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":3,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-287\",\"topic\":\"Human performance\",\"stem\":\"The primary and most reliable sense for spatial orientation is\",\"opts\":[\"The vestibular system\",\"Vision (eyesight)\",\"Hearing\"],\"ans\":1,\"exp\":\"Eyesight is primary; the balance organs of the inner ear are a secondary system. That is why losing the visual horizon leads to disorientation.\",\"seenIn\":[\"Apr 2025 · Regular 01\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-288\",\"topic\":\"Human performance\",\"stem\":\"Staring at a single stationary light in the dark may make it appear to move. This is\",\"opts\":[\"The autokinetic effect\",\"The black-hole effect\",\"The somatogravic illusion\"],\"ans\":0,\"exp\":\"Autokinesis: with no other references, a fixed light seems to wander. Keep your eyes moving and cross-check the instruments.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-289\",\"topic\":\"Human performance\",\"stem\":\"For a demanding task such as an approach, performance is best at\",\"opts\":[\"Very low arousal\",\"An optimum (moderate) level of arousal\",\"Very high arousal\"],\"ans\":1,\"exp\":\"Performance peaks in the middle of the arousal curve. Too little brings boredom and missed information; too much narrows attention.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-290\",\"topic\":\"Human performance\",\"stem\":\"Presbyopia is\",\"opts\":[\"Loss of the eye's ability to focus on near objects, due to the lens stiffening with age\",\"Colour blindness\",\"Night blindness caused by lack of vitamin A\"],\"ans\":0,\"exp\":\"Presbyopia comes with age: the lens stiffens and near focus is lost. It is corrected with reading or bifocal lenses.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-291\",\"topic\":\"Human performance\",\"stem\":\"The rate of breathing is mainly regulated by the level of\",\"opts\":[\"Oxygen in the blood\",\"Carbon dioxide in the blood\",\"Nitrogen in the blood\"],\"ans\":1,\"exp\":\"The respiratory centre responds mainly to carbon dioxide. That is why hyperventilation, which washes CO2 out, confuses the breathing drive.\",\"seenIn\":[\"Feb 2021\",\"Dec 2022 · Session 04\",\"Feb 2025 · OLODE 02\",\"Sep 2025 · Regular 03\"],\"undated\":false,\"times\":4,\"years\":[2021,2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-292\",\"topic\":\"Human performance\",\"stem\":\"On climbing, gases trapped in the stomach and intestines\",\"opts\":[\"Expand\",\"Contract\",\"Stay the same\"],\"ans\":0,\"exp\":\"Boyle's law: gas volume grows as pressure falls. Gut gas can roughly double by 18,000 ft cabin altitude, causing pain.\",\"seenIn\":[\"Apr 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-293\",\"topic\":\"Human performance\",\"stem\":\"During departure, a sudden decrease in headwind (windshear) causes\",\"opts\":[\"A loss of airspeed and climb performance\",\"A gain in airspeed\",\"No change in airspeed\"],\"ans\":0,\"exp\":\"Losing headwind costs indicated airspeed and performance straight away - the microburst trap after the initial headwind has made the climb look good.\",\"seenIn\":[\"Feb 2025 · OLODE 02\",\"Oct 2025 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-294\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"According to ICAO Annex 8, the continuing airworthiness of an aircraft shall be determined by\",\"opts\":[\"ICAO\",\"The operator's State\",\"The State of Registry\"],\"ans\":2,\"exp\":\"The State of Registry - the State on whose register the aircraft is entered - is responsible for its airworthiness, including continuing airworthiness. ICAO sets the Standards but does not certify individual aircraft.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-295\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"According to ICAO Annex 8, a certificate of airworthiness shall be renewed or remain valid subject to the\",\"opts\":[\"Laws of the State of Registry and of the State of operation\",\"Laws of the State of Registry\",\"Requirements laid down by ICAO\"],\"ans\":1,\"exp\":\"The C of A belongs to the State of Registry, and its renewal and validity follow that State's laws. The State the aircraft happens to operate in does not control it.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-296\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"An Indian-registered aircraft is to fly from London to Bosnia. Its certificate of airworthiness is governed by the rules of\",\"opts\":[\"The United Kingdom\",\"India\",\"Bosnia\"],\"ans\":1,\"exp\":\"The C of A follows the State of Registry wherever the aircraft flies, so an Indian-registered aircraft keeps its Indian C of A in London or Bosnia.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-297\",\"topic\":\"Instrument procedures\",\"stem\":\"For simultaneous approaches to parallel instrument runways, the missed approach track of one approach must diverge from that of the adjacent approach by at least\",\"opts\":[\"30 degrees\",\"15 degrees\",\"45 degrees\"],\"ans\":0,\"exp\":\"With two approaches running side by side, a go-around on one must not turn into the traffic on the other. So the missed approach tracks are designed to split apart by at least 30 degrees.\",\"seenIn\":[\"Feb 2021\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-298\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"ICAO Annex 2 deals with\",\"opts\":[\"Rules of the Air\",\"Personnel Licensing\",\"Air Traffic Services\"],\"ans\":0,\"exp\":\"Annex 2 is the Rules of the Air - one of the few Annexes that contains Standards only, with no Recommended Practices. Personnel Licensing is Annex 1 and Air Traffic Services is Annex 11.\",\"seenIn\":[\"Feb 2021\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2021,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-299\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"The lower limit of a control area shall be established at a height above the ground or water of not less than\",\"opts\":[\"200 m (700 ft)\",\"150 m (500 ft)\",\"300 m (1000 ft)\"],\"ans\":0,\"exp\":\"A control area starts above the ground - never lower than 200 m (700 ft). It is the control zone that runs from the surface upwards, around an aerodrome.\",\"seenIn\":[\"Feb 2021\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2021,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-300\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"Under the public health rules, the incubation period of relapsing fever is\",\"opts\":[\"8 days\",\"6 days\",\"14 days\"],\"ans\":0,\"exp\":\"The quarantinable-disease table: yellow fever 6 days, plague 6 days, cholera 5 days, smallpox 14 days, typhus 14 days, and relapsing fever 8 days.\",\"seenIn\":[\"Feb 2021\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-301\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"Under the Aircraft Rules, a notice permitting smoking may be displayed in an aircraft only if smoking is permitted by\",\"opts\":[\"The certificate of airworthiness or a direction of the Central Government\",\"The pilot-in-command alone\",\"The owner of the aircraft\"],\"ans\":0,\"exp\":\"Rule 25 makes the owner, operator and PIC display notices showing where smoking is prohibited or permitted. A notice permitting smoking may go up only if the C of A (or a Central Government direction) allows smoking in that aircraft.\",\"seenIn\":[\"Feb 2021\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-302\",\"topic\":\"Rules of the air & signals\",\"stem\":\"In the ground-to-air visual code used by survivors, the symbol \\\"V\\\" means\",\"opts\":[\"Require assistance\",\"Require medical assistance\",\"Proceeding in this direction\"],\"ans\":0,\"exp\":\"V = require assistance (general help). X = require medical assistance, and an arrow means proceeding in this direction. V and X are the pair that gets swapped in the exam.\",\"seenIn\":[\"Feb 2021\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-303\",\"topic\":\"Human performance\",\"stem\":\"Dark adaptation (night vision) is impaired by\",\"opts\":[\"Vitamin A deficiency and carbon monoxide from smoking\",\"Breathing 100 % oxygen\",\"Keeping one eye closed in bright light\"],\"ans\":0,\"exp\":\"Night vision suffers from a lack of vitamin A, from carbon monoxide inhaled while smoking, from cabin altitudes above 5000 ft and from long exposure to bright sunlight. Closing one eye in bright light is the trick that preserves it.\",\"seenIn\":[\"Feb 2021\",\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2021,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-304\",\"topic\":\"Altimetry\",\"stem\":\"While passing through the transition layer, vertical position is expressed as\",\"opts\":[\"Flight level when climbing, altitude when descending\",\"Altitude when climbing, flight level when descending\",\"Flight level whether climbing or descending\"],\"ans\":0,\"exp\":\"Climbing, you are heading into flight levels, so report flight levels. Descending, you are heading onto QNH, so report altitudes. Below the transition altitude it is always altitude; above the transition level it is always flight level.\",\"seenIn\":[\"Aug 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-305\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"In India, a certificate of airworthiness is issued or renewed by the\",\"opts\":[\"Director General of Civil Aviation\",\"Airports Authority of India\",\"Bureau of Civil Aviation Security\"],\"ans\":0,\"exp\":\"The owner or operator applies to the Director-General, who may issue, renew or validate the C of A. The AAI runs airports and air navigation services; the BCAS is the security regulator.\",\"seenIn\":[\"Aug 2022\",\"Oct 2023 · FC 07\"],\"undated\":false,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-306\",\"topic\":\"Human performance\",\"stem\":\"The Eustachian tube\",\"opts\":[\"Equalises the pressure in the middle ear with the outside (cabin) pressure\",\"Carries sound waves from the eardrum to the inner ear\",\"Senses angular acceleration of the head\"],\"ans\":0,\"exp\":\"The Eustachian tube links the middle ear to the throat so that its pressure can equalise with the cabin. If it is blocked - a cold is the usual cause - descent is when the ear hurts, because air cannot get back in.\",\"seenIn\":[\"Aug 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-307\",\"topic\":\"Human performance\",\"stem\":\"Sound is carried from the eardrum across the middle ear to the inner ear by\",\"opts\":[\"Three tiny bones - the ossicles\",\"The Eustachian tube\",\"The semicircular canals\"],\"ans\":0,\"exp\":\"The ossicles - malleus, incus and stapes - form a small lever system that turns the vibration of the eardrum into movement at the inner ear. The Eustachian tube only equalises pressure, and the semicircular canals sense rotation.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-308\",\"topic\":\"Human performance\",\"stem\":\"A pilot can raise his tolerance to positive G (+Gz) by\",\"opts\":[\"Tensing the leg and abdominal muscles (anti-G straining)\",\"Relaxing all the muscles\",\"Tilting the head well back\"],\"ans\":0,\"exp\":\"Under +Gz the blood drains away from the head, bringing grey-out, then black-out, then G-LOC. Tensing the lower body raises the arterial pressure and keeps blood in the brain a little longer.\",\"seenIn\":[\"Aug 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-309\",\"topic\":\"Instrument procedures\",\"stem\":\"Joining a holding pattern from sector 3, the entry is\",\"opts\":[\"Direct\",\"Parallel\",\"Offset\"],\"ans\":0,\"exp\":\"Sector 1 is the parallel entry, sector 2 the offset (30 degree) entry and sector 3 the direct entry: having reached the fix, turn to follow the holding pattern.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-310\",\"topic\":\"Instrument procedures\",\"stem\":\"In the cross-section of an instrument procedure segment, the primary area is the area\",\"opts\":[\"Over which the full minimum obstacle clearance is applied\",\"Where obstacle clearance reduces to zero at the outer edge\",\"Used only for the missed approach\"],\"ans\":0,\"exp\":\"Each segment is split into a primary area in the middle, where the full MOC applies, and secondary areas either side, where the clearance tapers to zero at the outer edge.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-311\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"Under the flight duty time rules, the maximum flight time in any 365 consecutive days is\",\"opts\":[\"1000 hours\",\"1200 hours\",\"1500 hours\"],\"ans\":0,\"exp\":\"The cumulative limits are 35 hours in 7 days, 65 in 14, 100 in 28, 300 in 90 and 1000 in 365 consecutive days.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-312\",\"topic\":\"Human performance\",\"stem\":\"The symptoms of decompression sickness\",\"opts\":[\"May be delayed and appear several hours after the exposure, even after landing\",\"Always appear within seconds of the exposure\",\"Occur only above 40,000 ft\"],\"ans\":0,\"exp\":\"Nitrogen bubbles do not always form at once. Symptoms - bends, chokes, skin manifestations, neurological symptoms, circulatory shock - may appear several hours after the exposure, so a pilot who feels fine on landing is not necessarily clear.\",\"seenIn\":[\"2022 · Regular 03\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-313\",\"topic\":\"Rules of the air & signals\",\"stem\":\"When two aircraft are converging at approximately the same level, which is correct?\",\"opts\":[\"Power-driven heavier-than-air aircraft give way to airships, gliders and balloons\",\"Balloons give way to gliders\",\"Gliders give way to power-driven aeroplanes\"],\"ans\":0,\"exp\":\"The least manoeuvrable has the right of way: power-driven heavier-than-air aircraft give way to airships, gliders and balloons; airships to gliders and balloons; gliders to balloons. And any power-driven aircraft gives way to one towing.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-314\",\"topic\":\"Rules of the air & signals\",\"stem\":\"An intercepted aircraft, unable to communicate in a common language, tells the interceptor it is unable to comply by saying\",\"opts\":[\"CAN NOT\",\"CAN NOT COMPLY\",\"UNABLE TO COMPLY\"],\"ans\":0,\"exp\":\"The interception phrase table gives short words anyone can pronounce: CAN NOT (KANN NOTT) means \\\"unable to comply\\\". WILCO means will comply. \\\"UNABLE TO COMPLY\\\" is the meaning, not the phrase to be spoken.\",\"seenIn\":[\"2022 · Regular 03\",\"Sep 2023 · Regular 03\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-315\",\"topic\":\"Transponder & emergencies\",\"stem\":\"An aircraft being intercepted should, unless otherwise instructed by ATS, set its transponder to\",\"opts\":[\"Mode A 7700\",\"Mode A 7600\",\"Mode A 7500\"],\"ans\":0,\"exp\":\"An intercepted aircraft follows the interceptor's instructions, tries to call on 121.5 MHz and, if it has a transponder, selects Mode A 7700 unless ATS says otherwise. 7600 is radio failure and 7500 unlawful interference.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-316\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"Landing behind a larger aircraft, you avoid its wake by\",\"opts\":[\"Staying above its approach path and touching down beyond its touchdown point\",\"Staying below its approach path and landing short of its touchdown point\",\"Flying slightly to the left of its approach path\"],\"ans\":0,\"exp\":\"Vortices sink behind the aircraft that makes them and stop at its touchdown point. Stay above its path and land beyond where it touched down, and you stay out of them.\",\"seenIn\":[\"2022 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-317\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"How many aeronautical Rescue Coordination Centres are there in India?\",\"opts\":[\"4\",\"3\",\"5\"],\"ans\":0,\"exp\":\"Four: Delhi, Mumbai, Kolkata and Chennai, one for each Indian FIR, coordinated by the Airports Authority of India.\",\"seenIn\":[\"2022 · Regular 03\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-318\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"The convention intended to ensure adequate compensation for persons who suffer damage on the surface caused by foreign aircraft is the\",\"opts\":[\"Rome Convention\",\"Paris Convention\",\"Warsaw Convention\"],\"ans\":0,\"exp\":\"The Rome Convention (1952) covers damage caused by foreign aircraft to third parties on the surface. Warsaw deals with the carrier's liability to its own passengers and cargo, and Paris 1919 was the first air navigation convention.\",\"seenIn\":[\"Dec 2022 · Session 04\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-319\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"ICAO establishes\",\"opts\":[\"Standards and Recommended Practices for Contracting States\",\"Standards that every State must apply without exception\",\"National regulations for each Contracting State\"],\"ans\":0,\"exp\":\"ICAO writes Standards and Recommended Practices in the Annexes for its Contracting States. They are not applied without exception - a State that cannot comply must notify its differences under Article 38.\",\"seenIn\":[\"Dec 2022 · Session 04\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-320\",\"topic\":\"Rules of the air & signals\",\"stem\":\"Over the high seas, the rules of the air in force are\",\"opts\":[\"The rules established under the Convention on International Civil Aviation (Annex 2)\",\"The rules of the State of the operator\",\"The rules of the States adjacent to the high seas\"],\"ans\":0,\"exp\":\"The ICAO Council adopted Annex 2 as the rules for flight and manoeuvre of aircraft within the meaning of Article 12 of the Chicago Convention. Over the high seas, therefore, those rules apply without exception.\",\"seenIn\":[\"Dec 2022 · Session 04\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-321\",\"topic\":\"Transponder & emergencies\",\"stem\":\"The special purpose SSR codes are\",\"opts\":[\"Distress 7700, unlawful interference 7500, radio failure 7600\",\"Distress 7600, unlawful interference 7500, radio failure 7700\",\"Distress 7500, unlawful interference 7700, radio failure 7600\"],\"ans\":0,\"exp\":\"7700 is emergency, 7600 is radio communication failure, 7500 is unlawful interference.\",\"seenIn\":[\"Dec 2022 · Session 04\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-322\",\"topic\":\"Instrument procedures\",\"stem\":\"A missed approach procedure has the following phases\",\"opts\":[\"Initial, intermediate and final\",\"Arrival, initial, intermediate and final\",\"Arrival, intermediate and final\"],\"ans\":0,\"exp\":\"Only the approach itself has an arrival and an initial segment. The missed approach has three phases: initial (from the MAPt to the start of climb), intermediate and final.\",\"seenIn\":[\"Dec 2022 · Session 04\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-323\",\"topic\":\"Rules of the air & signals\",\"stem\":\"Where the appropriate ATS authority permits, helicopters may operate in a flight visibility of less than ___, if manoeuvred at a speed that gives adequate opportunity to see other traffic or obstacles in time to avoid them\",\"opts\":[\"1500 m\",\"800 m\",\"5 km\"],\"ans\":0,\"exp\":\"The VMC table allows helicopters below the normal 1500 m flight visibility, provided they fly slowly enough to see and avoid traffic and obstacles in time.\",\"seenIn\":[\"Dec 2022 · Session 04\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-324\",\"topic\":\"Instrument procedures\",\"stem\":\"An aircraft in oceanic airspace that cannot continue in accordance with its clearance should leave its route or track and acquire a track offset from it by\",\"opts\":[\"15 NM\",\"5 NM\",\"50 NM\"],\"ans\":0,\"exp\":\"The oceanic contingency procedure is to turn at least 45 degrees left or right and establish a same- or opposite-direction track offset 15 NM (28 km) from the assigned track centreline, then change level so as not to meet traffic on the normal levels.\",\"seenIn\":[\"Dec 2022 · Session 04\",\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check could not confirm this answer from the official sources we hold; treat it with care and confirm with your instructor.\"},{\"id\":\"CPLREG-325\",\"topic\":\"Instrument procedures\",\"stem\":\"The touchdown-zone RVR is always controlling. The mid-point and stop-end RVR are\",\"opts\":[\"Also controlling, if reported and relevant\",\"Controlling only if ATC decides so\",\"Controlling at the discretion of the PIC\"],\"ans\":0,\"exp\":\"The touchdown RVR always controls. When the mid-point and stop-end RVR are reported and relevant, they are controlling too - the pilot does not choose to ignore them.\",\"seenIn\":[\"Dec 2022 · Session 04\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-326\",\"topic\":\"Human performance\",\"stem\":\"Which of these are symptoms of hypoxia?\",\"opts\":[\"Visual disturbances, lack of concentration, euphoria\",\"Nausea and barotitis\",\"Dizziness and hypothermia\"],\"ans\":0,\"exp\":\"Hypoxia sneaks up on you: night vision goes first, reasoning and concentration slip, and a feeling of well-being - euphoria - hides the danger. Barotitis is an ear problem and hypothermia is cold.\",\"seenIn\":[\"Dec 2022 · Session 04\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-327\",\"topic\":\"Rules of the air & signals\",\"stem\":\"Responsibility for operating an aircraft in accordance with the rules of the air lies with the\",\"opts\":[\"Pilot-in-command\",\"ATC\",\"Flight information centre\"],\"ans\":0,\"exp\":\"The PIC, whether manipulating the controls or not, is responsible for operating the aircraft in accordance with the rules of the air. He may depart from them only when that is absolutely necessary for safety.\",\"seenIn\":[\"Dec 2022 · Session 04\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-328\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"A situation wherein apprehension exists as to the safety of an aircraft and its occupants is the\",\"opts\":[\"Alert phase\",\"Uncertainty phase\",\"Distress phase\"],\"ans\":0,\"exp\":\"Uncertainty - doubt exists. Alert - apprehension exists. Distress - reasonable certainty of grave and imminent danger requiring immediate assistance.\",\"seenIn\":[\"Dec 2022 · Session 04\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-329\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"The DME-based longitudinal separation for aircraft at the same cruising level on the same track, using the same on-track DME station, is\",\"opts\":[\"20 NM\",\"10 NM\",\"5 NM\"],\"ans\":0,\"exp\":\"With both aircraft using on-track DME and position reports frequently checked, 37 km (20 NM) separates two aircraft on the same track at the same level. It reduces to 10 NM only when the leading aircraft is faster by the prescribed margin.\",\"seenIn\":[\"Jul 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-330\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"The power to detain aircraft comes from which section of the Aircraft Act, 1934?\",\"opts\":[\"Section 8\",\"Section 8A\",\"Section 8B\"],\"ans\":0,\"exp\":\"Rule 18 of the Aircraft Rules refers to \\\"an authority authorised under section 8 of the Aircraft Act, 1934, to detain aircraft\\\", who may do so by a written direction to the pilot or person in charge.\",\"seenIn\":[\"Jul 2023 · OLODE\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-331\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"RPAS stands for\",\"opts\":[\"Remotely Piloted Aircraft System\",\"Remote Pilot Aviation Service\",\"Radar Position Advisory System\"],\"ans\":0,\"exp\":\"A remotely piloted aircraft (RPA) is an unmanned aircraft flown from a remote pilot station. The whole set - aircraft, station and command-and-control link - is the RPAS.\",\"seenIn\":[\"Jul 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-332\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"When an IFR flight in airspace where VFR is permitted wishes to continue under VFR to its destination: 1 the pilot must inform the control unit that the IFR flight is cancelled; 2 he must request and obtain a clearance; 3 he communicates the changes to be made to his current flight plan; 4 the flight plan automatically becomes a VFR flight plan. The correct statements are\",\"opts\":[\"1 and 3\",\"2 and 4\",\"1 and 4\"],\"ans\":0,\"exp\":\"Changing from IFR to VFR is the pilot's decision, not a clearance: he notifies ATS specifically that the IFR flight is cancelled and passes the changes to his current flight plan. Nothing happens automatically, and no clearance is requested.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-333\",\"topic\":\"Altimetry\",\"stem\":\"In non-RVSM (CVSM) airspace, an IFR flight on a magnetic track of 125 degrees may cruise at\",\"opts\":[\"FL290\",\"FL310\",\"FL160\"],\"ans\":0,\"exp\":\"Track 000-179 flies the odd levels. Above FL290 in non-RVSM airspace the levels are 4000 ft apart: eastbound FL290, 330, 370, 410; westbound FL310, 350, 390. FL160 is a westbound level too.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-334\",\"topic\":\"Rules of the air & signals\",\"stem\":\"When one aircraft is overtaking another, the right of way belongs to the\",\"opts\":[\"Aircraft being overtaken\",\"Overtaking aircraft\",\"Heavier aircraft\"],\"ans\":0,\"exp\":\"In the air and on the ground alike, the aircraft being overtaken has the right of way; the overtaking aircraft keeps well clear - in the air by altering heading to the right. Size does not come into it.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-335\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"\\\"Air traffic services unit\\\" is a generic term meaning\",\"opts\":[\"An air traffic control unit, flight information centre or air traffic services reporting office\",\"Only air traffic control units and ATS reporting offices\",\"Only flight information centres and ATS reporting offices\"],\"ans\":0,\"exp\":\"All three are ATS units: an ATC unit (area control centre, approach control office or aerodrome tower), a flight information centre, and an ATS reporting office.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-336\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"Time-based longitudinal separation for aircraft at the same cruising level on the same track, where navigation aids allow frequent fixes, when the preceding aircraft is 40 kt or more faster than the following one, is\",\"opts\":[\"3 minutes\",\"5 minutes\",\"10 minutes\"],\"ans\":0,\"exp\":\"The correct answer is: 3 minutes.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-337\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"An IFR flight approaching a controlled aerodrome is cleared for a visual approach. Separation between it and other arriving and departing aircraft is\",\"opts\":[\"Provided by ATC\",\"The pilot's responsibility alone\",\"Not required, because the flight is now VFR\"],\"ans\":0,\"exp\":\"A visual approach is still an IFR flight. ATC keeps separating it from other arriving and departing aircraft; only for successive visual approaches, once the pilot reports the aircraft ahead in sight, may he be told to maintain his own separation from it.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-338\",\"topic\":\"Communications & phraseology\",\"stem\":\"In radiotelephony, the Q code QFE is spoken as\",\"opts\":[\"QUEBEC FOXTROT ECHO\",\"QUEEN FOXTROT ECHO\",\"QUEBEC FOX ELEVATION\"],\"ans\":0,\"exp\":\"The correct answer is: QUEBEC FOXTROT ECHO.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Oct 2023 · FC 07\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-339\",\"topic\":\"Aeronautical information\",\"stem\":\"In India, a NOTAM about changes at locations used by domestic flights only is issued in Series\",\"opts\":[\"C\",\"A\",\"D\"],\"ans\":0,\"exp\":\"Series A carries information of international importance valid for more than 2 hours; Series B shorter international items with limited distribution; Series C changes at locations used by domestic flights only; Series D military-controlled airfields used by domestic flights.\",\"seenIn\":[\"Oct 2023 · FC 07\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-340\",\"topic\":\"Rules of the air & signals\",\"stem\":\"An aircraft taxiing on the manoeuvring area of an aerodrome shall give way to\",\"opts\":[\"Aircraft landing and aircraft taking off or about to take off\",\"Only aircraft landing\",\"Only aircraft taking off\"],\"ans\":0,\"exp\":\"Everything - in flight, on the ground or on the water - gives way to an aircraft landing or on final. And an aircraft taxiing gives way to aircraft taking off or about to take off. Both have priority over a taxiing aircraft.\",\"seenIn\":[\"Oct 2023 · FC 07\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-341\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"Under the flight duty time rules, the maximum flight time in any 28 consecutive days is\",\"opts\":[\"100 hours\",\"125 hours\",\"135 hours\"],\"ans\":0,\"exp\":\"The CAR limits flight time to 35 hours in 7 days, 65 in 14, 100 in 28, 300 in 90 and 1000 in 365 consecutive days. The older 125-hours-in-30-days figure is a different period and the CAR limit is the tighter one.\",\"seenIn\":[\"Oct 2023 · FC 07\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-342\",\"topic\":\"Instrument procedures\",\"stem\":\"Simultaneous approaches to parallel instrument runways where radar separation minima are prescribed between aircraft on adjacent extended centrelines are called\",\"opts\":[\"Dependent parallel approaches\",\"Independent parallel approaches\",\"Segregated parallel operations\"],\"ans\":0,\"exp\":\"Dependent: radar separation is kept between aircraft on the adjacent centrelines, so the approaches depend on each other. Independent: no such separation minima are prescribed between the two streams.\",\"seenIn\":[\"Oct 2023 · FC 07\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-343\",\"topic\":\"Instrument procedures\",\"stem\":\"An aerodrome at which an aircraft would be able to land after experiencing an abnormal or emergency condition while en route is\",\"opts\":[\"An en-route alternate\",\"A take-off alternate\",\"A destination alternate\"],\"ans\":0,\"exp\":\"Take-off alternate: for a problem shortly after take-off when the departure aerodrome cannot be used. En-route alternate: for an abnormal or emergency condition en route. Destination alternate: when landing at the destination becomes impossible or inadvisable.\",\"seenIn\":[\"Oct 2023 · FC 07\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-344\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"Under Rule 38B, a helicopter with a passenger seating capacity of 18 must carry\",\"opts\":[\"No cabin crew member - the requirement starts at 20 seats for helicopters\",\"One cabin crew member\",\"Two cabin crew members\"],\"ans\":0,\"exp\":\"Cabin crew are counted on seats installed. An aeroplane needs one from 10 to 50 seats; a helicopter needs one from 20 to 50 seats; above 50, two plus one for each 50 seats (or part) above 99.\",\"seenIn\":[\"Nov 2023 · OLODE 08\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-345\",\"topic\":\"Human performance\",\"stem\":\"Daytime vision, with its sharpest detail and colour, depends mainly on the\",\"opts\":[\"Cones, concentrated in the fovea\",\"Rods, at the periphery of the retina\",\"Blind spot\"],\"ans\":0,\"exp\":\"The fovea is all cones - it gives the sharpest day vision and colour, and no night vision at all. The rods, spread around the periphery, take over in dim light.\",\"seenIn\":[\"Nov 2023 · OLODE 08\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-346\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"An IFR flight in VFR-permitted airspace decides to continue under VFR. The pilot\",\"opts\":[\"Informs ATS that he is cancelling his IFR flight\",\"Requests a special VFR clearance\",\"Requests a clearance to cancel IFR\"],\"ans\":0,\"exp\":\"Changing to VFR is the pilot's call: he notifies the ATS unit specifically that the IFR flight is cancelled, and passes the changes to the flight plan. No clearance is asked for, and special VFR is something else entirely.\",\"seenIn\":[\"Nov 2023 · OLODE 08\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-347\",\"topic\":\"Rules of the air & signals\",\"stem\":\"In flight, by day, an aircraft acknowledges a light signal from the aerodrome control tower by\",\"opts\":[\"Rocking its wings\",\"Moving its ailerons or rudder\",\"Flashing its landing lights twice\"],\"ans\":0,\"exp\":\"In flight: rocking the wings by day (not expected on base and final), flashing the landing lights by night. On the ground: moving ailerons or rudder by day, flashing landing lights by night.\",\"seenIn\":[\"Nov 2023 · OLODE 08\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-348\",\"topic\":\"Altimetry\",\"stem\":\"To fly at a flight level, the altimeter sub-scale is set to\",\"opts\":[\"1013.2 hPa\",\"QNH\",\"QFE\"],\"ans\":0,\"exp\":\"Flight levels are surfaces of constant pressure referenced to 1013.2 hPa. QNH gives altitude and QFE gives height above the aerodrome.\",\"seenIn\":[\"Nov 2023 · OLODE 08\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-349\",\"topic\":\"Human performance\",\"stem\":\"Nitrogen bubbles released under the skin after a decompression cause\",\"opts\":[\"The creeps\",\"The chokes\",\"The leans\"],\"ans\":0,\"exp\":\"Bends in the joints, chokes in the lungs, creeps under the skin - a crawling sensation. The leans is a vestibular illusion, nothing to do with nitrogen.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-350\",\"topic\":\"ICAO, conventions & documents\",\"stem\":\"ICAO Annex 17 deals with\",\"opts\":[\"Security - safeguarding civil aviation against acts of unlawful interference\",\"Aerodromes\",\"Facilitation\"],\"ans\":0,\"exp\":\"Annex 17 is Security. Aerodromes is Annex 14 and Facilitation Annex 9. Dangerous goods is Annex 18.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-351\",\"topic\":\"Instrument procedures\",\"stem\":\"An instrument approach operation with a decision height at or above 75 m (250 ft) is a\",\"opts\":[\"Type A, CAT I precision approach\",\"Type B, CAT I precision approach\",\"Type A, CAT II precision approach\"],\"ans\":0,\"exp\":\"Type A: MDH or DH at or above 75 m (250 ft) - it includes non-precision, APV and CAT I precision approaches with DH of 75 m or more. Type B: DH below 75 m. A CAT II approach always has a DH below 75 m, so it cannot be Type A.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-352\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"In Class B airspace below 3050 m (10,000 ft) AMSL, the speed limitation for IFR and VFR flights is\",\"opts\":[\"Not applicable\",\"250 kt IAS\",\"260 kt IAS\"],\"ans\":0,\"exp\":\"Classes A and B carry no speed limitation. The 250 kt IAS limit below 10,000 ft applies in Class C (to VFR) and in Classes D to G.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-353\",\"topic\":\"Separation & wake turbulence\",\"stem\":\"An aircraft climbing through the level of another aircraft on the same track must be separated from it, while vertical separation does not exist, by at least\",\"opts\":[\"15 minutes\",\"15 NM\",\"20 NM\"],\"ans\":0,\"exp\":\"The basic figure for a climb or descent through the level of another aircraft on the same track is 15 minutes; it reduces to 10 or 5 minutes only under specific conditions.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-354\",\"topic\":\"Rules of the air & signals\",\"stem\":\"The aircraft that has the right of way shall\",\"opts\":[\"Maintain its heading and speed\",\"Turn right\",\"Turn left\"],\"ans\":0,\"exp\":\"The one with the right of way holds its heading and speed so the other can plan around it - but the PIC is still responsible for doing whatever best averts a collision.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-355\",\"topic\":\"Licensing, medical & national rules\",\"stem\":\"Under the flight duty time rules, flight crew may not undertake duty covering 0000-0600 local time on more than\",\"opts\":[\"Two consecutive nights, except once in any 168 hours\",\"Three consecutive nights\",\"Four consecutive nights\"],\"ans\":0,\"exp\":\"Night duties are limited to two consecutive nights, with one exception allowed in any 168-hour period, because working through the body's low point night after night builds fatigue.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-356\",\"topic\":\"Human performance\",\"stem\":\"At 30,000 ft the average time of useful consciousness is about\",\"opts\":[\"1 to 2 minutes\",\"12 seconds\",\"5 minutes\"],\"ans\":0,\"exp\":\"TUC falls fast with height: about 3-5 minutes at FL250, 1-2 minutes at FL300, 30 seconds to 1 minute at FL350. Moving about shortens it further.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-357\",\"topic\":\"Human performance\",\"stem\":\"Another aircraft is on a collision course with yours when\",\"opts\":[\"It shows no apparent relative motion - it stays at a constant bearing\",\"It always appears to grow rapidly\",\"Its nose points at the same point as yours\"],\"ans\":0,\"exp\":\"A target on a collision course sits still on the windscreen at a constant bearing, growing only slowly until the last seconds. That lack of movement is exactly why it is the hardest to see.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-358\",\"topic\":\"Air traffic services & airspace\",\"stem\":\"Does air traffic control service prevent collisions with terrain?\",\"opts\":[\"No - except that when an IFR flight is vectored, ATC must keep it at the prescribed obstacle clearance\",\"Yes, always\",\"Only for an IFR flight in IMC\"],\"ans\":0,\"exp\":\"ATC service prevents collisions between aircraft, and on the manoeuvring area between aircraft and obstructions. Terrain clearance is the pilot's - except when ATC vectors an IFR flight, when the controller must keep the prescribed obstacle clearance until the pilot resumes own navigation.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-359\",\"topic\":\"Human performance\",\"stem\":\"Carbon dioxide passes from the blood into the alveoli by\",\"opts\":[\"Diffusion\",\"Boyle's law\",\"Dalton's law\"],\"ans\":0,\"exp\":\"Gas exchange in the lungs is diffusion across the respiratory membrane: oxygen into the blood, carbon dioxide out of it, each moving from higher to lower partial pressure.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLREG-360\",\"topic\":\"Human performance\",\"stem\":\"The audible range of the human ear is about\",\"opts\":[\"20 Hz to 20 kHz\",\"2 kHz to 20 kHz\",\"20 MHz to 20,000 MHz\"],\"ans\":0,\"exp\":\"A young, healthy ear hears from about 20 Hz to 20,000 Hz. Prolonged exposure above 80-90 dB causes permanent hearing loss.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false}]},{\"slug\":\"cpl-navigation\",\"subjectId\":\"air-navigation\",\"title\":\"CPL Air Navigation\",\"short\":\"Air Navigation\",\"published\":true,\"checked\":\"17 Oct 2026\",\"sittings\":[\"Jan 2019\",\"Oct 2021 · Attempt 2\",\"Mar 2022\",\"May 2022\",\"Sep 2022 · FC 03\",\"Mar 2023 · ATPL\",\"Jun 2023 · Regular\",\"Jun 2023 · Regular (ATPL)\",\"Jul 2023 · OLODE\",\"Aug 2023 · OLODE\",\"Sep 2023 · Regular 03\",\"Oct 2023 · OLODE\",\"Nov 2023 · OLODE (29 Nov)\",\"Nov 2023 · OLODE (30 Nov)\",\"Dec 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\",\"Feb 2024 · OLODE 02\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"May 2024 · OLODE 04\",\"Jun 2024 · Regular\",\"Jul 2024 · OLODE 05\",\"Aug 2024 · OLODE 06\",\"Sep 2024 · Regular 03\",\"Oct 2024 · OLODE 07\",\"Nov 2024 · OLODE 08\",\"Dec 2024 · Regular 04\",\"Jan 2025 · OLODE 01\",\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\",\"Jul 2025 · OLODE 05\",\"Aug 2025 · OLODE 06\",\"Jan 2026 · OLODE 01\",\"Feb 2026 · OLODE 02\",\"Mar 2026 · Regular 01\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\",\"Aug 2026 · OLODE 06\",\"Sep 2026 · Regular 03\"],\"firstYear\":2019,\"lastYear\":2026,\"questions\":[{\"id\":\"CPLNAV-001\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"The circumference of the earth is approximately:\",\"opts\":[\"21600 NM\",\"43200 NM\",\"5400 NM\",\"10800 NM\"],\"ans\":0,\"exp\":\"The circumference of the earth is 360 x 60 = 21,600 NM.\",\"seenIn\":[\"Jan 2019\",\"Jun 2023 · Regular\",\"Oct 2023 · OLODE\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":5,\"years\":[2019,2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-002\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Parallels of latitude, except the equator, are:\",\"opts\":[\"both Rhumb lines and Great circles\",\"Great circles\",\"Rhumb lines\",\"are neither Rhumb lines nor Great circles\"],\"ans\":2,\"exp\":\"A parallel of latitude cuts every meridian at 90 deg, so it is a rhumb line; only the equator is also a great circle.\",\"seenIn\":[\"Jan 2019\",\"Jun 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\",\"May 2026 · OLODE 04\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":5,\"years\":[2019,2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-003\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Shortest distance between two points on Earth?\",\"opts\":[\"GC routes\",\"RL routes\",\"Both\"],\"ans\":0,\"exp\":\"The shortest distance between two points on the earth is along the great circle.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Apr 2025 · OLODE 03\",\"Jun 2025 · Regular 02\",\"Feb 2026 · OLODE 02\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":5,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-004\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"The ICAO nautical mile is defined as:\",\"opts\":[\"1609 metres\",\"1852 metres\",\"6080 feet\",\"1863 feet\"],\"ans\":1,\"exp\":\"ICAO fixes the nautical mile at exactly 1852 m (about 6076 ft) - the mean length of one minute of arc of a meridian. 1609 m is the statute mile.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jan 2024 · Regular (Day 2)\",\"Apr 2024 · OLODE 03\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":4,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-005\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"004°00'N , 030°00'W : 600 NM South, then 600 NM East, then 600 NM North, then600 NM West. The final position of the aircraft is:\",\"opts\":[\"04°00'N 029°58'W\",\"04°00'N 030°02'W\",\"04°00'N 030°00'W\",\"03°58'N 030°02'W\"],\"ans\":0,\"exp\":\"South and north legs cancel. East leg at 6 deg S: 600/cos6 = 603.3 NM east; west leg at 4 deg N: 600/cos4 = 601.5 NM west. Net 1.8 NM east, so longitude is 030 deg 00 W less 1.8 = 029 deg 58 W.\",\"seenIn\":[\"Jan 2019\",\"Jun 2023 · Regular (ATPL)\",\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":3,\"years\":[2019,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-006\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Longitude is measured:\",\"opts\":[\"0 to 90 deg north or south of the equator\",\"0 to 180 deg east or west of the prime meridian\",\"0 to 360 deg east of Greenwich\",\"0 to 180 deg from the date line\"],\"ans\":1,\"exp\":\"Longitude is the angle at the earth's axis between the prime (Greenwich) meridian and the meridian of the place, 0-180 deg E or W. Latitude is 0-90 deg N or S.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Dec 2023 · Regular\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-007\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"The difference between geodetic and geocentric latitude is greatest at about:\",\"opts\":[\"0 deg\",\"45 deg N and S\",\"60 deg N and S\",\"90 deg N and S\"],\"ans\":1,\"exp\":\"Geodetic (the local vertical) and geocentric (line to the centre) latitude are equal at the equator and poles, where the vertical passes through the centre; the difference peaks (about 11.6') at 45 deg.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Dec 2024 · Regular 04\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-008\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"A line which cuts all meridians at the same angle is called a:\",\"opts\":[\"line of variation\",\"great circle\",\"rhumb line\",\"agonic line\"],\"ans\":2,\"exp\":\"A rhumb line keeps a constant true direction because it crosses every meridian at the same angle. A great circle (except a meridian or the equator) crosses each meridian at a different angle.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Jul 2025 · OLODE 05\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-009\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Two positions on latitude 60 deg N are 10 deg of longitude apart. The rhumb line distance (departure) between them is:\",\"opts\":[\"300 NM\",\"520 NM\",\"600 NM\",\"866 NM\"],\"ans\":0,\"exp\":\"Departure = dlong (minutes) x cos lat = 600 x cos 60 = 300 NM.\",\"seenIn\":[\"Aug 2024 · OLODE 06\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-010\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"An aircraft at latitude 02°20'N tracks 180°(T) for 685 km. On completion of the flight, the latitude will be:\",\"opts\":[\"04°10'S\",\"03°50'S\",\"04°30'S\"],\"ans\":1,\"exp\":\"685 km = 369.9 NM = 6 deg 10 min of latitude. 02 20 N less 6 10 = 03 50 S.\",\"seenIn\":[\"Mar 2025 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-011\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Standing at the south pole you will be facing\",\"opts\":[\"north pole\",\"south pole\",\"equator\"],\"ans\":0,\"exp\":\"At the south pole every direction is north.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Aug 2023 · OLODE\"],\"undated\":false,\"times\":2,\"years\":[2021,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-012\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Length of 1 NM at the poles\",\"opts\":[\"6108 ft (approx)\",\"5280 ft\",\"3280 ft\"],\"ans\":0,\"exp\":\"A minute of latitude is longest at the poles, about 1,861.6 m = 6,108 ft (6,046 ft at the equator).\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-013\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"What is a great circle?\",\"opts\":[\"the shortest distance between 2 points\",\"the longest distance between 2 points\",\"constant distance\"],\"ans\":0,\"exp\":\"A great circle is the shortest path between two points on the surface of a sphere (its plane passes through the centre of the earth).\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-014\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"The shape of the earth is\",\"opts\":[\"oblate spheroid\",\"ellipse\",\"sphere\"],\"ans\":0,\"exp\":\"The earth is an oblate spheroid.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Nov 2023 · OLODE (29 Nov)\"],\"undated\":false,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-015\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"What is the time required to travel along the parallel of latitude 60° N between Meridians 015° E and 025° W at a groundspeed of 480 kt?\",\"opts\":[\"1 HR 45 MIN\",\"1 HR 15 MIN\",\"2 HR 30 MIN\",\"5 HR 00 MIN\"],\"ans\":2,\"exp\":\"d.long = 40 deg; distance = 40 x 60 x cos 60 = 1,200 NM; time = 1,200 / 480 = 2.5 h.\",\"seenIn\":[\"Jan 2019\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2019,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-016\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"An aircraft at 60 deg 00'N 005 deg 22'W flies 165 km due east. What is the new position?\",\"opts\":[\"60 deg 00'N 008 deg 20'E\",\"60 deg 00'N 002 deg 24'W\",\"60 deg 00'N 001 deg 08'E\",\"60 deg 00'N 001 deg 08'W\"],\"ans\":1,\"exp\":\"165 km = 89.1 NM. dlong = 89.1 / cos 60 = 178' = 2 deg 58'. 005 22 W - 2 58 = 002 deg 24'W.\",\"seenIn\":[\"Jul 2024 · OLODE 05\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-017\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"How many feet are equivalent to 9.5 km?\",\"opts\":[\"57,760 ft\",\"31,160 ft\",\"50,160 ft\"],\"ans\":1,\"exp\":\"9.5 km x 3,281 ft/km = 31,170 ft.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-018\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Any meridian is a:\",\"opts\":[\"rhumb line only\",\"semi great circle only\",\"rhumb line and a semi great circle\",\"small circle\"],\"ans\":2,\"exp\":\"A meridian runs pole to pole: half of a great circle (its plane contains the earth's axis) and a line of constant direction (000/180), so a rhumb line too.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-019\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"One degree of arc measured along a meridian is approximately:\",\"opts\":[\"1 NM\",\"60 NM\",\"69 NM\",\"111 NM\"],\"ans\":1,\"exp\":\"One minute of latitude = 1 NM, so one degree = 60 NM (about 111 km - a distractor here, it is not in NM).\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-020\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"A rhumb line cuts all meridians at the same angle. This gives:\",\"opts\":[\"the shortest distance between two points\",\"a line which can never be a great circle\",\"a line of constant direction\",\"a line always curving towards the equator\"],\"ans\":2,\"exp\":\"Same angle with every meridian = same true track all the way, which is why it is easy to fly. It is generally NOT the shortest route (that is the great circle), and meridians and the equator are both.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-021\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"What is the shortest distance between 62 N 087 W and 62 N 093 E?\",\"opts\":[\"3360 NM (about 6220 km)\",\"5070 NM\",\"6300 NM\",\"2520 NM\"],\"ans\":0,\"exp\":\"dlong is exactly 180, so the great circle runs over the North Pole: (90 - 62) x 2 = 56 deg = 3360 NM (6220 km). Along the parallel it would be 10,800 x cos 62 = 5070 NM.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2021,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-022\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"The anti-meridian of 030 deg W is:\",\"opts\":[\"030 deg E\",\"150 deg E\",\"150 deg W\",\"210 deg E\"],\"ans\":1,\"exp\":\"The anti-meridian is the other half of the same great circle: 180 - 30 = 150, on the opposite side - East.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-023\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"The circumference of the parallel of latitude 60 deg N is approximately:\",\"opts\":[\"10,800 NM\",\"18,706 NM\",\"20,000 NM\",\"21,600 NM\"],\"ans\":0,\"exp\":\"A parallel shrinks with the cosine of latitude: 21,600 x cos 60 = 10,800 NM.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-024\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"An aircraft at latitude 10° North flies south at a groundspeed of 445 km/h. What will be its latitude after 3 hours?\",\"opts\":[\"03°50'S\",\"02°00'S\",\"12°15'S\"],\"ans\":1,\"exp\":\"445 km/h x 3 h = 1,335 km = 721 NM = 12 deg 01 min. 10 deg N less 12 01 = 02 deg 01 min S, i.e. about 02 00 S.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-025\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Flying from A (50 N 010 W) to B (58 N 002 E), the initial great circle track is 047(T). The final great circle track is about:\",\"opts\":[\"057\",\"052\",\"043\",\"029\"],\"ans\":0,\"exp\":\"Convergency = dlong x sin mean lat = 12 x sin 54 = 9.7 deg. In the northern hemisphere an easterly great circle track increases: 047 + 10 = 057.\",\"seenIn\":[\"Aug 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-026\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"A great circle is near to ______ and a rhumb line is near to ______\",\"opts\":[\"poles, equator\",\"poles, poles\",\"equator, equator\"],\"ans\":0,\"exp\":\"A great circle curves towards the nearer pole; a rhumb line on a Mercator-type diagram lies on the equator side of it.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-027\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Given: value for the Ellipticity of the Earth is 1/297. Earth's semi-major axis, as Measured at the equator, equals 6378.4 km. What is the semi-minor axis (km) of the earth at the axis of the Poles?\",\"opts\":[\"6356.9\",\"6378.4\",\"6 367.0\",\"6 399.9\"],\"ans\":0,\"exp\":\"Semi-minor axis = a (1 - f) = 6378.4 x (1 - 1/297) = 6356.9 km.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-028\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"The diameter of the Earth is approximately:\",\"opts\":[\"about 12,700 km (6,880 NM)\",\"about 6,370 km (3,440 NM)\",\"about 40,000 km (21,600 NM)\"],\"ans\":0,\"exp\":\"The mean diameter of the earth is about 12,740 km, i.e. about 6,880 NM. 6,370 km is the radius and 40,000 km (21,600 NM) is the circumference.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-029\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"The coordinates of the place are: N17°50' E002°16.5' The coordinates of the antipodes are:\",\"opts\":[\"S41°10' W177°43.5'\",\"S48°50' E177°43.5'\",\"S17°50' W177°43.5'\",\"S41°10' E177°43.5'\"],\"ans\":2,\"exp\":\"Antipodes: latitude same, opposite name (S17 50); longitude 180 - 002 16.5 = 177 43.5 on the other side (W).\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-030\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"In international aviation the following units shall be used, for horizontal distance:\",\"opts\":[\"Meters, Statute miles and Nautical miles\",\"Kilometers, Feet and Nautical miles\",\"Meters, Kilometers and Nautical miles\",\"Kilometers,Statute miles and Nautical miles\"],\"ans\":2,\"exp\":\"ICAO Annex 5 lists metre, kilometre and nautical mile for distances; statute miles and feet (for distance) are not used.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-031\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"For heights and altitudes in international aviation the units used are:\",\"opts\":[\"metres and feet\",\"feet, kilometres and decimals of NM\",\"feet and yards\",\"all of these\"],\"ans\":0,\"exp\":\"ICAO (Annex 5): altitude, elevation and height in metres (feet as the alternative non-SI unit). Horizontal distance uses NM and km.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-032\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"How long is 65 Kilometers at 60 20'N?\",\"opts\":[\"40.2 Statute miles\",\"46.3 Nautical mile\",\"35.0 Nautical mile\",\"27.0 Nautical mile\"],\"ans\":2,\"exp\":\"65 km / 1.852 = 35.1 NM; the latitude does not matter for a distance already in km.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-033\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"At what approximate latitude is the length of one minute of arc along a meridian equal to one NM (1852 m) correct?\",\"opts\":[\"45°\",\"0°\",\"90°\",\"30°\"],\"ans\":0,\"exp\":\"A minute of latitude equals 1 NM (1852 m) at about 45 deg latitude, where the earth radius of curvature gives exactly that.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-034\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"The distance between the parallels of latitude 17 deg 23'S and 23 deg 59'N is:\",\"opts\":[\"4122 NM\",\"636 NM\",\"2473 NM\",\"2482 NM\"],\"ans\":3,\"exp\":\"One is south, one north of the equator: ADD them. 17 23 + 23 59 = 41 deg 22' = 41 x 60 + 22 = 2482 NM.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-035\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"What is the longitude of a position 6 NM to the east of 58°42'N 094°00'W?\",\"opts\":[\"093 53.1'W\",\"093 54.0'W\",\"093 48.5'W\",\"094 12.0'W\"],\"ans\":2,\"exp\":\"d.long = 6 / cos 58 42 = 11.5 min, so longitude is 094 00 W less 11.5 = 093 48.5 W.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-036\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"What is the shortest distance between ROME (4155' N 011°10°E) and HONOLULU 2117' N168°50'W\",\"opts\":[\"7008 nm\",\"6008 nm\",\"6900 nm\",\"8008 nm\"],\"ans\":0,\"exp\":\"Great circle: cos d = sin 41.92 sin 21.28 + cos 41.92 cos 21.28 cos 180.0 -> d = 116.8 deg = 7,008 NM.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-037\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"An aircraft circles the earth along the 60 deg parallel at a groundspeed of 240 kt. What groundspeed is needed along the 20 deg parallel to circle the earth in the same time?\",\"opts\":[\"240 kt\",\"451 kt\",\"128 kt\",\"480 kt\"],\"ans\":1,\"exp\":\"Each parallel's length is proportional to cos lat: 240 x cos 20 / cos 60 = 240 x 0.94 / 0.5 = 451 kt.\",\"seenIn\":[\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-038\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"For navigation purposes the earth is:\",\"opts\":[\"a sphere with a larger polar than equatorial circumference\",\"a sphere whose centre is the same distance from every point on the surface\",\"considered a perfect sphere (though it is really an oblate spheroid)\",\"none of these\"],\"ans\":2,\"exp\":\"The real earth is slightly flattened at the poles (about 1/298), but for nearly all navigation sums it is treated as a sphere, so 1' of latitude = 1 NM everywhere.\",\"seenIn\":[\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true,\"note\":\"Our independent check found that more than one option can be argued for, as worded in the recall. The key gives the answer most references support.\"},{\"id\":\"CPLNAV-039\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Find the change of latitude and longitude from 47 deg 26'N 002 deg 16'W to 43 deg 56'N 001 deg 12'E.\",\"opts\":[\"03 deg 30'S, 003 deg 28'E\",\"03 deg 30'S, 001 deg 04'E\",\"05 deg 36'S, 001 deg 28'E\",\"03 deg 30'N, 003 deg 28'W\"],\"ans\":0,\"exp\":\"Latitude: 47 26 - 43 56 = 3 deg 30', towards the south. Longitude: 002 16 W to 001 12 E crosses Greenwich, so add: 3 deg 28', towards the east.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-040\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"An aircraft flew along a parallel for 10 hrs 24 min at GS of 540 kt and completed 360°. Find out the parallel of latitude:\",\"opts\":[\"15° N or S\",\"75° N or S\",\"45° N or S\"],\"ans\":1,\"exp\":\"Distance = 540 x 10.4 = 5,616 NM = 21,600 x cos lat, so cos lat = 0.26 and the latitude is 75 deg.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-041\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Find Dlat from 00°15'N to 090°00'S\",\"opts\":[\"090°15'N\",\"090°15'S\"],\"ans\":1,\"exp\":\"From 00 15 N to 90 00 S: 15 + 90 deg = 90 deg 15 min, southwards.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-042\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"An aircraft departing A (N40° 00' E080° 00' ) flies a constant true track of 270° at a ground speed of 120 kts. What are the coordinates of the position reached in 6 HR?\",\"opts\":[\"N40° 00' E060° 00' .\",\"N40° 00' E064° 20'.\",\"N40° 00' E068° 10'.\"],\"ans\":1,\"exp\":\"120 kt x 6 h = 720 NM west along the 40 N parallel. d.long = 720 / cos 40 = 940 min = 15 deg 40 min. 080 E less 15 40 = 064 20 E.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-043\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"1 statute mile is equal to:\",\"opts\":[\"5280 ft and 0.869 NM\",\"6076 ft and 1 NM\",\"3280 ft and 1.15 NM\",\"5280 ft and 1.15 NM\"],\"ans\":0,\"exp\":\"1 SM = 5280 ft = 1609 m; 1 NM = 6076 ft = 1852 m, so 1 SM = 0.869 NM and 1 NM = 1.15 SM.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-044\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"The northern vertex of a great circle is at 70 deg N 130 deg E. Its southern vertex is at:\",\"opts\":[\"70 S 050 W\",\"70 S 130 E\",\"70 S 130 W\",\"20 S 050 W\"],\"ans\":0,\"exp\":\"The two vertices of a great circle are antipodal: opposite latitude, longitude differing by 180 deg (130 E -> 050 W).\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-045\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"34.6 inches is about:\",\"opts\":[\"87.9 cm\",\"13.6 cm\",\"34.6 cm\",\"96.1 cm\"],\"ans\":0,\"exp\":\"One inch is exactly 2.54 cm: 34.6 x 2.54 = 87.9 cm.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-046\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"An aircraft flies 448 NM along a parallel of latitude and its longitude changes by 8 deg 21'. What is the latitude?\",\"opts\":[\"26 deg 36' N/S\",\"46 deg 36' N/S\",\"16 deg 36' N/S\",\"63 deg 24' N/S\"],\"ans\":0,\"exp\":\"cos lat = departure / dlong = 448 / 501 = 0.894, lat = 26.6 deg = 26 deg 36' (N or S - the data cannot tell).\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-047\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Which of these is both a great circle and a rhumb line?\",\"opts\":[\"the equator\",\"the parallel of 60 deg N\",\"the Tropic of Cancer\",\"any small circle\"],\"ans\":0,\"exp\":\"The equator's plane passes through the earth's centre (great circle) and it crosses every meridian at 90 deg (rhumb line). Meridians are also both. Other parallels are rhumb lines but small circles.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-048\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"A parallel of latitude (other than the equator) is:\",\"opts\":[\"a great circle\",\"a rhumb line and a small circle\",\"a great circle and a rhumb line\",\"neither a rhumb line nor a small circle\"],\"ans\":1,\"exp\":\"Its plane does not pass through the earth's centre, so it is a small circle; it crosses every meridian at 90 deg, so it is a rhumb line.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-049\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"36.4 inches is about:\",\"opts\":[\"92.5 cm\",\"14.3 cm\",\"36.4 cm\",\"1.09 m\"],\"ans\":0,\"exp\":\"1 inch = 2.54 cm: 36.4 x 2.54 = 92.5 cm.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-050\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"From A (45 deg 00'N 010 deg 00'E) to B (30 deg 00'S 020 deg 00'W), the change of latitude and change of longitude are:\",\"opts\":[\"75 deg S, 30 deg W\",\"15 deg S, 10 deg W\",\"75 deg S, 10 deg E\",\"15 deg N, 30 deg E\"],\"ans\":0,\"exp\":\"Same-name values subtract, opposite names add. Latitude: 45 N to 30 S crosses the equator: 75 deg S. Longitude: 010 E to 020 W crosses Greenwich: 30 deg W.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Apr 2024 · OLODE 03\",\"Jun 2024 · Regular\",\"Sep 2024 · Regular 03\",\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\",\"Mar 2026 · Regular 01\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":8,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-051\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"250 km is equal to approximately:\",\"opts\":[\"135 NM and 155 SM\",\"155 NM and 135 SM\",\"463 NM and 402 SM\",\"135 NM and 402 SM\"],\"ans\":0,\"exp\":\"km / 1.852 = NM: 250 / 1.852 = 135 NM. km / 1.609 = SM: 250 / 1.609 = 155 SM.\",\"seenIn\":[\"Jul 2023 · OLODE\",\"Sep 2023 · Regular 03\",\"Nov 2023 · OLODE (30 Nov)\",\"Jul 2024 · OLODE 05\",\"Jun 2025 · Regular 02\",\"Jul 2025 · OLODE 05\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":7,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-052\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Position A is 12 deg 30'N and position B is 07 deg 45'S on the same meridian. The change of latitude and the distance are:\",\"opts\":[\"20 deg 15'S, 1215 NM\",\"04 deg 45'S, 285 NM\",\"20 deg 15'N, 1215 NM\",\"20 deg 15'S, 2025 NM\"],\"ans\":0,\"exp\":\"Across the equator, add: 12 30 + 07 45 = 20 deg 15', = 1215 NM. Direction is towards B, i.e. south.\",\"seenIn\":[\"Jul 2024 · OLODE 05\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-053\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"An aircraft at 60 deg 00'N 010 deg 00'W flies 300 NM due east. Its new position is:\",\"opts\":[\"60 deg N 005 deg 00'W\",\"60 deg N 000 deg 00'\",\"60 deg N 010 deg 00'E\",\"55 deg N 010 deg 00'W\"],\"ans\":1,\"exp\":\"dlong = departure / cos lat = 300 / 0.5 = 600' = 10 deg; 010 W + 10 deg east = 000.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-054\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Two points on latitude 60 deg N have a change of longitude of 180 deg. Compare the great circle distance over the pole with the rhumb line distance along the parallel:\",\"opts\":[\"3600 NM and 5400 NM\",\"5400 NM and 3600 NM\",\"3600 NM and 10800 NM\",\"7200 NM and 5400 NM\"],\"ans\":0,\"exp\":\"Over the pole: (90 - 60) x 2 = 60 deg of a meridian = 3600 NM. Along the parallel: 180 x 60 x cos 60 = 5400 NM. With dlong 180 the great circle runs up one meridian and down its anti-meridian.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-055\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"Seen from above the North Pole, the earth rotates:\",\"opts\":[\"clockwise, east to west\",\"anticlockwise, west to east\",\"clockwise, west to east\",\"anticlockwise, east to west\"],\"ans\":1,\"exp\":\"The earth turns west to east (anticlockwise from above the North Pole), which is why the sun rises in the east and local time is ahead east of Greenwich.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-056\",\"topic\":\"The Earth, Latitude, Longitude & Distance\",\"stem\":\"What is the change of longitude from 150 deg E to 160 deg W, going east?\",\"opts\":[\"50 deg\",\"310 deg\",\"10 deg\",\"130 deg\"],\"ans\":0,\"exp\":\"Crossing the 180 deg meridian: 180 - 150 = 30 deg to the date line, plus 180 - 160 = 20 deg beyond it = 50 deg east. (Crossing Greenwich you add the two longitudes; crossing 180 you add their differences from 180.)\",\"seenIn\":[\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-057\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"An aircraft accelerates on a westerly heading in the northern hemisphere. The direct reading compass shows:\",\"opts\":[\"an apparent turn to the west\",\"an apparent turn towards north\",\"a decrease of heading towards south\",\"an apparent turn towards south\"],\"ans\":1,\"exp\":\"ANDS (northern hemisphere): Accelerate - North, Decelerate - South. Dip makes the magnet's centre of gravity lag behind the pivot, turning the card.\",\"seenIn\":[\"May 2022\",\"Sep 2023 · Regular 03\",\"Nov 2023 · OLODE (29 Nov)\",\"Nov 2023 · OLODE (30 Nov)\",\"Feb 2024 · OLODE 02\",\"Apr 2024 · OLODE 03\",\"Jun 2024 · Regular\",\"Feb 2026 · OLODE 02\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":9,\"years\":[2022,2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-058\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"A flight log gives, in order: true track, drift, true heading, variation, magnetic heading, deviation, compass heading. Which line is correct?\",\"opts\":[\"125, 2R, 123, 2W, 121, -4, 117\",\"115, 5R, 120, 3W, 123, +2, 121\",\"117, 4L, 121, 1E, 122, -3, 119\",\"119, 3L, 122, 2E, 120, +4, 116\"],\"ans\":3,\"exp\":\"Check every step: 119 with 3 L drift needs heading 122; 2E variation: 122 - 2 = 120 magnetic; +4 (east) deviation: 120 - 4 = 116 compass. The others fail a step (e.g. 123 true with 2W must give 125 magnetic, not 121).\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"May 2024 · OLODE 04\",\"Oct 2024 · OLODE 07\",\"Mar 2025 · Regular 01\",\"Jun 2025 · Regular 02\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":6,\"years\":[2021,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-059\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Lines joining places of equal variation shown on a map/chart are called:\",\"opts\":[\"Isogonals\",\"Isobars\",\"Aclinic lines\"],\"ans\":0,\"exp\":\"Lines joining places of equal magnetic variation are isogonals (isoclinals join equal dip, isogonals equal variation).\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Mar 2025 · Regular 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-060\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The main cause of error in a DRMC is\",\"opts\":[\"parallax in the rose\",\"turning\",\"magnetic deviation\"],\"ans\":1,\"exp\":\"The largest errors of a direct reading compass in flight are the turning and acceleration errors (due to dip).\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Dec 2023 · Regular\",\"Jul 2024 · OLODE 05\",\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":4,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-061\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The sensitivity of a direct reading compass varies:\",\"opts\":[\"inversely with the vertical component of the earth's magnetic field\",\"directly with the vertical component of the earth's magnetic field\",\"inversely with both vertical and horizontal components of the earth's magnetic field\",\"directly with the horizontal component of the earth's magnetic field\"],\"ans\":3,\"exp\":\"Compass sensitivity (directive force) is proportional to the horizontal component H of the earth field - which is why a compass is best midway between the magnetic poles.\",\"seenIn\":[\"Jan 2019\",\"Aug 2023 · OLODE\",\"Jan 2024 · Regular (Day 2)\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":4,\"years\":[2019,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-062\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Agonic lines connect positions that have\",\"opts\":[\"the same variation\",\"0 deg variation\",\"the same elevation\",\"the same angle of magnetic dip\"],\"ans\":1,\"exp\":\"Agonic lines connect points where the magnetic variation is zero; isogonals join points of equal variation.\",\"seenIn\":[\"Jul 2023 · OLODE\",\"Dec 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":4,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-063\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The purpose of a compass swing is to\",\"opts\":[\"measure the angle between true north and magnetic north\",\"find the deviation, reduce it with the compensators and record the residual deviation\",\"measure the dip of the earth field\"],\"ans\":1,\"exp\":\"A compass swing measures deviation on a number of headings, reduces it with the compensators and records the residual deviation on a deviation card.\",\"seenIn\":[\"Mar 2023 · ATPL\",\"Jun 2023 · Regular\",\"Jul 2023 · OLODE\",\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":4,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-064\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The maximum value of magnetic dip, found at the magnetic poles, is:\",\"opts\":[\"0 deg\",\"45 deg\",\"90 deg\",\"180 deg\"],\"ans\":2,\"exp\":\"At the magnetic poles the lines of force are vertical: dip 90 deg. At the magnetic equator they are horizontal: dip 0 deg.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Dec 2023 · Regular\",\"Apr 2025 · OLODE 03\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-065\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"At magnetic equator\",\"opts\":[\"Deviation is zero\",\"Variation is zero\",\"Dip is zero\",\"Agonic line\"],\"ans\":2,\"exp\":\"At the magnetic equator the field is horizontal, so dip is zero. Variation and deviation are not zero there.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Dec 2023 · Regular\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-066\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"At what point on the earth is a magnetic compass most effective?\",\"opts\":[\"At the geographic equator.\",\"Close to the magnetic North Pole.\",\"Approximately midway between the magnetic poles.\"],\"ans\":2,\"exp\":\"A compass is most effective where the horizontal field is strongest and dip smallest - roughly midway between the magnetic poles.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Mar 2024 · Regular 01\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-067\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"True track 352, variation 11 W, deviation -5, drift 10 R. The compass heading is:\",\"opts\":[\"358\",\"346\",\"018\",\"025\"],\"ans\":0,\"exp\":\"Heading = track - starboard drift = 342 T; + 11 W = 353 M; deviation -5 (west) is added going to compass: 358 C.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Jan 2025 · OLODE 01\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-068\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"If variation is west\",\"opts\":[\"True north is east of mag north\",\"True north is west of mag north\"],\"ans\":0,\"exp\":\"West variation means magnetic north lies west of true north, so true north is east of magnetic north.\",\"seenIn\":[\"Apr 2025 · OLODE 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-069\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"During a sustained turn ...... the nearer magnetic pole, the effect of liquid swirl will ...... compass turning error.\",\"opts\":[\"away from; increase\",\"towards; not affect\",\"away from; not affect\",\"towards; increase\"],\"ans\":3,\"exp\":\"In a sustained turn the liquid is dragged round with the bowl, in the direction of the turn. Turning towards the nearer magnetic pole, the turning error already swings the magnet system in the direction of the turn, so the swirl adds to it; turning away, it partly cancels it.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Aug 2023 · OLODE\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-070\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"An aircraft in the northern hemisphere is making an accurate rate one turn to the right. If the initial heading was 135 deg, after 30 seconds the direct reading magnetic compass should read\",\"opts\":[\"225 deg\",\"less than 225 deg\",\"more than 225 deg\"],\"ans\":2,\"exp\":\"The correct answer is: more than 225 deg.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-071\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Isogonals converge at the\",\"opts\":[\"North and South geographic and magnetic poles\",\"North and South magnetic poles only\",\"magnetic equator\",\"North magnetic pole only\"],\"ans\":0,\"exp\":\"Isogonals converge at the magnetic poles and also at the geographic poles.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-072\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Given: True track = 070°, Variation = 35° W, Deviation = +4°, Drift = 10° R Calculate compass heading:\",\"opts\":[\"106°\",\"091°\",\"081°\"],\"ans\":1,\"exp\":\"TH = 070 - 10 (right drift) = 060; MH = 060 + 35 (west variation) = 095; CH = 095 - 4 = 091.\",\"seenIn\":[\"Jul 2025 · OLODE 05\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-073\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"If the total Force of earth field is T and horizontal component and vertical component is H and Z respectively. The value of H will be\",\"opts\":[\"H=T sin dip\",\"H=T cos dip\",\"H=T tan dip\"],\"ans\":1,\"exp\":\"Horizontal component H = T cos (dip); vertical component Z = T sin (dip).\",\"seenIn\":[\"Jun 2023 · Regular\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-074\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Hard-iron magnetism in an aircraft:\",\"opts\":[\"is permanent in nature\",\"is the same in all aircraft of a type\",\"is easily removed by de-gaussing\",\"changes with the aircraft's heading\"],\"ans\":0,\"exp\":\"Hard iron (steel parts) keeps its magnetism - it does not change with heading or latitude, though the DEVIATION it causes changes with heading. Soft iron magnetism is induced by the earth's field and changes as the aircraft moves.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-075\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"A direct reading compass should be swung when:\",\"opts\":[\"there is a large and permanent change of magnetic latitude\",\"there is a large change of magnetic longitude\",\"the aircraft has been stored for a short time\",\"every 7 days\"],\"ans\":0,\"exp\":\"Deviation from soft iron changes with magnetic latitude, so after a permanent move to a very different magnetic latitude (and after lightning strike, major repair or new equipment) the compass is swung.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-076\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"A line joining places of equal magnetic dip is called:\",\"opts\":[\"an agonic line\",\"an isogonal\",\"an aclinic line\",\"an isoclinal\"],\"ans\":3,\"exp\":\"Isoclinal = equal dip; aclinic = zero dip (the magnetic equator). Isogonal = equal variation; agonic = zero variation.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-077\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Maximum variation?\",\"opts\":[\"180\",\"90\",\"none of the above\"],\"ans\":0,\"exp\":\"Magnetic variation can theoretically be as large as 180 deg.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-078\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The line joining points of zero dip (the magnetic equator) is called:\",\"opts\":[\"isogonal\",\"isoclinal\",\"aclinic\",\"agonic\"],\"ans\":2,\"exp\":\"A-clinic = no dip. Do not confuse it with the agonic line, which has zero VARIATION.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-079\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The angle between true north and magnetic north is called:\",\"opts\":[\"compass error\",\"deviation\",\"variation\",\"drift\"],\"ans\":2,\"exp\":\"Variation (declination) = true vs magnetic north, a property of the place. Deviation = magnetic vs compass north, a property of the aircraft.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-080\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"To keep the flux valve of a remote indicating compass away from aircraft (induced) magnetism, it is usually mounted:\",\"opts\":[\"in the cockpit next to the indicator\",\"in a wing tip or the tail\",\"next to the engine\",\"under the floor near the battery\"],\"ans\":1,\"exp\":\"The detector unit (flux valve) is placed as far as possible from the aircraft's hard- and soft-iron sources and electrical fields - typically a wing tip or the fin - and feeds the gyro-stabilised indicator remotely.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2021,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-081\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"In the southern hemisphere an aircraft lands (decelerates) on a westerly heading. The compass will show:\",\"opts\":[\"an apparent turn to the south\",\"no apparent turn\",\"an apparent turn to the north\",\"a heading of 270 exactly\"],\"ans\":2,\"exp\":\"In the southern hemisphere everything reverses: Accelerate - South, Decelerate - North. So a landing on a westerly heading shows a turn towards north.\",\"seenIn\":[\"Dec 2023 · Regular\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-082\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Compass turning error is caused by:\",\"opts\":[\"variation and deviation\",\"magnetic dip together with the centripetal force in the turn acting on the offset centre of gravity of the magnet\",\"friction in the pivot only\",\"liquid viscosity only\"],\"ans\":1,\"exp\":\"Dip tilts the magnet system so its centre of gravity is offset from the pivot; in a turn the centripetal force acts on that offset mass and swings the card. Liquid swirl adds to it.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-083\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"True track= 350 deg, variation= 11W, Deviation= -5, Drift= 10R, What is Compass heading?\",\"opts\":[\"356 deg\",\"078 deg\",\"346 deg\",\"025 deg\"],\"ans\":0,\"exp\":\"TH = 350 - 10 = 340; MH = 340 + 11 = 351; CH = 351 - (-5) = 356.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-084\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Acceleration errors of a direct reading compass are greatest on headings of:\",\"opts\":[\"000 and 180\",\"045 and 225\",\"135 and 315\",\"090 and 270\"],\"ans\":3,\"exp\":\"The error comes from the dip-offset magnet swinging across the heading. On east/west headings the force acts across the magnet and turns it most; on north/south it acts along it (no error).\",\"seenIn\":[\"Aug 2024 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-085\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"A line joining places of zero variation is called\",\"opts\":[\"an aclinic line\",\"an isoclinic line\",\"an agonic line\"],\"ans\":2,\"exp\":\"An agonic line joins places of zero magnetic variation; an isogonal joins equal variation and an isoclinal joins equal dip.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-086\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The Earth can be considered as being a magnet with the\",\"opts\":[\"blue pole near the north pole of the earth and the direction of the magnetic force pointing straight up from the earth's surface\",\"red pole near the north pole of the earth and the direction of the magnetic force pointing straight up from the earth's surface\",\"blue pole near the north pole of the earth and the direction of the magnetic force pointing straight down to the earth's surface\"],\"ans\":2,\"exp\":\"The earth behaves as a magnet whose blue (south-seeking) pole is near the geographic north pole, with the field pointing down there.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-087\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"When magnetic north is east of true north, variation is\",\"opts\":[\"(+) easterly\",\"(-) westerly\",\"(+) westerly\"],\"ans\":0,\"exp\":\"Magnetic north east of true north is easterly (+) variation.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-088\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The coefficient C is equivalent to\",\"opts\":[\"P\",\"Q\",\"R\"],\"ans\":1,\"exp\":\"Coefficient C comes from athwartships hard iron Q (and soft iron fZ).\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-089\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"A direct reading magnetic compass is made aperiodic (dead beat) by:\",\"opts\":[\"using the lowest-viscosity liquid\",\"keeping the magnet mass close to the pivot, using several short magnets, and damping liquid\",\"using long magnets\",\"pendulous suspension\"],\"ans\":1,\"exp\":\"Aperiodic = settles without oscillating. Mass near the pivot (low moment of inertia), short magnets and damping filaments in liquid do it.\",\"seenIn\":[\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-090\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"When accelerations on an easterly heading in the Northern hemisphere, the compass card of a direct reading magnetic compass will turn?\",\"opts\":[\"Anti-clockwise giving an apparent turn toward the south.\",\"Clockwise giving an apparent turn toward the north.\",\"Clockwise giving an apparent turn toward the south.\",\"Anti-clockwise giving an apparent turn toward the north.\"],\"ans\":1,\"exp\":\"Accelerating on an easterly heading in the northern hemisphere the card turns clockwise, an apparent turn towards the north (ANDS).\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-091\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The total Magnetic Force of the terrestrial magnetic field\",\"opts\":[\"Is horizontal in all positions on the surface of the Earth\",\"Is vertical at the magnetic equator\",\"Is strongest at the magnetic poles\",\"Will be stronger at higher altitudes because the attenuation is less at high altitudes\"],\"ans\":2,\"exp\":\"The total magnetic force is strongest at the magnetic poles.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-092\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Coefficient B, as used in aircraft magnetism, presents\",\"opts\":[\"The resultant deviation from magnetism along the aircraft lateral axis\",\"A value representing the deviation registered on headings East and West\",\"The resultant deviation from magnetism along the aircraft vertical (normal) axis\",\"Deviation values caused by hard iron magnetism only\"],\"ans\":1,\"exp\":\"Coefficient B is the deviation that is greatest on easterly and westerly headings (it comes from fore-and-aft hard iron P).\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-093\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Deviation on MH 180 is -5 and on MH 000 it is +3. Calculate coefficient C:\",\"opts\":[\"Coefficient C=-1\",\"Coefficient C = +4\",\"Coefficient C = -2\",\"Coefficient C = +8\"],\"ans\":1,\"exp\":\"Coefficient C = (deviation on 000 - deviation on 180) / 2 = (+3 - (-5)) / 2 = +4.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-094\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"An aircraft in the northern hemisphere makes an accurate rate one turn to the right/starboard. If the initial heading was 330°, after 30 seconds of the turn the direct reading magnetic compass should read:\",\"opts\":[\"060°\",\"less than 060°\",\"more than 060°\",\"more or less than 060° depending on the pendulous suspension used\"],\"ans\":1,\"exp\":\"Turning right through north in the northern hemisphere the compass lags - UNOS (undershoot north) - so after 90 deg of turn it reads less than 060.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-095\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Given: true track is 348°, drift 17 ° left, variation 32° W, deviation 4° E. What is the compass heading?\",\"opts\":[\"041°\",\"141°\",\"044°\",\"033°\"],\"ans\":3,\"exp\":\"TH = 348 + 17 = 005; MH = 005 + 32 = 037; CH = 037 - 4 (east deviation) = 033.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-096\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Charted values of magnetic variation on earth normally change annually due to\",\"opts\":[\"magnetic pole movement causing numerical values at all locations to increase or decrease\",\"an increasing field strength causing numerical values at all locations to increase\",\"magnetic pole movement causing numerical values at all locations to increase\",\"a reducing field strength causing numerical values at all locations to decrease\"],\"ans\":0,\"exp\":\"Variation charted at a place changes slowly with time because the magnetic poles move - the numerical value at different places may increase or decrease.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-097\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Northern hemisphere, heading 145 on a direct reading magnetic compass. You make an accurate rate 1 turn to the right for 30 seconds. On rolling out, the compass reads:\",\"opts\":[\"more than 235\",\"less than 235\",\"exactly 235\",\"more or less, depending on speed\"],\"ans\":0,\"exp\":\"Rate 1 = 3 deg/s, so 30 s = 90 deg: the real heading is 235. Turning through SOUTH in the northern hemisphere the compass LEADS (reads ahead of the turn) - UNOS: Undershoot North, Overshoot South - so it over-reads, showing more than 235. Hence roll out early on northerly headings and late on southerly ones.\",\"seenIn\":[\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-098\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"An aircraft is completing a timed turn in the Northern hemisphere from 330°C to 040°C. After the turn has been stopped but before the direct indicating magnetic compass settles down , will the compass overread or underread. or error increased or decreased by liquid swirl?\",\"opts\":[\"Over read and increased\",\"Underread and increased\",\"Under read and decreased\"],\"ans\":1,\"exp\":\"Turning through north in the northern hemisphere the compass under-reads (it lags the turn). The liquid in the bowl is dragged round in the direction of the turn and carries the magnet with it, so the error is increased.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-099\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The horizontal component of the earth's magnetic field?\",\"opts\":[\"Weakens with increasing distance from the magnetic poles\",\"Weakens with increasing distance from the nearer magnetic poles\",\"Is Approximately the same at magnetic latitude 50°N and 50°S\"],\"ans\":2,\"exp\":\"H is about equal at equal magnetic latitudes N and S, and falls toward the poles.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-100\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Which component for Permanent magnetism induced along longitudinal axis or fore and aft axis?\",\"opts\":[\"+P\",\"+Q\",\"+R\"],\"ans\":0,\"exp\":\"Permanent (hard iron) magnetism along the fore-and-aft axis is +P.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-101\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The angle between magnetic north and compass North is called\",\"opts\":[\"Magnetic variation\",\"Compass deviation\",\"Alignment error\"],\"ans\":1,\"exp\":\"Deviation is the angle between magnetic north and compass north.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-102\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The fore-and-aft component of an aircraft's permanent (hard-iron) magnetism is denoted by:\",\"opts\":[\"P\",\"Q\",\"R\"],\"ans\":0,\"exp\":\"Hard iron P (fore and aft) produces coefficient B, Q (athwartships) coefficient C and R (vertical) the vertical-force terms.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-103\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Angular difference between magnetic north and true north\",\"opts\":[\"Variation\",\"Deviation\",\"Convergency\"],\"ans\":0,\"exp\":\"Variation is the angle between true north and magnetic north; deviation is between magnetic north and compass north.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-104\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Magnetism in vertical soft iron of an aircraft:\",\"opts\":[\"varies with heading but not latitude\",\"varies with magnetic latitude but not heading\",\"is not affected by latitude or heading\",\"varies as the cosine of heading\"],\"ans\":1,\"exp\":\"Soft iron is magnetised by induction from the earth's field. Vertical soft iron sees the vertical component Z, which grows with magnetic latitude but is the same on every heading.\",\"seenIn\":[\"May 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-105\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"An aircraft lands (decelerates) on a southerly heading in the southern hemisphere. The direct reading compass shows:\",\"opts\":[\"an apparent turn to the west\",\"an apparent turn to the east\",\"no apparent turn\",\"an apparent turn through 180 deg\"],\"ans\":2,\"exp\":\"Acceleration and deceleration errors come from the dip (vertical) component acting through the offset centre of gravity of the magnet system. On north and south headings the force lies along the magnet, so there is no turning moment - no error, either hemisphere.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-106\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The red pole of a freely suspended magnet points towards ......, and at latitude 60 deg N points ...... at an angle known as ......\",\"opts\":[\"the nose of the aircraft, downwards, deviation\",\"the north magnetic pole, downwards, variation\",\"the nearest pole, downwards, declination\",\"the north magnetic pole, downwards, dip\"],\"ans\":3,\"exp\":\"The red (north-seeking) pole points to the north magnetic pole and, away from the magnetic equator, dips below the horizontal along the lines of force. The angle below horizontal is the dip.\",\"seenIn\":[\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-107\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"A landing compass:\",\"opts\":[\"Is used to establish aircraft magnetic heading during a compass swing\",\"Is the compass used as reference during landing\",\"Is a compass on which compass direction for landing may be set\"],\"ans\":0,\"exp\":\"A landing compass is a hand-held reference compass used to establish magnetic heading during a compass swing.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-108\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Residual deviation is corrected by:\",\"opts\":[\"Deviation card\",\"Lubber line\",\"Micro adjusters\"],\"ans\":0,\"exp\":\"Residual deviation after the swing cannot be removed; it is recorded on the deviation card and applied by the pilot.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-109\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"An aircraft accelerating on a westerly heading in the northern hemisphere: the DRC indicates a turn to\",\"opts\":[\"north\",\"south\"],\"ans\":0,\"exp\":\"Accelerating on an east or west heading in the northern hemisphere the compass shows an apparent turn towards the north (ANDS: Accelerate North).\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-110\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Magnetic dip is the angle between the earth's magnetic lines of force and\",\"opts\":[\"true north\",\"the horizontal\",\"the magnetic meridian\",\"the vertical\"],\"ans\":1,\"exp\":\"Dip (inclination) is measured from the horizontal down to the line of force; the needle's red end dips downwards in the northern hemisphere.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-111\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The magnetic meridian at a place is:\",\"opts\":[\"the great circle through the magnetic poles\",\"the horizontal direction of the earth's magnetic field at that place\",\"the direction of the earth's lines of force including dip\",\"the line of zero variation\"],\"ans\":1,\"exp\":\"Magnetic north is the direction a freely suspended, horizontally constrained needle settles - the horizontal component of the field. It does not in general point exactly at the magnetic pole.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-112\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The earth's magnetic poles are not fixed. As a result:\",\"opts\":[\"variation at a place changes slowly year by year\",\"deviation changes year by year\",\"dip is always zero at the geographic poles\",\"the agonic line never moves\"],\"ans\":0,\"exp\":\"The magnetic poles wander, so the variation at any place drifts (typically a few minutes of arc a year). Charts state the variation for a year and the annual change.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-113\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"In a remote indicating compass, the flux valve (detector unit):\",\"opts\":[\"seeks north with a magnet like a direct compass\",\"senses the direction of the horizontal component of the earth's field electrically\",\"measures dip\",\"is a gyro\"],\"ans\":1,\"exp\":\"The flux valve has no moving magnet: its windings sense the horizontal field electrically and the signal slaves the directional gyro, so it senses rather than seeks north.\",\"seenIn\":[\"May 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-114\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Northern hemisphere, turning left from 090 to 360 using a direct reading compass, you should roll out:\",\"opts\":[\"when the compass reads 360\",\"before the compass reads 360\",\"after the compass passes 360\",\"when the compass reads 330 exactly\"],\"ans\":1,\"exp\":\"Turning towards north the compass lags, so it still reads less than the turn made: stop the turn early - Undershoot North.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-115\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"The directive force (sensitivity) of a magnetic compass depends on the horizontal component H of the earth's field. H is:\",\"opts\":[\"strongest near the magnetic poles\",\"strongest near the magnetic equator\",\"the same everywhere\",\"zero at the magnetic equator\"],\"ans\":1,\"exp\":\"H = T cos dip: greatest where dip is zero (magnetic equator), zero at the magnetic poles - which is why the compass is useless near the poles and best roughly midway.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-116\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Northern hemisphere, heading north, you start a turn to the right. The direct reading compass will initially:\",\"opts\":[\"lead the turn\",\"lag behind the turn (or even show a turn the other way)\",\"read correctly\",\"swing to south\"],\"ans\":1,\"exp\":\"Turning error: through north in the northern hemisphere the compass lags (sluggish); through south it leads. Hence UNOS - Undershoot North, Overshoot South when rolling out.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-117\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"A line of constant MAGNETIC track over a long distance is:\",\"opts\":[\"a great circle\",\"a rhumb line\",\"neither, because the variation changes along it\",\"a parallel of latitude\"],\"ans\":2,\"exp\":\"A rhumb line keeps a constant TRUE direction; a great circle is the shortest. A constant magnetic track only matches a rhumb line where the variation stays the same.\",\"seenIn\":[\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-118\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"Moving from the magnetic equator towards a magnetic pole, the horizontal (H) and vertical (Z) components of the earth's field:\",\"opts\":[\"H increases, Z decreases\",\"H decreases, Z increases\",\"both increase\",\"both decrease\"],\"ans\":1,\"exp\":\"At the magnetic equator the field is horizontal (H maximum, Z zero); at the magnetic pole it is vertical (H zero, Z maximum). H = T cos dip, Z = T sin dip.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-119\",\"topic\":\"Earth Magnetism & the Magnetic Compass\",\"stem\":\"When an aircraft turns through east or west (northern hemisphere), the compass turning error is:\",\"opts\":[\"greatest\",\"about zero\",\"always a lag\",\"always a lead\"],\"ans\":1,\"exp\":\"Turning error is largest through north and south and close to zero through east and west, where the dip force lies along the turn.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-120\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"A Lambert conformal conic projection, with two standard parallels:\",\"opts\":[\"shows lines of longitude as parallel straight lines\",\"shows all great circles as straight lines\",\"the scale is only correct at parallel of origin\",\"the scale is only correct along the standard parallels\"],\"ans\":3,\"exp\":\"With two standard parallels a Lambert chart has its true scale along the standard parallels (smaller between them, larger outside).\",\"seenIn\":[\"Jan 2019\",\"Jun 2023 · Regular (ATPL)\",\"Jun 2023 · Regular\",\"Sep 2023 · Regular 03\",\"Oct 2023 · OLODE\",\"Nov 2023 · OLODE (30 Nov)\",\"Jun 2025 · Regular 02\",\"Aug 2025 · OLODE 06\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":9,\"years\":[2019,2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-121\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a direct Mercator chart the scale at 30 deg N is 1 : 3,500,000. The scale at 40 deg N is about:\",\"opts\":[\"1 : 3,096,000\",\"1 : 3,957,000\",\"1 : 2,627,000\",\"1 : 4,667,000\"],\"ans\":0,\"exp\":\"Denominators are proportional to cos lat: 3,500,000 x cos 40 / cos 30 = 3,500,000 x 0.766 / 0.866 = 3,096,000. Higher latitude, bigger chart, smaller denominator.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Sep 2024 · Regular 03\",\"Jun 2025 · Regular 02\",\"Aug 2025 · OLODE 06\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":6,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-122\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a Direct Mercator chart a great circle will be represented by a?\",\"opts\":[\"Straight lines.\",\"Curves convex to the equator.\",\"Curve concave to the equator.\",\"Curves concave to the nearest pole\"],\"ans\":2,\"exp\":\"A great circle (other than a meridian or the equator) is a curve that is concave to the equator on a direct Mercator, i.e. convex towards the nearer pole.\",\"seenIn\":[\"Jan 2019\",\"Jan 2024 · Regular (Day 2)\",\"Apr 2024 · OLODE 03\",\"Oct 2024 · OLODE 07\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":5,\"years\":[2019,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-123\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a Direct Mercator chart, a rhumb line appears as a:\",\"opts\":[\"straight line\",\"small circle concave to the nearer pole\",\"spiral curve\",\"curve convex to the nearer pole\"],\"ans\":0,\"exp\":\"On a direct Mercator chart a rhumb line is a straight line.\",\"seenIn\":[\"Jan 2019\",\"Jul 2023 · OLODE\",\"Dec 2023 · Regular\",\"May 2024 · OLODE 04\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":5,\"years\":[2019,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-124\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"A direct mercator chart projection is :\",\"opts\":[\"cylindrical, perspective & conformal\",\"conical, non-perspective & conformal\",\"cylindrical, non-perspective & conformal\"],\"ans\":2,\"exp\":\"The direct Mercator is a cylindrical, mathematically derived (non-perspective) and conformal projection.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Mar 2024 · Regular 01\",\"May 2024 · OLODE 04\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-125\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"Convergency of the meridians is:\",\"opts\":[\"the angle of inclination of the meridians to each other\",\"the change of direction of a rhumb line\",\"the angle at which a meridian cuts the equator\",\"the angle between two parallels\"],\"ans\":0,\"exp\":\"Meridians are parallel at the equator and meet at the poles; the angle between two of them at a given latitude is the convergency, = dlong x sin lat.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Apr 2024 · OLODE 03\",\"May 2024 · OLODE 04\",\"Aug 2025 · OLODE 06\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":5,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-126\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"Rhumb line on a polar stereographic chart\",\"opts\":[\"straight lines\",\"curves concave to the nearer pole\",\"curves convex to the nearer pole\"],\"ans\":1,\"exp\":\"On a polar stereographic chart rhumb lines are curves concave to the pole.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Jun 2023 · Regular (ATPL)\",\"Dec 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":4,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-127\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a transverse Mercator chart the scale is correct along:\",\"opts\":[\"the 180 deg meridian\",\"the false meridian\",\"the equator\",\"the meridian of tangency\"],\"ans\":3,\"exp\":\"The cylinder is wrapped round the earth touching along a chosen meridian (the meridian of tangency); scale is correct along it and expands with distance from it - the transverse version of \\\"correct at the equator\\\" on the direct Mercator.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":4,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-128\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a direct Mercator chart two meridians 5 deg apart are 8 cm apart at 60 deg N. The scale at 60 deg N is about:\",\"opts\":[\"1 : 4,750,000\",\"1 : 7,000,000\",\"1 : 6,000,000\",\"1 : 3,500,000\"],\"ans\":3,\"exp\":\"Departure = 300 x cos 60 = 150 NM = 277.8 km = 27,780,000 cm. Scale = 8 : 27,780,000 = 1 : 3,470,000.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2023 · Regular\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-129\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"The value of the convergence factor (n) on a polar stereographic chart is:\",\"opts\":[\"0.866\",\"0.5\",\"0\",\"1.0\"],\"ans\":3,\"exp\":\"On a polar stereographic chart meridians meet at the pole at their true angle, so chart convergence = dlong x 1: n = 1 (= sin 90). On a Mercator n = 0; on a Lambert n = sin of the parallel of origin.\",\"seenIn\":[\"Jul 2023 · OLODE\",\"Nov 2023 · OLODE (30 Nov)\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-130\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a direct Mercator chart the scale:\",\"opts\":[\"is constant everywhere\",\"is correct at the equator and expands as the secant of the latitude\",\"is correct at the standard parallels\",\"contracts away from the equator\"],\"ans\":1,\"exp\":\"The projection stretches each parallel to the length of the equator, by sec lat, and stretches the meridians by the same amount to keep it conformal. So scale at latitude L = scale at the equator x sec L - at 60 deg it is doubled.\",\"seenIn\":[\"Mar 2025 · Regular 01\",\"Jun 2025 · Regular 02\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-131\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"If the chart scale is 1 : 500,000, what earth distance is represented by 7 cm on the chart?\",\"opts\":[\"35 NM\",\"3.5 km\",\"35,000 m\",\"0.35 km\"],\"ans\":2,\"exp\":\"7 cm x 500,000 = 3,500,000 cm = 35,000 m = 35 km (about 19 NM).\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Aug 2024 · OLODE 06\",\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-132\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"What shape is the graticule of a direct Mercator chart?\",\"opts\":[\"Rectangular\",\"Square\",\"Triangular\"],\"ans\":0,\"exp\":\"The graticule of a direct Mercator chart is rectangular (straight, perpendicular lines; the parallels are unequally spaced).\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jun 2023 · Regular\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2021,2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-133\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a direct Mercator chart convergency is\",\"opts\":[\"increases with latitude\",\"decreases with latitude\",\"constant everywhere\"],\"ans\":2,\"exp\":\"On a direct Mercator chart the meridians are parallel, so chart convergency is zero (constant) everywhere.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\",\"Aug 2023 · OLODE\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-134\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"Which one of the following, concerning great circles on a Direct Mercator chart, is correct?\",\"opts\":[\"with the exception of meridians and the equator, they are curves concave to the equator\",\"straight lines\",\"curves concave to the nearest pole\"],\"ans\":0,\"exp\":\"Apart from meridians and the equator, a great circle on a direct Mercator chart is a curve concave to the equator (convex to the nearer pole).\",\"seenIn\":[\"Dec 2023 · Regular\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-135\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"Transverse Mercator charts are used for\",\"opts\":[\"large N/S extension\",\"large E/W extension\"],\"ans\":0,\"exp\":\"Transverse Mercator suits areas of large north-south extent.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-136\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"The nominal scale of a Lambert conformal conic chart is the\",\"opts\":[\"scale at the standard parallels\",\"scale at the equator\",\"mean scale between pole and equator\",\"mean scale between the parallels of the secant cone\"],\"ans\":0,\"exp\":\"The nominal scale of a Lambert chart is the scale at the standard parallels.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-137\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a Lambert conformal conic chart earth convergency is most accurately represented at the\",\"opts\":[\"parallel of origin\",\"equator\",\"north and south limits of the chart\",\"standard parallels\"],\"ans\":0,\"exp\":\"On a Lambert conformal conic chart convergence equals earth convergence only at the parallel of origin.\",\"seenIn\":[\"Jan 2019\",\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":2,\"years\":[2019,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-138\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a direct Mercator projection, at latitude 45° north, a certain length represents 70 Nm. At latitude 30° North, the same length represents approximately?\",\"opts\":[\"86Nm\",\"75Nm\",\"45Nm\"],\"ans\":0,\"exp\":\"70 x cos 30 / cos 45 = 85.7, about 86 NM.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-139\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"Perfectly straight line on a Lamberts chart is?\",\"opts\":[\"Parallel of latitude.\",\"Rhumb line.\",\"Meridian of longitude.\"],\"ans\":2,\"exp\":\"Only meridians are perfectly straight on a Lambert chart; great circles are curved (nearly straight) and parallels are arcs.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-140\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"In the polar stereographic projection, a plane touches the reduced earth at one pole and the projection (light) point is at:\",\"opts\":[\"the centre of the earth\",\"the opposite pole\",\"infinity\",\"the equator\"],\"ans\":1,\"exp\":\"Polar stereographic: tangent plane at one pole, light at the OTHER pole - which makes it conformal. With the light at the centre it is the gnomonic (great circles straight); with it at infinity, orthographic.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-141\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a Lambert conformal conic chart the convergence of the meridians is?\",\"opts\":[\"The same as earth convergency at the parallel of origin.\",\"The same as the scale.\",\"Most accurate at the standard parallels.\"],\"ans\":0,\"exp\":\"Lambert chart convergence equals earth convergency at the parallel of origin and is constant over the chart.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-142\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"The scale on a Lambert conformal conic chart:\",\"opts\":[\"is constant along a meridian of longitude\",\"is constant along a parallel of latitude\",\"varies slightly as a function of latitude and longitude\"],\"ans\":1,\"exp\":\"Lambert scale is constant along a parallel and varies with latitude only.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-143\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"What is the earth convergency between the meridians 010 deg W and 020 deg E at latitude 50 deg N?\",\"opts\":[\"23 deg\",\"30 deg\",\"19 deg\",\"15 deg\"],\"ans\":0,\"exp\":\"dlong 30 deg x sin 50 (0.766) = 23 deg.\",\"seenIn\":[\"Apr 2025 · OLODE 03\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-144\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a transverse Mercator chart, with the exception of the equator, parallels of latitude appear as:\",\"opts\":[\"hyperbolic lines\",\"straight lines\",\"ellipses\",\"parabolas\"],\"ans\":2,\"exp\":\"Turned on its side, the Mercator shows the meridian of tangency and the equator straight; the parallels become ellipses round the poles.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-145\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"Which chart cannot show the polar regions?\",\"opts\":[\"Polar stereographic\",\"Direct Mercator\",\"Transverse Mercator\",\"Lambert conformal with parallel of origin at 75 deg\"],\"ans\":1,\"exp\":\"On a direct Mercator chart the scale expands as sec latitude, so the poles lie at infinity and cannot be shown; polar areas use the polar stereographic (or a transverse Mercator) chart.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-146\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"A direct Mercator chart has a scale of 1 : 3,704,000 at the equator. The scale at 60 deg S is:\",\"opts\":[\"1 : 1,852,000\",\"1 : 7,408,000\",\"1 : 3,208,000\",\"1 : 185,200\"],\"ans\":0,\"exp\":\"Scale expands as sec lat: at 60 deg the chart is twice as big, so the denominator halves: 3,704,000 x cos 60 = 1,852,000.\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-147\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"Contours are lines drawn on a map or chart joining:\",\"opts\":[\"Places of equal elevation\",\"Equal pressure\",\"Equal variation\"],\"ans\":0,\"exp\":\"Contours are lines joining places of equal elevation.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-148\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"The distance between positions A and B, located on the same parallel and 10 deg of longitude apart, is 6 cm. The scale at the parallel is 1:9 260 000. What is the latitude of A and B?\",\"opts\":[\"30 N or S\",\"60 N or S\",\"45 N or S\"],\"ans\":1,\"exp\":\"6 cm x 9,260,000 = 555.6 km = 300 NM for 10 deg of longitude: 30 NM per degree = 60 x cos lat, so cos lat = 0.5 and lat = 60.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-149\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"The angular difference, on a Lambert conformal conic chart, between the arrival and departure track is equal to\",\"opts\":[\"departure angle\",\"map convergence\",\"secant of half latitude\"],\"ans\":1,\"exp\":\"The change of track between two points on a Lambert chart equals the map (chart) convergence.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-150\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a chart, 49 nautical miles is represented by 7.0 centimetres. What is the scale?\",\"opts\":[\"1/700000\",\"1/2015396\",\"1/1296400\"],\"ans\":2,\"exp\":\"49 NM = 90,748 m; 7 cm = 0.07 m; scale = 90,748 / 0.07 = 1 : 1,296,400.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-151\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On which of the following chart projections is it NOT possible to represent the north or south poles?\",\"opts\":[\"Lambert's conformal\",\"Direct Mercator\",\"Transverse Mercator\",\"Polar stereographic\"],\"ans\":1,\"exp\":\"The poles lie at infinity on a direct Mercator chart.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-152\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a Direct Mercator chart at latitude 15°S, a certain length represents a distance of 120 NM on the earth. The same length on the chart will represent on the earth, at latitude 10°N, a distance of :\",\"opts\":[\"122.3NM\",\"117.7NM\",\"124.2NM\",\"118.2 NM\"],\"ans\":0,\"exp\":\"Distance for a given chart length varies as cos (lat): 120 x cos 10 / cos 15 = 122.3 NM.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-153\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a Direct Mercator chart at latitude of 45°N, a certain length represents a distance of 90 NM on the earth. The same length on the chart will represent on the earth, at latitude 30°N, a distance of\",\"opts\":[\"45 NM\",\"73.5 NM\",\"78 NM\",\"110 NM\"],\"ans\":3,\"exp\":\"90 x cos 30 / cos 45 = 110 NM.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-154\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"The total length of the 53°N parallel of latitude on a direct Mercator chart is 133 cm. What is the approximate scale of the chart at latitude 30°S?\",\"opts\":[\"1:26 000 000\",\"1 : 30 000 000\",\"1: 18 000 000\",\"1: 21 000 000\"],\"ans\":0,\"exp\":\"The 53 N parallel is 21,600 x cos 53 = 13,000 NM = 24,075 km long, drawn as 133 cm: scale 1:18.1 million at 53 N. Mercator scale varies with the secant of latitude, so at 30 S it is 1:18.1 M x cos 30 / cos 53 = about 1:26 million.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-155\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"Given: Great circle from P to Q measured at P=095° Southern hemisphere Conversion angle P - Q=7° what is the rhumb line track P - Q?\",\"opts\":[\"081\",\"102\",\"088\",\"109\"],\"ans\":2,\"exp\":\"In the southern hemisphere the rhumb line track is the GC track minus the conversion angle when heading east: 095 - 7 = 088.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-156\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"To plot an ADF bearing from the NDB on a Lambert conformal chart, the true bearing measured at the aircraft must be corrected by:\",\"opts\":[\"the conversion angle\",\"the chart convergence between the aircraft and station meridians\",\"the magnetic variation at the station\",\"nothing - it is plotted as measured\"],\"ans\":1,\"exp\":\"The ADF gives the true bearing at the AIRCRAFT meridian (heading + relative bearing). A Lambert straight line is (nearly) a great circle, so no conversion angle is applied; but to draw it from the station the direction must be referred to the STATION meridian, which differs by the chart convergence = change of longitude x sin (parallel of origin). Then add or subtract 180 for the QTE.\",\"seenIn\":[\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-157\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"A great circle passes through A and B. The initial track at A is 350 and the final track at B is 290. The convergence angle is:\",\"opts\":[\"-60 deg\",\"+60 deg\",\"-120 deg\",\"+120 deg\"],\"ans\":0,\"exp\":\"Convergency = final - initial great-circle track = 290 - 350 = -60 deg (the track decreased).\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-158\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"A GC track from A (59°N 141°W) to B (61°N 148°W). At B it will\",\"opts\":[\"Increase by 6°\",\"Decrease by 6°\",\"Increase by 3°\"],\"ans\":1,\"exp\":\"Convergency = d.long x sin mean lat = 7 x sin 60 = 6 deg. Travelling west in the northern hemisphere the great-circle track decreases, here by about 6 deg.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-159\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On the Mercator's chart,\",\"opts\":[\"Distortion increases away from the Equator.\",\"Distortion increases away from the Pole\",\"Parallels of latitude are not straight lines.\"],\"ans\":0,\"exp\":\"Mercator distortion grows with distance from the equator (scale = sec lat).\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-160\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"The standard formula for earth convergency is:\",\"opts\":[\"dlat x cos mean lat\",\"dlat x sin mean lat\",\"dlong x sin mean lat\",\"dlong x cos mean lat\"],\"ans\":2,\"exp\":\"Convergency grows from zero at the equator to dlong at the pole, as the sine of latitude. Departure (distance) uses the cosine.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-161\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"Contour lines on aeronautical maps join points:\",\"opts\":[\"of equal latitude\",\"with the same variation\",\"of the same longitude\",\"of the same elevation above mean sea level\"],\"ans\":3,\"exp\":\"Contours join places of equal height; isogonals join equal variation.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-162\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"The angle between true north and grid north is called:\",\"opts\":[\"magnetic variation\",\"compass deviation\",\"convergency (grid convergence)\",\"grivation\"],\"ans\":2,\"exp\":\"A grid is laid over a polar chart because meridians converge so fast; grid north differs from true north by the convergence. Grid north vs magnetic north is grivation.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-163\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"The angle between a straight line on a Mercator chart and the corresponding great circle is:\",\"opts\":[\"zero\",\"earth convergency\",\"conversion angle\",\"chart convergence\"],\"ans\":2,\"exp\":\"A straight line on a Mercator is a rhumb line. Between the rhumb line and the great circle joining the same points lies the conversion angle = 1/2 x dlong x sin mean lat.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-164\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a chart, meridians 10 deg apart at 45 deg N are 14 cm apart. The scale is:\",\"opts\":[\"1 : 2,000,000\",\"1 : 4,000,000\",\"1 : 5,000,000\",\"1 : 5,600,000\"],\"ans\":3,\"exp\":\"Departure = 600 x cos 45 = 424 NM = 785.8 km. 78,580,000 / 14 = 5.6 million.\",\"seenIn\":[\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-165\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"The conversion angle (between the great circle and the rhumb line joining two places) is:\",\"opts\":[\"equal to the convergency\",\"half the convergency\",\"twice the convergency\",\"four times the convergency\"],\"ans\":1,\"exp\":\"Conversion angle = 1/2 x convergency = 1/2 x dlong x sin mean lat. It is applied to a radio (great-circle) bearing to plot it as a straight line on a Mercator chart.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-166\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"A straight line on a Lambert chart joins A and B. To read the rhumb line track A to B, measure the angle against the meridian:\",\"opts\":[\"at A\",\"at B\",\"midway between A and B\",\"at the parallel of origin\"],\"ans\":2,\"exp\":\"The straight line is (nearly) a great circle, whose track changes along the way. Its direction at the mid meridian equals the rhumb line track between the two points.\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-167\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a Mercator chart two meridians 1 deg apart are 7.62 cm apart at 48 deg N. The scale at 48 deg N is about:\",\"opts\":[\"1 : 1,549,000\",\"1 : 976,000\",\"1 : 2,166,000\",\"1 : 650,000\"],\"ans\":1,\"exp\":\"60 x cos 48 = 40.15 NM = 74.36 km = 7,436,000 cm; / 7.62 = 976,000.\",\"seenIn\":[\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-168\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"How is the Parallel of latitudes in Mercator chart\",\"opts\":[\"Parallel and equally spaced\",\"Parallel and Un-equally spaced\"],\"ans\":1,\"exp\":\"On a direct Mercator chart the parallels are parallel straight lines whose spacing grows towards the poles.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-169\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a direct Mercator chart, meridians 10 deg apart measure 6 cm at 60 deg N. The scale at 60 deg N is about:\",\"opts\":[\"1 : 9,260,000\",\"1 : 18,520,000\",\"1 : 4,630,000\",\"1 : 12,000,000\"],\"ans\":0,\"exp\":\"Departure = 600 x 0.5 = 300 NM = 555.6 km = 55,560,000 cm; / 6 = 9.26 million. (At the equator the same 10 deg would give 1 : 18.5 million.)\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-170\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"The chart distance between meridians 10 deg apart at 65 deg N is 3.75 inches. The chart scale there is about:\",\"opts\":[\"1 : 6,000,000\",\"1 : 5,000,000\",\"1 : 2,500,000\",\"1 : 3,000,000\"],\"ans\":1,\"exp\":\"600 x cos 65 = 254 NM = 470 km. 3.75 in = 9.5 cm. 47,000,000 / 9.5 = 4.9 million - about 1 : 5,000,000.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-171\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a polar stereographic chart of the south pole a straight line joins A (70 S 065 E) to B (70 S 025 W). The true course on leaving A is:\",\"opts\":[\"225\",\"315\",\"250\",\"135\"],\"ans\":0,\"exp\":\"dlong = 90 deg. A, B and the pole form an isosceles triangle with 90 deg at the pole, so the line leaves A at 45 deg to the meridian, swinging west of the direction to the pole (180): 180 + 45 = 225.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-172\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On an IFR en-route chart a 1 deg latitude/longitude square carries the figure 80. This means the grid minimum safe (off-route) altitude in that square is:\",\"opts\":[\"800 ft\",\"8,000 ft\",\"80 NM\",\"FL 080 only above the transition altitude\"],\"ans\":1,\"exp\":\"The grid MORA/MSA figure is shown in hundreds of feet: 80 = 8,000 ft, giving terrain and obstacle clearance anywhere in that square.\",\"seenIn\":[\"Jun 2024 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-173\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a direct Mercator chart the scale at 30 deg N is 1 : 1,000,000. The scale at 40 deg S is about:\",\"opts\":[\"1 : 885,000\",\"1 : 1,130,000\",\"1 : 1,000,000\",\"1 : 532,000\"],\"ans\":0,\"exp\":\"North or south makes no difference - only the latitude: 1,000,000 x cos 40 / cos 30 = 885,000.\",\"seenIn\":[\"Jun 2024 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-174\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"A Mercator chart uses a ______ projection\",\"opts\":[\"cylindrical\",\"conical\"],\"ans\":0,\"exp\":\"The Mercator projection is cylindrical.\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-175\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"The main use of an oblique Mercator chart is:\",\"opts\":[\"for countries with large changes of latitude but small changes of longitude\",\"route charts along a selected great circle\",\"topographical coverage of the poles\",\"charts of equatorial regions\"],\"ans\":1,\"exp\":\"The cylinder is tilted to touch the earth along any chosen great circle, so the chart is accurate along that great-circle route - used for long-range route charts.\",\"seenIn\":[\"Aug 2024 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-176\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a polar stereographic chart a great circle (other than a meridian) appears as:\",\"opts\":[\"a straight line exactly\",\"a curve concave to the pole, nearly straight\",\"a curve convex to the pole\",\"an ellipse round the pole\"],\"ans\":1,\"exp\":\"Near the pole a great circle is very nearly a straight line, curving slightly towards the pole - concave to it. Rhumb lines curve much more, also concave to the pole.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-177\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"A direct Mercator chart has a scale of 1 : 2,000,000 at the equator. A line 5 cm long measured near 60 deg N represents about:\",\"opts\":[\"27 NM\",\"54 NM\",\"100 km\",\"13.5 NM\"],\"ans\":0,\"exp\":\"At 60 deg the scale is doubled: 1 : 1,000,000. 5 cm = 50 km = 27 NM.\",\"seenIn\":[\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-178\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a Lambert conformal chart with two standard parallels, the scale between the standard parallels is:\",\"opts\":[\"slightly smaller (contracted) than the nominal scale, and larger outside them\",\"larger than the nominal scale everywhere\",\"exactly correct everywhere between them\",\"smaller outside them\"],\"ans\":0,\"exp\":\"The correct answer is: slightly smaller (contracted) than the nominal scale, and larger outside them.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-179\",\"topic\":\"Maps, Charts & Projections\",\"stem\":\"On a chart of scale 1 : 1,000,000, what chart length represents 54 NM?\",\"opts\":[\"10 cm\",\"5.4 cm\",\"1 cm\",\"18.5 cm\"],\"ans\":0,\"exp\":\"54 NM x 1.852 = 100 km = 10,000,000 cm; / 1,000,000 = 10 cm.\",\"seenIn\":[\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-180\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"An aircraft at FL350 must descend to cross a VOR 85 NM ahead at FL080. Mean groundspeed in the descent 340 kt. Minimum rate of descent?\",\"opts\":[\"1900 ft/min\",\"1600 ft/min\",\"1800 ft/min\",\"1700 ft/min\"],\"ans\":2,\"exp\":\"Height to lose 27,000 ft. Time available = 85 / 340 h = 15 min. ROD = 27,000 / 15 = 1800 ft/min. ROD = height / time, and time = distance / GS.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Oct 2023 · OLODE\",\"Nov 2023 · OLODE (29 Nov)\",\"Nov 2023 · OLODE (30 Nov)\",\"Apr 2024 · OLODE 03\",\"Aug 2024 · OLODE 06\",\"Sep 2024 · Regular 03\",\"Jan 2025 · OLODE 01\",\"Mar 2025 · Regular 01\",\"Jun 2025 · Regular 02\",\"Jul 2026 · OLODE 05\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":12,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-181\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"At what approximate date is the earth furthest from the sun (aphelion)?\",\"opts\":[\"Beginning of July\",\"End of December\",\"Beginning of January\",\"End of September\"],\"ans\":0,\"exp\":\"Aphelion, when the earth is furthest from the sun, is in early July.\",\"seenIn\":[\"Jan 2019\",\"Oct 2021 · Attempt 2\",\"Jul 2023 · OLODE\",\"Aug 2023 · OLODE\",\"Apr 2024 · OLODE 03\",\"May 2024 · OLODE 04\",\"Jun 2024 · Regular\",\"Jul 2024 · OLODE 05\",\"Jun 2025 · Regular 02\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":10,\"years\":[2019,2021,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-182\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Civil twilight is between\",\"opts\":[\"0-6 degrees\",\"6-12 degrees\",\"12-18 degrees\"],\"ans\":0,\"exp\":\"Civil twilight covers the time when the centre of the sun is between 0 and 6 deg below the horizon.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Aug 2023 · OLODE\",\"Sep 2023 · Regular 03\",\"Nov 2023 · OLODE (29 Nov)\",\"Dec 2024 · Regular 04\",\"Jan 2025 · OLODE 01\",\"Aug 2025 · OLODE 06\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":8,\"years\":[2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-183\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"In which months is the difference between apparent noon and mean noon the greatest?\",\"opts\":[\"March and September.\",\"June and December.\",\"November and February.\",\"January and July.\"],\"ans\":2,\"exp\":\"The equation of time is greatest (about 14-16 min) in early November and mid-February.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Dec 2023 · Regular\",\"Apr 2024 · OLODE 03\",\"May 2024 · OLODE 04\",\"Sep 2024 · Regular 03\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":6,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-184\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Seasons are due to the:\",\"opts\":[\"Earth's elliptical orbit around the Sun\",\"inclination of the polar axis with the ecliptic plane\",\"Earth's rotation on its polar axis\"],\"ans\":1,\"exp\":\"Seasons exist because the earth's polar axis is inclined about 23.5 deg to the plane of its orbit (the ecliptic).\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Aug 2023 · OLODE\",\"Nov 2023 · OLODE (29 Nov)\",\"Mar 2024 · Regular 01\",\"Jun 2025 · Regular 02\",\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":6,\"years\":[2021,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-185\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Approx date on which earth is closest to the sun? (perihelion)\",\"opts\":[\"Beginning of January\",\"End of June\",\"Beginning of July\",\"End of March\"],\"ans\":0,\"exp\":\"Perihelion, when the earth is closest to the sun, is in early January (aphelion in early July).\",\"seenIn\":[\"Jun 2023 · Regular\",\"Apr 2024 · OLODE 03\",\"May 2024 · OLODE 04\",\"Jun 2025 · Regular 02\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-186\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"The angle between the plane of the ecliptic and the plane of the equator is approximately\",\"opts\":[\"66.5 deg\",\"23.5 deg\",\"27.5 deg\"],\"ans\":1,\"exp\":\"The earth's equatorial plane is inclined about 23.5 deg to the plane of the ecliptic.\",\"seenIn\":[\"Jul 2023 · OLODE\",\"Aug 2023 · OLODE\",\"Sep 2023 · Regular 03\",\"Dec 2023 · Regular\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":5,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-187\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"The main reason that day and night have different durations through the year is:\",\"opts\":[\"the earth's rotation\",\"the relative speed of the sun along the ecliptic\",\"the inclination of the ecliptic to the equator\",\"the gravitational effect of the sun and moon\"],\"ans\":2,\"exp\":\"Because the equator is tilted 23.5 deg to the ecliptic, the sun's declination swings between 23.5 N and S, and with it the share of each parallel that is in daylight. Rotation gives day and night, but not their changing length.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Sep 2024 · Regular 03\",\"Jan 2025 · OLODE 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-188\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Groundspeed 240 kt, distance to go 500 NM. Time to go?\",\"opts\":[\"20 min\",\"29 min\",\"2 h 05 min\",\"2 h 12 min\"],\"ans\":2,\"exp\":\"500 / 240 = 2.083 h = 2 h 05 min.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Jan 2025 · OLODE 01\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-189\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"The highest Lat on which sun can be vertically overhead?\",\"opts\":[\"90 deg\",\"66 deg\",\"45 deg\",\"23 deg\"],\"ans\":3,\"exp\":\"The sun is overhead at most at 23.5 deg (tropic).\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Apr 2024 · OLODE 03\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2021,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-190\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"At 1000 UTC, what are the LMT and the standard time at a place on longitude 022 deg 30'E, if the standard time there is UTC + 1 h?\",\"opts\":[\"LMT 1130, ST 1100\",\"LMT 0830, ST 1100\",\"LMT 1130, ST 0900\",\"LMT 1100, ST 1130\"],\"ans\":0,\"exp\":\"Arc to time: 15 deg = 1 h, 1 deg = 4 min. 22 30 E = 1 h 30 min ahead: LMT 1130. Standard time is set by the state, here UTC + 1 = 1100. Memory aid: longitude east, UTC least - so east of Greenwich the local time is ahead and you add.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jul 2025 · OLODE 05\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2022,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-191\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"An aircraft flies once round the earth eastwards along the 60 deg N parallel at a groundspeed of 240 kt. At what groundspeed must another fly round the equator to take the same time?\",\"opts\":[\"600 kt\",\"240 kt\",\"480 kt\",\"120 kt\"],\"ans\":2,\"exp\":\"Same time, so speed is proportional to the length of the path. The 60 deg parallel is cos 60 = half the equator: 240 / 0.5 = 480 kt.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2023 · Regular (ATPL)\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-192\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"The duration of civil twilight is the time?\",\"opts\":[\"Between Sunset and when the centre of the sun is 6° below the true horizon.\",\"Between Sunset and when the top of the Sun is 6° below the visual horizon.\",\"Between sunset and when the centre of the Sun is 6° below the visual horizon.\",\"When the Sunset and Sunrise\"],\"ans\":0,\"exp\":\"Civil twilight lasts from sunset until the centre of the sun is 6 deg below the true horizon.\",\"seenIn\":[\"Jan 2019\",\"Jan 2024 · Regular (Day 2)\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2019,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-193\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"West to East across the international date line\",\"opts\":[\"day gained, date lost\",\"day lost, date gained\",\"date and day remain the same\"],\"ans\":0,\"exp\":\"Crossing the International Date Line from west to east the calendar date goes back one day - you gain a day and lose a date.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-194\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"The inclination of the earths axis of rotation with the plane of the ecliptic:\",\"opts\":[\"Causing the seasons\",\"Stable throughout the year\",\"Is causing the variation of length of daylight during a year.\",\"All the above\"],\"ans\":3,\"exp\":\"The inclination of the earth's axis to the ecliptic causes the seasons and the varying length of daylight through the year; it stays constant.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-195\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"At what latitude will the sun be vertically overhead?\",\"opts\":[\"23.5\",\"66\",\"90\"],\"ans\":0,\"exp\":\"The sun is vertically overhead at most at the latitude of the tropics, 23.5 deg.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\",\"Aug 2023 · OLODE\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-196\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"With air distance AD, ground distance GD, TAS and GS, the ground distance flown is:\",\"opts\":[\"GD = AD x GS / TAS\",\"GD = AD x TAS / GS\",\"GD = AD - TAS / GS\",\"GD = TAS / (GS x AD)\"],\"ans\":0,\"exp\":\"Same time in the air: GD / GS = AD / TAS. In still air GS = TAS, so the ground distance equals the air distance.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2022,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-197\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Two aircraft fly eastwards once round the earth in the same time: A along 45 deg N at 300 kt, B along the equator. B's groundspeed is:\",\"opts\":[\"300 kt\",\"212 kt\",\"424 kt\",\"600 kt\"],\"ans\":2,\"exp\":\"GS is proportional to the length of the parallel: 300 / cos 45 = 300 / 0.707 = 424 kt.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-198\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"What is the meaning of the term \\\"standard time\\\"?\",\"opts\":[\"it is another term for UTC\",\"it is the time set by the legal authorities for a country or part of a country\",\"it is an expression for local mean time.\"],\"ans\":1,\"exp\":\"Standard time is the time set by the legal authority of a country or part of it.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-199\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"It is 1830 UTC on 2 December. Hong Kong (22 19 N 114 12 E) keeps standard time UTC + 8. The standard time and date in Hong Kong are:\",\"opts\":[\"0230 on 3 December\",\"0207 on 3 December\",\"1030 on 2 December\",\"0630 on 3 December\"],\"ans\":0,\"exp\":\"1830 + 8 h = 2630, i.e. 0230 the next day. (0207 would be LMT, using the longitude: 7 h 37 min.)\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-200\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"It is 1400 UTC. What is the LMT at longitude 060 deg E?\",\"opts\":[\"1000\",\"1800\",\"1400\",\"2000\"],\"ans\":1,\"exp\":\"60 deg = 4 h. East is ahead: 1400 + 4 = 1800 LMT. (\\\"Longitude east, UTC least; longitude west, UTC best.\\\")\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-201\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"An aircraft flies 800 NM: it climbs for 30 min at a groundspeed of 84 kt, cruises at 180 kt groundspeed and descends for 30 min at 85 kt groundspeed. Total flight time?\",\"opts\":[\"4 h 59 min\",\"4 h 27 min\",\"5 h 30 min\",\"3 h 58 min\"],\"ans\":0,\"exp\":\"Climb covers 42 NM, descent 42.5 NM, leaving 715.5 NM of cruise: 715.5 / 180 = 3 h 58.5 min. Add the 1 h of climb and descent: 4 h 59 min.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-202\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"The LMT at 075 deg 30'E is 1530. What is the UTC?\",\"opts\":[\"1028\",\"2032\",\"1530\",\"1100\"],\"ans\":0,\"exp\":\"75 30 E = 5 h 02 min of time. East of Greenwich LMT is ahead of UTC, so UTC = 1530 - 0502 = 1028.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-203\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"The duration of the apparent solar day\",\"opts\":[\"is the same all year round\",\"varies through the year\"],\"ans\":1,\"exp\":\"The apparent solar day is not a constant length: it changes through the year (equation of time).\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2021,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-204\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Which is the highest latitude listed below at which the sun will rise above the horizon and set every day?\",\"opts\":[\"72°\",\"68°\",\"66°\"],\"ans\":2,\"exp\":\"The highest latitude at which the sun rises and sets every day is 66 deg (about 66.5).\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-205\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"The times given for sunrise, sunset, morning and evening twilight in the Air Almanac:\",\"opts\":[\"are given in UTC.\",\"are given in standard time.\",\"are given in LMT.\"],\"ans\":2,\"exp\":\"The Air Almanac lists sunrise, sunset and twilight as LMT (for sea level). To get UTC or standard time you convert the LMT using the longitude afterwards.\",\"seenIn\":[\"Jun 2023 · Regular\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-206\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"In mid-latitudes the length of day and night, and the sun's declination, change fastest at:\",\"opts\":[\"the summer solstice and spring equinox\",\"the spring and autumn equinoxes\",\"the summer and winter solstices\",\"the winter solstice and autumn equinox\"],\"ans\":1,\"exp\":\"At the equinoxes the sun crosses the equator and its declination changes fastest (about 0.4 deg a day); at the solstices it is at its turning point and hardly changes - so day length is almost constant for a few days.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Aug 2024 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-207\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"When the LMT at 000 deg is 0800 on 5 May, the LMT at 180 deg E is:\",\"opts\":[\"2000 on 5 May\",\"2000 on 4 May\",\"0800 on 6 May\",\"0800 on 5 May\"],\"ans\":0,\"exp\":\"LMT on the Greenwich meridian is UTC. 180 deg E is 12 h ahead: 0800 + 12 = 2000, same date.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-208\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"What is the reason for seasonal changes in climate?\",\"opts\":[\"Because the Earth's spin axis is inclined to the plane of its orbit around the Sun.\",\"Because the distance between the Earth and the Sun varies over a year.\",\"Because the Earth's orbital speed around the Sun varies according to the time of the year.\"],\"ans\":0,\"exp\":\"Seasons result from the inclination of the earth axis to its orbital plane.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-209\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"The time it takes for the Earth to complete one orbit around the Sun is\",\"opts\":[\"360 days 45 hours, 5 minutes 48 seconds\",\"360 days 5 hours 45 minutes 48 seconds\",\"365 days 45 hours 48 minutes 5 seconds\",\"365 days 5 hours48 minutes 45 seconds\"],\"ans\":3,\"exp\":\"The correct answer is: 365 days 5 hours48 minutes 45 seconds.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-210\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"At what times of the year does the length of the hours of daylight change most rapidly?\",\"opts\":[\"Autumn Equinox and Winter Solstice.\",\"Spring (Vernal) Equinox and Autumn Equinox)\",\"Summer Solstice and Winter Solstice.\",\"Spring (Vernal)-Equinox and Summer Solstice.\"],\"ans\":1,\"exp\":\"Day length changes fastest at the equinoxes, when the sun's declination changes at its greatest rate.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-211\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Aircraft A flies round the 35 deg N parallel at 300 kt. What groundspeed lets aircraft B fly round the 45 deg S parallel in the same time?\",\"opts\":[\"259 kt\",\"300 kt\",\"347 kt\",\"212 kt\"],\"ans\":0,\"exp\":\"300 x cos 45 / cos 35 = 300 x 0.707 / 0.819 = 259 kt. The higher latitude has the shorter circle, so the lower speed.\",\"seenIn\":[\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-212\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"At a place on 010 deg 24'E the LMT is 1200. Its standard time is UTC + 1. What is the standard time?\",\"opts\":[\"1218\",\"1241\",\"1159\",\"1100\"],\"ans\":0,\"exp\":\"010 24 E = 41.6 min of time, so UTC = 1200 - 0042 = 1118 (about). Standard time = UTC + 1 = 1218.\",\"seenIn\":[\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-213\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Morning civil twilight begins when:\",\"opts\":[\"The center of Sun is 18° below the celestial horizon\",\"The center of Sun is 12° below the celestial horizon\",\"The center of Sun is 6° below the celestial horizon\"],\"ans\":2,\"exp\":\"Morning civil twilight begins when the centre of the sun is 6 deg below the horizon.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-214\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"A time difference of 5 h 20 min 20 s is equivalent to a change of longitude of:\",\"opts\":[\"81°30'\",\"80°05'\",\"79°10'\"],\"ans\":1,\"exp\":\"5 h = 75 deg, 20 min = 5 deg, 20 s = 5 arc minutes: 80 deg 05 min.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-215\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"the 5h30mins time in long\",\"opts\":[\"85 30'\",\"82 30'\",\"70 30'\"],\"ans\":1,\"exp\":\"5 h 30 min x 15 deg/h = 82 deg 30 min.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-216\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"When does aphelion occur\",\"opts\":[\"July\",\"Dec\",\"Jan\"],\"ans\":0,\"exp\":\"Aphelion is in early July.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-217\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Sun rises over head Delhi\",\"opts\":[\"Once a year\",\"Twice a year\",\"Never\"],\"ans\":2,\"exp\":\"Delhi is at 28.6 N, north of the tropic (23.5 N), so the sun is never overhead there.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-218\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"What is the LMT at longitude 095 deg 20'W at 0000 UTC?\",\"opts\":[\"1738:40 same day\",\"0621:20 same day\",\"1738:40 previous day\",\"0621:20 previous day\"],\"ans\":2,\"exp\":\"95 20 W = 6 h 21 min 20 s. West of Greenwich LMT is behind UTC: 0000 - 6:21:20 = 17:38:40 on the previous day.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-219\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"A sidereal day is measured with reference to:\",\"opts\":[\"the mean sun\",\"the apparent sun\",\"a fixed (distant) star\",\"the moon\"],\"ans\":2,\"exp\":\"A sidereal day is one rotation relative to the stars: about 23 h 56 min, about 4 minutes shorter than the solar day.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-220\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"At the equator around the equinox, evening civil twilight lasts about:\",\"opts\":[\"24 minutes\",\"60 minutes\",\"120 minutes\",\"180 minutes\"],\"ans\":0,\"exp\":\"The correct answer is: 24 minutes.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-221\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"The synodic period (e.g. of the moon) is the time between:\",\"opts\":[\"two transits of a star\",\"two successive identical phases as seen from the earth (new moon to new moon, about 29.5 days)\",\"two perihelions\",\"two equinoxes\"],\"ans\":1,\"exp\":\"Synodic = relative to the sun (phase to phase, 29.5 days); sidereal month = relative to the stars (27.3 days).\",\"seenIn\":[\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-222\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"An aircraft must land at least 15 minutes before sunset, which at destination is 1810 UTC. Flight time 2 h 00 min. Latest departure time?\",\"opts\":[\"1555 UTC\",\"1610 UTC\",\"1625 UTC\",\"1540 UTC\"],\"ans\":0,\"exp\":\"Latest landing 1810 - 0015 = 1755; minus 2 h flight time = 1555 UTC. Work backwards from the limit, in one time system.\",\"seenIn\":[\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-223\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Aircraft A circles the earth along the equator at 420 kt. To complete its parallel in the same time, aircraft B on 53 deg N needs a groundspeed of:\",\"opts\":[\"420 kt\",\"253 kt\",\"335 kt\",\"698 kt\"],\"ans\":1,\"exp\":\"420 x cos 53 = 420 x 0.602 = 253 kt.\",\"seenIn\":[\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-224\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"A is at longitude 012 deg 30'E and B at 043 deg 15'E. The LMT at B is 1749. What is the LMT at A?\",\"opts\":[\"1546\",\"1952\",\"1706\",\"1456\"],\"ans\":0,\"exp\":\"dlong = 30 deg 45' = 2 h 03 min of time. A is west of B, so its LMT is earlier: 1749 - 0203 = 1546.\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-225\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Aircraft A flies east along 75 deg N at 300 kt, aircraft B along 45 deg S; both take the same time to fly once round their parallel. B's groundspeed is:\",\"opts\":[\"300 kt\",\"820 kt\",\"110 kt\",\"424 kt\"],\"ans\":1,\"exp\":\"Speed ratio = cos 45 / cos 75 = 0.707 / 0.259: 300 x 2.73 = 820 kt. North or south does not matter - only the latitude.\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-226\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"The longest day in the northern hemisphere occurs at about:\",\"opts\":[\"21 March\",\"21 June\",\"23 September\",\"22 December\"],\"ans\":1,\"exp\":\"At the summer solstice (about 21 June) the sun's declination is 23.5 N, so northern parallels have their largest share of daylight. 22 December is the longest day in the southern hemisphere.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Jul 2025 · OLODE 05\",\"Feb 2026 · OLODE 02\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-227\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"The earth's axis is inclined to the plane of its orbit (the ecliptic) at about:\",\"opts\":[\"23.5 deg\",\"66.5 deg\",\"90 deg\",\"45 deg\"],\"ans\":1,\"exp\":\"The axis makes 66.5 deg with the orbital plane - equivalently the equator is tilted 23.5 deg to the ecliptic. That tilt, not the elliptical orbit, causes the seasons.\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-228\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Crossing the International Date Line travelling EASTWARDS (from east longitude into west longitude):\",\"opts\":[\"the date goes back one day\",\"the date goes forward one day\",\"the date does not change\",\"the LMT changes by 12 hours\"],\"ans\":0,\"exp\":\"Going east you move into the zone 24 h behind: the date decreases by one (you \\\"gain\\\" a day), while LMT runs on continuously.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-229\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Planned A to B 320 NM at an average groundspeed of 180 kt, departing A at 1200 UTC. After 70 NM the aircraft is 3 min ahead of plan. Using the actual groundspeed, the revised ETA at B is:\",\"opts\":[\"1401 UTC\",\"1333 UTC\",\"1347 UTC\",\"1340 UTC\"],\"ans\":1,\"exp\":\"Planned time for 70 NM = 23.3 min; actual 20.3 min, so GS = 70 / 20.3 x 60 = 207 kt. Remaining 250 NM at 207 kt = 72.5 min: 1200 + 20.3 + 72.5 = about 1333.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-230\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Nautical twilight ends (evening) when the centre of the sun is:\",\"opts\":[\"6 deg below the horizon\",\"12 deg below the horizon\",\"18 deg below the horizon\",\"on the horizon\"],\"ans\":1,\"exp\":\"Civil twilight: sunset to 6 deg below. Nautical: 6 to 12 deg. Astronomical: 12 to 18 deg. Aviation uses civil twilight.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-231\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Compared with the tropical (seasonal) year, the sidereal year is:\",\"opts\":[\"about 20 minutes longer\",\"about 20 minutes shorter\",\"the same\",\"one day longer\"],\"ans\":0,\"exp\":\"Sidereal year = 365.256 days (orbit relative to the stars); tropical year = 365.242 days (equinox to equinox) - shorter by about 20 min because of the precession of the equinoxes.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-232\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"Standard time differs from UTC by:\",\"opts\":[\"the longitude of the place converted to time\",\"an amount fixed by the government of the state, usually a whole or half hour\",\"exactly 4 minutes per degree of latitude\",\"nothing - they are the same\"],\"ans\":1,\"exp\":\"Standard time is legal time set by each state (India: IST = UTC + 5:30, kept on 82 deg 30' E). LMT is the one that follows the exact longitude (4 min per degree).\",\"seenIn\":[\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-233\",\"topic\":\"Time, the Sun & Twilight\",\"stem\":\"An aircraft passes A at 1015 UTC and B, 186 NM further on, at 1117 UTC. Its groundspeed is:\",\"opts\":[\"180 kt\",\"162 kt\",\"186 kt\",\"200 kt\"],\"ans\":0,\"exp\":\"Time 62 min. GS = 186 / 62 x 60 = 180 kt.\",\"seenIn\":[\"Jun 2024 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-234\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Compass heading 095, deviation 3 deg E, variation 5 deg W. What is the true heading?\",\"opts\":[\"093\",\"103\",\"087\",\"097\"],\"ans\":0,\"exp\":\"C-D-M-V-T, East is added, West subtracted going towards True: compass 095 + 3E = magnetic 098; 098 - 5W = true 093.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Oct 2023 · OLODE\",\"Nov 2023 · OLODE (29 Nov)\",\"Nov 2023 · OLODE (30 Nov)\",\"Apr 2024 · OLODE 03\",\"Jun 2024 · Regular\",\"Sep 2024 · Regular 03\",\"Oct 2024 · OLODE 07\",\"Dec 2024 · Regular 04\",\"Mar 2025 · Regular 01\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\",\"Jul 2025 · OLODE 05\",\"Aug 2025 · OLODE 06\",\"Jan 2026 · OLODE 01\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":16,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-235\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"TAS 235 kt, true heading 076, W/V 040/40 kt. What are the drift angle and groundspeed?\",\"opts\":[\"5 deg R, 207 kt\",\"7 deg L, 269 kt\",\"5 deg L, 255 kt\",\"7 deg R, 204 kt\"],\"ans\":3,\"exp\":\"The wind comes from 36 deg left of the nose, so it blows the aircraft to the right (starboard drift) and is mostly a headwind. Vector sum: track 083, GS 204 kt, drift 7 deg right. Drift is the angle from heading to track, named by the side the aircraft is blown to.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Sep 2023 · Regular 03\",\"Nov 2023 · OLODE (30 Nov)\",\"Mar 2024 · Regular 01\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\",\"Mar 2026 · Regular 01\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":8,\"years\":[2021,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-236\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"The still air distance in the climb is 189 Nautical Air Miles (NAM) and the time 30 minutes. What ground distance would be covered in a 30 kt headwind?\",\"opts\":[\"193 NM\",\"174 NM\",\"188 NM\"],\"ans\":1,\"exp\":\"The 30-minute climb covers 189 NAM, so TAS is 378 kt. With a 30 kt headwind GS is 348 kt, and 348 x 0.5 h = 174 NM.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Aug 2023 · OLODE\",\"Dec 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\",\"Mar 2024 · Regular 01\",\"Jun 2025 · Regular 02\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":7,\"years\":[2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-237\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"TAS 140 kt, W/V 050/20 kt, desired track 090(T). The wind correction angle (WCA) is approximately:\",\"opts\":[\"5 deg L\",\"8 deg L\",\"5 deg R\",\"8 deg R\"],\"ans\":0,\"exp\":\"Crosswind = 20 sin 40 = 12.9 kt from the left. WCA = asin(12.9 / 140) = 5.3 deg - steer LEFT, into the wind: heading 085. (1 in 60 check: 12.9 x 60 / 140 = 5.5 deg.)\",\"seenIn\":[\"Jun 2023 · Regular\",\"Oct 2023 · OLODE\",\"Nov 2023 · OLODE (30 Nov)\",\"Dec 2023 · Regular\",\"Jun 2024 · Regular\",\"Apr 2025 · OLODE 03\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":7,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-238\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Runway 210(M), surface W/V 230(M)/30 kt. What is the crosswind component?\",\"opts\":[\"19 kt\",\"10 kt\",\"16 kt\",\"13 kt\"],\"ans\":1,\"exp\":\"Angle between wind and runway = 20 deg. Crosswind = 30 sin 20 = 10 kt; headwind = 30 cos 20 = 28 kt.\",\"seenIn\":[\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\",\"Jan 2026 · OLODE 01\",\"Feb 2026 · OLODE 02\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":5,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-239\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"A to B is 135 NM. After 45 NM the aircraft is 3 NM left of track. Using the 1 in 60 rule, what heading change will take it directly to B?\",\"opts\":[\"6 deg right\",\"4 deg right\",\"8 deg right\",\"4 deg left\"],\"ans\":0,\"exp\":\"Track error = 3 x 60/45 = 4 deg; closing angle = 3 x 60/90 = 2 deg. Total correction = 6 deg to the right.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Jun 2024 · Regular\",\"Sep 2024 · Regular 03\",\"Jul 2026 · OLODE 05\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-240\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"True heading 265, TAS 290 kt, W/V 210/35 kt. What are the true track and groundspeed?\",\"opts\":[\"259 deg and 305 kt\",\"259 deg and 272 kt\",\"260 deg and 315 kt\",\"271 deg and 272 kt\"],\"ans\":3,\"exp\":\"Wind from 55 deg left of the nose: it pushes the track right of heading (to about 271) and takes off about 20 kt: GS 272 kt.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Mar 2024 · Regular 01\",\"Jul 2024 · OLODE 05\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-241\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"An aircraft takes 14 minutes to climb to FL290, covering 71 nautical air miles, with a 30 kt headwind component. What ground distance does it cover?\",\"opts\":[\"71 NM\",\"64 NM\",\"51 NM\",\"78 NM\"],\"ans\":1,\"exp\":\"Ground distance = air distance + wind effect over the time: 71 - 30 x 14/60 = 71 - 7 = 64 NM.\",\"seenIn\":[\"Mar 2022\",\"Aug 2023 · OLODE\",\"Jul 2024 · OLODE 05\",\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":4,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-242\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"The time to reach the closing level at a given gross mass is 36 minutes and the distance travelled is 157Nm (zero wind). what will be the distance travelled with an average tail wind component of 60kts?\",\"opts\":[\"193Nm\",\"228Nm\",\"157Nm\"],\"ans\":0,\"exp\":\"Climb is 36 min = 0.6 h. A 60 kt tailwind adds 60 x 0.6 = 36 NM: 157 + 36 = 193 NM.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Jul 2024 · OLODE 05\",\"May 2025 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-243\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Sector distance is 450 Nm. TAS is 460 kts and 50 kt tailwind, what is still air distance?\",\"opts\":[\"499 Nm\",\"414 Nm\",\"511 Nm\",\"406 Nm\"],\"ans\":3,\"exp\":\"GS = 460 + 50 = 510 kt, so the sector takes 450/510 h. Still-air distance = TAS x time = 460 x 0.882 = 406 NAM.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Dec 2023 · Regular\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-244\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"The forecast W/V is 030/20 kt at the surface and 070/40 kt at FL80. What is the mean W/V for the climb?\",\"opts\":[\"057 / 28 kt\",\"050 / 30 kt\",\"050 / 60 kt\",\"070 / 30 kt\"],\"ans\":0,\"exp\":\"Winds are averaged as VECTORS, not as numbers: resolving both into north and east components and halving gives about 057 / 28 kt. Simply averaging the figures (050 / 30) ignores that the two winds partly cancel and is wrong.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"May 2024 · OLODE 04\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-245\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"An approach requires a 3.3 % descent gradient. Groundspeed 160 kt. What rate of descent is needed?\",\"opts\":[\"535 ft/min\",\"440 ft/min\",\"610 ft/min\",\"330 ft/min\"],\"ans\":0,\"exp\":\"ROD = gradient x GS in ft/min = 0.033 x 160 x 6076 / 60 = 535 ft/min (quick: % x GS x 1.013).\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2023 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-246\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"1 nautical mile and 1 statute mile are, in kilometres:\",\"opts\":[\"1.852 km and 1.609 km\",\"1.609 km and 1.852 km\",\"1.852 km and 1.524 km\",\"1.000 km and 1.609 km\"],\"ans\":0,\"exp\":\"1 NM = 1852 m (one minute of latitude, by definition); 1 SM = 5280 ft = 1609 m. So NM x 1.852 = km, SM x 1.609 = km.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-247\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Flying from A to B you find you are 60 NM out from A and 7 NM left of the required track. What is the track error?\",\"opts\":[\"3 deg L\",\"4 deg L\",\"7 deg L\",\"9 deg L\"],\"ans\":2,\"exp\":\"1 in 60: track error = distance off x 60 / distance gone = 7 x 60 / 60 = 7 deg, left of track.\",\"seenIn\":[\"Apr 2025 · OLODE 03\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-248\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"The wind is 60 deg off the runway. The minimum headwind required is 10 kt and the maximum crosswind allowed is 35 kt. What are the maximum and minimum wind speeds acceptable?\",\"opts\":[\"40 and 15 kt\",\"40 and 20 kt\",\"45 and 15 kt\",\"45 and 20 kt\"],\"ans\":1,\"exp\":\"Maximum: crosswind = V sin 60 = 35, V = 40 kt. Minimum: headwind = V cos 60 = 10, V = 20 kt.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-249\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"The three vectors of the triangle of velocities are:\",\"opts\":[\"TAS, GS and wind speed\",\"heading/TAS (air vector), track/GS (ground vector) and the wind velocity\",\"true heading, magnetic heading and drift\",\"airspeed, groundspeed and wind component\"],\"ans\":1,\"exp\":\"Each side is a VECTOR (direction and speed): the air vector heading/TAS plus the wind vector W/V gives the ground vector track/GS.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-250\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"True heading 090, TAS 180 kt. The aircraft makes good a track 5 deg right of heading at a groundspeed of 180 kt. The W/V is:\",\"opts\":[\"360 / 15 kt\",\"180 / 15 kt\",\"010 / 15 kt\",\"190 / 15 kt\"],\"ans\":0,\"exp\":\"Drift right means the wind blows from the LEFT of the nose (northerly for an easterly heading); GS equal to TAS means no head or tail component, so the wind is square across: 360. Size: 180 sin 5 = 15.7, about 15 kt.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-251\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"The angle between the required (planned) track and the track made good is called:\",\"opts\":[\"drift\",\"track error\",\"wind correction angle\",\"closing angle\"],\"ans\":1,\"exp\":\"Track error = required track vs track made good. Drift = heading vs track made good. Closing angle = correction needed to reach the next point.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-252\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Given: Magnetic heading = 255° VAR = 40°W GS = 375 kt W/V = 235°(T) / 120 kt Calculate the drift angle?\",\"opts\":[\"7° left\",\"7° right\",\"9° left\",\"16° right\"],\"ans\":0,\"exp\":\"True heading = 255 - 40 = 215. Solving the triangle with GS 375 and wind 235/120 gives TAS about 485 kt and drift 6-7 deg; the wind comes from the right of heading, so drift is left.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-253\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"An aircraft is following a true track of 048° at a constant TAS of 210 kt. The wind velocity is 350° / 30 kt. The GS and drift angle are:\",\"opts\":[\"192 kt, 7° left\",\"200 kt, 3.5° right\",\"192kt,7° right\",\"225 kt, 7° left\"],\"ans\":2,\"exp\":\"Wind 350/30 is 58 deg to the left of track 048: crosswind 25 kt, headwind 16 kt. Drift = 7 deg (wind from the left, so right drift); GS = 210 cos 7 - 16 = 192 kt.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-254\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"The following information is displayed on an Inertial Navigation System: GS 520 kt, True HDG 090°, Drift angle 5° right, TAS 480 kt. SAT (static air temperature) The W/V being experienced is:\",\"opts\":[\"225° / 60 kt\",\"320° / 60 kt\",\"220° / 60 kt\",\"325° / 60 kt\"],\"ans\":1,\"exp\":\"Track = 090 + 5 = 095. Ground vector minus air vector gives wind towards 140 at 59 kt, i.e. from 320 at about 60 kt.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-255\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Given: For take-off an aircraft requires a headwind component of at least 10 and has a cross-wind limitation of 35 kt. The angle between the wind direction and the runway is 60°, Calculate the minimum and maximum allowable wind speeds?\",\"opts\":[\"12kt and 38kt\",\"20kt and 40 kt\",\"15kt and 43kt\",\"18kt and 50 kt\"],\"ans\":1,\"exp\":\"Minimum wind = 10 / cos 60 = 20 kt; maximum = 35 / sin 60 = 40 kt.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-256\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Given: TAS = 472 kt, True HDG = 005°, W/V = 110°(T)/50kt. Calculate the drift angle and GS?\",\"opts\":[\"6°L-487 kt\",\"7°R-491 kt\",\"7°L-491 kt\",\"7°R=487 kt\"],\"ans\":0,\"exp\":\"The wind 110/50 blows towards 290, 105 deg to the right of the heading 005. Adding the wind vector to the air vector (472 kt on 005) gives a ground vector of 487 kt on 359: drift 6 deg left, GS 487 kt.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-257\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Given: Runway direction 083°(M), Surface W/WV_035/35kt. Calculate the effective headwind component?\",\"opts\":[\"24kt\",\"27kt\",\"31kt\",\"34kt\"],\"ans\":0,\"exp\":\"Angle between wind and runway = 83 - 35 = 48 deg: headwind = 35 x cos 48 = 23.4, about 24 kt.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-258\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"An aircraft descends to an airport under the following conditions:- . Cruising Altitude 10500 feet . Airport elevation 1700 feet . Descending to 1000 feet AGL . Rate of descent 600 feet/Min . Average CAS 119K . Mean Temp +18 C . Track 263° . Average W/V 330/30 . Variation 5 E . Deviation -1 . Average Fuel consumption 11.5 Gal/Hr Find the time, Hdg (C) & Distance & fuel used-during descend\",\"opts\":[\"9Min,. 274, 26 nm, 2.8 Gal\",\"13 Min, 274, 2.8 nm, 2.5 Gal\",\"13 Min, 271, 26 nm, 2.5 Gal\"],\"ans\":2,\"exp\":\"Descent 10,500 to 2,700 ft (1,000 ft above the 1,700 ft airport) = 7,800 ft at 600 ft/min = 13 min. TAS about 135 kt, headwind component about 12 kt gives GS about 123 kt: 26 NM. Drift about 12 deg: heading 263 + 12 = 275 T, 270 M, 271 C. Fuel 11.5 x 13/60 = 2.5 gal.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-259\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"An a/c A departs from a station at 0900 and flies on a track of 090 at G/S of 250 K. Another a/c departs from the same station at 0930 and flies on a track of 090 with a G/S of 350 K. Find time when ac B will overtake A, place of meeting from the station and dist. from station when ac B will be 5 min behind A.\",\"opts\":[\"1045 Hrs, 408.7 nm, 437.5 nm.\",\"1045 Hrs, 437.5 nm, 408.7 nm.\",\"1040 Hrs, 450 nm, 425 nm.\",\"1040 Hrs, 425 nm, 450 nm.\"],\"ans\":1,\"exp\":\"The correct answer is: 1045 Hrs, 437.5 nm, 408.7 nm..\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-260\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"The reported surface wind from the control tower is 240/35 kt. Runway 30 (300 deg). What is the cross-wind component?\",\"opts\":[\"30 kt\",\"24 kt\",\"27 kt\",\"21 kt\"],\"ans\":0,\"exp\":\"Wind 240 against runway 300 is 60 deg off: crosswind = 35 x sin 60 = 30 kt.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-261\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"An aircraft travels 100 statute miles in 20 min. How long does it take to travel 215 NM?\",\"opts\":[\"50 min\",\"80 min\",\"100 min\",\"90 min\"],\"ans\":0,\"exp\":\"100 SM in 20 min = 300 SM/h = 261 kt. 215 NM / 261 kt = 0.82 h = about 50 min.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-262\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Course 085(T), forecast W/V 020/40 kt, TAS 470 kt, distance 275 NM. The flight time is about:\",\"opts\":[\"37 min\",\"30 min\",\"25 min\",\"42 min\"],\"ans\":0,\"exp\":\"Wind 65 deg off the nose from the left: headwind 40 cos 65 = 17 kt, crosswind 36 kt (4.4 deg drift). GS = 470 - 17 = 452 kt. Time = 275 / 452 = 0.61 h = 37 min.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-263\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Course 040°(T), TAS is 120Kt, wind speed 30Kt. Maximum drift angle will be obtained from a wind direction of\",\"opts\":[\"130°\",\"145°\",\"115°\"],\"ans\":0,\"exp\":\"Drift is greatest when the wind is at 90 deg to the track: wind from 040 + 90 = 130 (or 310). Maximum drift = arcsin (30/120) = 14.5 deg.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-264\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Course 040(T), TAS 120 kt, wind speed 30 kt. The greatest drift (wind correction) occurs with the wind from:\",\"opts\":[\"145\",\"130\",\"115\",\"220\"],\"ans\":1,\"exp\":\"For a FIXED TRACK the crosswind component, and so the drift, is greatest when the wind blows at 90 deg to the track: 040 + 90 = 130 (or 310). Drift = asin(30/120) = 14.5 deg.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-265\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"True Course 017°,W/V 340°/30kt , TAS 420kt. Find wind correction angle and ground speed.\",\"opts\":[\"WCA +2° , GS 396 Kts\",\"WCA -2° , GS 426 Kts\",\"WCA -2° , GS 396 Kts\"],\"ans\":2,\"exp\":\"Wind 340 is 37 deg left of track 017: crosswind 18 kt gives WCA about -2 (heading left); headwind 24 kt gives GS 396 kt.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-266\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Rate of climb 1000 ft/min, groundspeed 198 kt. What is the climb gradient?\",\"opts\":[\"5.08 %\",\"3 %\",\"4 %\",\"4.98 %\"],\"ans\":3,\"exp\":\"Gradient = height gained / distance covered. In one minute the aircraft covers 198 x 6076 / 60 = 20,050 ft and climbs 1000 ft: 1000 / 20,050 = 4.99 %. Rule of thumb: ROC (ft/min) = gradient % x GS (kt) x 1.013.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-267\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"one nano second is ?\",\"opts\":[\"0.000,000,001\",\"0.000,000,000,001\",\"fraction of microsecond\"],\"ans\":0,\"exp\":\"A nanosecond is 10^-9 s = 0.000 000 001 s.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check found that more than one option can be argued for, as worded in the recall. The key gives the answer most references support.\"},{\"id\":\"CPLNAV-268\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"70 m/s is about:\",\"opts\":[\"136 kt\",\"126 kt\",\"70 kt\",\"252 kt\"],\"ans\":0,\"exp\":\"1 kt = 0.514 m/s, so 70 / 0.514 = 136 kt (70 m/s x 3.6 = 252 km/h).\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-269\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"On a 3 deg glide path at 100 kt groundspeed, the rate of descent is about:\",\"opts\":[\"530 ft/min\",\"300 ft/min\",\"700 ft/min\",\"1000 ft/min\"],\"ans\":0,\"exp\":\"ROD = GS x 101 x tan 3 = 100 x 101 x 0.0524 = 530 ft/min (quick: GS x 5 = 500).\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-270\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"On a 3 deg glide path at a groundspeed of 90 kt, the rate of descent is about:\",\"opts\":[\"480 ft/min\",\"270 ft/min\",\"900 ft/min\",\"600 ft/min\"],\"ans\":0,\"exp\":\"ROD = GS x 101 x tan 3 = 90 x 101 x 0.0524 = 478 ft/min (quick: GS x 5 = 450).\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-271\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Runway 14 (140 M). The reported wind is 160/20 kt TRUE and the variation is 10 deg W. The crosswind component is:\",\"opts\":[\"10 kt\",\"7 kt\",\"17 kt\",\"3 kt\"],\"ans\":0,\"exp\":\"Convert the wind to magnetic first: 160 T + 10 W = 170 M. Angle to the runway 30 deg: crosswind 20 sin 30 = 10 kt (headwind 17 kt). Using the true wind directly would give 20 deg and 7 kt.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-272\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Using the 3-to-1 rule (3 NM per 1000 ft), an aircraft at FL370 that must be at FL100 6 NM before the threshold should start descent at about ...... NM from the threshold:\",\"opts\":[\"87\",\"81\",\"111\",\"60\"],\"ans\":0,\"exp\":\"27,000 ft to lose x 3 NM / 1000 ft = 81 NM, plus the 6 NM: begin about 87 NM out.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-273\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"On a constant glide path, if the groundspeed decreases the rate of descent required will:\",\"opts\":[\"increase\",\"decrease\",\"stay the same\",\"depend only on the TAS\"],\"ans\":1,\"exp\":\"The glide path fixes the height lost per mile. At a lower groundspeed the miles pass more slowly, so fewer feet per minute are needed - a headwind on final means a smaller ROD.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-274\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"An aircraft is on a 2.5 deg glide path at a groundspeed of 142 kt. The rate of descent required is about:\",\"opts\":[\"630 ft/min\",\"710 ft/min\",\"500 ft/min\",\"850 ft/min\"],\"ans\":0,\"exp\":\"ROD = GS x 101.3 x tan(angle) = 142 x 101.3 x 0.0437 = 628 ft/min. (For 3 deg the shortcut is GS x 5; for 2.5 deg it is GS x 4.4.)\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-275\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"M 0.80, OAT -50°C, FL 330, GS 490 kt, VAR 20°W, Magnetic heading 140°, Drift is 11° right, Calculate the true W/V?\",\"opts\":[\"020°/95 kts,\",\"020°/80 kts.\",\"025°/90 kts,\"],\"ans\":0,\"exp\":\"LSS at -50 C = 38.95 x sqrt 223 = 582 kt, so TAS = 0.80 x 582 = 465 kt. TH = 140 - 20 = 120; track = 131. Wind = ground vector - air vector gives 020/95.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-276\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"TAS 370 kt, true heading 181, W/V 095/35. The true track and GS are:\",\"opts\":[\"192, 370 kt\",\"176, 370 kt\",\"186, 370 kt\",\"189, 370 kt\"],\"ans\":2,\"exp\":\"The wind blows from 86 deg left of the nose - almost a pure crosswind from the left: drift 35/370 x 57 = 5 deg right, track 186; with no head or tail component the GS stays about 370 kt.\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-277\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Taking off (or landing) with a tailwind instead of a headwind, for the same IAS:\",\"opts\":[\"the groundspeed is higher and the ground roll longer\",\"the groundspeed is lower and the ground roll shorter\",\"the groundspeed and ground roll are unchanged\",\"the groundspeed is higher but the ground roll shorter\"],\"ans\":0,\"exp\":\"The wing needs the same airspeed; with a tailwind the aircraft must also go faster over the ground (TAS + tailwind), so it needs more runway and arrives at a higher groundspeed. That is why a downwind landing in an emergency is fast and long.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Apr 2024 · OLODE 03\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-278\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"On a given track the wind component is +45 kt (tail) and the drift is 15 deg left, TAS 240 kt. What is the wind component on the reverse track?\",\"opts\":[\"-45 kt\",\"-61 kt\",\"-37 kt\",\"-53 kt\"],\"ans\":1,\"exp\":\"Wind component here means GS - TAS. With 15 deg drift, GS = 240 cos 15 + along-track wind, so the real along-track wind is 285 - 232 = 53 kt. Reversed: GS = 232 - 53 = 179 kt, component 179 - 240 = -61 kt. Large drift makes the reverse component worse than just changing the sign.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Jul 2024 · OLODE 05\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-279\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"An aircraft flies for 2 hours at TAS 200 kt into a 30 kt headwind. The air distance and ground distance covered are:\",\"opts\":[\"400 NAM and 340 NGM\",\"340 NAM and 400 NGM\",\"400 NAM and 460 NGM\",\"460 NAM and 400 NGM\"],\"ans\":0,\"exp\":\"Air distance = TAS x time = 400 NAM. Ground distance = GS x time = 170 x 2 = 340 NGM.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jun 2023 · Regular\",\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":3,\"years\":[2021,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-280\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"In a climb flown at a given TAS with a tailwind component, the ground distance covered compared with the air distance is:\",\"opts\":[\"greater\",\"less\",\"the same\",\"impossible to tell\"],\"ans\":0,\"exp\":\"Ground miles = air miles + wind component x time. A tailwind adds ground distance (NGM > NAM); a headwind takes it away. Climb tables give NAM, so correct them for wind before planning top of climb.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-281\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"TAS 375 kt, required track 335(T), W/V 340/50 kt. What heading must be flown and what is the groundspeed?\",\"opts\":[\"335(T), 322 kt\",\"336(T), 325 kt\",\"333(T), 325 kt\",\"334(T), 375 kt\"],\"ans\":1,\"exp\":\"The wind is 5 deg right of the track and almost head-on: crosswind 50 sin 5 = 4 kt needs under 1 deg of correction into wind (right), heading 336; headwind 50 cos 5 = 50 kt, GS = 375 - 50 = 325 kt.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-282\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"Distance to go 210 NM, groundspeed 180 kt, time now 1040 UTC. ETE and ETA are:\",\"opts\":[\"1 h 10 min, 1150 UTC\",\"1 h 10 min, 1140 UTC\",\"1 h 20 min, 1200 UTC\",\"0 h 70 min, 1210 UTC\"],\"ans\":0,\"exp\":\"ETE = 210 / 180 = 1.167 h = 1 h 10 min. ETA = 1040 + 1:10 = 1150 UTC.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-283\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"An aircraft at FL330 must be at FL080 over a fix. Groundspeed in the descent 300 kt, rate of descent 1500 ft/min. How far before the fix must the descent start?\",\"opts\":[\"83 NM\",\"50 NM\",\"100 NM\",\"70 NM\"],\"ans\":0,\"exp\":\"Height to lose 25,000 ft / 1500 = 16.7 min. Distance = 300 x 16.7 / 60 = 83 NM. (Shortcut: 3 NM per 1000 ft at 300 kt / 1500 ft/min gives 75 NM - close, but work it when the options are this far apart.)\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-284\",\"topic\":\"Dead Reckoning, Wind & the CX-3\",\"stem\":\"An EFIS/HSI display shows heading 090 and 8 deg starboard drift. The track pointer shows:\",\"opts\":[\"082\",\"090\",\"098\",\"270\"],\"ans\":2,\"exp\":\"Track = heading + starboard drift (or - port drift): 090 + 8 = 098. The lubber line shows heading; the track line shows where the aircraft actually goes.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-285\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"CP 480 , what happens when tailwind changes to 30kts from 20 kts, what happens to CP ?\",\"opts\":[\"less than 480\",\"more than 480\",\"does not change\"],\"ans\":0,\"exp\":\"DCP = D x H / (O+H). A stronger tailwind increases O and reduces H, which moves the CP closer: less than 480.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Aug 2023 · OLODE\",\"Nov 2023 · OLODE (30 Nov)\",\"Jun 2024 · Regular\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":5,\"years\":[2021,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-286\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"An aircraft has a TAS of 300 kt and a safe endurance of 10 hours. The wind component is 50 kt head on the outbound leg. What is the distance to the Point of No Return?\",\"opts\":[\"1458 NM\",\"1622 NM\",\"1544 NM\",\"1500 NM\"],\"ans\":0,\"exp\":\"O = 250, H = 350. PNR = E x O x H / (O + H) = 10 x 250 x 350 / 600 = 1458 NM (time 5.83 h).\",\"seenIn\":[\"Jun 2024 · Regular\",\"Jun 2025 · Regular 02\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-287\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"P to Q 2000 NM, track 090. TAS: 4 engines 180 kt, 3 engines 150 kt. Wind 090/20 for the first 1000 NM, 150/20 for the rest. Fuel on board 1600 gal, reserve 200 gal; consumption 4 engines 100 gal/h, 3 engines 80 gal/h. Find the distance and time from P to the critical point (engine failure).\",\"opts\":[\"1097 NM, 6 h 49 min\",\"1000 NM, 6 h 15 min\",\"903 NM, 5 h 39 min\",\"1278 NM, 7 h 53 min\"],\"ans\":0,\"exp\":\"Use 3-engine groundspeeds for the CP: first half out 130 / home 170 kt, second half out 139 / home 159 kt. Equal times forward and back come at 1097 NM. Time to get there on 4 engines (GS 160 then 169 kt): 1000/160 + 97/169 = 6 h 49 min. With different winds on each part of the route, work it part by part - one formula for the whole route does not apply.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-288\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Distance A to B 2346 NM, groundspeed out 365 kt, groundspeed back 480 kt. What is the time from A to the point of equal time (PET)?\",\"opts\":[\"167 min\",\"219 min\",\"260 min\",\"197 min\"],\"ans\":1,\"exp\":\"PET distance = 2346 x 480 / (365 + 480) = 1333 NM; time = 1333 / 365 = 3.65 h = 219 min.\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-289\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"For a flight from station 'Z', aircraft cruises 235 kts, track outbound 090 (T), FOB 2500 lb, normal fuel Consumption 255 lb/hr and in case of one engine failure, reduced TAS and F/C are 180 kt TAS and 190 lb/hr, respectively. Average wind component + 30 kt, What shall be the radius of action if one engine fails at the time of returning back ?\",\"opts\":[\"1122 nm\",\"1143 nm\",\"0985 nm\"],\"ans\":0,\"exp\":\"Endurance = 2500/255 = 9.8 h. Out GS = 235 + 30 = 265 kt; home GS with one engine = 180 - 30 = 150 kt at 190 lb/h. Fuel: 255X/265 + 190X/150 = 2500 gives X = 1,122 NM.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-290\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"An aircraft with a TAS of 300 kt flies over water between two airfields 500 NM apart. The wind component is 60 kt head on the way out. What is the distance from the first airfield to the critical point?\",\"opts\":[\"250 NM\",\"200 NM\",\"300 NM\",\"280 NM\"],\"ans\":2,\"exp\":\"GS out O = 300 - 60 = 240 kt, GS home H = 300 + 60 = 360 kt. CP = D x H / (O + H) = 500 x 360 / 600 = 300 NM. A headwind out pushes the CP beyond the mid-point (into wind).\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-291\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Distance A to B 2368 NM, groundspeed out 365 kt, groundspeed home 480 kt, safe endurance 8 h 30 min. What is the time to the PNR?\",\"opts\":[\"290 min\",\"209 min\",\"219 min\",\"190 min\"],\"ans\":0,\"exp\":\"Time to PNR = E x H / (O + H) = 8.5 x 480 / 845 = 4.83 h = 290 min (distance 290/60 x 365 = 1764 NM). Note 219 min is the PET time for similar figures - do not mix the two formulas.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-292\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"DCP is independent of fuel endurance ?\",\"opts\":[\"True\",\"False\",\"DCP is dependent on fuel endurance\"],\"ans\":0,\"exp\":\"The distance to the critical point depends on distance and the wind-affected speeds only, not on fuel or endurance.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2021,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-293\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"When calculating the Point of Safe Return, which endurance is used?\",\"opts\":[\"total endurance\",\"safe endurance (usable fuel excluding the reserve, divided by fuel flow)\",\"endurance to dry tanks plus 30 minutes\",\"half the total endurance\"],\"ans\":1,\"exp\":\"The PSR/PNR is worked on SAFE endurance - fuel that may be used without touching the reserve. Using total endurance would plan the reserve away. Papers give both figures to see whether you pick the right one.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-294\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Which of these does NOT affect the position of the point of equal time (PET / CP)?\",\"opts\":[\"the wind component\",\"the TAS\",\"the fuel on board\",\"the distance between the aerodromes\"],\"ans\":2,\"exp\":\"PET = D x H / (O + H): distance and the two groundspeeds (TAS and wind) move it; fuel does not appear in it.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-295\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"You fly from C to D, a distance of 450 NM. The WC C - D is +30, and the WC D - Cis -40. TAS is 160 Kt and reduced TAS is 130 Kt. The Fuel Flow is 165 kg/hr, and the Safe endurance when overhead C is 4 hours. Calculate PNR for return to C. What is the distance from PNR to D?\",\"opts\":[\"244 nm\",\"205 nm\",\"150 nm\"],\"ans\":1,\"exp\":\"Return GS on reduced TAS = 130 - 40 = 90 kt; out GS 190 kt. PNR distance from C = 4 x 190 x 90 / 280 = 244 NM, so 450 - 244 = 205 NM from D.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-296\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Same flight (P to Q 2000 NM, 4 engines out at 100 gal/h, return on 3 engines at 80 gal/h, 1400 gal usable). Find the distance and time from P to the PNR.\",\"opts\":[\"1278 NM, 7 h 53 min\",\"1097 NM, 6 h 49 min\",\"1400 NM, 8 h 36 min\",\"1150 NM, 7 h 11 min\"],\"ans\":0,\"exp\":\"Fuel out (4 engines) + fuel back (3 engines) = 1400 gal: out 1000/160 x 100 + (x-1000)/169 x 100; back (x-1000)/159 x 80 + 1000/170 x 80. Solving gives x = 1278 NM, reached after 7 h 53 min.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true,\"note\":\"As recalled, this question depended on a chart or table that is not reproduced here; the key is the recalled paper's answer.\"},{\"id\":\"CPLNAV-297\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Distance 1020 NM, track 190, W/V 180/40, TAS 280 kt. What are the groundspeed and the flight time?\",\"opts\":[\"240 kt, 4 h 15 min\",\"320 kt, 3 h 11 min\",\"280 kt, 3 h 39 min\",\"260 kt, 3 h 55 min\"],\"ans\":0,\"exp\":\"The wind is only 10 deg off the nose: headwind 40 cos 10 = 39 kt, drift about 1.4 deg, GS = 280 - 39 = 240 kt. Time = 1020 / 240 = 4.24 h = 4 h 15 min.\",\"seenIn\":[\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-298\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Track 225(T), distance 477 NM, normal TAS 470 kt, TAS after an engine failure 180 kt, wind component 30 kt head on the outbound leg. Find the distance and time from departure to the critical point.\",\"opts\":[\"278 NM / 38 min\",\"199 NM / 27 min\",\"239 NM / 33 min\",\"278 NM / 111 min\"],\"ans\":0,\"exp\":\"Engine-failure CP uses the reduced TAS: O = 180 - 30 = 150, H = 180 + 30 = 210, CP = 477 x 210 / 360 = 278 NM. Time to it at the normal groundspeed 470 - 30 = 440 kt: 278 / 440 = 0.63 h = 38 min.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-299\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Distance A to B is 360 NM. Wind component A to B is 15 kt head, B to A 15 kt tail. TAS 180 kt. What is the distance from the equal-time point (CP) to B?\",\"opts\":[\"170 NM\",\"195 NM\",\"180 NM\",\"165 NM\"],\"ans\":3,\"exp\":\"O = 165 kt, H = 195 kt. CP from A = 360 x 195 / 360 = 195 NM, so CP to B = 360 - 195 = 165 NM.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-300\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"An aircraft was over 'A' at 1435 flying direct to 'B'. Distance A to B 2900 NM, TAS 470 kt, mean wind component out +55 kt, back -75 kt, safe endurance 9 h 30 min. What is the distance from A to the Point of Safe Return (PSR)?\",\"opts\":[\"2844 NM\",\"1611 NM\",\"1759 NM\",\"2141 NM\"],\"ans\":3,\"exp\":\"O = 470 + 55 = 525 kt, H = 470 - 75 = 395 kt. Time to PSR = E x H / (O + H) = 9.5 x 395 / 920 = 4.08 h; distance = 4.08 x 525 = 2141 NM.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-301\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"The Critical Point (Equal Time Point) is the point along track where:\",\"opts\":[\"fuel remaining equals fuel used\",\"the time to continue to destination equals the time to return to departure\",\"the headwind becomes a tailwind\",\"the aircraft can no longer return to departure\"],\"ans\":1,\"exp\":\"At the CP the time to go on and the time to turn back are equal, so it tells the crew which way to go after an engine failure or medical emergency. The point beyond which you cannot return is the PNR.\",\"seenIn\":[\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-302\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"The Point of No Return (Point of Safe Return) is:\",\"opts\":[\"the point at which the time to continue equals the time to return\",\"the furthest point along track from which the aircraft can still return to the departure aerodrome with its reserves intact\",\"the point where half the fuel has been used\",\"the mid-point of the route corrected for wind\"],\"ans\":1,\"exp\":\"Beyond the PNR there is not enough usable fuel to get back with reserves intact, so the decision to go on is final. The point where continuing and returning take equal time is the CP (equal-time point), a different point.\",\"seenIn\":[\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-303\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"The PNR was planned at 580 NM with a fuel flow of 200 lb/h. In flight the actual fuel flow is 230 lb/h (TAS and wind as planned). Where is the new PNR?\",\"opts\":[\"504 NM\",\"580 NM\",\"667 NM\",\"460 NM\"],\"ans\":0,\"exp\":\"The PNR distance is proportional to the safe endurance, which is fuel / fuel flow. Same fuel, higher flow: 580 x 200 / 230 = 504 NM. More fuel flow always brings the PNR closer to departure.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-304\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Usable fuel (excluding reserve) 4000 kg. Out: TAS 250 kt, 800 kg/h, 20 kt headwind. Return at a reduced TAS of 200 kt using 700 kg/h, with the 20 kt wind now behind. Find the time to the PNR.\",\"opts\":[\"2 h 37 min\",\"2 h 23 min\",\"3 h 00 min\",\"2 h 10 min\"],\"ans\":0,\"exp\":\"With different fuel flows out and back, solve on FUEL, not time. GS out 250 - 20 = 230 kt, GS home 200 + 20 = 220 kt. x/230 x 800 + x/220 x 700 = 4000, so x (3.478 + 3.182) = 4000 and x = 601 NM. Time = 601 / 230 = 2.61 h = 2 h 37 min.\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-305\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Same aircraft (fuel flow 473 lb/h, 2200 lb usable, track 047, W/V 200/30, TAS 240 kt normal / 190 kt with an engine failed). The time to the critical point is 35 min less than the time to the PNR. What is the stage distance?\",\"opts\":[\"898 NM\",\"918 NM\",\"985 NM\",\"1020 NM\"],\"ans\":1,\"exp\":\"Time to PNR = E x H / (O + H) = 4.65 x 213 / 479 = 124 min, so time to CP = 89 min; at GS 266 kt that is 395 NM. The engine-failure CP uses the reduced TAS (GS 216 out, 163 home): D = 395 x (216 + 163) / 163 = 918 NM.\",\"seenIn\":[\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-306\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"When actual FC is 220 but planned was 200, What happens to PNR\",\"opts\":[\"20% less\",\"20% more\",\"10% less\"],\"ans\":2,\"exp\":\"Actual consumption is 10% higher, so endurance and the distance to the PNR fall by about 10%.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-307\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Distance 2400 NM, TAS 300 kt. With a 50 kt headwind out (50 kt tail home) the CP was planned at 1400 NM from departure. In flight the wind is found to be a 50 kt TAILwind out instead. Where is the new CP?\",\"opts\":[\"1000 NM\",\"1200 NM\",\"1400 NM\",\"1600 NM\"],\"ans\":0,\"exp\":\"O = 350, H = 250: CP = 2400 x 250 / 600 = 1000 NM. The CP always moves INTO the wind: headwind out puts it beyond the mid-point, tailwind out brings it back towards departure.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-308\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Fuel on board 14,000 lb, reserve to be kept 2,000 lb. Twin-engine aircraft, fuel flow 1,000 lb/h per engine, TAS 180 kt, wind component 45 kt head out. Distance to the PNR?\",\"opts\":[\"506 NM\",\"540 NM\",\"608 NM\",\"450 NM\"],\"ans\":0,\"exp\":\"Safe endurance = 12,000 / 2,000 = 6 h. O = 135, H = 225. PNR = 6 x 135 x 225 / 360 = 506 NM (time 3 h 45 min).\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-309\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Given a distance (DCP) of 500 NM with a 20 kt tailwind, what will be the new DCP if the wind changes to a 30 kt tailwind?\",\"opts\":[\"LESS than 500 Nm\",\"More than 500 Nm\",\"equal to 500 Nm\"],\"ans\":0,\"exp\":\"DCP = D x H / (O+H): a stronger tailwind lowers H and raises O, so the CP moves closer to the departure point.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-310\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"The fuel flow increases from 200 to 220 kg/h (other factors unchanged). The PNR distance:\",\"opts\":[\"increases by about 10 %\",\"decreases by about 10 %\",\"does not change\",\"decreases by about 20 %\"],\"ans\":1,\"exp\":\"PNR distance is proportional to safe endurance = fuel / fuel flow: 200/220 = 0.91, a decrease of 9 % - about 10 %.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-311\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Dist. = 800 nm, TRK = 330°, W/V = 270°/30 kts, TAS = 240 kts DCP?\",\"opts\":[\"524 Nm\",\"425 Nm\",\"480 Nm\"],\"ans\":1,\"exp\":\"Out GS = 223.6 kt (track 330), home GS = 253.6 kt (track 150). DCP = 800 x 253.6 / (223.6 + 253.6) = 425 NM.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-312\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Track 200(T), W/V 047/30 kt, TAS 240 kt (190 kt if an engine fails). Fuel on board (usable) 2200 lb. The distance to the PNR is 550 NM. What is the fuel consumption?\",\"opts\":[\"473 lb/h\",\"400 lb/h\",\"550 lb/h\",\"510 lb/h\"],\"ans\":0,\"exp\":\"Wind 27 kt behind going out: GS out 266 kt, GS home 213 kt. Endurance E = PNR x (O + H) / (O x H) = 550 x 479 / 56,700 = 4.65 h. Fuel flow = 2200 / 4.65 = 473 lb/h.\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-313\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"True track 190, W/V 150/40, TAS 280 kt, distance 1020 NM. Find the distance and time to the critical point.\",\"opts\":[\"566 NM, 2 h 17 min\",\"510 NM, 2 h 03 min\",\"454 NM, 1 h 50 min\",\"566 NM, 1 h 50 min\"],\"ans\":0,\"exp\":\"Wind 40 deg off the nose: headwind 40 cos 40 = 31 kt. GS out about 248 kt, GS home (track 010, wind 40 deg behind) about 309 kt. CP = 1020 x 309 / (248 + 309) = 566 NM; time = 566 / 248 = 2.28 h = 2 h 17 min.\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-314\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Which statement about the Critical Point (CP, equal-time point) and the Point of No Return (PNR) is correct?\",\"opts\":[\"The CP depends on the fuel on board; the PNR depends only on the wind\",\"The CP depends only on distance and groundspeeds (not on fuel); the PNR depends on the safe endurance and the groundspeeds\",\"Both the CP and the PNR depend on the safe endurance\",\"Neither the CP nor the PNR is affected by the wind\"],\"ans\":1,\"exp\":\"CP distance from departure = D x H / (O + H): only the total distance and the groundspeeds out (O) and home (H) appear, so fuel never moves it. PNR distance = E x O x H / (O + H): it depends on the safe endurance E and the two groundspeeds, and not on the distance to the destination at all.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Dec 2023 · Regular\",\"Jul 2025 · OLODE 05\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":5,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-315\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Distance A to B 1200 NM. Normal TAS 400 kt, TAS with one engine inoperative 300 kt. Wind component 40 kt head on the way out. Find the distance from A to the CP for an engine failure, and the time to reach it.\",\"opts\":[\"680 NM, 1 h 53 min\",\"660 NM, 1 h 50 min\",\"520 NM, 1 h 27 min\",\"680 NM, 2 h 37 min\"],\"ans\":0,\"exp\":\"The CP for an engine failure uses the REDUCED TAS, because that is the speed you will fly after the failure: O = 300 - 40 = 260, H = 300 + 40 = 340, CP = 1200 x 340 / 600 = 680 NM. You get there at the NORMAL groundspeed (400 - 40 = 360 kt): 680 / 360 = 1.89 h = 1 h 53 min.\",\"seenIn\":[\"Feb 2026 · OLODE 02\",\"May 2026 · OLODE 04\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":3,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-316\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"Distance 600 NM, groundspeed out 200 kt, groundspeed home 250 kt. The time from departure to the critical point is:\",\"opts\":[\"100 min\",\"80 min\",\"90 min\",\"120 min\"],\"ans\":0,\"exp\":\"CP distance = D x H / (O + H) = 600 x 250 / 450 = 333 NM; time at the outbound GS = 333 / 200 = 1.67 h = 100 min.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-317\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"The distance from departure to the PNR depends on:\",\"opts\":[\"safe endurance, outbound and homebound groundspeeds - not on the distance to the destination\",\"the distance between the two aerodromes only\",\"the outbound groundspeed only\",\"the reserve fuel only\"],\"ans\":0,\"exp\":\"PNR = E x O x H / (O + H). Move the destination further away and the PNR does not move; burn fuel faster (lower E) or meet a stronger wind and it moves back towards departure.\",\"seenIn\":[\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-318\",\"topic\":\"Critical Point & Point of No Return\",\"stem\":\"A four-engine aircraft flies out at TAS 400 kt using 4000 kg/h into a 40 kt headwind. If it has to return on three engines, its TAS is 350 kt and fuel flow 3500 kg/h (40 kt tailwind home). Fuel available (excluding reserve) 24,000 kg. Distance to the PNR?\",\"opts\":[\"1195 NM\",\"1290 NM\",\"1080 NM\",\"1350 NM\"],\"ans\":0,\"exp\":\"With different fuel flows, solve on fuel: x/360 x 4000 + x/390 x 3500 = 24000, so x (11.11 + 8.97) = 24000 and x = 1195 NM (time out 3 h 19 min).\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-319\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"An aircraft plans to depart London at 1000 UTC and arrive at Munich (EDDM) at 1215 UTC. In the ATS flight plan Item 16 (destination / EET) should be entered with\",\"opts\":[\"EDDM 1215\",\"EDDM 1415\",\"EDDM 0215\",\"EDDM 2H15\"],\"ans\":2,\"exp\":\"Item 16 carries destination and total EET: 1000 to 1215 UTC is 2 h 15 min, written EDDM0215.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Nov 2023 · OLODE (29 Nov)\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"May 2024 · OLODE 04\",\"Jan 2025 · OLODE 01\",\"Jan 2026 · OLODE 01\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":8,\"years\":[2021,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-320\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"For a flight plan filed before flight, the indicated time of departure is\",\"opts\":[\"the time overhead the first reporting point after take off\",\"the time at which the flight plan is filed\",\"the estimated off block time\"],\"ans\":2,\"exp\":\"The departure time in a filed flight plan is the estimated off-block time.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jun 2023 · Regular\",\"Aug 2023 · OLODE\",\"Nov 2023 · OLODE (29 Nov)\",\"Nov 2023 · OLODE (30 Nov)\",\"Dec 2023 · Regular\",\"Apr 2024 · OLODE 03\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":8,\"years\":[2021,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-321\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"In the ATS flight plan item 15, when entering a route for which standard departure (SID) and standard arrival (STAR) procedures exist\",\"opts\":[\"both should be entered in the ATS plan where appropriate\",\"SIDs should be entered but not STARs\",\"STARs should be entered but not SIDs\",\"neither SID nor STAR should be entered\"],\"ans\":0,\"exp\":\"In Item 15 a route that has standard departure and arrival procedures carries the SID and STAR designators where appropriate.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Aug 2023 · OLODE\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Aug 2024 · OLODE 06\",\"Sep 2024 · Regular 03\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":7,\"years\":[2022,2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-322\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"Cruise speed of 285 Knots will be written in flight plan as\",\"opts\":[\"N0285\",\"N285\",\"K285\"],\"ans\":0,\"exp\":\"Cruising speed in Item 15 is N followed by the TAS in four digits: 285 kt is N0285, 230 kt N0230, 480 kt N0480.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Nov 2023 · OLODE (29 Nov)\",\"Mar 2024 · Regular 01\",\"Jun 2024 · Regular\",\"Sep 2024 · Regular 03\",\"Jun 2025 · Regular 02\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":7,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-323\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"In the ATS flight plan, for a non-scheduled flight which of the following letters should be entered in Item 8 (Type of Flight)?\",\"opts\":[\"N\",\"N/S\",\"G\",\"V\"],\"ans\":0,\"exp\":\"Item 8 type of flight: S scheduled, N non-scheduled air transport, G general aviation, M military, X other.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Nov 2023 · OLODE (29 Nov)\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Jun 2025 · Regular 02\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":6,\"years\":[2021,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-324\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"A CURRENT flight plan is a\",\"opts\":[\"flight plan in the course of which radio communication should be practised between aeroplane and ATC\",\"filed flight plan\",\"flight plan with the correct time of departure\",\"filed flight plan with amendments and clearance included\"],\"ans\":3,\"exp\":\"A current flight plan is the filed flight plan together with any amendments and ATC clearances.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Nov 2023 · OLODE (29 Nov)\",\"Dec 2023 · Regular\",\"May 2024 · OLODE 04\",\"Jul 2024 · OLODE 05\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":6,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-325\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"The ICAO flight plan comes under\",\"opts\":[\"Doc 4444\",\"Doc 8869\",\"Doc 8879\"],\"ans\":0,\"exp\":\"The ICAO flight plan is described in Doc 4444 (PANS-ATM).\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Nov 2023 · OLODE (30 Nov)\",\"Feb 2024 · OLODE 02\",\"Jul 2024 · OLODE 05\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-326\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"An aeroplane is flying from an airport to another. In cruise, the calibrated airspeed is 150 kt, true airspeed 180 kt, average groundspeed 210 kt. The speed box on the filed flight plan shall be filled as follows\",\"opts\":[\"K0150\",\"K0210\",\"K0180\",\"N0180\"],\"ans\":3,\"exp\":\"The cruising speed in the flight plan is the TAS: 180 kt is written N0180.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Nov 2023 · OLODE (29 Nov)\",\"Dec 2023 · Regular\",\"May 2024 · OLODE 04\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":5,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-327\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"the shape of holding pattern is\",\"opts\":[\"Circular\",\"Race track\",\"Rectangular\"],\"ans\":1,\"exp\":\"A holding pattern is flown as a racetrack: two turns joined by two straight legs.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Nov 2023 · OLODE (30 Nov)\",\"Jun 2024 · Regular\",\"Sep 2024 · Regular 03\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-328\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"Airspeed Entered in Item.15 of the flight plan is always ?\",\"opts\":[\"TAS\",\"IAS\",\"G/S\"],\"ans\":0,\"exp\":\"Item 15 cruising speed is the true airspeed (N plus four digits).\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Dec 2023 · Regular\",\"May 2024 · OLODE 04\",\"Sep 2024 · Regular 03\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-329\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"In the ATS flight plan item 15, it is necessary to enter any point at which a change of cruising speed takes place. For this purpose a CHANGE OF SPEED is defined as\",\"opts\":[\"20 km per hour or 0.1 Mach or more\",\"10% TAS or 0.05 Mach or more\",\"5% TAS or 0.01 Mach or more\",\"20 knots or 0.05 Mach or more\"],\"ans\":2,\"exp\":\"A change of speed is significant when it is 5% of TAS or 0.01 Mach or more.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Dec 2023 · Regular\",\"May 2024 · OLODE 04\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-330\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"In the ICAO flight plan, how is time written?\",\"opts\":[\"4 digits in UTC\",\"4 digits in IST\"],\"ans\":0,\"exp\":\"Times in the flight plan are four digits in UTC.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2024 · Regular\",\"Jan 2025 · OLODE 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-331\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"At least how much time before departure you can fill flight plan\",\"opts\":[\"30 min\",\"60 min\",\"2 hours\"],\"ans\":1,\"exp\":\"The correct answer is: 60 min.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Jun 2024 · Regular\",\"Jan 2025 · OLODE 01\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":4,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-332\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"In Item 10 of the flight plan, the letter \\\"O\\\" indicates:\",\"opts\":[\"GNSS\",\"Omega\",\"VOR\",\"ILS\"],\"ans\":2,\"exp\":\"O = VOR; L = ILS; G = GNSS; D = DME; F = ADF; I = inertial; S = standard equipment (VHF RTF, VOR, ILS).\",\"seenIn\":[\"Jul 2023 · OLODE\",\"Sep 2023 · Regular 03\",\"Mar 2024 · Regular 01\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-333\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"The aircraft identification in Item 7 of the ICAO flight plan may contain at most:\",\"opts\":[\"5 characters\",\"7 characters\",\"8 characters\",\"10 characters\"],\"ans\":1,\"exp\":\"Item 7: the aircraft identification, not more than 7 alphanumeric characters with no hyphens or symbols (e.g. AIC101 or VTABC).\",\"seenIn\":[\"Mar 2022\",\"Sep 2023 · Regular 03\",\"Nov 2023 · OLODE (30 Nov)\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":4,\"years\":[2022,2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-334\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"Given the following flight plan information: Trip Fuel: 136 kg Flight Time: 2.75 hours Reserve Fuel: 30% of Trip Fuel Minimum Taxi Fuel: 3 kg Fuel in Tanks: Minimum required How should the “Endurance” be completed in the ICAO flight plan?\",\"opts\":[\"03:38\",\"03:34\",\"02:45\"],\"ans\":1,\"exp\":\"Reserve = 30% x 136 = 40.8 kg; fuel flow = 136 / 2.75 = 49.5 kg/h, so reserve = 49.5 min. Endurance = 2 h 45 + 0 h 49 = 3 h 34 (taxi fuel is not in endurance).\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Aug 2023 · OLODE\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-335\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"In an ICAO flight plan, which item is used to mention the FIR boundary?\",\"opts\":[\"Item 9\",\"Item 12\",\"Item 18\"],\"ans\":2,\"exp\":\"The accumulated EET to FIR boundary points is entered in Item 18 (EET/).\",\"seenIn\":[\"Dec 2024 · Regular 04\",\"Mar 2025 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-336\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"Reference item 19 of the ICAO flight plan, endurance is\",\"opts\":[\"maximum flight time plus 45 minutes holding fuel\",\"maximum flight time plus 30 minutes holding fuel\",\"fuel endurance of the aircraft\",\"total usable fuel required for the flight\"],\"ans\":2,\"exp\":\"Item 19 endurance is the time the usable fuel on board will keep the aeroplane flying.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Nov 2023 · OLODE (29 Nov)\",\"Dec 2023 · Regular\"],\"undated\":false,\"times\":3,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-337\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"How is a flight level xyz written in the ICAO flight plan?\",\"opts\":[\"FLxyz\",\"Fxyz\",\"F0xyz\"],\"ans\":1,\"exp\":\"A flight level is written F followed by three digits (F085), or A for altitude; FL is not used in Item 15.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2024 · Regular\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-338\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"If your destination airport has no ICAO indicator, in the appropriate box of your ATC flight plan, you write:\",\"opts\":[\"XXXX\",\"/////////\",\"ZZZZ\",\"XXX\"],\"ans\":2,\"exp\":\"If the destination has no ICAO location indicator, ZZZZ is written in Item 16 and the name of the aerodrome is put in Item 18 (DEST/).\",\"seenIn\":[\"Jan 2019\",\"Dec 2023 · Regular\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2019,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-339\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"A total estimated elapsed time of 1 h 55 min is written in the flight plan as:\",\"opts\":[\"1h55\",\"115\",\"155\",\"0155\"],\"ans\":3,\"exp\":\"Times and durations in the flight plan are four figures, hours then minutes: 0155.\",\"seenIn\":[\"Jul 2024 · OLODE 05\",\"Jan 2025 · OLODE 01\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-340\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"How ILS and GNSS filled in flight plan?\",\"opts\":[\"L & G\",\"L & N\",\"I & N\"],\"ans\":0,\"exp\":\"In Item 10 the letter L means ILS and G means GNSS.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Jun 2025 · Regular 02\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-341\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"How endurance is filled in flight plan?\",\"opts\":[\"Total usable fuel on board\",\"Total usable fuel minus reserve fuel\"],\"ans\":0,\"exp\":\"Item 19 endurance is the time corresponding to the total usable fuel on board (not minus reserves).\",\"seenIn\":[\"Jun 2023 · Regular\",\"Nov 2023 · OLODE (29 Nov)\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":3,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-342\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"When the number of persons on board is not known at the time of filing, Item 19 shows:\",\"opts\":[\"P/000\",\"P/TBN\",\"P/NIL\",\"nothing\"],\"ans\":1,\"exp\":\"PANS-ATM: insert TBN (to be notified) if the total number of persons is not known at the time of filing.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jun 2024 · Regular\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":3,\"years\":[2021,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-343\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"Cruising at TAS 300 kt at FL250, the speed and level group in Item 15 is:\",\"opts\":[\"N0300F250\",\"N300F250\",\"K0300F250\",\"N0300A250\"],\"ans\":0,\"exp\":\"Speed N + 4 figures (knots), level F + 3 figures (flight level). A = altitude in hundreds of feet, K = km/h.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-344\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"On an IFR flight, ATC must be informed when the average TAS at cruising level differs from the flight plan by ...... or the time estimate for the next reporting point/FIR boundary/destination is wrong by more than ......:\",\"opts\":[\"5 %; 3 minutes\",\"10 %; 5 minutes\",\"5 kt; 2 minutes\",\"3 %; 5 minutes\"],\"ans\":0,\"exp\":\"Annex 2, 3.6.2.2: TAS variation of +/- 5 % (newer edition: Mach 0.02 / 10 kt), time estimate error over 3 minutes (or as the ATS authority prescribes).\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-345\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"The expected approach time (EAT) is the time at which ATC expects an arriving aircraft, after holding, to:\",\"opts\":[\"be overhead the aerodrome\",\"leave the holding fix (initial approach fix) to start its approach\",\"reach the final approach fix\",\"land\"],\"ans\":1,\"exp\":\"EAT = when the aircraft is expected to leave the holding point and commence the approach; it protects radio-failure procedures.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-346\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"In Item 10 (surveillance equipment), the letter for a serviceable transponder with Mode A (4096 codes) and Mode C is:\",\"opts\":[\"A\",\"C\",\"P\",\"S\"],\"ans\":1,\"exp\":\"A = Mode A only; C = Modes A and C; S = Mode S with altitude and identity. N = no surveillance equipment.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Dec 2023 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-347\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"In the ATS flight plan (Item 10 - Equipment), which letter is used to indicate the carriage of a serviceable transponder?\",\"opts\":[\"A, C, and S\",\"X, Y, and Z\",\"B, D, and T\"],\"ans\":0,\"exp\":\"In Item 10 the surveillance letters A (Mode A), C (Modes A and C) and S (Mode S) indicate a transponder.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-348\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"An aircraft has a maximum certificated take-off mass of 137000 kg but is operating at take-off mass 135000 kg. In Item 9 of the ATS flight plan its wake turbulence category is\",\"opts\":[\"medium plus (M+)\",\"heavy/medium (H/M)\",\"medium (M)\",\"heavy (H)\"],\"ans\":3,\"exp\":\"The wake turbulence category comes from the certificated maximum take-off mass, not the actual one: 137,000 kg is 136,000 kg or more, so Heavy (H).\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-349\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"On an ATC flight plan, to indicate that you will overfly the way-point ROMEO at 120 kt at flight level 085, you will write\",\"opts\":[\"ROMEO / K0120 FL085\",\"ROMEO / N0120 F085\",\"ROMEO / FL085 N0120\",\"ROMEO / F085 N0120\"],\"ans\":1,\"exp\":\"A route point is written with the speed first, then the level: ROMEO/N0120F085.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-350\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"You make a diversion from the route given in the flight plan and land at an uncontrolled airfield. Within what time after landing should you inform ATC?\",\"opts\":[\"10 mins\",\"20 mins\",\"30 mins\"],\"ans\":2,\"exp\":\"The correct answer is: 30 mins.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-351\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"You are flying to a destination airport that has no ICAO indicator. What should be written in Item 18?\",\"opts\":[\"ZZZZ\",\"DEST\",\"DEST/(the name of the airfield)\",\"XXXX\"],\"ans\":2,\"exp\":\"ZZZZ goes in the destination box and DEST/ name of the airfield in Item 18.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-352\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"Unless otherwise shown on charts for standard instrument departure routes, the routes are given with\",\"opts\":[\"magnetic course\",\"true headings\",\"magnetic headings\"],\"ans\":0,\"exp\":\"SID routes are shown as magnetic courses unless the chart says otherwise.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-353\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"In ICAO flight plan Item 9 the letter M will be written for (wake turbulence category)\",\"opts\":[\"aircraft with maximum take-off mass more than 136,000 kg\",\"aircraft with maximum take-off mass less than 136,000 kg\",\"aircraft with maximum take-off mass less than 7,000 kg\"],\"ans\":1,\"exp\":\"Wake turbulence category M (medium) covers a MTOM of less than 136,000 kg and more than 7,000 kg.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-354\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"An aircraft has a flight time of 2 hrs 30 mins, a contingency fuel of 30% is carried. What is the total endurance?\",\"opts\":[\"03:15\",\"02:45\",\"03:45\"],\"ans\":0,\"exp\":\"Contingency 30% of 2 h 30 = 45 min, so endurance is 2 h 30 + 0 h 45 = 3 h 15.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-355\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"If a pilot lands at an aerodrome other than the destination aerodrome specified in the ICAO flight plan, she must ensure that the ATS unit at the destination is informed within a specified time of her planned ETA at destination. The time is:\",\"opts\":[\"30 minutes\",\"45 minutes\",\"1 hour\",\"No time limit\"],\"ans\":0,\"exp\":\"After landing at another aerodrome the pilot must have the destination ATS unit informed within 30 minutes of the planned ETA.\",\"seenIn\":[\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-356\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"For an aeroplane over 5,700 kg first issued a certificate of airworthiness after 1 April 1998, the minimum recording durations are:\",\"opts\":[\"FDR 25 hours, CVR 2 hours\",\"FDR 10 hours, CVR 30 minutes\",\"FDR 25 hours, CVR 30 minutes\",\"FDR 2 hours, CVR 25 hours\"],\"ans\":0,\"exp\":\"FDR: last 25 hours of operation; CVR: last 2 hours (older aircraft: CVR 30 minutes). Newer rules extend the CVR to 25 hours for large aeroplanes certificated recently.\",\"seenIn\":[\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-357\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"A flight from Birmingham(EGBB) to Dublin(EIDW) as an EOBT of 1000hrs actual time of destination is 1215hrs how should be complete item number 16 of the flight plan\",\"opts\":[\"1215hrs\",\"0215hrs\"],\"ans\":1,\"exp\":\"The correct answer is: 0215hrs.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-358\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"An aircraft is planned to take off from London at 1000 UTC and land at the destination at 1215 UTC. The total EET is entered in the flight plan as:\",\"opts\":[\"0215\",\"1215\",\"2:15\",\"135\"],\"ans\":0,\"exp\":\"Total EET (Item 16) is four figures, hours and minutes: 2 h 15 min = 0215. It is the estimated time from take-off to arrival at destination, not a clock time.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-359\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"A cruising TAS of 150 kt is entered in Item 15 of the ICAO flight plan as:\",\"opts\":[\"N0150\",\"K0150\",\"N150\",\"M0150\"],\"ans\":0,\"exp\":\"Speed in Item 15: N + four figures for knots (N0150), K + four figures for km/h, M + three figures for Mach (M082).\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-360\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"The position 50 deg N 005 deg 27'E is written in Item 15 as:\",\"opts\":[\"50N00527E\",\"5000N00527E\",\"N5000E00527\",\"50N0527E\"],\"ans\":1,\"exp\":\"Degrees and minutes: 2 figures + 2 figures + N/S, then 3 figures + 2 figures + E/W - eleven characters. (A CDU may want a different format, e.g. N5000.0E00527.0.)\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-361\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"Wake turbulence category L (light) applies to aircraft with an MTOM of:\",\"opts\":[\"7,000 kg or less\",\"5,700 kg or less\",\"less than 136,000 kg\",\"15,000 kg or less\"],\"ans\":0,\"exp\":\"L: 7,000 kg or less; M: more than 7,000 but less than 136,000 kg; H: 136,000 kg or more (J for A380-type).\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-362\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"If the aircraft's transponder has Mode A only (no altitude reporting), Item 10 shows:\",\"opts\":[\"A\",\"C\",\"N\",\"S\"],\"ans\":0,\"exp\":\"A = transponder Mode A (4 digits, 4096 codes) only. Add Mode C capability and the letter becomes C.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-363\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"An ICAO flight plan should be submitted:\",\"opts\":[\"at least 60 minutes before EOBT and not more than 120 hours before it\",\"at least 30 minutes before take-off\",\"any time after take-off\",\"at least 24 hours before EOBT\"],\"ans\":0,\"exp\":\"File at least 60 minutes before the estimated off-block time (or as the ATS unit requires); the 2012 flight plan rules also stop filing more than 120 hours ahead.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-364\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"After a diversionary landing at an aerodrome other than the planned destination, the arrival report must be made:\",\"opts\":[\"within 24 hours\",\"as soon as practicable after landing, by the quickest means, and it must name the original destination\",\"only if the flight crossed a FIR boundary\",\"by the operator the next day\"],\"ans\":1,\"exp\":\"Annex 2 (3.3.5): the arrival report is made as soon as practicable after landing by the quickest means; in a diversion it must include the destination aerodrome. Missing it can start an unnecessary search and rescue.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-365\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"On an en-route chart an airway is marked \\\"5000 2900a\\\". The 5000 is the:\",\"opts\":[\"maximum authorised altitude\",\"minimum holding altitude\",\"minimum en-route altitude (MEA)\",\"transition altitude\"],\"ans\":2,\"exp\":\"The correct answer is: minimum en-route altitude (MEA).\",\"seenIn\":[\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-366\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"A/C Structural Mass 140000, On the day it weighs 130000 what should be entered in wake turbulence category ?\",\"opts\":[\"H\",\"M\",\"L\"],\"ans\":0,\"exp\":\"Wake category is set by the certificated maximum take-off mass: 140,000 kg (136,000 or more) is Heavy (H).\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-367\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"The initial approach segment of an instrument approach begins at the:\",\"opts\":[\"FAF\",\"initial approach fix (IAF)\",\"missed approach point\",\"threshold\"],\"ans\":1,\"exp\":\"Arrival -> IAF -> initial segment -> IF -> intermediate -> FAF -> final -> MAPt / missed approach.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-368\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"The planned departure time from the parking area is 1815UTC. The estimated take-off time is 1825UTC. The IFR flight plan must be filed with ATC at the latest at:\",\"opts\":[\"1745UTC\",\"1715UTC\",\"1725UTC\"],\"ans\":1,\"exp\":\"A flight plan is filed at least 60 minutes before the estimated off-block time (1815): 1715.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-369\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"Under the current ICAO rule, ATC must be told when the sustained Mach number/TAS at cruising level varies from the current flight plan by:\",\"opts\":[\"Mach 0.02 or 19 km/h (10 kt) TAS, or more\",\"Mach 0.01 or 19 kt\",\"Mach 0.05 or 10 kt\",\"Mach 0.1 or 5 %\"],\"ans\":0,\"exp\":\"Annex 2 (later editions) replaced the 5 % TAS rule with Mach 0.02 or 19 km/h (10 kt). The older edition on many syllabi states 5 % of TAS.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-370\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"In Item 10 of the flight plan, the letter \\\"S\\\" means:\",\"opts\":[\"satellite navigation\",\"standard equipment: VHF RTF, VOR and ILS\",\"Mode S transponder\",\"SELCAL\"],\"ans\":1,\"exp\":\"S stands for the standard set (VHF RTF, VOR, ILS) unless the ATS authority prescribes another combination; Mode S is a surveillance letter after the stroke.\",\"seenIn\":[\"Jun 2024 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-371\",\"topic\":\"The ICAO Flight Plan\",\"stem\":\"The purpose of a Standard Instrument Departure (SID) is to:\",\"opts\":[\"give the shortest route to destination\",\"provide a published IFR route from take-off to the en-route structure, with obstacle clearance and less radio traffic\",\"replace the flight plan\",\"allow departure without an ATC clearance\"],\"ans\":1,\"exp\":\"A SID is a designated departure route linking the runway to the en-route phase. It keeps traffic and terrain separation built in and lets ATC clear an aircraft with a short name instead of a long route.\",\"seenIn\":[\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-372\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The fuel burn-off is 200 kg/h with a relative fuel density of 0.8. If the relative fuel density is 0.75, the fuel burn will be\",\"opts\":[\"213 kg/h\",\"200 kg/h\",\"188 kg/h\"],\"ans\":1,\"exp\":\"The burn is given in kg/h, which is a mass flow. The engine burns a mass of fuel for the power it makes, so a change of fuel density changes the volume used, not the mass: the burn stays 200 kg/h.\",\"seenIn\":[\"Mar 2022\",\"Sep 2022 · FC 03\",\"Nov 2023 · OLODE (30 Nov)\",\"Dec 2023 · Regular\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":5,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-373\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"During a VFR flight at a navigation check point the remaining usable fuel is 60 US gal. The reserve fuel is 12 US gal. According to the flight plan the remaining flight time is 1h 35mins. Calculate the highest acceptable rate of consumption possible for the rest of the trip.\",\"opts\":[\"30.3US gal/hr\",\"33US gal/hr\",\"37.9 us gal/hr\"],\"ans\":0,\"exp\":\"Fuel available for the trip = 60 - 12 = 48 US gal over 1 h 35 min (1.583 h): 48 / 1.583 = 30.3 US gal/h.\",\"seenIn\":[\"Mar 2022\",\"Jun 2023 · Regular\",\"Jul 2024 · OLODE 05\",\"Jun 2025 · Regular 02\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":5,\"years\":[2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-374\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"1 US gallon and 1 Imperial gallon are, in litres:\",\"opts\":[\"3.785 and 4.546\",\"4.546 and 3.785\",\"3.785 and 3.785\",\"4.546 and 4.546\"],\"ans\":0,\"exp\":\"US gal x 3.785 = litres; Imp gal x 4.546 = litres; 1 Imp gal = 1.2 US gal.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Jun 2024 · Regular\",\"Jan 2026 · OLODE 01\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-375\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"DOM 33510. Traffic Load 7600, Final reserve 983, Alternate fuel 1100, contingency fuel 102, estimated landing mass at destination alternate will be:\",\"opts\":[\"42093 kg\",\"42210 kg\",\"42195 kg\"],\"ans\":2,\"exp\":\"At the alternate the aeroplane still carries the final reserve and the unused contingency fuel; only the alternate fuel has been burnt. Landing mass = 33,510 + 7,600 + 983 + 102 = 42,195 kg (and at the destination it would be 1,100 kg more, 43,295 kg).\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Dec 2023 · Regular\",\"Jul 2024 · OLODE 05\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-376\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"ETOPS (EDTO) diversion distances are calculated using:\",\"opts\":[\"the forecast winds and actual temperatures\",\"the approved one-engine-inoperative cruise speed in ISA and still-air conditions\",\"the all-engine cruise speed\",\"the actual wind on the day\"],\"ans\":1,\"exp\":\"The ETOPS threshold and maximum diversion distance are fixed figures: diversion time at the approved OEI cruise speed in standard (ISA), still-air conditions.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\",\"Sep 2023 · Regular 03\",\"Aug 2024 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-377\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"A turbo-jet aeroplane has taxi fuel 600 kg, cruise fuel flow 10000 kg/h, holding fuel flow 8000 kg/h, alternate fuel 10200 kg, flight time 6 hours, visibility at destination 2000 m. What is the minimum ramp fuel?\",\"opts\":[\"80,500 kg\",\"79,200 kg\",\"77,800 kg\"],\"ans\":2,\"exp\":\"Taxi 600 + trip 6 x 10,000 = 60,000 + contingency 5% = 3,000 + alternate 10,200 + final reserve 30 min x 8,000 = 4,000 = 77,800 kg.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Dec 2023 · Regular\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-378\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"MTOM 40 t, MLM 32 t, MZFM 28 t, DOM 15 t, trip fuel 7,500 kg, contingency 1,100 kg, final reserve 400 kg. The maximum traffic load is:\",\"opts\":[\"13,000 kg\",\"16,000 kg\",\"15,500 kg\",\"12,500 kg\"],\"ans\":0,\"exp\":\"MZFM: 28,000 - 15,000 = 13,000. MTOM: 40,000 - 9,000 fuel - 15,000 = 16,000. MLM: 32,000 - 1,500 remaining fuel - 15,000 = 15,500. The lowest is 13,000 kg.\",\"seenIn\":[\"Jan 2026 · OLODE 01\",\"Feb 2026 · OLODE 02\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-379\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"A turbojet aircraft flies to an ISOLATED aerodrome (no alternate). Cruise fuel burn 7,500 kg/h, holding 5,000 kg/h. The minimum additional fuel to carry (instead of alternate + final reserve) is:\",\"opts\":[\"15,000 kg\",\"10,000 kg\",\"5,800 kg\",\"7,500 kg\"],\"ans\":0,\"exp\":\"For an isolated destination a turbine aeroplane carries fuel to fly for 2 hours at normal cruise consumption above the destination, including final reserve: 2 x 7,500 = 15,000 kg.\",\"seenIn\":[\"Sep 2024 · Regular 03\",\"Mar 2025 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-380\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The zero fuel mass is:\",\"opts\":[\"DOM + traffic load\",\"DOM + fuel\",\"basic empty mass + crew\",\"TOM - trip fuel\"],\"ans\":0,\"exp\":\"ZFM = dry operating mass + traffic load; + take-off fuel = TOM; + taxi fuel = ramp/taxi mass.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Sep 2023 · Regular 03\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2021,2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-381\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Fuel flow 120 kg/h for 1 h 20 min uses:\",\"opts\":[\"160 kg\",\"144 kg\",\"120 kg\",\"200 kg\"],\"ans\":0,\"exp\":\"Fuel used = fuel flow x time = 120 x 1 h 20 min (1.333 h) = 160 kg.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Jan 2025 · OLODE 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-382\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"IFR flight: trip fuel 65 US gal, contingency 5 % of trip, alternate fuel (including final reserve) 17 US gal, usable fuel at departure 93 US gal. At the half-way point 40 US gal have been used. Assuming the consumption stays the same:\",\"opts\":[\"at departure the required reserves were 28 US gal\",\"the aircraft will arrive at destination with the required reserves intact\",\"the remaining fuel is insufficient to reach destination with the required reserves intact\",\"the aircraft cannot reach destination\"],\"ans\":2,\"exp\":\"Required reserves = 3.25 + 17 = 20.25 US gal. Half the trip used 40 (planned 32.5), so the second half also needs 40: 93 - 80 = 13 US gal at destination - below 20.25. It reaches destination, but not with reserves intact; plan a diversion or refuel.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Aug 2024 · OLODE 06\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-383\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"On an aero plane without central fuel tank, the maximum Zero Fuel Mass is related to:\",\"opts\":[\"maximum structural take-off mass.\",\"wing loaded trip fuel.\",\"the bending moment at the wing root.\"],\"ans\":2,\"exp\":\"On an aeroplane with wing tanks only, MZFM is set by the wing-root bending moment: the fuel in the wings relieves it.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Nov 2023 · OLODE (30 Nov)\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-384\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Given: DOM=33500kg, load= 7600kg, MTOM= 66200Kg, taxi fuel= 200Kg Tank capacity= 16100Kg, The maximum possible take off fuel is:\",\"opts\":[\"17100 Kg\",\"16300 Kg\",\"15900 Kg\",\"17300 Kg\"],\"ans\":2,\"exp\":\"Ramp fuel is limited by the tanks (16,100 kg); taxi fuel 200 kg leaves 15,900 kg for take-off. The mass limit (66,200 - 33,500 - 7,600 = 25,100 kg) is not limiting.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-385\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Payload does not include\",\"opts\":[\"passengers\",\"fuel\",\"cargo\"],\"ans\":1,\"exp\":\"Payload is the traffic load (passengers, baggage, cargo); fuel is not part of it.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-386\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Fuel flow per HR is 25 US-GAL; total fuel on board is 90 IMP GAL. What is the Endurance?\",\"opts\":[\"4 HR 32 MIN\",\"3 HR 12 MIN\",\"3HR53MIN\",\"4 HR 19 MIN\"],\"ans\":3,\"exp\":\"90 imp gal x 1.2 = 108 US gal; 108 / 25 = 4.32 h = 4 h 19 min.\",\"seenIn\":[\"Jan 2019\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2019,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-387\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The maximum zero fuel mass is the maximum permissible mass of the aeroplane:\",\"opts\":[\"with no usable fuel\",\"with no usable fuel, unless the flight manual says otherwise\",\"including take-off fuel\",\"including all usable fuel\"],\"ans\":1,\"exp\":\"MZFM limits the mass in the fuselage (wing-root bending): above it, extra load must be fuel in the wings. Unusable fuel is counted in it.\",\"seenIn\":[\"Jul 2023 · OLODE\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-388\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Convert 40 US gallons of fuel of specific gravity 0.72 to litres and kilograms\",\"opts\":[\"182 kg / 131 litres\",\"151 litres / 109 kg\",\"182 litres / 131 kg\"],\"ans\":1,\"exp\":\"40 US gal x 3.785 = 151 litres; x 0.72 = 109 kg.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-389\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Payload (traffic load) in mass and balance is:\",\"opts\":[\"passengers, baggage and cargo (including non-revenue load)\",\"crew and their baggage\",\"usable fuel\",\"the basic empty mass\"],\"ans\":0,\"exp\":\"Traffic load/payload = everything carried for reward or delivery. Dry operating mass + traffic load = zero fuel mass; + take-off fuel = take-off mass.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-390\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The dry operating mass is:\",\"opts\":[\"basic empty mass + payload\",\"basic empty mass + variable load (crew and their baggage, catering, removable service equipment)\",\"zero fuel mass - fuel\",\"take-off mass - fuel\"],\"ans\":1,\"exp\":\"DOM = everything needed for the operation except usable fuel and traffic load. Payload is added on top to get the ZFM.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-391\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The DOM of an aeroplane is:\",\"opts\":[\"TOM minus operating mass.\",\"LM plus trip fuel.\",\"TOM minus useful load.\"],\"ans\":2,\"exp\":\"DOM = TOM minus useful load (traffic load plus usable fuel).\",\"seenIn\":[\"May 2024 · OLODE 04\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-392\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Fuel consumption is 220 kg/hr with Density of 0.8. What would be the FC when density changes to 0.75 ?\",\"opts\":[\"275 kg/hr\",\"206 kg/hr\",\"220 kg/hr\"],\"ans\":2,\"exp\":\"Fuel consumption in kg/hr is a mass flow, and the engine needs the same mass of fuel for the same power whatever the density. Only the volume (litres per hour) changes, so the consumption stays 220 kg/hr.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-393\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"MTOW 64400 kg, MLM 56200, MZFM 53300, trip fuel 4900, FOB 7400, minimum take-off fuel 7400, DOM 35500, payload 14500: find the maximum take-off fuel\",\"opts\":[\"11100\",\"11400\",\"14400\"],\"ans\":0,\"exp\":\"Zero-fuel mass 35,500 + 14,500 = 50,000 kg. Landing limit 56,200 - 50,000 = 6,200 kg at landing, plus trip 4,900 = 11,100 kg; the take-off limit gives 14,400 kg, so 11,100 kg governs.\",\"seenIn\":[\"Jan 2019\",\"Mar 2022\"],\"undated\":false,\"times\":2,\"years\":[2019,2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-394\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Given the following aircraft data: Dry Operating Mass (DOM): 33,510 kg Traffic Load: 7,600 kg Trip Fuel: 2,040 kg Final Reserve Fuel: 983 kg Alternate Fuel: 1,100 kg Contingency Fuel: 5% of Trip Fuel Which of the following is correct?\",\"opts\":[\"Estimated landing mass at destination: 43,193 kg\",\"Estimated landing mass at destination: 43,295 kg\",\"Estimated take-off mass: 43,295 kg\"],\"ans\":1,\"exp\":\"Landing mass at destination = DOM 33,510 + traffic load 7,600 + final reserve 983 + alternate 1,100 + contingency (5% of 2,040 = 102) = 43,295 kg.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-395\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"You are given the following aircraft parameters: MTOM (Maximum Takeoff Mass): 64,400 kg MLM (Maximum Landing Mass): 56,200 kg MZFM (Maximum Zero Fuel Mass): 53,000 kg DOM (Dry Operating Mass): 35,500 kg Load: 14,500 kg Trip Fuel: 4,900 kg Takeoff Fuel: 7,400 kg What is the maximum additional load?\",\"opts\":[\"3,000 kg\",\"4,000 kg\",\"5,600 kg\"],\"ans\":0,\"exp\":\"Zero-fuel mass 50,000 kg against MZFM 53,000 leaves 3,000 kg; the take-off and landing limits leave more.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-396\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Given the following fuel data: Block Fuel: 7,300 kg Trip Fuel: 4,300 kg Contingency Fuel (CF): 30% of Trip Fuel The captain decides to change the Block Fuel to 9,000 kg according to the ICAO Flight Manual. What happens to the Trip Fuel?\",\"opts\":[\"4,300 kg\",\"5,250 kg\",\"7,200 kg\"],\"ans\":0,\"exp\":\"The correct answer is: 4,300 kg.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-397\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"As fuel warms up its volume increases. Its density (specific gravity):\",\"opts\":[\"increases\",\"decreases\",\"stays the same\",\"doubles\"],\"ans\":1,\"exp\":\"The same mass occupies more volume, so the mass per litre falls. Quantity by mass (kg) is unchanged - which is why fuel is planned in mass.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-398\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The Trip Fuel for a jet aeroplane to fly from the departure aerodrome to the destination aerodrome is 5 350 kg. Fuel consumption in holding mode is 6 000 kg/h. The quantity of fuel which is needed to carry out one go-around and land on the alternate airfield is 4 380 kg. The destination aerodrome has a single runway. What is the minimum quantity of fuel which should be on board at take-off?\",\"opts\":[\"13050 kg\",\"12 700 kg\",\"13000 kg\",\"10000 kg\"],\"ans\":2,\"exp\":\"Trip 5,350 + contingency 5% (268) + alternate/go-around 4,380 + final reserve 30 min at 6,000 = 3,000 = about 13,000 kg.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-399\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"When calculating the fuel required to carry out a given flight, one must take into account: 1. the wind 2. foreseeable airborne delays 3. other weather forecasts 4. any foreseeable conditions which may delay landing. The combination of correct statements is\",\"opts\":[\"1, 2, 3, 4\",\"1, 2, 3\",\"1, 3\"],\"ans\":0,\"exp\":\"Fuel planning must allow for wind, foreseeable airborne delays, weather forecasts and any conditions that may delay landing.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-400\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The ramp (taxi) mass is:\",\"opts\":[\"ZFM + take-off fuel\",\"ZFM + total fuel on board including taxi fuel\",\"TOM - taxi fuel\",\"DOM + payload\"],\"ans\":1,\"exp\":\"Ramp mass = take-off mass + taxi fuel = ZFM + block fuel. It is the heaviest the aircraft is on the ground.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-401\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"T/0 weight 65000 lb, landing weight 49750 lb. climb fuel 4500 lb Descent fuel 1950 lb Find the Mid cruise weight.\",\"opts\":[\"24500 kgs\",\"56100 kgs\",\"56500 lb\",\"56100 lb\"],\"ans\":3,\"exp\":\"Start of cruise 65,000 - 4,500 = 60,500 lb; end of cruise 49,750 + 1,950 = 51,700 lb; mid-cruise = 56,100 lb.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-402\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"You are required to uplift 40 US gallons of AVGAS with Sp. Gravity of 0.72. How many litres and kilograms is this?\",\"opts\":[\"109 kg\",\"450 kg\",\"100 kg\"],\"ans\":0,\"exp\":\"40 US gal = 151 L; x 0.72 = 109 kg.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-403\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The tank capacity of an aircraft is 310 US GAL. Fuel specific gravity is 0,78 kg/litre. The tanks are now 3/4 full. You want to refuel so that total fuel will be 850 kg. How much fuel will you have to refuel? Answer in pounds.\",\"opts\":[\"164 lB\",\"360 LB\",\"320 LB\",\"410LB\"],\"ans\":1,\"exp\":\"3/4 of 310 USG = 232.5 USG = 880 L = 686 kg; to reach 850 kg add 164 kg = 361 lb.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-404\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"A fuel amount of 146 Imp Gal allows a endurance of 4 HR 26 Min. What is the corresponding fuel flow ?\",\"opts\":[\"34.3 Imp Gal/hr\",\"32.9 US Gal/hr\",\"39.5 US Gal/hr\",\"39.5 Imp Gal/hr\"],\"ans\":2,\"exp\":\"146 imp gal / 4.433 h = 32.9 imp gal/h = 39.5 US gal/h (1 imp gal = 1.2 US gal).\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-405\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"A fuel amount of 160 US Gal,allows a endurance of 3 HR 10 Min with a light twin engine piston aircraft. What is the corresponding fuel flow per engine ?\",\"opts\":[\"25.3 US Gal / HR\",\"50.5 US Gal/ HR\",\"51.6 US Gal / HR\",\"25.8 US Gal / HR\"],\"ans\":0,\"exp\":\"160 US gal / 3.167 h = 50.5 US gal/h for two engines = 25.3 US gal/h per engine.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-406\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The Dry Operating Mass of an aircraft is 2 000 kg. The maximum take-off mass, landing and zero fuel mass are identical at 3500 kg. The block fuel mass is 550 kg, and the taxi, fuel mass is 50 kg. The available mass of pay load is:\",\"opts\":[\"1500 kg\",\"950 kg\",\"1000 kg\",\"1450 kg\"],\"ans\":2,\"exp\":\"Fuel at take-off = 550 - 50 = 500 kg; TOM limit 3,500 - 2,000 - 500 = 1,000 kg payload (ZFM limit would allow 1,500).\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-407\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Maximum structural take-off mass: 72 000 kg Maximum structural landing mass: 56 000 kg Maximum zero fuel mass: 48 000 kg Taxi fuel: 800 kg Trip fuel: 18 000 kg Contingency fuel: 900 kg Alternate fuel: 700 kg Final reserve fuel: 2 000 kg Determine the actual take-off mass:\",\"opts\":[\"74 000 kg\",\"69 600 kg\",\"72 000 kg\",\"70 400 kg\"],\"ans\":1,\"exp\":\"Maximum zero-fuel mass 48,000 + reserves (900 + 700 + 2,000) = 51,600 kg landing mass, within the 56,000 limit; TOM = 51,600 + trip 18,000 = 69,600 kg (taxi fuel is burnt before take-off).\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-408\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"345 IMP-GAL equals? (Specific gravity 0.78)\",\"opts\":[\"803 kg.\",\"1223 lb.\",\"1226 kgs.\",\"1223 kgs\"],\"ans\":3,\"exp\":\"345 imp gal x 4.546 = 1568 litres; x 0.78 = 1223 kg.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-409\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"380 US gallons of fuel with a specific gravity of 0.78 weigh about:\",\"opts\":[\"1123 kg\",\"2470 kg\",\"5434 kg\",\"543 kg\"],\"ans\":0,\"exp\":\"380 x 3.785 = 1438 litres; x 0.78 = 1122 kg.\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-410\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"A fuel flow of 220 litres/h at a density of 0.80 kg/l is needed. If the fuel density becomes 0.75, the volume flow for the SAME mass flow is:\",\"opts\":[\"235 l/h\",\"206 l/h\",\"220 l/h\",\"176 l/h\"],\"ans\":0,\"exp\":\"Mass flow = 220 x 0.80 = 176 kg/h. Lighter fuel needs more litres: 176 / 0.75 = 235 l/h. (If the pump fixes the VOLUME instead, the mass flow falls - a different question.)\",\"seenIn\":[\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-411\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Fuel density 0.781 kg/l, DOW 33,500 kg, traffic load 10,000 kg, MTOM 66,000 kg, taxi fuel 200 kg, tank capacity 22,560 litres. The maximum possible take-off fuel is about:\",\"opts\":[\"17,420 kg\",\"22,100 kg\",\"22,450 kg\",\"17,620 kg\"],\"ans\":0,\"exp\":\"Tank capacity = 22,560 x 0.781 = 17,620 kg; less 200 kg taxi = 17,420 kg at take-off. MTOM would allow 66,000 - 43,500 = 22,500 kg, so the tanks limit.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-412\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Fuel flows: 1407 lb/h for 1 h 00 min, 8743 lb/h for 4 h 15 min, 9800 lb/h for 5 h 20 min. Total fuel used:\",\"opts\":[\"90,830 lb\",\"52,270 lb\",\"37,160 lb\",\"19,950 lb\"],\"ans\":0,\"exp\":\"1407 + 8743 x 4.25 (37,158) + 9800 x 5.333 (52,267) = 90,832 lb.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-413\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"DOW 33,510 kg, traffic load 7,600 kg, final reserve 988 kg, alternate fuel 1,190 kg, trip fuel 2,600 kg (no contingency stated). The estimated landing mass at destination is:\",\"opts\":[\"43,288 kg\",\"45,888 kg\",\"42,098 kg\",\"41,110 kg\"],\"ans\":0,\"exp\":\"At destination only the reserves are left: ZFM 41,110 + alternate 1,190 + final reserve 988 = 43,288 kg.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-414\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The quantity of fuel which is calculated to be necessary for a Jet aeroplane to fly IFR from departure to destination aerodrome is 5325kg. Fuel consumption in holding mode is 6000kg per hour , Alternate fuel is 4380 kg ,Contingency should be 5% of trip fuel. What is the minimum required quantity of fuel which should be on board at take off?\",\"opts\":[\"13220\",\"13000\",\"14500\"],\"ans\":1,\"exp\":\"Trip 5,325 + contingency 5% (266) + alternate 4,380 + final reserve 30 min at 6,000 = 3,000 = about 13,000 kg.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-415\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Maximum zero fuel mass 13.5 t, dry operating mass 6.5 t. The maximum traffic load is:\",\"opts\":[\"6.5 t\",\"7.0 t\",\"13.5 t\",\"20.0 t\"],\"ans\":1,\"exp\":\"The traffic load can only fill the gap between the dry operating mass and the maximum zero fuel mass: 13.5 t - 6.5 t = 7.0 t (fuel is not part of the zero fuel mass).\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-416\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The operational details of an aircraft are: MTOW = 72000 kg, MLW = 63000 kg, MZFW = 60000 kg, Burn-off = 6.5T, Reserve = 3.5T, Operating weight = 42000 kg. Maximum payload = ?\",\"opts\":[\"20000 kg\",\"18000 kg\",\"17500 kg\"],\"ans\":2,\"exp\":\"ZFM limit gives 60,000 - 42,000 = 18,000; landing limit: ZFM + 3.5 t reserve <= 63,000 gives 17,500; take-off limit 20,000. The landing limit governs: 17,500 kg.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-417\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"DOM 33,500 kg, traffic load 7,600 kg, MTOM 66,200 kg, taxi fuel 200 kg, tank capacity 16,100 kg. The maximum fuel that can be on board at the ramp is:\",\"opts\":[\"16,100 kg\",\"25,100 kg\",\"25,300 kg\",\"15,900 kg\"],\"ans\":0,\"exp\":\"ZFM = 41,100 kg, so MTOM would allow 66,200 - 41,100 = 25,100 kg of take-off fuel - more than the tanks hold. The tank capacity, 16,100 kg, limits it (15,900 kg at take-off after taxi).\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-418\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"Trip fuel 4,300 kg, taxi 500 kg, contingency 250 kg, alternate 700 kg, planned block fuel 7,000 kg. The captain asks for 9,000 kg. The effect is:\",\"opts\":[\"take-off and landing mass both rise by 2,000 kg and trip fuel increases slightly\",\"only the reserves change\",\"take-off mass unchanged\",\"landing mass unchanged\"],\"ans\":0,\"exp\":\"The extra 2,000 kg is carried throughout: TOM up by 2,000; the heavier aircraft burns a little more trip fuel, and almost all of the extra is still on board at landing.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-419\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"DOM 43.5 t and MZFM 60.5 t. The maximum payload (ZFM-limited) is:\",\"opts\":[\"15 t\",\"16.5 t\",\"17 t\",\"none of these\"],\"ans\":2,\"exp\":\"Maximum payload = MZFM - DOM = 60.5 - 43.5 = 17 t.\",\"seenIn\":[\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-420\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"MTOM 64,400 kg, MLM 56,200 kg, MZFM 53,000 kg, DOM 35,500 kg, estimated load 14,500 kg, trip fuel 4,900 kg, minimum take-off fuel 7,400 kg. The maximum ADDITIONAL load that can be carried is:\",\"opts\":[\"5,600 kg\",\"7,000 kg\",\"3,000 kg\",\"6,200 kg\"],\"ans\":2,\"exp\":\"Traffic-load limits: MZFM 53,000 - 35,500 = 17,500; MTOM 64,400 - 7,400 - 35,500 = 21,500; MLM 56,200 - 2,500 - 35,500 = 18,200. The lowest, 17,500, governs; 17,500 - 14,500 = 3,000 kg more.\",\"seenIn\":[\"Aug 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-421\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The take-off mass equals:\",\"opts\":[\"landing mass + trip fuel\",\"landing mass - trip fuel\",\"zero fuel mass + trip fuel\",\"dry operating mass + trip fuel\"],\"ans\":0,\"exp\":\"Trip fuel is burnt between take-off and landing, so TOM = landing mass + trip fuel (and landing mass = TOM - trip fuel).\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-422\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The Operating mass of an aircraft is\",\"opts\":[\"the dry operating mass plus the take off fuel mass\",\"the empty mass plus the take off fuel mass\",\"the empty mass plus crew, crew baggage and catering\"],\"ans\":0,\"exp\":\"Operating mass is the dry operating mass plus the take-off fuel mass.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-423\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"State the FALSE statement\",\"opts\":[\"ZFM = DOM + take-off fuel\",\"TOM = ZFM + take-off fuel\",\"LM = TOM - take-off fuel\"],\"ans\":0,\"exp\":\"The correct answer is: ZFM = DOM + take-off fuel.\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-424\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"MTOW 76,850 kg, MLW 68,040 kg, MZFW 62,600 kg, DOM 45,680 kg, take-off fuel (all reserves included) 15,620 kg. Assuming the landing mass limit is not the restriction, the maximum payload is:\",\"opts\":[\"15,550 kg\",\"16,920 kg\",\"13,550 kg\",\"22,360 kg\"],\"ans\":0,\"exp\":\"MZFW limit: 62,600 - 45,680 = 16,920. MTOW limit: 76,850 - 15,620 - 45,680 = 15,550. The smaller, 15,550 kg, governs.\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-425\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"On a payload-range diagram, beyond the range at which maximum payload can be carried:\",\"opts\":[\"range can be increased only by trading payload for fuel (take-off mass limited), up to the point where the tanks are full\",\"range increases with no loss of payload\",\"payload increases with range\",\"the aircraft becomes landing-mass limited\"],\"ans\":0,\"exp\":\"Up to the first corner the aircraft carries full payload; beyond it MTOM is reached, so every extra kg of fuel costs a kg of payload; beyond full tanks, range increases only as payload (mass) is shed further.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Sep 2024 · Regular 03\",\"Nov 2024 · OLODE 08\",\"Mar 2026 · Regular 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":7,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-426\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"MTOM 62,000 kg, actual zero fuel mass 48,000 kg, required reserve fuel (contingency, alternate, final reserve) 4,000 kg. Ignoring taxi fuel and fuel capacity, the maximum trip fuel that can be carried is:\",\"opts\":[\"10,000 kg\",\"14,000 kg\",\"6,000 kg\",\"4,000 kg\"],\"ans\":0,\"exp\":\"Take-off fuel cannot exceed MTOM - ZFM = 14,000 kg. Of that, 4,000 kg must remain as reserves, leaving at most 10,000 kg of trip fuel.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Aug 2025 · OLODE 06\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":5,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-427\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"100 US gallons are equal to about:\",\"opts\":[\"83 Imperial gallons\",\"120 Imperial gallons\",\"100 Imperial gallons\",\"379 Imperial gallons\"],\"ans\":0,\"exp\":\"Imperial gallon is larger: 1 US gal = 0.833 Imp gal, so 100 US gal = 83 Imp gal (= 379 litres).\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-428\",\"topic\":\"Fuel Planning, Payload & Loading\",\"stem\":\"The final reserve fuel for a turbojet aeroplane is fuel to fly for:\",\"opts\":[\"30 minutes at holding speed at 1500 ft above the alternate (destination) aerodrome, ISA\",\"45 minutes at holding speed\",\"30 minutes at cruising speed\",\"45 minutes at cruising speed\"],\"ans\":0,\"exp\":\"Turbojet: 30 min holding at 1500 ft; piston: 45 min (VFR/IFR differ). Planned fuel = taxi + trip + contingency + alternate + final reserve (+ additional + extra).\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-429\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"Moving the CG towards (but within) the aft limit:\",\"opts\":[\"increases stability and stalling speed\",\"reduces longitudinal stability, lightens the controls and improves range (less tail download and drag)\",\"has no effect on range\",\"increases the stalling speed\"],\"ans\":1,\"exp\":\"Aft CG: smaller static margin (less stable, more manoeuvrable, lighter stick forces) and less tailplane download, so less induced drag and fuel burn - better range. Behind the aft limit it becomes dangerously unstable.\",\"seenIn\":[\"Jul 2023 · OLODE\",\"Aug 2023 · OLODE\",\"Nov 2023 · OLODE (29 Nov)\",\"Jun 2024 · Regular\",\"Jul 2024 · OLODE 05\",\"Apr 2025 · OLODE 03\",\"Jun 2025 · Regular 02\",\"Jul 2025 · OLODE 05\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":9,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-430\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"When the centre of gravity is at the forward limit, an aeroplane will be\",\"opts\":[\"extremely stable and will require excessive elevator control to change pitch\",\"extremely unstable and require excessive elevator control to change pitch\",\"extremely stable and require small elevator control to change pitch\"],\"ans\":0,\"exp\":\"A forward CG makes the aeroplane very stable but the elevator must be moved a lot to change pitch (heavy controls, higher stall speed).\",\"seenIn\":[\"Jun 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\",\"Jun 2025 · Regular 02\",\"Feb 2026 · OLODE 02\",\"Jul 2026 · OLODE 05\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":6,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-431\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"An aeroplane is said to be neutrally stable. This is likely to:\",\"opts\":[\"Causes the centre of gravity to move forward.\",\"Be caused by a centre of gravity which is towards the forward limit.\",\"Be caused by a centre of gravity which is towards the rearward limit.\"],\"ans\":2,\"exp\":\"Neutral stability occurs when the CG reaches the neutral point, which lies behind the aft CG limit - so it is associated with a CG towards the rearward limit.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\",\"Sep 2024 · Regular 03\",\"May 2025 · OLODE 04\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":6,\"years\":[2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-432\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"Forward CG will cause\",\"opts\":[\"higher stalling speed\",\"lower stalling speed\",\"no effect on the stalling speed\"],\"ans\":0,\"exp\":\"With the CG forward the tailplane must supply a larger download, so the stalling speed rises.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Oct 2023 · OLODE\",\"Nov 2023 · OLODE (30 Nov)\",\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":4,\"years\":[2021,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-433\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"If the centre of gravity of an aeroplane moves forward during flight the elevator control will\",\"opts\":[\"become heavier, making the aeroplane more difficult to manoeuvre in pitch\",\"become lighter, making the aeroplane more difficult to manoeuvre in pitch\",\"become heavier, making the aeroplane easier to manoeuvre in pitch\"],\"ans\":0,\"exp\":\"Moving the CG forward makes the aeroplane more stable and the elevator control heavier, so it is harder to manoeuvre in pitch.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Mar 2024 · Regular 01\",\"Jan 2026 · OLODE 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-434\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"The longitudinal (pitch) stability of an aeroplane depends mainly on:\",\"opts\":[\"the wing dihedral\",\"the position of the CG relative to the neutral point, with the tailplane providing the restoring moment\",\"the fin size\",\"the engine power\"],\"ans\":1,\"exp\":\"The further the CG is ahead of the neutral point (static margin), the more stable; the horizontal tailplane provides the restoring moment. Moving the CG aft reduces stability.\",\"seenIn\":[\"Jul 2023 · OLODE\",\"Mar 2024 · Regular 01\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-435\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"If weight is increased, what happens to stalling?\",\"opts\":[\"Increases\",\"Decreases\",\"Remains the same\"],\"ans\":0,\"exp\":\"A higher mass needs a higher lift coefficient / speed for the same lift: the stalling speed increases.\",\"seenIn\":[\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-436\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"The stalling speed of an aeroplane will be highest when it is loaded with a:\",\"opts\":[\"High gross mass and aft centre of gravity\",\"Low gross mass and forward centre of gravity\",\"Low gross mass and aft centre of gravity\",\"High gross mass and forward centre of gravity\"],\"ans\":3,\"exp\":\"Stalling speed is highest with high gross mass and a forward CG.\",\"seenIn\":[\"Jan 2019\",\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":2,\"years\":[2019,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-437\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"The centre of gravity is:\",\"opts\":[\"the point where the datum is\",\"the point through which the total weight of the aircraft acts\",\"the point about which the aircraft rolls\",\"the centre of lift\"],\"ans\":1,\"exp\":\"All the individual weights can be replaced by one force, the total weight, acting through the CG. CG arm = total moment / total mass.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-438\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"Who establishes the limits of C of G?\",\"opts\":[\"The CAA\",\"The JAA\",\"The manufacturer\",\"The insurers\"],\"ans\":2,\"exp\":\"The manufacturer establishes the CG limits (approved by the authority).\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-439\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"One effect on an aircraft that is nose-heavy is:\",\"opts\":[\"A tendency for the nose to pitch up\",\"An increase in range\",\"A decrease in stability\",\"An increase in drag, due to excessive elevator trim\"],\"ans\":3,\"exp\":\"A nose-heavy aeroplane needs nose-up elevator trim, which adds drag.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-440\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"With the centre of gravity outside (ahead of) the forward limit:\",\"opts\":[\"longitudinal stability reduced, pitch stick forces increased\",\"stability reduced, stick forces reduced\",\"stability increased, stick forces reduced\",\"stability increased, pitch stick forces increased\"],\"ans\":3,\"exp\":\"A very forward CG makes the aeroplane too stable: large elevator forces/deflection are needed to rotate and flare, and there may not be enough elevator authority.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-441\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"If center of gravity is forward limit the a/c will\",\"opts\":[\"benefit from reduced drag due to increase in aoa\",\"required more trim elevation which will increase the fuel consumption\",\"required less power consumption for a given airspeed\"],\"ans\":1,\"exp\":\"A forward CG needs more nose-up trim (elevator down-load), which increases drag and fuel consumption.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-442\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"An autopilot changes the aeroplane's pitch attitude (angle of attack) through the:\",\"opts\":[\"elevator, with auto-trim relieving the sustained load\",\"ailerons\",\"rudder\",\"flaps\"],\"ans\":0,\"exp\":\"The pitch channel drives the elevator servo; the auto-trim moves the stabiliser to remove the steady elevator load so the AP can disconnect without a jolt.\",\"seenIn\":[\"May 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-443\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"If an aero plane is at a higher mass than anticipated, for a given airspeed the angle of attack will?\",\"opts\":[\"remain constant, drag will decrease and endurance will decrease.\",\"remain constant, drag will increase and endurance will increase.\",\"be greater, drag will increase and endurance will decrease.\"],\"ans\":2,\"exp\":\"A heavier aeroplane at the same speed needs a higher angle of attack, so drag increases and endurance falls.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-444\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"The basic empty mass includes:\",\"opts\":[\"crew and catering\",\"the structure, engines, fixed equipment, unusable fuel and full operating fluids\",\"usable fuel\",\"passengers\"],\"ans\":1,\"exp\":\"BEM + variable load (crew, catering, etc.) = DOM; + traffic load = ZFM.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-445\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"An aircraft of 1000 kg has its CG 2.00 m aft of the datum. 200 kg of baggage is loaded 3.00 m aft of the datum. The new CG is:\",\"opts\":[\"2.17 m aft of datum\",\"2.50 m aft\",\"2.20 m aft\",\"2.00 m aft\"],\"ans\":0,\"exp\":\"Moments: 1000 x 2.00 = 2000; 200 x 3.00 = 600; total 2600 kg m. Mass 1200 kg. CG = 2600 / 1200 = 2.17 m.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-446\",\"topic\":\"Mass, Balance & Stability\",\"stem\":\"Overloading an aeroplane above its maximum mass results in:\",\"opts\":[\"a lower stalling speed and shorter take-off\",\"a higher stalling speed, longer take-off and landing runs, poorer climb, and reduced structural safety margins\",\"no change if the CG is within limits\",\"better stability only\"],\"ans\":1,\"exp\":\"More weight needs more lift: higher stall speed and approach speed, longer runs, lower climb gradient and ceiling, and the structure is loaded beyond its design limits.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-447\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"V1 should be a minimum of\",\"opts\":[\"Vmcg\",\"Vmbe\",\"Vef\"],\"ans\":0,\"exp\":\"V1 may not be less than VMCG, the minimum control speed on the ground.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2023 · Regular\",\"Jul 2023 · OLODE\",\"Nov 2023 · OLODE (29 Nov)\",\"Jan 2024 · Regular (Day 2)\",\"Jun 2024 · Regular\",\"Jul 2024 · OLODE 05\",\"Mar 2025 · Regular 01\",\"May 2025 · OLODE 04\",\"Jan 2026 · OLODE 01\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":13,\"years\":[2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-448\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Vr should not be less than:\",\"opts\":[\"V2\",\"Vmcg\",\"1.05 Vmca\"],\"ans\":2,\"exp\":\"For a Class A aeroplane VR must not be less than V1 and not less than 1.05 VMCA.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Oct 2024 · OLODE 07\",\"Dec 2024 · Regular 04\",\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\",\"Feb 2026 · OLODE 02\",\"Mar 2026 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":10,\"years\":[2021,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-449\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"What is a “Stopway”\",\"opts\":[\"Can be used for T/O & landings\",\"Means an area beyond the takeoff runway, no less wide than the runway and centered upon the extended centerline of the runway\",\"It is not a portion of Runway Safety Area\"],\"ans\":1,\"exp\":\"A stopway is a rectangular area beyond the take-off run, at least as wide as the runway and centred on its extended centreline, able to support the aeroplane in an abandoned take-off.\",\"seenIn\":[\"Jan 2019\",\"Sep 2023 · Regular 03\",\"Nov 2023 · OLODE (30 Nov)\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Jun 2024 · Regular\",\"Dec 2024 · Regular 04\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":10,\"years\":[2019,2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-450\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Minimum speed on the ground is:\",\"opts\":[\"Vmcg\",\"Vmca\",\"Vmcg and Vmca\"],\"ans\":0,\"exp\":\"VMCG is the minimum control speed on the ground, using only primary aerodynamic controls with the critical engine failed.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Nov 2023 · OLODE (30 Nov)\",\"Mar 2024 · Regular 01\",\"Nov 2024 · OLODE 08\",\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":7,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-451\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"About the clearway\",\"opts\":[\"clearway is beyond the stopway\",\"clearway is beyond the runway\",\"clearway is beyond the runway whether a stopway is present or not\"],\"ans\":2,\"exp\":\"A clearway starts at the end of the take-off run available (TORA) and may overlie a stopway or not - its existence does not depend on a stopway.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Nov 2023 · OLODE (30 Nov)\",\"Mar 2024 · Regular 01\",\"Sep 2024 · Regular 03\",\"Jun 2025 · Regular 02\",\"May 2026 · OLODE 04\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":7,\"years\":[2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-452\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Maximum operating limit of Runway slope?\",\"opts\":[\"±2%\",\"±1%\",\"±1.5%\"],\"ans\":0,\"exp\":\"Take-off and landing performance data are valid for runway slopes up to +/- 2%.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Dec 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\",\"Sep 2024 · Regular 03\",\"Jan 2025 · OLODE 01\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":6,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-453\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"VEF is:\",\"opts\":[\"the speed at which the critical engine is assumed to fail during take-off\",\"the minimum unstick speed\",\"the maximum flap extended speed\",\"the speed for best rate of climb on one engine\"],\"ans\":0,\"exp\":\"VEF: critical engine failure speed, not less than VMCG; V1 is at least VEF plus the recognition time. VMU = minimum unstick speed; VFE = flaps extended limit.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Sep 2024 · Regular 03\",\"Mar 2025 · Regular 01\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":6,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-454\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The take-off climb segment that usually limits the take-off (climb-limited) mass is the:\",\"opts\":[\"first segment\",\"second segment\",\"third segment\",\"final segment\"],\"ans\":1,\"exp\":\"Second segment: gear up, take-off flap, V2, one engine out - it has the most demanding gradient (2.4 % for twins) and usually sets the climb limit.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"May 2024 · OLODE 04\",\"Aug 2024 · OLODE 06\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":6,\"years\":[2021,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-455\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"How much max length of clearway is required for takeoff?\",\"opts\":[\"As equal to Runway length\",\"Half of Runway length\",\"1/4th of Runway length\"],\"ans\":1,\"exp\":\"A clearway may not exceed half the length of the take-off run available.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Sep 2024 · Regular 03\",\"Dec 2024 · Regular 04\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-456\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"VMCG is determined so that, after a sudden failure of the critical engine, the aeroplane can be kept on the runway using primary aerodynamic controls without deviating from the centreline by more than:\",\"opts\":[\"30 ft (9 m)\",\"50 ft\",\"60 ft\",\"35 ft\"],\"ans\":0,\"exp\":\"Certification (CS/FAR 25.149): with rudder alone (no nosewheel steering), the path must stay within 30 ft (9.1 m) of the centreline.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Nov 2023 · OLODE (30 Nov)\",\"Jun 2024 · Regular\",\"Oct 2024 · OLODE 07\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-457\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"In Vmcg rudder paddle force should not exceed\",\"opts\":[\"300lbs\",\"150Lbs\",\"200lbs\"],\"ans\":1,\"exp\":\"In establishing VMCG/VMCA the rudder pedal force must not exceed 150 lb.\",\"seenIn\":[\"Mar 2022\",\"Mar 2024 · Regular 01\",\"Dec 2024 · Regular 04\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-458\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"T/o obstacle clearance?\",\"opts\":[\"400ft\",\"35ft\",\"50ft\"],\"ans\":1,\"exp\":\"The take-off flight path must clear obstacles with a margin of at least 35 ft.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":4,\"years\":[2021,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-459\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"A balanced field exists if\",\"opts\":[\"the same distance is required to accelerate to V1 and stop\",\"ASDA = TODA\"],\"ans\":1,\"exp\":\"A balanced field is one where the accelerate-stop distance available equals the take-off distance available (ASDA = TODA).\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Aug 2023 · OLODE\",\"Dec 2023 · Regular\"],\"undated\":false,\"times\":3,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-460\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"What is the minimum control speed with critical engine out (in takeoff configuration ) with critical engine out\",\"opts\":[\"Vmca\",\"Vmb\",\"Vmca and Vmcg\"],\"ans\":0,\"exp\":\"The minimum control speed in the air with the critical engine out in the take-off configuration is VMCA.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Oct 2023 · OLODE\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":3,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-461\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"TODA (take-off distance available) is:\",\"opts\":[\"TORA + stopway\",\"TORA + clearway\",\"TORA + stopway + clearway\",\"the same as TORA\"],\"ans\":1,\"exp\":\"TODA = runway available for the take-off run plus any clearway; ASDA = TORA + stopway.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Aug 2024 · OLODE 06\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-462\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The worst (highest) VMCA occurs with the CG at the:\",\"opts\":[\"forward limit\",\"aft limit\",\"mid position\",\"it does not affect VMCA\"],\"ans\":1,\"exp\":\"With an aft CG the rudder's moment arm about the CG is shortest, so more speed is needed for the rudder to balance the asymmetric thrust: VMCA is highest.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\",\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-463\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Density altitude increase .\",\"opts\":[\"Engine performance increase\",\"Takeoff performance increase\",\"Performance reduces\"],\"ans\":2,\"exp\":\"A higher density altitude means thinner air: engine thrust and lift fall, take-off and climb performance reduce.\",\"seenIn\":[\"Jul 2024 · OLODE 05\",\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-464\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Minimum speed in the air is:\",\"opts\":[\"Vmca\",\"V2\",\"Vmcg and Vmca\"],\"ans\":0,\"exp\":\"VMCA is the minimum control speed in the air; VMCG is on the ground.\",\"seenIn\":[\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-465\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Worst performance is when:\",\"opts\":[\"High humidity, high temperature\",\"Low temperature, low humidity\",\"Low temperature, high humidity\"],\"ans\":0,\"exp\":\"High temperature and high humidity both reduce air density and performance.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-466\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"During engine failure at VMCA\",\"opts\":[\"maintain heading with 5 deg bank\",\"full opposite rudder\",\"both a and b\"],\"ans\":2,\"exp\":\"VMCA is established with full opposite rudder and the aeroplane banked not more than 5 deg towards the live engine, holding heading.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-467\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The take-off safety speed V2 must not be less than:\",\"opts\":[\"VMCG\",\"1.1 VMCA (and 1.13 VSR)\",\"1.05 VMCA only\",\"VMBE\"],\"ans\":1,\"exp\":\"V2 min = the greater of 1.1 x VMCA and 1.13 x VSR (1.2 VS in older rules); VR must be at least 1.05 VMCA.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":2,\"years\":[2021,2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-468\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"For a grass runway, the landing distance required for a paved runway should be increased by 15%\",\"opts\":[\"true\",\"false\",\"not increased, not decreased\"],\"ans\":0,\"exp\":\"For a grass or unpaved runway the landing distance required for a paved runway is increased by 15%.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2022,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-469\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Choose appropriate option regarding stopway\",\"opts\":[\"Centerline of runway need to be aligned with stopway\",\"Center line of stopway is offset to 50ft\",\"Centerline of runway need not to be aligned with stopway\"],\"ans\":0,\"exp\":\"A stopway lies on the extended centreline of the runway and is at least as wide as the runway.\",\"seenIn\":[\"Jul 2024 · OLODE 05\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-470\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The take-off speed that includes the pilot's recognition of, and reaction to, an engine failure is:\",\"opts\":[\"VEF\",\"V1\",\"VR\",\"V2\"],\"ans\":1,\"exp\":\"V1 is not less than VEF plus the speed gained while the pilot recognises the failure and takes the first action to stop.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-471\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"On the ASI of a light twin, the blue radial line marks:\",\"opts\":[\"VMCA\",\"VYSE - best rate of climb with one engine inoperative\",\"VXSE - best angle with one engine out\",\"VFE\"],\"ans\":1,\"exp\":\"Blue line = VYSE; red radial line = VMCA. VXSE (best angle, one engine out) is not normally marked.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-472\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"An increase in atmospheric pressure has, among other things, the following consequences on take-off performance:\",\"opts\":[\"a reduced take-off distance and degraded initial climb performance\",\"a reduced take-off distance and improved initial climb performance\",\"an increased take-off distance and degraded initial climb performance\"],\"ans\":1,\"exp\":\"Higher pressure means denser air: more thrust and lift, so a shorter take-off distance and a better initial climb.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-473\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The climb angle (climb gradient) of an aeroplane is given by:\",\"opts\":[\"(Thrust - Drag) / Weight\",\"(Lift - Weight) / Drag\",\"Rate of climb / Weight\",\"(Power available - Power required) / Weight\"],\"ans\":0,\"exp\":\"Climb gradient (sin of the climb angle) = excess THRUST / weight. Excess POWER / weight gives the rate of climb, not the angle.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-474\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The correct ascending order of these take-off speeds is:\",\"opts\":[\"VMCG, V1, VR, V2\",\"V1, VMCG, V2, VR\",\"VR, V1, V2, VMCG\",\"V2, VR, V1, VMCG\"],\"ans\":0,\"exp\":\"VMCG <= VEF < V1 <= VR < V2 (V2 >= 1.1 VMCA). V1 can equal VR but never exceeds it.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-475\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The absolute ceiling of an aeroplane is the altitude at which:\",\"opts\":[\"the rate of climb is 100 ft/min\",\"the maximum rate of climb becomes zero\",\"the cabin pressure differential is maximum\",\"Vx equals Vy\"],\"ans\":1,\"exp\":\"Absolute ceiling: no excess power, rate of climb zero (Vx = Vy there). Service ceiling: 100 ft/min (piston) or 500 ft/min (jet) remaining.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-476\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Adding a stopway to a runway allows:\",\"opts\":[\"a lower V1\",\"a higher V1, because the accelerate-stop distance available is longer\",\"a shorter TODA\",\"no change\"],\"ans\":1,\"exp\":\"With more ASDA the aircraft can reject from a higher speed and still stop, so V1 (limited by ASDA) can be raised.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-477\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Approaching to land at a high aerodrome (elevation 7500 ft), the pilot should fly:\",\"opts\":[\"the same IAS as at sea level (TAS and groundspeed will be higher)\",\"a higher IAS\",\"a lower IAS\",\"the same TAS as at sea level\"],\"ans\":0,\"exp\":\"The wing stalls at the same IAS whatever the altitude, so use the normal approach IAS. Thinner air makes the TAS and groundspeed higher, so the landing roll is longer.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-478\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"To increase the angle of climb at a given weight you must increase the:\",\"opts\":[\"weight\",\"excess thrust (thrust - drag)\",\"lift only\",\"altitude\"],\"ans\":1,\"exp\":\"Climb gradient = (T - D)/W: more thrust or less drag (or less weight) steepens the climb.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-479\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"VXSE is:\",\"opts\":[\"the best angle of climb speed with one engine inoperative\",\"the best rate of climb speed with one engine inoperative\",\"the minimum control speed\",\"the maximum speed with flaps extended\"],\"ans\":0,\"exp\":\"VXSE = best angle (gradient) on one engine; VYSE = best rate on one engine (blue line).\",\"seenIn\":[\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-480\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"A non-ETOPS twin-engine Class A aeroplane with 20 or more passenger seats (or a large MTOM) must stay within ...... of an adequate aerodrome at the one-engine-inoperative cruise speed:\",\"opts\":[\"180 minutes\",\"90 minutes\",\"60 minutes\",\"120 minutes\"],\"ans\":2,\"exp\":\"The 60-minute rule (OEI cruise speed, still air, ISA). Beyond it the operation needs ETOPS/EDTO approval. Smaller aeroplanes may use 120 (or 180) minutes.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-481\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"At which minimum height will the second climb segment end?\",\"opts\":[\"1500ft above field elevation\",\"35ft above ground\",\"400ft above field elevation\"],\"ans\":2,\"exp\":\"The correct answer is: 400ft above field elevation.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-482\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The speed at which the aircraft can be controlled on the ground using primary control surfaces at critical engine failure\",\"opts\":[\"Vmcg\",\"Vmca\"],\"ans\":0,\"exp\":\"VMCG is the minimum control speed on the ground using primary controls only.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-483\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Compared with a dry runway, the landing distance required on a wet runway is increased by:\",\"opts\":[\"10 %\",\"15 %\",\"25 %\",\"43 %\"],\"ans\":1,\"exp\":\"The landing distance required on a wet runway is the dry-runway landing distance required plus 15 % (x 1.15); the dry figure itself is the demonstrated distance divided by 0.6 (jets) or 0.7 (turboprops).\",\"seenIn\":[\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-484\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"For a nose-wheel (tricycle) aeroplane, a higher take-off mass gives:\",\"opts\":[\"a lower rotation speed and shorter take-off distance\",\"a higher rotation speed and a longer take-off distance\",\"no change in take-off speeds\",\"a shorter ground run\"],\"ans\":1,\"exp\":\"More mass needs more lift: higher VR/V2 and longer ground run and distance; climb gradient falls too.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-485\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Block fuel 40,000 kg, trip fuel 29,000 kg, taxi 800 kg, MTOM 170,000 kg, MLM 148,500 kg, MZFM 112,500 kg, DOM 80,400 kg. The maximum traffic load is:\",\"opts\":[\"40,400 kg\",\"32,900 kg\",\"18,900 kg\",\"32,100 kg\"],\"ans\":3,\"exp\":\"Take-off fuel 39,200, landing fuel 10,200. Limits: MZFM 112,500 - 80,400 = 32,100; MTOM 170,000 - 39,200 - 80,400 = 50,400; MLM 148,500 - 10,200 - 80,400 = 57,900. The lowest, 32,100 kg, governs.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-486\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The speed Vlo is defined as\",\"opts\":[\"landing gear operating speed\",\"long distance operating speed\",\"lift off speed\"],\"ans\":0,\"exp\":\"VLO is the maximum landing gear operating speed.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-487\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"if A/c is overloaded then\",\"opts\":[\"take off distance increases climb performance increases\",\"take off distance decreases climb performance increase\",\"take off distance increases climb performance decreases\"],\"ans\":2,\"exp\":\"Overloading lengthens the take-off run and reduces climb performance.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-488\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Before V1, a take-off should be rejected if the aircraft is:\",\"opts\":[\"unable to fly\",\"unsafe to fly\",\"either unable or unsafe to fly\",\"still below VR\"],\"ans\":2,\"exp\":\"V1 is the last point to start stopping. Below it, abort for any failure that makes flight impossible or unsafe; above it, continue.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-489\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"VNO is:\",\"opts\":[\"the never-exceed speed\",\"the maximum structural cruising speed (top of the green arc)\",\"the flap limit\",\"the stall speed\"],\"ans\":1,\"exp\":\"VNO marks the end of the normal operating range; above it (yellow arc) fly only in smooth air. VNE is the red line.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-490\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The primary input to a basic stall warning system is:\",\"opts\":[\"angle of attack\",\"IAS\",\"flap position\",\"Mach number\"],\"ans\":0,\"exp\":\"A wing stalls at its critical angle of attack, so the vane/sensor measures AoA. Flap position adjusts the threshold.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-491\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Vx is the speed for:\",\"opts\":[\"best rate of climb\",\"best angle of climb (greatest height gain per distance)\",\"maximum range\",\"minimum drag\"],\"ans\":1,\"exp\":\"Vx = best angle (obstacle clearance); Vy = best rate (height per time). Vx is lower than Vy.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-492\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"An aircraft climbing at Vx lets its speed fall below Vx. The climb gradient and rate of climb will:\",\"opts\":[\"both increase\",\"both decrease\",\"gradient increase, rate decrease\",\"gradient decrease, rate increase\"],\"ans\":1,\"exp\":\"Vx already gives the maximum gradient and is below Vy, so any further speed loss reduces both the angle and the rate of climb.\",\"seenIn\":[\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-493\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The first segment of the take-off climb ends when:\",\"opts\":[\"the aircraft reaches 35 ft\",\"the landing gear is fully retracted\",\"the aircraft reaches 400 ft\",\"flaps are fully retracted\"],\"ans\":1,\"exp\":\"Segment 1: from 35 ft (end of TOD) to gear up. Segment 2: to at least 400 ft. Segment 3: acceleration/flap retraction. Final: to 1500 ft.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-494\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"If the take-off mass increases, the angle of climb, take-off distance and landing distance will:\",\"opts\":[\"increase, increase, increase\",\"decrease, increase, increase\",\"decrease, decrease, increase\",\"increase, decrease, decrease\"],\"ans\":1,\"exp\":\"Heavier: less excess thrust per kg (lower climb angle) and higher speeds with more energy to accelerate and to stop.\",\"seenIn\":[\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-495\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The area beyond the runway over which the aeroplane may make part of its initial climb to 35 ft is the:\",\"opts\":[\"stopway\",\"clearway\",\"runway strip\",\"RESA\"],\"ans\":1,\"exp\":\"Clearway = airborne part (up to half the TORA long); stopway = for stopping in an abandoned take-off.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-496\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Regarding take-off, the take-off decision speed V1:\",\"opts\":[\"is the airspeed on the ground at which the pilot is assumed to have made a decision to continue or discontinue the take-off\",\"is an airspeed at which the aero plane is airborne but below 35ft and the pilot is assumed to have made a decision to continue or discontinue the take-off\",\"is the airspeed of the aero plane upon reaching 35ft above the take-off surface\"],\"ans\":0,\"exp\":\"V1 is the speed on the ground at which the pilot is assumed to have decided to continue or stop the take-off.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-497\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The gross take-off distance required for a single-engine aeroplane is the distance from the start of the runway to the screen height of 50 ft\",\"opts\":[\"true\",\"false\",\"up to screen height 35 ft\"],\"ans\":0,\"exp\":\"For a single-engine aeroplane the take-off distance is measured to a screen height of 50 ft.\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-498\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"A clearway must be at least ...... wide:\",\"opts\":[\"the runway width\",\"150 m (75 m each side of the extended centreline)\",\"60 m\",\"300 m\"],\"ans\":1,\"exp\":\"ICAO Annex 14: a clearway extends laterally at least 75 m each side of the extended runway centreline (150 m total). The stopway only needs to be as wide as the runway.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Feb 2024 · OLODE 02\",\"Oct 2024 · OLODE 07\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2021,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-499\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"An increase in aeroplane mass (same power/thrust):\",\"opts\":[\"increases both the rate and angle of climb\",\"reduces both the rate and the angle of climb\",\"reduces the rate but not the angle\",\"has no effect on climb\"],\"ans\":1,\"exp\":\"Climb gradient = (T - D)/W and rate of climb = excess power / W: more weight (and more induced drag) reduces both.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Aug 2024 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-500\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The lift coefficient of a wing is increased by:\",\"opts\":[\"reducing the angle of attack\",\"increasing the angle of attack (up to the stall) or extending flaps\",\"reducing camber\",\"reducing speed only\"],\"ans\":1,\"exp\":\"CL rises with angle of attack up to CLmax at the critical angle; flaps (more camber/area) raise CLmax.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-501\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Compared with ISA, a positive ISA deviation (warmer air) at a given pressure altitude:\",\"opts\":[\"improves take-off and climb performance\",\"raises the density altitude and degrades take-off and climb performance\",\"has no effect on performance\",\"lowers the density altitude\"],\"ans\":1,\"exp\":\"Warmer air is less dense: density altitude rises about 120 ft per deg C above ISA, engines and wings produce less, so take-off distance grows and climb gradient falls.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-502\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"High humidity affects aeroplane performance because humid air:\",\"opts\":[\"is denser, so performance improves\",\"is less dense, so take-off and climb performance are reduced\",\"has no effect\",\"cools the engine and improves thrust\"],\"ans\":1,\"exp\":\"Water vapour is lighter than dry air, so humid air is less dense: a higher density altitude, less lift and thrust.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-503\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"Rotating the aircraft early (below VR) is likely to:\",\"opts\":[\"shorten the take-off distance\",\"increase drag, and may increase the take-off distance and risk a tail strike\",\"have no effect\",\"reduce V2\"],\"ans\":1,\"exp\":\"Early, over-pitched rotation raises drag (and the aircraft cannot fly before VMU), lengthening the take-off and risking a tail strike or a low-speed climb.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-504\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The take-off obstacle accountability area (domain) for a large aeroplane starts with a semi-width of about ...... at the end of the TODA and widens to a maximum of ......:\",\"opts\":[\"90 m (60 m + half wingspan); 600 m (900 m if track changes)\",\"45 m; 300 m\",\"150 m; 1500 m\",\"60 m; 6000 m\"],\"ans\":0,\"exp\":\"The correct answer is: 90 m (60 m + half wingspan); 600 m (900 m if track changes).\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-505\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"An increase in pressure altitude (aerodrome higher, or lower pressure) causes:\",\"opts\":[\"a shorter take-off distance and a better climb gradient\",\"a longer take-off distance and a lower climb gradient\",\"no change in take-off performance\",\"a longer take-off distance but a better climb gradient\"],\"ans\":1,\"exp\":\"Higher pressure altitude = thinner air: less thrust and lift for a given TAS, a higher TAS for the same IAS - longer take-off run, poorer climb.\",\"seenIn\":[\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-506\",\"topic\":\"Performance & V-Speeds\",\"stem\":\"The stalling angle of attack of a wing in a given configuration:\",\"opts\":[\"increases with weight\",\"is constant - it does not change with weight, speed or altitude\",\"decreases with altitude\",\"depends on the IAS\"],\"ans\":1,\"exp\":\"The wing always stalls at its critical angle of attack (about 15-16 deg clean); weight, bank and altitude change the SPEED at which that angle is reached, not the angle. Flaps and ice change it.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-507\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"If the static source of an altimeter becomes blocked during a descent, the instrument will:\",\"opts\":[\"under-read\",\"gradually indicate zero\",\"continue to show the reading at which the blockage occurred\",\"over-read and then fall\"],\"ans\":2,\"exp\":\"The altimeter measures static pressure only. With the source blocked, the pressure in the case stays as it was, so the reading freezes - in a climb or a descent.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Aug 2023 · OLODE\",\"Jul 2024 · OLODE 05\",\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\",\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":8,\"years\":[2021,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-508\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"An aircraft at FL75 takes off from an aerodrome with elevation 1500 ft, QNH at the aerodrome 1023.25. What is the true vertical distance?\",\"opts\":[\"6300 ft\",\"6000 ft\",\"5700 ft\"],\"ans\":0,\"exp\":\"FL75 is 7500 ft on 1013.25. QNH 1023.25 is 10 hPa higher = 300 ft at 30 ft/hPa, so true altitude is 7800 ft; less 1500 ft aerodrome elevation = 6300 ft.\",\"seenIn\":[\"Mar 2022\",\"Jun 2023 · Regular\",\"Dec 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\",\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":7,\"years\":[2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-509\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"Aerodrome A: QNH 1000 hPa, elevation 240 ft. Aerodrome B: QFE 1000 hPa, elevation 240 ft. Taking 30 ft per hPa, what is the QNH at B and how does the pressure change from A to B?\",\"opts\":[\"1008 hPa, increasing by 8 hPa\",\"992 hPa, decreasing by 8 hPa\",\"1000 hPa, no change\",\"1004 hPa, increasing by 4 hPa\"],\"ans\":0,\"exp\":\"The correct answer is: 1008 hPa, increasing by 8 hPa.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\",\"Jun 2025 · Regular 02\",\"Aug 2025 · OLODE 06\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":6,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-510\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"The single most significant item which makes a servo altimeter more accurate is\",\"opts\":[\"electromagnetic pick-off\",\"logarithmic scale\",\"temperature compensated spring\"],\"ans\":0,\"exp\":\"A servo altimeter is more accurate mainly because of its electromagnetic (induction) pick-off.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"May 2022\",\"Sep 2022 · FC 03\",\"Jun 2023 · Regular\",\"Jul 2023 · OLODE\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":6,\"years\":[2021,2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-511\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"How many feet do you have to climb to reach FL75? Departure aerodrome elevation = 1500 ft, QNH = 1023 hPa, temperature = ISA, 1 hPa = 30 ft\",\"opts\":[\"6000 ft\",\"6600 ft\",\"6300 ft\"],\"ans\":2,\"exp\":\"Aerodrome pressure altitude = 1500 + (1013 - 1023) x 30 = 1200 ft. To reach FL75 (7500 ft) it must climb 7500 - 1200 = 6300 ft.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2023 · Regular\",\"Nov 2023 · OLODE (30 Nov)\",\"Mar 2024 · Regular 01\",\"Aug 2024 · OLODE 06\",\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":6,\"years\":[2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-512\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"An aircraft has two altimeters; one is corrected for position error, the other is not. All other errors being zero:\",\"opts\":[\"ATC will receive wrong flight level information\",\"at high speed the non-compensated altimeter shows a lower altitude\",\"there will be no error in either\",\"at high speed the non-compensated altimeter shows a higher altitude\"],\"ans\":3,\"exp\":\"Position error grows with speed and usually makes the static source sense a lower pressure than ambient, so the uncorrected altimeter over-reads (shows higher) at high speed. Mode C reporting comes from the corrected (ADC) source.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2023 · Regular\",\"Feb 2024 · OLODE 02\",\"Apr 2025 · OLODE 03\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":5,\"years\":[2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-513\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"When flying from a sector of warm air into one of colder air, the altimeter will?\",\"opts\":[\"Over read\",\"Be just as correct as before.\",\"Show the actual height above ground.\"],\"ans\":0,\"exp\":\"Cold air is denser, so pressure drops faster with height: the altimeter, calibrated for ISA, over-reads in colder air (when flying from warm to cold, from high to low).\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jul 2023 · OLODE\",\"Mar 2024 · Regular 01\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":5,\"years\":[2021,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-514\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"The QNH at an aerodrome rises from 1013 hPa to 1022 hPa. Which is true?\",\"opts\":[\"the aerodrome elevation is unchanged; its pressure altitude falls by about 270 ft\",\"the aerodrome elevation increases by 270 ft\",\"the aerodrome pressure altitude increases by 270 ft\",\"nothing changes at all\"],\"ans\":0,\"exp\":\"Elevation is a fixed height above sea level. Higher pressure means the 1013 hPa level lies lower, so the aerodrome's pressure altitude drops by 9 x 30 = 270 ft; an altimeter left on 1013 would read 270 ft less.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"May 2024 · OLODE 04\",\"Mar 2025 · Regular 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-515\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"The altimeter consists of one or several aneroid capsules located in a sealed casing. The pressures in the aneroid capsule (i) and casing (ii) are respectively\",\"opts\":[\"(i) vacuum (or a very low pressure), (ii) static pressure\",\"(i) total pressure, (ii) static pressure\",\"(i) static pressure, (ii) total pressure\"],\"ans\":0,\"exp\":\"The capsule is evacuated (a very low pressure); static pressure surrounds it in the sealed case.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Dec 2023 · Regular\",\"May 2026 · OLODE 04\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-516\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"What is density altitude?\",\"opts\":[\"altitude in the standard atmosphere at which the prevailing density is equal to the density in the standard atmosphere\",\"pressure altitude corrected for prevailing temperature\",\"temperature altitude\"],\"ans\":0,\"exp\":\"Density altitude is defined as the altitude in the standard atmosphere at which the prevailing density occurs. Pressure altitude corrected for temperature is the practical way to work it out, but the definition asked for is (a).\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2024 · Regular\",\"Sep 2024 · Regular 03\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":4,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-517\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"Which combination gives the highest density altitude?\",\"opts\":[\"high elevation, low temperature, low humidity\",\"low elevation, high temperature, high humidity\",\"high elevation, high temperature, high humidity\",\"sea level, ISA, dry air\"],\"ans\":2,\"exp\":\"Density altitude rises with height (low pressure), heat and humidity (water vapour is lighter than dry air). \\\"Hot, high and humid\\\" is the worst for performance.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Nov 2023 · OLODE (30 Nov)\",\"Jul 2024 · OLODE 05\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2021,2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true,\"note\":\"Our independent check found that more than one option can be argued for, as worded in the recall. The key gives the answer most references support.\"},{\"id\":\"CPLNAV-518\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"An altitude alerting system warns the crew:\",\"opts\":[\"only when the selected altitude is reached\",\"when approaching the selected altitude and when deviating from it after capture\",\"only below the minimum safe altitude\",\"only when the altimeter subscale is wrong\"],\"ans\":1,\"exp\":\"It gives an alert as the aircraft approaches the selected altitude (typically about 1000 ft before) and again if it then departs from it (typically by more than 200-300 ft).\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Dec 2023 · Regular\",\"May 2024 · OLODE 04\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":4,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-519\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"What will happen to the Indicated Altitude if an aircraft in level flight enters a warmer air mass?\",\"opts\":[\"Over indicate\",\"Under indicate\",\"Not change\"],\"ans\":1,\"exp\":\"Warmer air is less dense per height, so true altitude is higher than indicated: the altimeter under-indicates.\",\"seenIn\":[\"Mar 2023 · ATPL\",\"Aug 2023 · OLODE\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-520\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"When the OAT decreases rapidly during descent, what will happen to the true altitude compared to the indicated altitude?\",\"opts\":[\"True altitude is higher\",\"True altitude is lower\",\"No difference\"],\"ans\":1,\"exp\":\"Colder air makes the true altitude lower than the indicated altitude.\",\"seenIn\":[\"Mar 2025 · Regular 01\",\"Jul 2025 · OLODE 05\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-521\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"With the aircraft on the runway, which setting makes the altimeter read the aerodrome ELEVATION?\",\"opts\":[\"QFE\",\"QNH\",\"QNE (1013.25)\",\"QFF\"],\"ans\":1,\"exp\":\"QNH -> altitude above mean sea level (reads elevation on the ground). QFE -> height above the aerodrome (reads zero). 1013.25 (standard) -> pressure altitude / flight level; QNE is the reading on 1013.25 at the aerodrome.\",\"seenIn\":[\"Jun 2025 · Regular 02\",\"Jul 2025 · OLODE 05\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-522\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"The hysteresis error of an altimeter varies with:\",\"opts\":[\"Aircraft altitude\",\"Time at given altitude\",\"Mach number\"],\"ans\":1,\"exp\":\"Altimeter hysteresis (the capsule slowly relaxing after a height change) depends on how long the altimeter has been at that altitude, not on Mach number.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-523\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"An aircraft is flying at an indicated altitude of 16000 ft. the outside air temperature is -30°C. What is the true altitude?\",\"opts\":[\"14200\",\"15200\",\"18600\"],\"ans\":1,\"exp\":\"ISA at 16,000 ft is -17 C; at -30 C it is 13 C colder, so true altitude is lower than indicated by about 4 ft x 13 x 16 = 830 ft: about 15,200 ft.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Aug 2023 · OLODE\",\"Dec 2023 · Regular\"],\"undated\":false,\"times\":3,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-524\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"Pressure altitude 5000 ft, OAT +35 C. The true altitude is about:\",\"opts\":[\"4550 ft\",\"5550 ft\",\"4290 ft\",\"5320 ft\"],\"ans\":1,\"exp\":\"ISA at 5000 ft is +5 C, so the air is ISA + 30: warm air expands, so you are higher than indicated - roughly 4 % per 10 C: 5000 x 308/278 = about 5540 ft.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-525\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"If field elevation is 3500 ft amsl and QFE is 1020 mb, what is the pressure altitude?\",\"opts\":[\"-210\",\"3710\",\"3290\"],\"ans\":0,\"exp\":\"Pressure altitude of the aerodrome = (1013 - QFE) x 30 = (1013 - 1020) x 30 = about -210 ft; the elevation does not enter.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Sep 2023 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-526\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"What will happen to the Altimeter reading if the aircraft flies from high pressure area to low pressure area without correcting the altimeter setting?\",\"opts\":[\"It will read higher than actual altitude\",\"It will read lower than actual altitude\",\"It will remain the same\"],\"ans\":0,\"exp\":\"Flying from high to low pressure without resetting, the altimeter over-reads: it shows higher than the true altitude.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-527\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"Pressure altitude 29,000 ft, SAT -55 C. The density altitude is about:\",\"opts\":[\"27,500 ft\",\"26,000 ft\",\"30,000 ft\",\"31,000 ft\"],\"ans\":0,\"exp\":\"ISA at 29,000 ft = 15 - 58 = -43 C, so ISA -12. Density altitude = 29,000 - 12 x 120 = 27,560, about 27,500 ft.\",\"seenIn\":[\"Mar 2022\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2022,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-528\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"The error in altimeter readings caused by the variation of the static pressure near the source is known as:\",\"opts\":[\"position pressure error\",\"barometric error\",\"hysteresis effect\"],\"ans\":0,\"exp\":\"Error from varying static pressure at the static source is position (pressure) error.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-529\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"What is true altitude of an aircraft if the altimeter indicate 10000ft when the ambient temperature is 0° C?\",\"opts\":[\"9800\",\"10000\",\"10200\"],\"ans\":2,\"exp\":\"ISA at 10,000 ft is -5 C; 0 C is ISA +5, so the air is warmer and true altitude is higher: about +4 ft x 5 x 10 = +200 ft.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-530\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"An aircraft climbs from 4000 ft to 16,000 ft pressure altitude at 500 ft/min, holding 130 kt RAS; temperature about ISA - 5. In nil wind, the time and distance for the climb are about:\",\"opts\":[\"24 min / 80 NM\",\"24 min / 60 NM\",\"40 min / 103 NM\",\"30 min / 65 NM\"],\"ans\":1,\"exp\":\"Time = 12,000 / 500 = 24 min. Mean TAS at the mid level (10,000 ft, ISA - 5) is about 150 kt: 150 x 24/60 = 60 NM.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-531\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"With 1013.25 hPa set on the subscale, the altimeter indicates:\",\"opts\":[\"density altitude\",\"pressure altitude\",\"true altitude\",\"height above the aerodrome\"],\"ans\":1,\"exp\":\"Pressure altitude is the reading on the standard setting; flight levels are pressure altitude in hundreds of feet.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Dec 2023 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-532\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"At sea level, the tolerance of a typical servo-assisted altimeter is about:\",\"opts\":[\"+/- 30 ft\",\"+/- 75 ft\",\"+/- 60 ft\",\"+/- 100 ft\"],\"ans\":0,\"exp\":\"Typical tolerances at sea level: simple altimeter about 100 ft, sensitive about 70 ft, servo about 30 ft.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-533\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"The only input a pressure altimeter uses is:\",\"opts\":[\"pitot pressure\",\"static pressure\",\"dynamic pressure\",\"a radio signal reflected from the ground\"],\"ans\":1,\"exp\":\"The altimeter compares static pressure with the ISA pressure-height law - it never measures distance to the ground; that is the radio altimeter.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-534\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"The purpose of the vibrating device in an altimeter is to:\",\"opts\":[\"Allow damping of the measurement in the unit\",\"Reduce the hysteresis effect\",\"Reduce the effect of friction in the linkages\"],\"ans\":2,\"exp\":\"The vibrator overcomes friction (stiction) in the linkage so the pointer does not stick.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-535\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"Servo altimeters are more\",\"opts\":[\"Accurate, electric pick off coil\",\"Accurate, aneroid capsule\",\"Inaccurate, electric pick off coil because of\"],\"ans\":0,\"exp\":\"A servo altimeter is more accurate because an electrical pick-off (induction) coil replaces mechanical linkage.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-536\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"If QNH is 999 hPa, what is the pressure altitude at an elevation of 25000 ft?\",\"opts\":[\"25400 ft\",\"25200 ft\",\"25300 ft\"],\"ans\":0,\"exp\":\"Pressure altitude = elevation + (1013 - QNH) x 30 = 25,000 + 14 x 30 = 25,420 ft, about 25,400 ft.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-537\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"In a barometric altimeter ______ is fed into the capsule and ______ is fed into the case\",\"opts\":[\"static pressure / dynamic pressure\",\"vacuum / static pressure\",\"dynamic pressure / vacuum\"],\"ans\":1,\"exp\":\"The capsule is evacuated and the case receives static pressure.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-538\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"At A where QNH is 1000 hPa, flying directly to B where QNH is less than A (QNH at B is 960 hPa), the altimeter setting remains unchanged. What will the altimeter read after reaching B?\",\"opts\":[\"1200 ft lower\",\"1200 ft higher\"],\"ans\":1,\"exp\":\"Flying from high pressure to low pressure with the setting unchanged, the altimeter over-reads: 40 hPa x 30 ft = 1,200 ft higher than the true altitude.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-539\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"An aircraft takes off from the aerodrome of Nanded (altitude 1 483 FT, QFE = 963 hPa, temperature = 32°C). Five minutes later, passing 5 000 FT on QFE, the Second altimeter set on 1 013 hPa will indicate approximately:\",\"opts\":[\"6800FT\",\"6400FT\",\"6000FT\",\"4000 FT\"],\"ans\":1,\"exp\":\"QFE 963 means the aerodrome is at 963 hPa; on 1013 that is about 50 hPa x 27 ft = 1,350-1,500 ft. Add 5,000 ft: about 6,400 ft.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-540\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"The pressure altimeter is calibrated in accordance with\",\"opts\":[\"the environmental lapse rate of temperature\",\"the jet standard atmosphere\",\"The International Standard Atmosphere.\",\"The Density altitude\"],\"ans\":2,\"exp\":\"Pressure altimeters are calibrated to the International Standard Atmosphere.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-541\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"An aircraft climbs away from the runway with static vents still sealed. If set to QFE, the altimeter will\",\"opts\":[\"to indicate zero feet\",\"Indicate correctly increasing altitude as the aircraft climbs\",\"Show a slower gain of altitude than correct\",\"Will indicate QNH for some time.\"],\"ans\":0,\"exp\":\"With the static vents sealed the pressure is trapped at the ground value, so with QFE set the altimeter stays at zero as the aircraft climbs.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-542\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"Pressure altitude 0 ft, temperature ISA - 5 C. The density altitude is about:\",\"opts\":[\"-600 ft\",\"+600 ft\",\"0 ft\",\"-120 ft\"],\"ans\":0,\"exp\":\"Density altitude = pressure altitude + 120 ft per degree of ISA deviation: 0 + 120 x (-5) = -600 ft. Cold air is dense - the aircraft performs as if below sea level.\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-543\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"Terrain elevation 10,600 ft, required obstacle clearance 1500 ft, QNH 1023 hPa. The minimum flight level is:\",\"opts\":[\"FL110\",\"FL115\",\"FL120\",\"FL130\"],\"ans\":2,\"exp\":\"Minimum altitude = 10,600 + 1,500 = 12,100 ft. QNH is 10 hPa above standard, so the 1013 datum lies about 300 ft higher: pressure altitude = 12,100 - 300 = 11,800 ft. The lowest flight level not below that is FL120. (Forgetting the QNH correction gives FL130 or FL110.)\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-544\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"Aneroid capsule in altimeter senses\",\"opts\":[\"Static pressure\",\"Pitot and static pressure\",\"Dynamic pressure\"],\"ans\":0,\"exp\":\"The aneroid capsule is evacuated and senses the static pressure of the surrounding case; it expands as static pressure falls.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-545\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"Aerodrome elevation 4000 ft, QNH 990 hPa. Using 30 ft per hPa, the pressure altitude of the aerodrome is:\",\"opts\":[\"4690 ft\",\"3310 ft\",\"4000 ft\",\"4230 ft\"],\"ans\":0,\"exp\":\"(1013 - 990) x 30 = 690 ft. Pressure below standard, so add: PA = 4000 + 690 = 4690 ft.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-546\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"True altitude 5500 ft, QNH 995 hPa, SAT +30 C. The density altitude is about:\",\"opts\":[\"7080 ft\",\"8120 ft\",\"9280 ft\",\"9930 ft\"],\"ans\":2,\"exp\":\"PA = 5500 + (1013 - 995) x 27 = about 5990 ft. ISA there = 15 - 12 = +3 C, so ISA + 27. DA = 5990 + 27 x 120 = about 9230 ft.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-547\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"An aircraft has a static vent on each side of the fuselage; the LEFT one is blocked. In a sideslip to the RIGHT the altimeter will:\",\"opts\":[\"under-read\",\"over-read\",\"read correctly\",\"freeze\"],\"ans\":0,\"exp\":\"In a right sideslip the air strikes the right side, raising the pressure at the right vent. With the left (low-pressure) vent blocked the two can no longer average out, the system senses too high a pressure, and the altimeter reads too LOW.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-548\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"The errors of a pressure altimeter are:\",\"opts\":[\"instrument, position, manoeuvre-induced, density, temperature, lag\",\"instrument, pressure, manoeuvre-induced, density, temperature, lag\",\"instrument, position, manoeuvre-induced, temperature, barometric, lag\",\"instrument, pressure, lag, barometric, temperature, compressibility\"],\"ans\":2,\"exp\":\"Altimeter: instrument, position (pressure), manoeuvre-induced, temperature, barometric (wrong datum) and time lag. Density and compressibility errors belong to the ASI.\",\"seenIn\":[\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-549\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"At an aerodrome the QFE increases from 1012 hPa to 1033 hPa. Then:\",\"opts\":[\"the QNH increases\",\"the QNH decreases\",\"the field elevation increases\",\"the QNH is unchanged\"],\"ans\":0,\"exp\":\"QNH is the field pressure reduced to sea level with a fixed correction for elevation: if QFE rises by 21 hPa, QNH rises by the same 21 hPa. Elevation never changes.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-550\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"The vibrator fitted to some altimeters overcomes:\",\"opts\":[\"static (starting) friction in the mechanism\",\"lag in the static line\",\"temperature error\",\"position error\"],\"ans\":0,\"exp\":\"Small pressure changes may not overcome the friction of the linkage (stiction); a vibrator keeps the mechanism moving so it responds smoothly.\",\"seenIn\":[\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-551\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"Airfield elevation 1000 ft, QNH 988 hPa. Using 27 ft per hPa, the pressure altitude is:\",\"opts\":[\"675 ft\",\"325 ft\",\"1675 ft\",\"825 ft\"],\"ans\":2,\"exp\":\"Lower pressure than standard means the 1013 level is below sea level: PA = 1000 + (1013 - 988) x 27 = 1000 + 675 = 1675 ft.\",\"seenIn\":[\"Aug 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-552\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"Aerodrome A: QFE 1000 hPa, elevation 240 ft. Aerodrome B: QNH 1000 hPa, elevation 240 ft. Taking 30 ft per hPa, the sea-level pressure from A to B:\",\"opts\":[\"increases by 8 hPa\",\"decreases by 8 hPa\",\"increases by 4 hPa\",\"does not change\"],\"ans\":1,\"exp\":\"A's QNH = 1000 + 240/30 = 1008 hPa; B's QNH = 1000 hPa. Sea-level pressure falls 8 hPa from A to B (4 hPa by the mid-way point) - \\\"high to low, beware below\\\": with A's setting the altimeter over-reads.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-553\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"QNH - 1022, Altimeter set QNE what is the altimeter reading ?\",\"opts\":[\"-270\",\"270\"],\"ans\":0,\"exp\":\"With 1013 set the altimeter reads pressure altitude. At a sea-level aerodrome with QNH 1022 that is (1013 - 1022) x 30 = -270 ft.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"As recalled, this question depended on a chart or table that is not reproduced here; the key is the recalled paper's answer.\"},{\"id\":\"CPLNAV-554\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"The QFE at an aerodrome is 992 hPa. Using 30 ft per hPa, its pressure altitude is:\",\"opts\":[\"630 ft\",\"-630 ft\",\"992 ft\",\"21 ft\"],\"ans\":0,\"exp\":\"Pressure altitude depends only on the pressure there: (1013 - 992) x 30 = +630 ft (above the standard datum).\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-555\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"Airfield elevation 2200 ft, pressure altitude 2800 ft. Using 30 ft per hPa, the QNH is:\",\"opts\":[\"993 hPa\",\"1033 hPa\",\"1013 hPa\",\"1003 hPa\"],\"ans\":0,\"exp\":\"PA is 600 ft above elevation, so the pressure is 600/30 = 20 hPa below standard: QNH = 1013 - 20 = 993 hPa.\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-556\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"Aerodrome elevation 1200 ft, QNH 1010 hPa. Taking 30 ft per hPa, the QFE is:\",\"opts\":[\"970 hPa\",\"1050 hPa\",\"1010 hPa\",\"983 hPa\"],\"ans\":0,\"exp\":\"QFE is the pressure at the aerodrome; QNH is that pressure reduced to sea level. Going up 1200 ft loses 1200/30 = 40 hPa: QFE = 1010 - 40 = 970 hPa.\",\"seenIn\":[\"Mar 2023 · ATPL\",\"Oct 2023 · OLODE\",\"Jan 2024 · Regular (Day 2)\",\"Mar 2024 · Regular 01\",\"Jan 2025 · OLODE 01\",\"Feb 2026 · OLODE 02\",\"Mar 2026 · Regular 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":8,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-557\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"In the standard atmosphere, as altitude increases:\",\"opts\":[\"pressure, temperature and density all decrease (temperature only up to the tropopause)\",\"density increases\",\"temperature increases\",\"pressure increases\"],\"ans\":0,\"exp\":\"Pressure and density fall continuously; temperature falls about 2 C/1000 ft to the tropopause, then stays constant.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-558\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"A sensitive altimeter differs from a simple one in having:\",\"opts\":[\"one capsule and no subscale\",\"a stack of evacuated capsules, jewelled bearings and a subscale, with two or three pointers\",\"a pitot input\",\"a gyro\"],\"ans\":1,\"exp\":\"More capsules give more movement per foot, jewelled bearings cut friction, and a subscale lets the pilot set QNH/QFE/1013.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Aug 2024 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-559\",\"topic\":\"Altimeter, Pressure Altitude & QNH\",\"stem\":\"An aircraft departs A (QNH 1013) and lands at B (elevation 500 ft, QNH 1003) without resetting the altimeter from 1013. On landing it reads (30 ft per hPa):\",\"opts\":[\"800 ft\",\"200 ft\",\"500 ft\",\"1100 ft\"],\"ans\":0,\"exp\":\"With 1013 set where the QNH is 1003, the altimeter shows 10 x 30 = 300 ft too high: 500 + 300 = 800 ft. Forgetting to reset into low pressure makes you lower than you think.\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-560\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"At FL330 with temperature ISA + 15, the TAS is 487 kt. The Mach number is:\",\"opts\":[\"0.78\",\"0.81\",\"0.84\",\"0.76\"],\"ans\":1,\"exp\":\"ISA at FL330 = -51 C, so -36 C = 237 K. LSS = 38.95 x sqrt(237) = 600 kt. M = 487 / 600 = 0.81.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Jun 2024 · Regular\",\"Sep 2024 · Regular 03\",\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\",\"May 2025 · OLODE 04\",\"Mar 2026 · Regular 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":8,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-561\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"A conventional VSI works by comparing:\",\"opts\":[\"pitot and static pressure\",\"static pressure in the capsule with static pressure in the case fed through a calibrated leak (metering unit)\",\"total pressure with a vacuum\",\"gyro precession\"],\"ans\":1,\"exp\":\"The capsule receives static directly; the case receives it through a restriction, so in a climb or descent the case lags and the difference shows the rate. No pitot input - a blocked pitot does not affect it.\",\"seenIn\":[\"Nov 2024 · OLODE 08\",\"Mar 2025 · Regular 01\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\",\"Aug 2025 · OLODE 06\",\"Jan 2026 · OLODE 01\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":8,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-562\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"What do the upper and lower limits of the yellow arc on an ASI represent?\",\"opts\":[\"Upper limit VNE, lower limit VNO\",\"Upper limit VNO, lower limit VNE\",\"Upper limit VMO, lower limit VNE\"],\"ans\":0,\"exp\":\"The yellow (caution) arc starts at VNO, the top of the green arc, and ends at VNE, the red line. So the upper limit is VNE and the lower limit is VNO.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Jun 2024 · Regular\",\"Dec 2024 · Regular 04\",\"Mar 2025 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":7,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-563\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"What is the local speed of sound at -25 C?\",\"opts\":[\"674 kt\",\"644 kt\",\"614 kt\",\"661 kt\"],\"ans\":2,\"exp\":\"LSS = 38.95 x sqrt(T in kelvin) = 38.95 x sqrt(248) = 614 kt. (661 kt is the sea-level ISA value at +15 C.)\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Aug 2023 · OLODE\",\"Nov 2023 · OLODE (30 Nov)\",\"Mar 2024 · Regular 01\",\"Jun 2024 · Regular\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":6,\"years\":[2022,2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-564\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"The static source of an ASI becomes blocked during a CLIMB. The ASI will:\",\"opts\":[\"increase regardless of the actual speed\",\"progressively under-read\",\"progressively over-read\",\"stick at the speed at the moment of blockage\"],\"ans\":1,\"exp\":\"Trapped static stays at the higher (lower-altitude) pressure while real static falls; the capsule sees pitot - trapped static, which is too small: the ASI under-reads. In a DESCENT it over-reads.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Nov 2023 · OLODE (29 Nov)\",\"Aug 2024 · OLODE 06\",\"Jun 2025 · Regular 02\",\"Jul 2025 · OLODE 05\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":6,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-565\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"On an ASI the colour markings from the low-speed end upwards are:\",\"opts\":[\"white, green, yellow, then the red line\",\"red, white, yellow, green\",\"green, white, yellow, red\",\"white, yellow, green, red\"],\"ans\":0,\"exp\":\"White arc: flap operating range (VS0-VFE). Green: normal range (VS1-VNO). Yellow: caution range (VNO-VNE). Red line: VNE.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Nov 2023 · OLODE (30 Nov)\",\"Oct 2024 · OLODE 07\",\"Mar 2025 · Regular 01\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-566\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Which statement about the Machmeter is correct?\",\"opts\":[\"at constant CAS the Mach number decreases in a climb\",\"at constant CAS the Mach number increases in a descent\",\"the Machmeter reading is independent of temperature\",\"the Machmeter has a temperature probe\"],\"ans\":2,\"exp\":\"The Machmeter works only from pitot and static pressure (Mach depends on (Pt - Ps)/Ps), so temperature never enters. At constant CAS the Mach number INCREASES in a climb and decreases in a descent - both other statements are reversed.\",\"seenIn\":[\"Jan 2019\",\"May 2022\",\"May 2024 · OLODE 04\",\"Apr 2025 · OLODE 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":5,\"years\":[2019,2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-567\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"CAS is IAS corrected for\",\"opts\":[\"position error only\",\"instrument error only\",\"instrument error and position error\",\"density error\"],\"ans\":2,\"exp\":\"CAS (also called RAS) is IAS corrected for both instrument error and position error.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Oct 2023 · OLODE\",\"Nov 2023 · OLODE (30 Nov)\",\"Dec 2023 · Regular\"],\"undated\":false,\"times\":4,\"years\":[2021,2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-568\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"The pitot tube and its drain become blocked; the static source is clear. During a DESCENT the ASI will:\",\"opts\":[\"increase\",\"decrease\",\"stay constant\",\"read zero\"],\"ans\":1,\"exp\":\"Pitot pressure is trapped; static increases as you descend, so pitot - static shrinks and the ASI falls, whatever the real speed. It now behaves like an altimeter: rising in a climb, falling in a descent.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Jul 2024 · OLODE 05\",\"Aug 2024 · OLODE 06\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-569\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"A blocked pitot tube affects:\",\"opts\":[\"the ASI (and Machmeter) only\",\"the ASI and the VSI\",\"the ASI, altimeter and VSI\",\"the altimeter only\"],\"ans\":0,\"exp\":\"Only the ASI and Machmeter use pitot pressure. The altimeter and VSI use static alone, so a blocked STATIC source affects all of them.\",\"seenIn\":[\"Jul 2023 · OLODE\",\"Aug 2023 · OLODE\",\"Nov 2023 · OLODE (30 Nov)\",\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":4,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-570\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"A pitot tube facing into the airflow measures:\",\"opts\":[\"static pressure only\",\"dynamic pressure only\",\"total pressure (static + dynamic)\",\"air density\"],\"ans\":2,\"exp\":\"The air brought to rest in the tube gives total (pitot) pressure = static + dynamic. The ASI subtracts static to leave the dynamic part.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Sep 2024 · Regular 03\",\"Mar 2025 · Regular 01\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-571\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"An aircraft descends at a constant Mach number in the standard atmosphere. The IAS will:\",\"opts\":[\"increase, and the margin to low-speed buffet increases\",\"increase, and the margin to low-speed buffet decreases\",\"decrease\",\"stay constant\"],\"ans\":0,\"exp\":\"Descending at constant Mach, the air gets denser and warmer: IAS (CAS) rises, moving the aircraft away from low-speed buffet and towards VMO - which is why the changeover from Mach to IAS is made in the descent.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Mar 2024 · Regular 01\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2022,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-572\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"What is the effect on the Mach number and TAS in an aircraft that is climbing with constant CAS?\",\"opts\":[\"Mach number decreases; TAS decreases\",\"Mach number remains constant TAS increases\",\"Mach number increases; TAS increases\",\"Mach number increases; TAS remains constant\"],\"ans\":2,\"exp\":\"Climbing at constant CAS the Mach number and TAS both increase.\",\"seenIn\":[\"Jan 2019\",\"Jun 2024 · Regular\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":3,\"years\":[2019,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-573\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Flying at a constant CAS, as the density altitude increases the TAS:\",\"opts\":[\"increases\",\"decreases\",\"stays the same\",\"increases only above the tropopause\"],\"ans\":0,\"exp\":\"TAS = CAS / sqrt(relative density). Higher density altitude means thinner air, so for the same CAS the TAS is higher.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"May 2024 · OLODE 04\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":3,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-574\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Because the VSI measures the RATE of change of static pressure, position error:\",\"opts\":[\"never affects it\",\"may cause errors during the take-off run\",\"affects it whenever the speed changes, even without a change of position error\",\"only affects it in a turn\"],\"ans\":1,\"exp\":\"A VSI is fooled only while the position error is changing - e.g. as speed builds rapidly on the take-off run. It also lags for a few seconds when a climb or descent starts or stops (lag + manoeuvre error).\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Aug 2024 · OLODE 06\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":3,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-575\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"An aircraft has a static vent on each side of the fuselage; the RIGHT one is blocked. In a sideslip to the RIGHT, the altimeter and ASI will:\",\"opts\":[\"over-read\",\"under-read\",\"read correctly\",\"read zero\"],\"ans\":0,\"exp\":\"In a right sideslip the right side meets the airflow (high pressure) and the left is in its lee (low pressure). With the right vent blocked, only the low left-side pressure is sensed: static too LOW - the altimeter over-reads and the ASI over-reads.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Oct 2024 · OLODE 07\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-576\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"If the static line to the ASI becomes blocked during a long descent, the danger is that the ASI:\",\"opts\":[\"over-reads, showing the aircraft further from the stall than it really is\",\"under-reads, showing it closer to the stall than it is\",\"under-reads, leading to flap/gear operation above the limits\",\"over-reads, leading to flap/gear operation above the limits\"],\"ans\":0,\"exp\":\"Static trapped at a lower (higher-altitude) pressure makes pitot - static too large as you descend: over-reading. The real speed is lower than shown - the stall is closer than you think.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-577\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"In a standard atmosphere and at sea level, CAS is\",\"opts\":[\"the same as TAS\",\"lower than TAS\",\"higher than TAS\"],\"ans\":0,\"exp\":\"CAS equals TAS only at ISA sea level, where density is 1.225 kg/m3.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Dec 2023 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-578\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"During the climb after take-off from a contaminated runway, the pitot (total pressure) probe becomes blocked. The IAS will:\",\"opts\":[\"decrease abruptly towards zero\",\"increase steadily\",\"increase abruptly towards VNE\",\"stay constant\"],\"ans\":1,\"exp\":\"Trapped pitot pressure against a falling static pressure: the indicated speed climbs steadily with altitude, regardless of the real speed.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-579\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"An aircraft flying at 7500 feet is cleared to descend to the level at 1000 feet. 6Nm before reaching a beacon is ground speed is 156 kts and rate of descent is 800 fpm. How many miles before the beacon should descent begin?\",\"opts\":[\"30.2\",\"27.1\",\"11.1\"],\"ans\":1,\"exp\":\"Descent 7,500 to 1,000 ft = 6,500 ft at 800 ft/min = 8.1 min; at 156 kt that is 21.1 NM. Add the 6 NM still to run: start the descent 27.1 NM before the beacon.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"As recalled, this question depended on a chart or table that is not reproduced here; the key is the recalled paper's answer.\"},{\"id\":\"CPLNAV-580\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"If pitot line become block during climb ASI reading will\",\"opts\":[\"Increase\",\"decrease\",\"Remain constant\"],\"ans\":0,\"exp\":\"With the pitot blocked (and its drain closed) the trapped pressure stays constant while static pressure falls in the climb, so the ASI over-reads and increases.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-581\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"In isothermal layer at constant Mach descent\",\"opts\":[\"TAS increases\",\"TAS decreases\",\"TAS remains constant\"],\"ans\":2,\"exp\":\"In an isothermal layer the speed of sound is constant, so at constant Mach the TAS is constant.\",\"seenIn\":[\"Feb 2024 · OLODE 02\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-582\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"The green arc of an ASI runs from:\",\"opts\":[\"VS0 to VFE\",\"VS1 to VNO\",\"VNO to VNE\",\"VS1 to VNE\"],\"ans\":1,\"exp\":\"Green = normal operating range: lower end VS1 (stall, clean, max weight), upper end VNO (max structural cruising speed).\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-583\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"The errors to which the Machmeter is subject are:\",\"opts\":[\"instrument, position, compressibility and manoeuvre-induced\",\"instrument, position and manoeuvre-induced\",\"instrument, position, barometric and manoeuvre-induced\",\"instrument, position, density and manoeuvre-induced\"],\"ans\":1,\"exp\":\"The Machmeter uses a pressure RATIO, so it has no density or temperature error, and compressibility is built into its calibration. That leaves instrument, position and manoeuvre-induced errors.\",\"seenIn\":[\"May 2022\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-584\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"When descending through an inversion at constant CAS?\",\"opts\":[\"TAS decreases\",\"Mach number increases.\",\"Mach number remains constant.\"],\"ans\":0,\"exp\":\"Descending at constant CAS the air gets denser, so TAS falls (and the Mach number falls).\",\"seenIn\":[\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-585\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"The correct order of corrections from indicated to true airspeed is:\",\"opts\":[\"IAS - EAS - CAS - TAS\",\"IAS - CAS - EAS - TAS\",\"IAS - TAS - CAS - EAS\",\"CAS - IAS - EAS - TAS\"],\"ans\":1,\"exp\":\"IAS + instrument and position error = CAS; CAS + compressibility = EAS; EAS + density error = TAS.\",\"seenIn\":[\"Aug 2024 · OLODE 06\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-586\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Climbing at a constant Mach number below the tropopause in ISA conditions:\",\"opts\":[\"CAS and TAS both decrease\",\"CAS increases, TAS decreases\",\"CAS decreases, TAS stays the same\",\"both increase\"],\"ans\":0,\"exp\":\"Temperature falls in the climb, so the speed of sound falls: same Mach = lower TAS. Air also gets thinner, so CAS falls even faster.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2022,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-587\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Ice or debris disturbing the airflow around the static source causes:\",\"opts\":[\"instrument error\",\"position (pressure) error\",\"density error\",\"compressibility error\"],\"ans\":1,\"exp\":\"Position error is the error from the static vent sensing a pressure different from the true ambient pressure because of the local airflow - ice or debris round the vent changes exactly that.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-588\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"In an isothermal layer, flying at a constant TAS, the Mach number:\",\"opts\":[\"increases\",\"decreases\",\"stays constant\",\"depends on the CAS\"],\"ans\":2,\"exp\":\"Mach = TAS / speed of sound, and the speed of sound depends only on temperature. Constant temperature + constant TAS = constant Mach.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-589\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"A leak in the pitot (total pressure) line of a non-pressurised aircraft makes the ASI:\",\"opts\":[\"over-read in a climb and under-read in a descent\",\"over-read\",\"under-read in a climb and over-read in a descent\",\"under-read\"],\"ans\":3,\"exp\":\"In an unpressurised cabin the leak lets pitot pressure escape to roughly static pressure, so the difference sensed is too small: the ASI under-reads.\",\"seenIn\":[\"Sep 2023 · Regular 03\",\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-590\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"An aircraft descends at a constant Mach number through an inversion (temperature falling as it descends). CAS and TAS:\",\"opts\":[\"CAS increases, TAS decreases\",\"both increase\",\"both decrease\",\"CAS decreases, TAS increases\"],\"ans\":0,\"exp\":\"CAS rises in any descent at constant Mach (denser air). TAS = Mach x speed of sound, and the speed of sound falls with the colder air in the inversion, so TAS falls.\",\"seenIn\":[\"Sep 2024 · Regular 03\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-591\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"In an airspeed indicator, the capsule is fed with ...... and the case with ......:\",\"opts\":[\"static; pitot (total) pressure\",\"pitot (total) pressure; static pressure\",\"static; vacuum\",\"vacuum; static\"],\"ans\":1,\"exp\":\"Total (pitot) pressure inside the capsule, static around it: the capsule expands with the difference, the dynamic pressure 1/2 rho V^2.\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-592\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Ice blocks the pitot inlet but the drain hole remains open. The ASI will:\",\"opts\":[\"over-read\",\"act like an altimeter\",\"gradually fall to zero\",\"freeze at the last reading\"],\"ans\":2,\"exp\":\"With the drain open, the pressure in the pitot line leaks away to atmospheric (static) pressure, so pitot - static becomes zero. If the drain is ALSO blocked, pressure is trapped and the ASI acts like an altimeter.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-593\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"If the pitot (ram air) inlet and its drain are blocked but the static port stays open, the ASI will:\",\"opts\":[\"read a little low\",\"read a little high\",\"react like an altimeter\",\"freeze at zero\"],\"ans\":2,\"exp\":\"Trapped pitot pressure is compared with a changing static pressure: in a climb the static falls and the ASI rises; in a descent it falls - just like an altimeter.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-594\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"If the static vent becomes blocked during climb:\",\"opts\":[\"the VSI will indicate an increasing rate of climb.\",\"the VSI will indicate a decreasing rate of climb,\",\"the VSI will return to zero..\"],\"ans\":2,\"exp\":\"Static pressure trapped at the blocked level while the aircraft climbs: the VSI returns to zero.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Aug 2024 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-595\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"At FL300 an aircraft flies at M 0.82 with OAT = ISA + 15 C. Its TAS is about:\",\"opts\":[\"499 kt\",\"483 kt\",\"470 kt\",\"520 kt\"],\"ans\":0,\"exp\":\"ISA at FL300 = -44.4 C, so OAT = -29.4 C = 243.8 K. Local speed of sound = 38.95 x sqrt(243.8) = 608 kt; TAS = 0.82 x 608 = 499 kt.\",\"seenIn\":[\"Mar 2022\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2022,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-596\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"At FL330, temperature ISA + 15, the aircraft flies M 0.90. Its TAS is about:\",\"opts\":[\"540 kt\",\"520 kt\",\"487 kt\",\"574 kt\"],\"ans\":0,\"exp\":\"ISA at FL330 = -51 C; + 15 gives -36 C = 237 K. Speed of sound = 38.95 x sqrt(237) = 600 kt; TAS = 0.9 x 600 = 540 kt.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-597\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"A rate of descent of 500 ft/min is about:\",\"opts\":[\"152 cm/s\",\"254 cm/s\",\"305 cm/s\",\"500 cm/s\"],\"ans\":1,\"exp\":\"1 ft = 30.48 cm, so 500 ft/min = 15,240 cm/min = 15,240 / 60 = 254 cm/s.\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-598\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"The air data computer receives:\",\"opts\":[\"pitot pressure, static pressure and total air temperature\",\"pressure and temperature only from the cabin\",\"GPS position\",\"heading\"],\"ans\":0,\"exp\":\"From pitot, static and TAT (and often AoA) the ADC computes altitude, vertical speed, IAS/CAS, Mach, TAS and SAT.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-599\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Considering MMO and VMO, the captain of a pressurised aircraft begins his descent from a high flight level. In order to meet his scheduled time of arrival he decides to use maximum ground speed at any time of the descent. He will be limited by\",\"opts\":[\"initially by MMO, then by VMO below a certain flight level\",\"initially by VMO, then by MMO below a certain flight level\",\"by the VMO in the still air\"],\"ans\":0,\"exp\":\"At high level the Mach limit (MMO) is reached first; below the crossover altitude the airspeed limit VMO becomes the limit.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-600\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"VMO is calculated based on\",\"opts\":[\"TAS\",\"EAS\",\"CAS\"],\"ans\":2,\"exp\":\"VMO is a calibrated airspeed limit.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-601\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"An aircraft at FL370 is required to commence descent when 100 NM from a DME facility and to cross the station at FL120. If the mean GS during the descent is 396 kt, the minimum rate of descent required is approximately\",\"opts\":[\"1650 ft/min\",\"2400 ft/min\",\"1000 ft/min\"],\"ans\":0,\"exp\":\"Height to lose = 37,000 - 12,000 = 25,000 ft. Time = 100 / 396 h = 15.15 min. Rate = 25,000 / 15.15 = 1,650 ft/min.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-602\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Static vents on BOTH sides of the fuselage (cross-coupled) are fitted mainly to:\",\"opts\":[\"provide a backup if one is blocked\",\"reduce the error caused by sideslip or yaw\",\"increase sensitivity\",\"prevent icing\"],\"ans\":1,\"exp\":\"Averaging the two sides cancels the pressure difference created by sideslip/yaw. The alternate static source is the backup for blockage.\",\"seenIn\":[\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-603\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"An aircraft is descending down a 12% slope whilst maintaining a GS of 540 kt. The rate of descent of the aircraft is approximately:\",\"opts\":[\"650 FT/MIN\",\"6500 FT/MIN\",\"4500 FT/MIN\",\"3900 FT/MIN\"],\"ans\":1,\"exp\":\"540 kt = 54,700 ft/min of ground distance; 12% of that = 6,560 ft/min, about 6,500 ft/min.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-604\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"When using the Vertical Speed Indicator, the pilot\",\"opts\":[\"can rely on its readings in all attitudes of flight\",\"Can only rely on the readings when changing to horizontal flight\",\"Cannot rely on its readings, especially when a change of pitch Attitude is occurring\",\"can rely throughout the flight\"],\"ans\":2,\"exp\":\"The VSI lags and gives wrong readings during pitch changes.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-605\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"An aircraft at FL350 is required to commence descent when 85 NM from a VOR to cross the VOR at FL80. The mean GS for the descent is 340 kt. What is the minimum rate of descent required?\",\"opts\":[\"1800 ft/min\",\"1600 ft/min\",\"1700 ft/min\",\"1900 ft/min\"],\"ans\":0,\"exp\":\"Height to lose = 35,000 - 8,000 = 27,000 ft. Time = 85 / 340 h = 15 min. Rate = 27,000 / 15 = 1,800 ft/min.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-606\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"IAS 84 kt, OAT +10 C, pressure altitude 8,000 ft. The TAS is about:\",\"opts\":[\"97 kt\",\"84 kt\",\"101 kt\",\"91 kt\"],\"ans\":0,\"exp\":\"ISA at 8000 ft is -1 C, so ISA + 11. Air density ratio gives TAS = 84 x 1.15 = 97 kt (rule of thumb: +2 % per 1000 ft = 97 kt).\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-607\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"If the static source AND the pitot are both blocked, the instruments affected are:\",\"opts\":[\"ASI only\",\"altimeter and VSI only\",\"ASI, altimeter, VSI and Machmeter\",\"none, they all have their own sources\"],\"ans\":2,\"exp\":\"Static feeds the altimeter, VSI, ASI and Machmeter; pitot feeds the ASI and Machmeter. Block both and every pressure instrument is wrong.\",\"seenIn\":[\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-608\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"The RIGHT static vent is blocked and the left is open. In a sideslip to the LEFT, the ASI and Machmeter will:\",\"opts\":[\"under-read\",\"over-read\",\"show no change\",\"read zero\"],\"ans\":0,\"exp\":\"Slipping left, the left side faces the airflow, so the open left vent senses a pressure ABOVE true static. Pitot - static is too small: the ASI (and Machmeter) under-read.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-609\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"At a constant Mach decent Cas will\",\"opts\":[\"Increase\",\"decrease\",\"remain constant\"],\"ans\":0,\"exp\":\"In a constant-Mach descent the speed of sound rises, so CAS and IAS increase.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-610\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"The airspeed indicator is calibrated to:\",\"opts\":[\"conditions of the ISA\",\"conditions of the ISA at mean sea level\",\"an air density of 1013.25 g/m3\",\"indicate correctly in any atmosphere\"],\"ans\":1,\"exp\":\"The ASI is calibrated to read TAS only in ISA sea-level air (1.225 kg/m3, 1013.25 hPa, +15 C). Anywhere else density error makes IAS differ from TAS.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-611\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"An aircraft at FL290, ISA deviation -6 C, has a CAS (RAS) of 255 kt. Its Mach number is about:\",\"opts\":[\"0.67\",\"0.62\",\"0.72\",\"0.58\"],\"ans\":0,\"exp\":\"Mach depends only on the ratio of dynamic to static pressure, i.e. on CAS and pressure altitude - not on temperature. At FL290, 255 kt CAS gives M 0.67. The ISA deviation changes the TAS (here about 390 kt), not the Mach.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-612\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"EPR (engine pressure ratio) is:\",\"opts\":[\"compressor inlet pressure / turbine outlet pressure\",\"turbine (jet pipe) outlet pressure / compressor inlet pressure\",\"fuel pressure / oil pressure\",\"cabin pressure / ambient pressure\"],\"ans\":1,\"exp\":\"EPR = exhaust (turbine outlet) total pressure divided by compressor inlet total pressure - a direct measure of thrust on many jets.\",\"seenIn\":[\"May 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-613\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"In a non-pressurized aircraft, if one or several static pressure ports are damaged, there is an ultimate emergency means for restoring a practically correct static pressure intake?\",\"opts\":[\"Breaking the rate-of climb indicator glass window.\",\"Slightly opening a window to restore the ambient pressure in the cabin.\",\"Descending as much as possible in order to fly at a pressure as close to 1013.25 hPa as possible.\"],\"ans\":0,\"exp\":\"In an unpressurised aeroplane, breaking the VSI glass admits cabin (ambient) pressure to the static system as an emergency static source.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-614\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Descending from 15000 ft to 1000 ft, TAS 180 kts, HW -20 kts, ROD 500 FPM, Ground Distance?\",\"opts\":[\"88 Nm\",\"75 Nm\",\"114 Nm\"],\"ans\":1,\"exp\":\"Time = 14,000 ft / 500 ft/min = 28 min. Ground speed with the 20 kt headwind = 160 kt: 160 x 28/60 = 75 NM.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-615\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"The static source of an unpressurised aircraft becomes blocked. The pilot's correct first action is to:\",\"opts\":[\"select the alternate static source\",\"break the VSI glass\",\"descend immediately\",\"switch off pitot heat\"],\"ans\":0,\"exp\":\"Select the alternate static source (usually inside the cabin; it may make the instruments over-read slightly). Breaking the VSI glass is the last-resort way to vent the system to cabin pressure if there is no alternate.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-616\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"The ISA temperature at FL330 is about:\",\"opts\":[\"-51 C\",\"-56.5 C\",\"-36 C\",\"-66 C\"],\"ans\":0,\"exp\":\"ISA: +15 C at sea level, falling about 2 C per 1000 ft: 15 - 66 = -51 C (-50.3 with 1.98). -56.5 C is the tropopause value, reached at 36,090 ft.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-617\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Pressure altitude 30,000 ft, TAT -10 C, Mach 0.82. The density altitude is about:\",\"opts\":[\"30,400 ft\",\"29,600 ft\",\"31,200 ft\",\"30,000 ft\"],\"ans\":0,\"exp\":\"First remove the ram rise: SAT = TAT / (1 + 0.2 M^2) = 263 / 1.134 = 232 K = -41 C. ISA at 30,000 ft is -44.4 C, so ISA + 3. Density altitude = 30,000 + 3 x 120 = about 30,400 ft.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-618\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Descending from high altitude at a constant Mach number, the speed limit reached first and then the next is:\",\"opts\":[\"VMO first, then MMO\",\"MMO first, then VMO\",\"only VMO\",\"only MMO\"],\"ans\":1,\"exp\":\"Up high the Mach limit (MMO) governs; descending at constant Mach the IAS rises until VMO is reached, after which the crew flies IAS.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-619\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"An aircraft at 120 kt TAS needs a rate 1 turn. The bank angle required is about:\",\"opts\":[\"36 deg\",\"19 deg\",\"12 deg\",\"30 deg\"],\"ans\":1,\"exp\":\"tan(bank) = V x rate / g = 61.7 m/s x 0.0524 rad/s / 9.81 = 0.33, bank = 18 deg. Rule of thumb: TAS/10 + 7 = 19 deg.\",\"seenIn\":[\"Aug 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-620\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"The local speed of sound is equal to (K = a constant):\",\"opts\":[\"K x sqrt(temperature F) knots\",\"K x sqrt(temperature in kelvin) knots\",\"K x sqrt(temperature C) knots\",\"K x sqrt(temperature in kelvin) metres per second\"],\"ans\":1,\"exp\":\"The correct answer is: K x sqrt(temperature in kelvin) knots.\",\"seenIn\":[\"Aug 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-621\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"The white arc of an ASI runs from:\",\"opts\":[\"VS0 to VFE\",\"VS1 to VNO\",\"VS0 to VNO\",\"VFE to VNE\"],\"ans\":0,\"exp\":\"White = flap operating range: VS0 (stall with full flap) to VFE (maximum flap-extended speed).\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-622\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"When descending through an isothermal layer at constant CAS:\",\"opts\":[\"Mach number increases.\",\"Mach number decreases.\",\"Mach number remains constant\"],\"ans\":1,\"exp\":\"In an isothermal layer the speed of sound is constant; at constant CAS the TAS and hence the Mach number fall in the descent.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-623\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"IAS 120 kt, FL 80, OAT +20 deg C. What is the TAS?\",\"opts\":[\"141 kt\",\"135 kt\",\"144 kt\"],\"ans\":0,\"exp\":\"At FL80 with +20 C (ISA +21): density ratio = 0.743 / 1.017 = 0.730, so TAS = 120 / sqrt 0.730 = 140-141 kt.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-624\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"The temperature probe of a fast aircraft reads TAT. The static air temperature is:\",\"opts\":[\"TAT + ram rise\",\"TAT - ram rise\",\"TAT x Mach\",\"the same as TAT\"],\"ans\":1,\"exp\":\"Air brought to rest on the probe heats up (ram rise): TAT = SAT + ram rise, so SAT = TAT - ram rise. ISA deviation uses SAT.\",\"seenIn\":[\"May 2022\",\"Sep 2022 · FC 03\",\"Oct 2023 · OLODE\",\"Mar 2024 · Regular 01\",\"Jul 2025 · OLODE 05\",\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":6,\"years\":[2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-625\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Cylinder head and exhaust gas temperatures are normally measured by:\",\"opts\":[\"a bourdon tube\",\"thermocouples\",\"a capsule\",\"a ratiometer bridge only\"],\"ans\":1,\"exp\":\"A thermocouple (two dissimilar metals) generates a voltage proportional to the hot-junction temperature with no external power - used for CHT (on the hottest cylinder) and EGT.\",\"seenIn\":[\"May 2022\",\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-626\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"An instantaneous VSI (IVSI) removes the lag of a normal VSI by using:\",\"opts\":[\"a pitot input\",\"an accelerometer (dashpot) that reacts at once to vertical acceleration\",\"a gyro\",\"a larger metering unit\"],\"ans\":1,\"exp\":\"A small spring-loaded piston (dashpot) moves with vertical acceleration and produces an immediate pressure difference, so the needle responds at once while the normal metering takes over.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-627\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Using ram rise = (TAS/100)^2 deg C, at a TAS of 400 kt the TAT exceeds the SAT by about:\",\"opts\":[\"16 C\",\"4 C\",\"40 C\",\"8 C\"],\"ans\":0,\"exp\":\"Ram rise = (TAS/100)^2 = (400/100)^2 = 16 C, so TAT is about 16 C warmer than SAT.\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-628\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"At a constant IAS and pressure altitude, if the OAT increases the TAS:\",\"opts\":[\"increases\",\"decreases\",\"stays the same\",\"depends on the Mach number\"],\"ans\":0,\"exp\":\"Warmer air is less dense; the same IAS needs a higher TAS (roughly +1 % per 5 C).\",\"seenIn\":[\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-629\",\"topic\":\"Airspeed, Mach & Vertical Speed\",\"stem\":\"Total air temperature (TAT) is:\",\"opts\":[\"static air temperature plus the ram rise\",\"static air temperature minus the ram rise\",\"the same as static air temperature at all speeds\",\"the temperature at the tropopause\"],\"ans\":0,\"exp\":\"Air brought to rest on the probe is heated by compression: TAT = SAT + ram rise. The ram rise grows with the square of TAS (about 1 deg C at 100 kt, about 9 deg C at 300 kt in round figures).\",\"seenIn\":[\"Jun 2024 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-630\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"What errors are there in a DGI? 1. Transport wander 2. Earth rate 3. Heading errors when banking and pitching 4. Mechanical imperfection\",\"opts\":[\"1, 2 and 3\",\"1, 2 and 4\",\"all of the above are correct\"],\"ans\":2,\"exp\":\"A directional gyro suffers transport wander, earth-rate drift, errors from banking and pitching, and mechanical imperfections: all four.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jun 2023 · Regular\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Jul 2024 · OLODE 05\",\"Jun 2025 · Regular 02\",\"Mar 2026 · Regular 01\",\"Jul 2026 · OLODE 05\",\"Aug 2026 · OLODE 06\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":11,\"years\":[2021,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-631\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"The two fundamental properties of a gyroscope are: (1) mass (2) rigidity (3) inertia (4) precession (5) rotational speed\",\"opts\":[\"1, 2 and 3\",\"2 and 4\",\"2 and 3\",\"1 and 3\"],\"ans\":1,\"exp\":\"Rigidity in space (it holds its axis fixed) and precession (an applied force acts 90 deg on in the direction of spin). Mass, radius and rpm only set how rigid it is.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Jun 2024 · Regular\",\"Aug 2024 · OLODE 06\",\"Mar 2025 · Regular 01\",\"Jan 2026 · OLODE 01\",\"Mar 2026 · Regular 01\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":7,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-632\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"A turn indicator is built around a gyroscope with\",\"opts\":[\"2 degrees of freedom\",\"1 degree of freedom\",\"3 degrees of freedom\"],\"ans\":1,\"exp\":\"The gyro of a turn indicator is a rate gyro with one degree of freedom (a single gimbal, spring-restrained).\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"May 2022\",\"Nov 2023 · OLODE (30 Nov)\",\"Dec 2023 · Regular\",\"May 2024 · OLODE 04\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":6,\"years\":[2021,2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-633\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"What is precession?\",\"opts\":[\"The tendency of a gyro to keep a fixed direction in space\",\"The movement of the spin axis 90 deg in the direction of rotation from the point where a force is applied\",\"The tendency of a gyro to topple when it is spinning slowly\"],\"ans\":1,\"exp\":\"Precession is the movement of the spin axis, 90 degrees in the direction of rotation from the point where a force is applied. Holding a fixed direction is rigidity.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Sep 2022 · FC 03\",\"Jun 2024 · Regular\",\"Oct 2024 · OLODE 07\",\"Jun 2025 · Regular 02\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":6,\"years\":[2021,2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-634\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"The term drift refers to the wander of the axis of a gyro in:\",\"opts\":[\"the vertical and horizontal plane\",\"the vertical plane\",\"the horizontal plane\"],\"ans\":2,\"exp\":\"Drift is the wander of the gyro spin axis in the horizontal plane (topple is in the vertical plane).\",\"seenIn\":[\"Jan 2019\",\"Oct 2023 · OLODE\",\"Nov 2023 · OLODE (29 Nov)\",\"Nov 2023 · OLODE (30 Nov)\",\"Jun 2025 · Regular 02\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":6,\"years\":[2019,2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-635\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"A slaved directional gyro derives its directional signal from\",\"opts\":[\"a direct reading magnetic compass\",\"the flight director\",\"the flux valve\"],\"ans\":2,\"exp\":\"A slaved gyro compass (remote indicating compass) is kept aligned to magnetic north by the flux valve.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\",\"May 2024 · OLODE 04\",\"Mar 2025 · Regular 01\",\"May 2025 · OLODE 04\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":6,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-636\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"An airborne instrument with a gyro having two degrees of freedom and a horizontal spin axis is the:\",\"opts\":[\"directional gyro\",\"turn indicator\",\"artificial horizon\",\"turn coordinator\"],\"ans\":0,\"exp\":\"DGI = 2 DOF, horizontal axis. Turn indicator = 1 DOF, horizontal axis. Artificial horizon = 2 DOF, vertical axis.\",\"seenIn\":[\"Dec 2023 · Regular\",\"May 2024 · OLODE 04\",\"Dec 2024 · Regular 04\",\"Jun 2025 · Regular 02\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-637\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"What is the function of the latitude nut on a DI?\",\"opts\":[\"to correct for Coriolis effect\",\"to compensate for earth rate error\",\"to correct for transport wander\"],\"ans\":1,\"exp\":\"The latitude nut on a directional gyro is set to the local latitude so that it can apply the correction for earth-rate drift.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Dec 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-638\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"If the needle and the ball of a turn and slip indicator both show right, what does it indicate?\",\"opts\":[\"turn to left and too much bank\",\"turn to right and too much bank\",\"turn to left and too little bank\"],\"ans\":1,\"exp\":\"Needle shows a right turn; the ball is on the inside of the turn (right), so the aircraft is slipping - too much bank for the rate of turn.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jan 2026 · OLODE 01\",\"Mar 2026 · Regular 01\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":4,\"years\":[2022,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-639\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"An aircraft turns through 180 deg at constant attitude and bank. A classic (air-driven) artificial horizon then shows:\",\"opts\":[\"nose up and correct angle of bank\",\"correct attitude and bank\",\"nose up and bank too low\",\"nose up and bank too high\"],\"ans\":0,\"exp\":\"Turning errors of the classic AH: after 90 deg - bank under-read, false climb; after 180 deg - bank correct, false climb; after 270 deg - bank over-read, false climb; after 360 deg - all correct.\",\"seenIn\":[\"Jul 2024 · OLODE 05\",\"Sep 2024 · Regular 03\",\"Jun 2025 · Regular 02\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-640\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"When, in flight, the needle of a needle-and-ball indicator is on the right and the ball on the left, the aircraft is\",\"opts\":[\"turning left with too much bank\",\"turning right with not enough bank\",\"turning left with not enough bank\"],\"ans\":1,\"exp\":\"Needle right = right turn; ball on the outside (left) = skidding = not enough bank.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Jan 2026 · OLODE 01\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":3,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-641\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"A turn indicator indicates rate of turn. Rate of turn depends upon 1. bank angle 2. aeroplane speed 3. aeroplane weight. The combination of correct statements is\",\"opts\":[\"1, 3\",\"2, 3\",\"1, 2\"],\"ans\":2,\"exp\":\"Rate of turn = g tan(bank) / TAS: it depends on bank angle and speed, not on weight.\",\"seenIn\":[\"May 2022\",\"Dec 2023 · Regular\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-642\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"The correct turn and slip indications when turning right on the ground are?\",\"opts\":[\"Needle and ball right.\",\"Needle and ball left.\",\"Needle right and ball left.\",\"Needle left and ball right\"],\"ans\":2,\"exp\":\"Taxiing a right turn: needle right, ball left (outside).\",\"seenIn\":[\"Jan 2019\",\"Jan 2024 · Regular (Day 2)\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":3,\"years\":[2019,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-643\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"A standby artificial horizon:\",\"opts\":[\"works only after a complete electrical failure\",\"contains its own gyro and has an independent (standby battery) power supply, and runs all the time\",\"shares the main AH gyro\",\"needs the vacuum system\"],\"ans\":1,\"exp\":\"It is a separate, self-contained instrument with its own gyro and an independent power source, running continuously so it is already erect and reliable when the main attitude display fails.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2023 · Regular\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-644\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"The gyro of an artificial horizon (vertical gyro) has:\",\"opts\":[\"one degree of freedom, vertical axis\",\"two degrees of freedom, vertical axis\",\"one degree of freedom, horizontal axis\",\"two degrees of freedom, horizontal axis\"],\"ans\":1,\"exp\":\"The AH needs freedom in pitch and roll and a vertical spin axis held to the earth vertical (earth gyro). DGI: 2 DOF, horizontal axis. Turn indicator: 1 DOF, horizontal axis.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Apr 2025 · OLODE 03\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":3,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-645\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"On a TSI what does it indicate when the turn needle is out to the left and the ball out to the right?\",\"opts\":[\"Right turn with too much bank,\",\"Left turn with too little bank.\",\"Left turn with too much bank.\"],\"ans\":1,\"exp\":\"The needle shows a left turn; the ball is displaced to the right (outside the turn) - skidding, which means too little bank for that rate of turn.\",\"seenIn\":[\"May 2022\",\"Oct 2023 · OLODE\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-646\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"In a turn at constant bank angle, if the TAS increases:\",\"opts\":[\"rate of turn increases and radius decreases\",\"rate of turn decreases and radius increases\",\"both increase\",\"both decrease\"],\"ans\":1,\"exp\":\"Rate of turn = g tan(bank) / V and radius = V^2 / (g tan bank). At fixed bank, faster means slower turn rate and a much larger radius.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Aug 2024 · OLODE 06\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-647\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"An aircraft taxies and turns LEFT on the ground. The turn and slip indicator shows:\",\"opts\":[\"needle left, ball right\",\"needle left, ball left\",\"needle right, ball left\",\"needle centred, ball right\"],\"ans\":0,\"exp\":\"The gyro senses the turn (needle left). With no bank on the ground the ball is thrown to the outside of the turn - right.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Jun 2024 · Regular\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":3,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-648\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"What is the advantage of remote indicating compass over direct reading magnetic compass\",\"opts\":[\"It is lighter\",\"It is connected to the electrical power so more accurate\",\"It senses the earth's magnetic field rather than it seeks, so it is more sensitive\"],\"ans\":2,\"exp\":\"A remote indicating compass senses the field (flux valve) rather than seeking it, so it is more sensitive.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Jun 2024 · Regular\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-649\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"An airborne instrument equipped with a gyro with 1 degree of freedom and a horizontal spin axis is a\",\"opts\":[\"turn indicator\",\"DGI\"],\"ans\":0,\"exp\":\"A rate gyro with one degree of freedom and a horizontal spin axis is the turn indicator.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-650\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"Drift of a gyro (wander in the horizontal plane) is a rotation of the spin axis about the:\",\"opts\":[\"vertical axis\",\"horizontal axis\",\"longitudinal axis\",\"spin axis itself\"],\"ans\":0,\"exp\":\"Turning in the horizontal plane means rotating about a vertical axis - which is exactly what upsets a DGI's heading.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-651\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"An aircraft is parked at 50 deg N. Its DGI (no latitude correction) was set to 090 and after one hour reads 082 - a decrease of 8 deg/h. What is the REAL wander of the gyro?\",\"opts\":[\"3.5 deg/h increasing\",\"3.5 deg/h decreasing\",\"8 deg/h decreasing\",\"11.5 deg/h decreasing\"],\"ans\":0,\"exp\":\"Parked, so there is no transport wander; the apparent wander (earth rate) is -15 sin 50 = -11.5 deg/h. Observed = real + apparent: -8 = real - 11.5, so the real wander is +3.5 deg/h (the gyro itself is drifting to increase the reading).\",\"seenIn\":[\"Jun 2023 · Regular\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-652\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"Gyro wander in the VERTICAL plane is called:\",\"opts\":[\"drift\",\"topple\",\"precession\",\"transport wander\"],\"ans\":1,\"exp\":\"Wander in the horizontal plane = drift; in the vertical plane = topple. Each can be real (friction, imbalance) or apparent (earth rate, transport across the earth).\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-653\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"Gyro rigidity can be increased by\",\"opts\":[\"More mass at periphery and high RPM\",\"More mass close to axis and low RPM\",\"More mass at periphery and low RPM\"],\"ans\":0,\"exp\":\"Rigidity rises with the mass of the rotor, the radius at which the mass is placed and its spin speed: more mass at the periphery and high RPM.\",\"seenIn\":[\"Jun 2025 · Regular 02\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-654\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"The caging knob of a gyro instrument is used to:\",\"opts\":[\"set the heading bug\",\"lock the gyro (and erect it quickly), preventing damage or toppling during manoeuvres beyond its limits\",\"adjust the latitude nut\",\"test the lights\"],\"ans\":1,\"exp\":\"Caging locks the gimbals in a fixed position - used to re-erect a toppled gyro or to protect it in aerobatics.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-655\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"A rate 3 turn completes 360 deg in:\",\"opts\":[\"40 seconds\",\"90 seconds\",\"1 minute\",\"2 minutes\"],\"ans\":0,\"exp\":\"Rate 1 = 3 deg/s (2 min for 360); rate 2 = 6 deg/s (1 min); rate 3 = 9 deg/s: 360 / 9 = 40 s.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2021,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-656\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"A/C turns right on ground\",\"opts\":[\"Needle right , ball left\",\"Needle left , ball right\"],\"ans\":0,\"exp\":\"Taxiing in a right turn the turn needle goes right and the ball (centrifugal force) goes left.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2021,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-657\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"Rate of turn is the\",\"opts\":[\"pitch rate in the turn\",\"change of heading rate of the aircraft\",\"yaw rate in the turn\"],\"ans\":1,\"exp\":\"Rate of turn is the rate of change of heading.\",\"seenIn\":[\"Mar 2022\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-658\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"A directional gyro indicator (DGI) is basically a:\",\"opts\":[\"horizontal-axis earth gyro\",\"horizontal-axis tied gyro\",\"vertical-axis earth gyro\",\"vertical-axis tied gyro\"],\"ans\":1,\"exp\":\"A tied gyro is held to a reference other than the earth's vertical (the DGI is tied to the aircraft's yaw axis/horizontal). An earth gyro is controlled by gravity - the artificial horizon, vertical spin axis.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Aug 2024 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-659\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"A two-axis gyro measuring vertical changes will have\",\"opts\":[\"two degrees of freedom and a vertical axis\",\"one degree of freedom and a vertical axis\",\"two degrees of freedom and a horizontal axis\"],\"ans\":0,\"exp\":\"A gyro that senses pitch and roll (artificial horizon) has two degrees of freedom and a vertical spin axis.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-660\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"The gyro in a rate of turn indicator has (i) ____ operating speed than the gyros used in other instruments because (ii) ____\",\"opts\":[\"(i) a lower (ii) higher rigidity is not required\",\"(i) the same (ii) it uses the property of rigidity\",\"(i) a higher (ii) precession rate gives a greater operating range\",\"(i) variable (ii) more than one rate of turn is desired\"],\"ans\":0,\"exp\":\"A rate gyro runs slower than others because the high rigidity of a fast gyro is not required.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-661\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"Apparent topple of a gyro is:\",\"opts\":[\"a real tilt caused by friction\",\"an apparent tilt of the spin axis in the vertical plane caused by the earth's rotation and movement over the earth - not by any torque\",\"drift in the horizontal plane\",\"gimballing error\"],\"ans\":1,\"exp\":\"The gyro stays fixed in space while the earth turns beneath it, so its axis appears to tilt (topple) relative to the local vertical.\",\"seenIn\":[\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-662\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"Turning from heading 050 to 320 at standard rate (rate 1), the turn takes:\",\"opts\":[\"30 seconds\",\"90 seconds\",\"1 minute\",\"2 minutes\"],\"ans\":0,\"exp\":\"The shortest way is left through 90 deg (050 -> 320). At 3 deg/s: 90 / 3 = 30 s.\",\"seenIn\":[\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-663\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"If the attitude indicator fails, the pilot controls attitude using:\",\"opts\":[\"the turn coordinator (bank) with the ASI, altimeter and VSI (pitch)\",\"the compass alone\",\"the radio altimeter alone\",\"the clock and ADF\"],\"ans\":0,\"exp\":\"Partial panel: the turn coordinator/turn needle and DGI give bank and turn; pitch is read from the airspeed, altimeter and VSI trend.\",\"seenIn\":[\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-664\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"The limitations of a typical air driven DI are\",\"opts\":[\"55° in roll and pitch\",\"110 in roll and 60° in pitch\",\"60° in roll and 110° in pitch.\",\"85° in pitch & roll\"],\"ans\":0,\"exp\":\"A typical air-driven directional gyro topples beyond about 55 deg of roll or pitch.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-665\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"What is the Schuler period?\",\"opts\":[\"48,minutes.\",\"84 seconds.\",\"48 seconds.\",\"84 minutes.\"],\"ans\":3,\"exp\":\"The Schuler period is 84 minutes.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-666\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"In a correctly coordinated turn to the LEFT, a turn coordinator shows:\",\"opts\":[\"aircraft symbol (needle) left, ball centred\",\"needle left, ball left\",\"needle left, ball right\",\"needle right, ball centred\"],\"ans\":0,\"exp\":\"Coordinated = no slip or skid, so the ball stays in the middle; the symbol/needle shows the direction and rate of turn. Ball to the inside of the turn = slipping (too much bank); to the outside = skidding (too little bank).\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-667\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"Gimballing error caused due to\",\"opts\":[\"Bank\",\"Acceleration\",\"Deceleration\"],\"ans\":0,\"exp\":\"Gimballing error arises when the aircraft banks or pitches and the gyro gimbals are no longer orthogonal.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-668\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"In the building principle of gyroscope the best efficiency is obtained through the concentration of mass\",\"opts\":[\"Close to the axis and with low rotation speed\",\"On the periphery and with a low rotation speed\",\"On the periphery and with a high rotation speed\"],\"ans\":2,\"exp\":\"Mass concentrated at the rim and a high spin speed give the greatest rigidity.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-669\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"Inside an artificial horizon:\",\"opts\":[\"the inner gimbal is pivoted laterally inside the outer gimbal, which is pivoted longitudinally inside the case\",\"the inner gimbal is tied to the vertical by a control system\",\"the rotor axis is kept level by a spring\",\"there is only one gimbal\"],\"ans\":0,\"exp\":\"Inner gimbal on the lateral (pitch) axis, outer gimbal on the longitudinal (roll) axis: the rotor stays vertical while the aircraft pitches and rolls round it.\",\"seenIn\":[\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-670\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"In a gyro-magnetic (remote indicating) compass the torque motor:\",\"opts\":[\"causes the directional gyro to precess to align with the magnetic heading\",\"drives the heading pointer directly\",\"feeds the flux valve\",\"compensates deviation\"],\"ans\":0,\"exp\":\"The flux valve signal is compared with the gyro position; any error drives the torque motor, which precesses the gyro slowly until it agrees with the magnetic heading (slaving).\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-671\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"During a forward acceleration (take-off run), a classic air-driven artificial horizon tends to show:\",\"opts\":[\"a false climb (with a right-wing-down error)\",\"a false descent\",\"no error\",\"a left bank only\"],\"ans\":0,\"exp\":\"Acceleration acts on the pendulous erection system and the bottom-heavy rotor housing: the classic AH shows nose up and right wing down. Deceleration gives the opposite. Electric horizons with a clockwise rotor give opposite errors.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-672\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"After turning through 90 deg at constant altitude and bank, a classic artificial horizon shows:\",\"opts\":[\"too much nose up and bank too high\",\"too much nose up and bank too low\",\"too much nose up and bank correct\",\"no error\"],\"ans\":1,\"exp\":\"At 90 deg of turn the classic AH under-reads the bank and shows a false climb (nose up). Errors cancel after a full 360.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-673\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"Real wander of a gyro is mainly caused by:\",\"opts\":[\"asymmetrical friction at the spin axis bearings and imbalance\",\"the rotation of the earth\",\"increasing rotor rpm\",\"moving north or south\"],\"ans\":0,\"exp\":\"Real wander comes from the gyro itself - bearing friction and imbalance produce torques that precess it. Earth rotation and transport give APPARENT wander.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-674\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"Following a left engine failure the pilot of a multi engine a/c uses rudder to oppose yaw and keeps the a/c on hdg while using bank to prevent side slip. The TSI will show:\",\"opts\":[\"both needle and ball central\",\"Both needle and ball to the right\",\"Needle central and ball to the right.\"],\"ans\":2,\"exp\":\"Right rudder holds the yaw and the wings are banked a few degrees towards the live (right) engine to remove sideslip. The fin side force is then balanced by that bank, so the ball sits about half a width towards the live engine (right), while the needle stays central because the aircraft is not turning.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-675\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"The rate gyro in a turn indicator has:\",\"opts\":[\"one degree of freedom\",\"two degrees of freedom\",\"three degrees of freedom\",\"no degrees of freedom\"],\"ans\":0,\"exp\":\"A rate gyro has one gimbal and is spring-restrained: it is free about one axis only and measures rate of turn by its precession. Displacement gyros (DGI, artificial horizon) have two.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Jun 2025 · Regular 02\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":3,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-676\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"The rate at which the earth rotates (earth rate) is about:\",\"opts\":[\"15 deg per hour\",\"1 deg per hour\",\"4 deg per minute\",\"30 deg per hour\"],\"ans\":0,\"exp\":\"360 deg in about 24 h = 15 deg/h (1 deg every 4 minutes). A gyro sees the vertical component of it, 15 sin lat deg/h, as apparent wander.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-677\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"An air-driven DGI is corrected for apparent wander at 56 deg N. The pilot keeps the DGI reading constant while flying south from 56 N. The true heading will:\",\"opts\":[\"increase\",\"decrease\",\"remain constant\",\"oscillate\"],\"ans\":1,\"exp\":\"The latitude correction is set for 56 N; further south the earth rate is smaller, so the fixed correction over-corrects and the DGI reading creeps up. Holding the reading constant, the pilot is actually turning left - the true heading decreases.\",\"seenIn\":[\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-678\",\"topic\":\"Gyros & Heading Instruments\",\"stem\":\"Compared with a directional gyro, a rate gyro:\",\"opts\":[\"has two degrees of freedom and shows heading\",\"has one degree of freedom and is spring-restrained, measuring rate of turn\",\"has a vertical spin axis\",\"is an earth gyro\"],\"ans\":1,\"exp\":\"A rate gyro has one gimbal restrained by a spring; the precession torque in a turn is balanced by the spring, so the deflection measures rate of turn. A DGI is a free (displacement) gyro with two gimbals showing heading.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-679\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"To double the range of a primary radar the power must be increased by a factor of:\",\"opts\":[\"2\",\"4\",\"16\"],\"ans\":2,\"exp\":\"Radar range varies as the fourth root of transmitted power, so doubling range needs 2^4 = 16 times the power.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Aug 2023 · OLODE\",\"Nov 2023 · OLODE (29 Nov)\",\"Mar 2024 · Regular 01\",\"Jun 2024 · Regular\",\"Jul 2024 · OLODE 05\",\"Mar 2025 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":8,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-680\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"SSR: the ground interrogator transmits on ...... and the aircraft transponder replies on ......:\",\"opts\":[\"1030 MHz; 1090 MHz\",\"1090 MHz; 1030 MHz\",\"960 MHz; 1215 MHz\",\"9375 MHz; 9375 MHz\"],\"ans\":0,\"exp\":\"Interrogation 1030 MHz up, reply 1090 MHz down - UHF, secondary radar.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Nov 2023 · OLODE (29 Nov)\",\"Mar 2024 · Regular 01\",\"Sep 2024 · Regular 03\",\"Mar 2025 · Regular 01\",\"Jun 2025 · Regular 02\",\"Feb 2026 · OLODE 02\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":8,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-681\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"The maximum range of primary radar depends on:\",\"opts\":[\"wave length\",\"pulse recurrence frequency\",\"frequency\",\"pulse length\"],\"ans\":1,\"exp\":\"The maximum unambiguous range of a pulse radar is set by the pulse recurrence frequency (range = c / 2 PRF); a higher PRF means a shorter maximum range.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Dec 2024 · Regular 04\",\"Mar 2025 · Regular 01\",\"May 2025 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":7,\"years\":[2022,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-682\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"During a flight at night a position has to be reported to ATC. The aeroplane is at a distance of 750 NM from the ground station and at flight level 350. The frequency to be used is:\",\"opts\":[\"17286KHz\",\"123.9MHz\",\"5649KHz\",\"11360 kHz\"],\"ans\":2,\"exp\":\"VHF range at FL350 is only about 230 NM, so 750 NM needs HF. At night the D layer disappears and lower HF frequencies refract best, so the lower frequency 5649 kHz is used (17286 kHz is the daytime frequency).\",\"seenIn\":[\"Jan 2019\",\"Jun 2023 · Regular\",\"Nov 2023 · OLODE (29 Nov)\",\"Dec 2023 · Regular\",\"May 2024 · OLODE 04\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":6,\"years\":[2019,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-683\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"If a radar has a beam width of 3 deg and a pulse of 4 microseconds, the target azimuth resolution at a range of 60 nm will be approximately\",\"opts\":[\"4 nm\",\"3 nm\",\"6 nm\"],\"ans\":1,\"exp\":\"Azimuth resolution = range x beam width (radians) = 60 NM x 0.0524 = about 3.1 NM; the pulse length affects range resolution, not azimuth.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Aug 2024 · OLODE 06\",\"Jul 2025 · OLODE 05\",\"May 2026 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":5,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-684\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"A secondary radar requires:\",\"opts\":[\"a target that responds, always an aircraft\",\"a target that responds, always on the ground\",\"a target that responds - an aircraft or a ground transponder\",\"a quiescent target\"],\"ans\":2,\"exp\":\"Secondary radar works by interrogation and reply. In SSR the aircraft replies; in DME the ground beacon does.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Dec 2023 · Regular\",\"Jun 2024 · Regular\",\"May 2025 · OLODE 04\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-685\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"SSR code for emergency ______, unlawful interference ______ & radio communication failure ______ ?\",\"opts\":[\"7500, 7600, 7700\",\"7700, 7500, 7600\",\"7600, 7700, 7500\"],\"ans\":1,\"exp\":\"Emergency 7700, unlawful interference 7500, radio communication failure 7600.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Sep 2023 · Regular 03\",\"Nov 2023 · OLODE (29 Nov)\",\"May 2024 · OLODE 04\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":5,\"years\":[2021,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-686\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"A radio aid has a wavelength of 2.4 m.the frequency is:\",\"opts\":[\"12.5 MHz\",\"72 MHz\",\"720 MHz\",\"125 MHz\"],\"ans\":3,\"exp\":\"Frequency = 300 / wavelength (m) = 300 / 2.4 = 125 MHz.\",\"seenIn\":[\"Jan 2019\",\"Oct 2023 · OLODE\",\"Mar 2025 · Regular 01\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2019,2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-687\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"How many codes assigned in Mode A?\",\"opts\":[\"4000\",\"4096\",\"3600\"],\"ans\":1,\"exp\":\"Mode A uses four octal digits: 8 x 8 x 8 x 8 = 4096 codes.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jun 2023 · Regular\",\"Sep 2023 · Regular 03\",\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":4,\"years\":[2021,2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-688\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"Which of the following is NOT an advantage of primary radar over secondary radar?\",\"opts\":[\"it needs no equipment in the aircraft\",\"it detects weather and aircraft without transponders\",\"it gives the aircraft's identity and pressure altitude\",\"it is independent of the target's cooperation\"],\"ans\":2,\"exp\":\"Primary radar detects reflections from anything, cooperating or not, but it cannot tell who the target is or its altitude - that is what SSR adds.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2022,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-689\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"SSR Mode C altitude as displayed to the controller is accurate to within:\",\"opts\":[\"+/- 25 ft\",\"+/- 50 ft\",\"+/- 75 ft\",\"+/- 100 ft\"],\"ans\":1,\"exp\":\"Mode C reports pressure altitude (1013.25) in 100 ft steps, so the displayed figure is within +/- 50 ft of the encoder value.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Jun 2025 · Regular 02\",\"Jul 2025 · OLODE 05\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-690\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"If no SSR code has been assigned by ATC, the transponder should be set to:\",\"opts\":[\"7000\",\"2000\",\"7500\",\"1200\"],\"ans\":1,\"exp\":\"ICAO procedures: 2000 when no instruction has been received from ATC (7000 is used as the VFR conspicuity code in some regions).\",\"seenIn\":[\"Jun 2023 · Regular\",\"Jul 2023 · OLODE\",\"Jun 2024 · Regular\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-691\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"Which SSR code is used for radio communication failure?\",\"opts\":[\"7600\",\"7500\",\"7700\"],\"ans\":0,\"exp\":\"SSR codes: 7700 emergency, 7600 radio communication failure, 7500 unlawful interference.\",\"seenIn\":[\"Mar 2022\",\"Nov 2023 · OLODE (30 Nov)\",\"Apr 2024 · OLODE 03\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2022,2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-692\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"The skip distance of an HF sky wave increases when:\",\"opts\":[\"the frequency is increased (and at night, when the layer is higher)\",\"the frequency is decreased\",\"attenuation increases\",\"absorption increases\"],\"ans\":0,\"exp\":\"A higher frequency is refracted less, so it returns further away; at night the reflecting layer is higher, which also lengthens the skip.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Apr 2024 · OLODE 03\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-693\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"The minimum range of radar depends on\",\"opts\":[\"Pulse repetition frequency\",\"Pulse width\",\"Pulse repetition time\"],\"ans\":1,\"exp\":\"The minimum range of a pulse radar is set by the pulse length (the receiver cannot listen while transmitting).\",\"seenIn\":[\"Mar 2022\",\"Jun 2023 · Regular\",\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":3,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-694\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"A Doppler navigation system measures the aircraft's drift and groundspeed from:\",\"opts\":[\"DVOR signals\",\"phase comparison of ground station signals\",\"the frequency shift of its own signals reflected from the ground\",\"DME range changes\"],\"ans\":2,\"exp\":\"Beams are aimed at the ground ahead/behind and sideways; the Doppler shift of the echoes gives speed along and across the aircraft axis - groundspeed and drift.\",\"seenIn\":[\"May 2022\",\"Mar 2023 · ATPL\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-695\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"The bearing of a primary radar target is measured by:\",\"opts\":[\"phase comparison\",\"the searchlight principle\",\"lobe comparison\",\"DF techniques\"],\"ans\":1,\"exp\":\"The narrow beam rotates like a searchlight; the bearing is the direction the aerial points when the echo returns.\",\"seenIn\":[\"Mar 2025 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-696\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"It is intended to increase the range of a VHF transmitter from 50 NM to 100 NM. This will be achieved by increasing the power output by a factor of\",\"opts\":[\"8\",\"16\",\"4\"],\"ans\":2,\"exp\":\"For one-way radio communication the signal strength falls with the square of distance, so doubling the range needs four times the power.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-697\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"The maximum range of a ground radar is limited by\",\"opts\":[\"peak power\",\"average power\",\"pulse recurrence rate\"],\"ans\":2,\"exp\":\"Maximum unambiguous range = c / (2 x PRF), so it is limited by the pulse recurrence rate.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-698\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"The wavelength of a 5035 MHz signal is about:\",\"opts\":[\"6 cm\",\"60 cm\",\"6 m\",\"0.6 cm\"],\"ans\":0,\"exp\":\"Wavelength = 300 / f(MHz) metres = 300 / 5035 = 0.06 m = 6 cm (an MLS frequency).\",\"seenIn\":[\"Jul 2024 · OLODE 05\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-699\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"Which is NOT an advantage of SSR over primary radar?\",\"opts\":[\"much less transmitter power is needed\",\"no weather clutter on the display\",\"identity and altitude are shown\",\"it shows weather returns\"],\"ans\":3,\"exp\":\"SSR receives transponder replies (one-way path, so far less power) and therefore sees no weather or ground clutter - which is also why it cannot show weather.\",\"seenIn\":[\"Aug 2024 · OLODE 06\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-700\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"Which statement about SSR Mode S is UNTRUE?\",\"opts\":[\"it can address individual aircraft selectively\",\"it uses just twice as many codes as Modes A and C\",\"it works together with Modes A and C\",\"it supports data link\"],\"ans\":1,\"exp\":\"Mode S gives every aircraft a unique 24-bit address (about 16.7 million), not \\\"twice\\\" the 4096 Mode A codes; it interrogates selectively, is compatible with A/C and carries data link.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-701\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"An aircraft at 2500 ft wants to talk to a VHF station at 196 ft AMSL. The maximum line-of-sight range is about:\",\"opts\":[\"80 NM\",\"64 NM\",\"52 NM\",\"65 NM\"],\"ans\":0,\"exp\":\"1.23 (sqrt 2500 + sqrt 196) = 1.23 (50 + 14) = 79 NM.\",\"seenIn\":[\"Sep 2024 · Regular 03\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-702\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"Primary radar measures range by:\",\"opts\":[\"phase comparison\",\"the pulse (echo-timing) technique\",\"frequency shift\",\"transponder interrogation\"],\"ans\":1,\"exp\":\"Range = speed of light x time to the echo / 2; bearing comes from the aerial direction (searchlight principle).\",\"seenIn\":[\"Jan 2025 · OLODE 01\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-703\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"The average height of the E layer is about ...... and the maximum single-hop sky-wave range from it about ......:\",\"opts\":[\"60 km, 1350 NM\",\"125 km, 2200 km\",\"225 km, 2200 km\",\"125 km, 1350 NM\"],\"ans\":3,\"exp\":\"E layer about 125 km; with the wave grazing the horizon, the longest single hop is about 1350 NM (2500 km). The F layer, being higher, gives about 2200 NM.\",\"seenIn\":[\"Jun 2025 · Regular 02\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":2,\"years\":[2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-704\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"ATC asks a pilot to stop Mode C (SSR altitude) when, after the pressure setting is checked, the displayed level still differs from the reported level by more than:\",\"opts\":[\"+/- 200 ft in RVSM airspace (+/- 300 ft elsewhere)\",\"+/- 50 ft\",\"+/- 100 ft\",\"+/- 500 ft\"],\"ans\":0,\"exp\":\"PANS-ATM 8.5.5: tolerance +/- 200 ft (60 m) in RVSM airspace, +/- 300 ft (90 m) elsewhere; outside it the pilot checks the setting and, if it persists, is asked to stop Mode C.\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-705\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"SSR interrogations are sent as pairs of pulses (P1-P3) in order to:\",\"opts\":[\"prevent random noise being transmitted\",\"suppress side lobes\",\"indicate the mode of interrogation\",\"double the power\"],\"ans\":2,\"exp\":\"The spacing between P1 and P3 tells the transponder which mode is wanted (8 us Mode A, 21 us Mode C). Side-lobe suppression uses P2.\",\"seenIn\":[\"Mar 2022\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2022,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-706\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"A radio wave of wavelength 3 cm has a frequency of:\",\"opts\":[\"10 GHz\",\"1 GHz\",\"100 MHz\",\"3 GHz\"],\"ans\":0,\"exp\":\"f = c / wavelength = 300,000,000 / 0.03 = 10,000,000,000 Hz = 10 GHz (SHF - weather radar region).\",\"seenIn\":[\"Mar 2022\",\"Aug 2024 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-707\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"For a phase comparison between two electromagnetic waves, the waves must have the same:\",\"opts\":[\"amplitude\",\"frequency\",\"amplitude and frequency\",\"phase\"],\"ans\":1,\"exp\":\"If the frequencies differ, the phase relationship keeps changing and the comparison means nothing. Amplitude does not matter.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-708\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"When a transmitter and receiver move apart, the frequency received is:\",\"opts\":[\"higher than transmitted\",\"lower than transmitted\",\"the same\",\"zero\"],\"ans\":1,\"exp\":\"Doppler effect: relative motion apart lowers the received frequency, together raises it. Doppler navigation measures this shift.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-709\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"In relation to radar systems that use pulse technology, the term 'pulse recurrence rate (PRR)' signifies the:\",\"opts\":[\"Delay after which the process re-starts\",\"Number of pulses per second\",\"The number of cycles per second\",\"Ratio of pulse period to pulse width\"],\"ans\":1,\"exp\":\"Pulse recurrence rate (PRR or PRF) is the number of pulses transmitted per second.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-710\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"The minimum range of a primary radar, using the pulse technique, is determined by the i)_____, the maximum unambiguous range by the ii)______?\",\"opts\":[\"i) Transmission frequency ii) transmitter power output\",\"i) Pulse length ii) length of time base\",\"i) Pulse length ii) PRF\",\"i) Transmission frequency ii) PRF\"],\"ans\":2,\"exp\":\"Minimum range is set by pulse length, maximum unambiguous range by PRF.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-711\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"The speed of radio wave?\",\"opts\":[\"300 km/sec\",\"300 million m/sec\",\"162 nm/sec\",\"162 million nm/sec\"],\"ans\":1,\"exp\":\"Radio waves travel at about 300 million metres per second.\",\"seenIn\":[\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-712\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"HF sky waves used for long-range communication are mainly refracted back to earth by the:\",\"opts\":[\"D layer\",\"E layer\",\"F layer\",\"troposphere\"],\"ans\":2,\"exp\":\"The F layer (150-400 km) returns HF; the D layer mostly absorbs (by day) and disappears at night; the E layer weakens at night.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-713\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"What is untrue about frequency?\",\"opts\":[\"frequency increase, skip distance increases\",\"frequency increase, dead space increases\",\"frequency increase, absorption increases\"],\"ans\":2,\"exp\":\"The correct answer is: frequency increase, absorption increases.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-714\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"The transponder code 7004\",\"opts\":[\"Aerobatic and display code countries\",\"Military intercept code\",\"VFR standard squawk.code when no other code has been assigned\",\"none\"],\"ans\":0,\"exp\":\"SSR code 7004 is the aerobatic and display code (in some countries).\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-715\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"Express 100 kHz in m.\",\"opts\":[\"3000 M\",\"3000 Cm\",\"300 M\",\"100 M\"],\"ans\":0,\"exp\":\"Wavelength = 300 / f(MHz) = 300 / 0.1 = 3,000 m.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-716\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"Which of the following statements is correct in respect of a RF signal:\",\"opts\":[\"the plane of polarisation is dictated by the oscillator unit in the transmitter.\",\"the electrical component of the signal is parallel to the aerial.\",\"the magnetic component of the signal is parallel to the aerial.\",\"both the electrical and magnetic components are parallel to the aerial.\"],\"ans\":1,\"exp\":\"The plane of polarisation is that of the electric field, parallel to a vertical aerial.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-717\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"Airborne weather radar uses a wavelength of about 3 cm because:\",\"opts\":[\"it penetrates cloud completely\",\"it reflects from the larger water droplets (precipitation), not from small cloud droplets\",\"it reflects from all cloud droplets\",\"it gives the longest range\"],\"ans\":1,\"exp\":\"A 3 cm wave is comparable to large raindrops and wet hail, so it shows the dangerous precipitation inside a Cb while ignoring harmless cloud.\",\"seenIn\":[\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-718\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"Doppler navigation systems are affected by heavy precipitation mainly because:\",\"opts\":[\"rain absorbs all the signal\",\"rain scatters the beams, giving returns from moving raindrops instead of the ground\",\"rain changes the transmitted frequency\",\"rain blocks the GPS\"],\"ans\":1,\"exp\":\"The SHF beams are reflected (scattered) by heavy rain; echoes from falling, wind-driven drops carry their own Doppler shift and corrupt the ground-speed/drift solution.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-719\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"EM wave consist of\",\"opts\":[\"electric wave alternating with magnetic wave\",\"electric wave perpendicular to magnetic wave\",\"electric and magnetic waves in the same plane\"],\"ans\":1,\"exp\":\"In a radio wave the electric and magnetic fields are at right angles to each other and to the direction of travel.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-720\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"The range of a radar target is given by:\",\"opts\":[\"speed of light x time to echo\",\"speed of light x time to echo / 2\",\"PRF x pulse width\",\"time / speed of light\"],\"ans\":1,\"exp\":\"The pulse goes out and back, so range = c x t / 2 (about 12.36 us per NM).\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-721\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"An airborne weather radar typically operates at about ...... (wavelength about ......):\",\"opts\":[\"9375 MHz; 3.2 cm\",\"4300 MHz; 7 cm\",\"1030 MHz; 29 cm\",\"13.3 GHz; 2.3 cm\"],\"ans\":0,\"exp\":\"AWR: 9375 MHz (SHF), wavelength 300/9375 = 0.032 m = 3.2 cm.\",\"seenIn\":[\"May 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-722\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"A wavelength of 1200 m lies in the ...... band\",\"opts\":[\"UHF\",\"LF\",\"HF\",\"MF\"],\"ans\":1,\"exp\":\"f = 300,000 / 1200 = 250 kHz - LF (30-300 kHz).\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-723\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"At night, which ionospheric layer disappears?\",\"opts\":[\"the D layer\",\"the E layer\",\"the F2 layer\",\"the F1 layer\"],\"ans\":0,\"exp\":\"Without the sun the low, dense D layer de-ionises and vanishes, so MF/HF sky waves are no longer absorbed - night sky waves travel further. The E layer weakens and F1 and F2 merge into one F layer, higher up.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-724\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"An aircraft at 9000 ft and a VHF/DF station at 400 ft AMSL. The maximum range is about:\",\"opts\":[\"115 NM\",\"143 NM\",\"63.5 NM\",\"400 NM\"],\"ans\":1,\"exp\":\"1.25 (sqrt 9000 + sqrt 400) = 1.25 (95 + 20) = 143 NM (1.23 gives 141).\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-725\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"On a colour weather radar the colours from weakest to strongest returns are:\",\"opts\":[\"red, yellow, green\",\"green, yellow, red (magenta strongest on some displays)\",\"yellow, green, red\",\"red, green, yellow\"],\"ans\":1,\"exp\":\"Green light precipitation, yellow moderate, red heavy (magenta extreme/turbulence). Avoid red cells by a wide margin.\",\"seenIn\":[\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-726\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"The maximum range of a VHF radio signal depends mainly on:\",\"opts\":[\"the heights of transmitter and receiver (line of sight) and the power\",\"the time of day\",\"the ionosphere\",\"the PRF\"],\"ans\":0,\"exp\":\"VHF travels by direct (space) wave, so range is set by line of sight: 1.23 (sqrt h1 + sqrt h2) NM, within the transmitter power.\",\"seenIn\":[\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-727\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"Primary radar works on the principle of ......; secondary radar works on ......:\",\"opts\":[\"interrogation and reply; the reflected echo\",\"the reflected echo; interrogation and transponder reply\",\"Doppler shift; phase comparison\",\"phase comparison; the reflected echo\"],\"ans\":1,\"exp\":\"Primary radar needs nothing on board: it detects its own pulse reflected from the target. Secondary radar transmits an interrogation and the aircraft transponder transmits a coded reply on another frequency (1030 MHz up, 1090 MHz down).\",\"seenIn\":[\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-728\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"When the SSR transponder IDENT button is pressed:\",\"opts\":[\"a momentary mark appears on the screen\",\"an identification pulse (SPI) is transmitted for about 20 s, 4.35 us after the last framing pulse\",\"it transmits for 10 s before the framing pulse\",\"the code changes to 7700\"],\"ans\":1,\"exp\":\"The special position identification pulse is added 4.35 us after F2 for about 20 seconds, making the return stand out.\",\"seenIn\":[\"Aug 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-729\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"A ground station is at 2500 ft AMSL. What minimum height must an aircraft have to receive it at 300 NM?\",\"opts\":[\"about 37,600 ft\",\"about 25,000 ft\",\"about 16,000 ft\",\"about 60,000 ft\"],\"ans\":0,\"exp\":\"300 = 1.23 (sqrt 2500 + sqrt h) = 1.23 (50 + sqrt h): sqrt h = 194, h = 37,600 ft.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-730\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"SSR ground interrogator sends ____ and receives signal at _____\",\"opts\":[\"1030, 1090\",\"1090, 1030\"],\"ans\":0,\"exp\":\"The SSR ground interrogator transmits on 1030 MHz and the airborne transponder replies on 1090 MHz.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-731\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"A moving target indicator (MTI) rejects stationary echoes by:\",\"opts\":[\"comparing successive returns and cancelling those that do not change (no Doppler shift)\",\"using a narrower beam\",\"jittering the PRF\",\"increasing power\"],\"ans\":0,\"exp\":\"MTI subtracts each sweep from the previous one; fixed echoes cancel, moving targets (with a phase/Doppler change) remain. PRF stagger removes blind speeds - it does not itself reject clutter.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-732\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"Which of these is NOT an advantage of a slotted (phased array) radar aerial?\",\"opts\":[\"reduced side lobes\",\"improved resolution\",\"reduced power\",\"directivity\"],\"ans\":3,\"exp\":\"A flat slotted array gives smaller side lobes, a narrower beam (better resolution) and needs less power for the same performance; directivity is a property of any radar dish, not an added advantage.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-733\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"The aerial of an airborne weather radar is stabilised in:\",\"opts\":[\"pitch, roll and yaw\",\"roll and yaw\",\"pitch and roll\",\"pitch only\"],\"ans\":2,\"exp\":\"Stabilisation keeps the scan level with the horizon as the aircraft pitches and rolls; heading changes just rotate the picture.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-734\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"To improve the resolution of a radar display requires:\",\"opts\":[\"a narrow pulse width and a narrow beam width\",\"a high frequency and a large reflector\",\"a wide beam and wide pulse\",\"a low frequency and narrow pulse\"],\"ans\":0,\"exp\":\"Range resolution depends on pulse width; bearing (azimuth) resolution on beam width - both narrower is better.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-735\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"A radar has a pulse recurrence interval of 2100 us. Its maximum unambiguous range is about:\",\"opts\":[\"170 NM\",\"315 NM\",\"340 NM\",\"630 NM\"],\"ans\":0,\"exp\":\"Range = c x PRI / 2 = 300,000 km/s x 0.0021 s / 2 = 315 km = 170 NM. (PRF 450 pps gives 333 km = 180 NM.)\",\"seenIn\":[\"Aug 2024 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-736\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"Surface-wave attenuation over the earth:\",\"opts\":[\"decreases as frequency increases\",\"increases as frequency increases, so LF travels furthest\",\"is the same at all frequencies\",\"is greatest over the sea\"],\"ans\":1,\"exp\":\"The higher the frequency, the more the surface wave loses energy into the ground; LF/MF (NDBs) have long surface-wave ranges, and the sea attenuates least.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-737\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"In HF sky-wave propagation the \\\"critical ray\\\" is:\",\"opts\":[\"the first sky wave to return to earth, at the critical angle - it defines the skip distance\",\"the surface wave\",\"the ray that penetrates the ionosphere\",\"the direct wave\"],\"ans\":0,\"exp\":\"The correct answer is: the first sky wave to return to earth, at the critical angle - it defines the skip distance.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-738\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"A primary radar echo returns 2000 microseconds after the pulse was transmitted. The range of the target is about:\",\"opts\":[\"81 NM\",\"162 NM\",\"324 NM\",\"600 NM\"],\"ans\":1,\"exp\":\"A radar mile (out and back for 1 NM) takes 2 x 1852 m / 300,000 km/s = 12.36 microseconds. 2000 / 12.36 = about 162 NM.\",\"seenIn\":[\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-739\",\"topic\":\"Radio Waves, Radar & SSR\",\"stem\":\"In frequency modulation (FM):\",\"opts\":[\"the amplitude of the carrier varies with the signal\",\"the frequency of the carrier varies with the signal while its amplitude stays constant\",\"the carrier is switched on and off\",\"two carriers are compared in phase\"],\"ans\":1,\"exp\":\"FM varies the carrier frequency in step with the audio/data; AM varies the amplitude. FM is less affected by static noise.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-740\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Compass heading: 270° Deviation: 2° W Variation: 30° E Relative bearing: 316° What is the QDR?\",\"opts\":[\"224°\",\"044°\",\"046°\"],\"ans\":1,\"exp\":\"MH = 270 - 2 = 268; QDM = MH + RB = 268 + 316 = 584 - 360 = 224; QDR = QDM +/- 180 = 044.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"May 2024 · OLODE 04\",\"Jul 2024 · OLODE 05\",\"Mar 2025 · Regular 01\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":5,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-741\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"In a Doppler VOR (DVOR), the reference signal is ______, the bearing signal is ______ and the direction of rotation of the bearing signal is ______\",\"opts\":[\"AM, FM, anti-clockwise\",\"AM, FM, clockwise\",\"FM, AM, anti-clockwise\"],\"ans\":0,\"exp\":\"In a Doppler VOR the reference signal is amplitude modulated, the bearing (variable) signal is frequency modulated and its rotation is anti-clockwise.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jan 2024 · Regular (Day 2)\",\"Jul 2025 · OLODE 05\",\"Aug 2025 · OLODE 06\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":5,\"years\":[2021,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-742\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Which disturbance is most likely to cause the greatest inaccuracy in ADF bearings?\",\"opts\":[\"local thunderstorm activity\",\"coastal effect\",\"quadrantal error\",\"precipitation interference\"],\"ans\":0,\"exp\":\"A Cb is a huge source of LF/MF static and can swing the ADF needle towards itself - the largest single error. Coastal refraction and quadrantal error are smaller and predictable.\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Jun 2025 · Regular 02\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-743\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"ADF bearing by the day within the published range should be accurate within maximum error of\",\"opts\":[\"+/- 5\",\"+/- 2\",\"+/- 10\"],\"ans\":0,\"exp\":\"By day, within the published range, ADF bearings should be accurate to +/- 5 deg.\",\"seenIn\":[\"May 2022\",\"Mar 2023 · ATPL\",\"Jun 2023 · Regular\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2022,2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-744\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"When converting bearings to true, the variation is applied at ...... for a VOR and at ...... for an ADF bearing:\",\"opts\":[\"the aircraft; the aircraft\",\"the aircraft; the station\",\"the station; the aircraft\",\"the station; the station\"],\"ans\":2,\"exp\":\"A VOR radial is measured at the station against magnetic north there; an ADF bearing is measured at the aircraft (heading + RB) with the aircraft's compass.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-745\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"The allocated frequency band of NDBs is:\",\"opts\":[\"250-450 kHz\",\"190-1750 kHz\",\"108-117.95 MHz\",\"2-20 MHz\"],\"ans\":1,\"exp\":\"NDBs use LF/MF, 190-1750 kHz (the ADF receiver tunes the same band). 108-117.95 MHz is VOR/ILS localiser.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-746\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"DME is a ...... radar operating at about ...... in the ...... band.\",\"opts\":[\"primary, 8800 MHz, SHF\",\"secondary, 1030 MHz, UHF\",\"secondary, 962-1213 MHz, UHF\",\"primary, 9375 MHz, SHF\"],\"ans\":2,\"exp\":\"The aircraft interrogates and the ground beacon replies (secondary radar), on UHF channels between about 960 and 1215 MHz - roughly 1000 MHz.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Jun 2024 · Regular\",\"Mar 2025 · Regular 01\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-747\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft at FL360 is 10 NM plan range from a DME. The DME reads about:\",\"opts\":[\"8 NM\",\"11.7 NM\",\"10 NM\",\"13.6 NM\"],\"ans\":1,\"exp\":\"Height = 36,000 / 6076 = 5.9 NM. Slant range = sqrt(10^2 + 5.9^2) = 11.6 NM. Slant-range error is small once the range exceeds about 3 x height in thousands of feet.\",\"seenIn\":[\"Oct 2023 · OLODE\",\"Sep 2024 · Regular 03\",\"Mar 2026 · Regular 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-748\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An NDB transmits a signal pattern that is:\",\"opts\":[\"a 30 Hz polar diagram\",\"omni-directional\",\"a bi-lobal pattern\",\"a beam rotating at 30 Hz\"],\"ans\":1,\"exp\":\"The NDB radiates equally in all directions; the direction-finding is done in the aircraft by the ADF loop and sense aerials.\",\"seenIn\":[\"Dec 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\",\"Jun 2024 · Regular\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-749\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An ADF uses a sense aerial to:\",\"opts\":[\"determine the null position.\",\"detect the receiver test signal.\",\"resolve ambiguous bearings.\",\"transmit the beacon ident.\"],\"ans\":2,\"exp\":\"The loop gives a bearing with 180 deg ambiguity; the sense aerial lets the ADF decide which of the two it is.\",\"seenIn\":[\"Jan 2019\",\"Aug 2023 · OLODE\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2019,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-750\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Quadrantal error associated with A/C ADF equipment are caused by\",\"opts\":[\"Signal bending by a/c metallic surface\",\"skywave/ ground wave contamination\",\"signal bending cause by electrical component\"],\"ans\":0,\"exp\":\"Quadrantal error is caused by the aircraft structure re-radiating (bending) the signal.\",\"seenIn\":[\"Mar 2023 · ATPL\",\"Jun 2023 · Regular\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-751\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An NDB transmits a NON/A1A signal (identification by keying an unmodulated carrier). To hear its ident the pilot must:\",\"opts\":[\"switch the BFO on\",\"switch the BFO off\",\"select the loop\",\"select ANT\"],\"ans\":0,\"exp\":\"A1A keying has no audio tone; the beat frequency oscillator mixes with the carrier to make it audible. NON/A2A beacons need no BFO for the ident.\",\"seenIn\":[\"Jan 2019\",\"May 2022\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2019,2022,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-752\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"The principal propagation path used by an NDB/ADF system is:\",\"opts\":[\"sky wave\",\"surface wave\",\"direct (space) wave\",\"ducted wave\"],\"ans\":1,\"exp\":\"LF/MF signals follow the earth's curvature as surface waves; sky waves at night cause night effect.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Oct 2023 · OLODE\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-753\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Coastal refraction error of an NDB bearing is least when:\",\"opts\":[\"the beacon is inland and the aircraft at high altitude\",\"the beacon is inland and the aircraft at low altitude\",\"the beacon is near the coast and the aircraft at high altitude\",\"the bearing crosses the coast at a shallow angle\"],\"ans\":2,\"exp\":\"Use a beacon close to the coast, a bearing that crosses the coast at about 90 deg, and fly high (the error falls with height).\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Jan 2024 · Regular (Day 2)\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-754\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"CDI with 3 dot deflection, where is the aircraft\",\"opts\":[\"6 from centerline\",\"along centerline\",\"3 degree from centerline\"],\"ans\":0,\"exp\":\"On a VOR indicator each dot is 2 deg, so 3 dots is 6 deg off the selected radial.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Nov 2023 · OLODE (30 Nov)\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2021,2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-755\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Aircraft is moving with constant heading, the adf needle moves from 45° to 90° in 6 mins If the aircraft is homing to the stn, tell the time aircraft will take to get to the stn\",\"opts\":[\"6mins\",\"12mins\",\"15 mins\"],\"ans\":0,\"exp\":\"Relative bearing going from 45 to 90 deg: the distance flown equals the distance abeam, so the time to the station from abeam equals the 6 minutes flown.\",\"seenIn\":[\"Jul 2024 · OLODE 05\",\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-756\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"You are overhead Mumbai airfield at FL120. Your DME will read\",\"opts\":[\"2 nm\",\"0 nm\"],\"ans\":0,\"exp\":\"Overhead the station the DME reads slant range = height: 12,000 ft = about 2 NM.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-757\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Radio bearings follow\",\"opts\":[\"rhumb line\",\"great circle\"],\"ans\":1,\"exp\":\"Radio waves follow great circle paths (the shortest route).\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Aug 2023 · OLODE\"],\"undated\":false,\"times\":2,\"years\":[2021,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-758\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Heading 060(M), ADF relative bearing 030. To intercept the 250 radial (QDR 250) inbound to the NDB with a 60 deg cut, the heading to steer is:\",\"opts\":[\"130\",\"250\",\"010\",\"070\"],\"ans\":0,\"exp\":\"QDM = 060 + 030 = 090, so the aircraft is on QDR 270. The inbound track for QDR 250 is 070; the aircraft is north of it, so turn right of 070 by 60: heading 130.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jun 2023 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-759\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft at 24380 ft, DME range 30 nm. What is the indicated (slant) range?\",\"opts\":[\"32.5 nm\",\"30.5 nm\",\"30.2 nm\"],\"ans\":2,\"exp\":\"Height 24,380 ft = 4.0 NM. Slant range = square root of (30 squared + 4.0 squared) = 30.3 NM, so the indicated range is about 30.2-30.3 NM.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-760\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"A DME ground beacon saturates (reaches its limit) at about:\",\"opts\":[\"20 aircraft\",\"100 aircraft (about 2700 pulse pairs per second)\",\"500 aircraft\",\"no limit\"],\"ans\":1,\"exp\":\"A beacon can answer about 2700 pulse pairs a second - roughly 100 aircraft. Beyond that it reduces its receiver sensitivity and ignores the weakest (furthest) interrogators.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2021,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-761\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"What is the accuracy of Class B?\",\"opts\":[\"±2°\",\"±5°\",\"±10°\"],\"ans\":1,\"exp\":\"VDF class A is +/- 2 deg, class B +/- 5 deg, class C +/- 10 deg.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-762\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"The allotted frequency coverage of NDBs is:\",\"opts\":[\"190-1750 kHz\",\"108-117.95 MHz\",\"250-450 kHz\"],\"ans\":0,\"exp\":\"NDBs/locators use 190-1750 kHz (VOR is 108-117.95 MHz).\",\"seenIn\":[\"Jun 2023 · Regular\",\"Apr 2024 · OLODE 03\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-763\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"The VOR system is limited to about 1° of accuracy at 200Nm represents a width of\",\"opts\":[\"2.5 Nm\",\"3.0 Nm\",\"3.5 Nm\"],\"ans\":2,\"exp\":\"One degree of error at 200 NM = 200 x tan 1 deg = 3.5 NM (1-in-60 rule gives about 3.3 NM).\",\"seenIn\":[\"Jun 2023 · Regular\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-764\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"OBS is set to 300 with to flying indicating , heading is 320 3 dot fly left what does CDI indicate if the flight turned in to reciprocal track\",\"opts\":[\"from, 3 dot fly right\",\"to, 3 dot fly right\",\"to, 3 dot fly left\"],\"ans\":2,\"exp\":\"The deviation indication depends only on position relative to the selected radial, not on heading, so turning to the reciprocal changes nothing: TO, 3 dots left.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jun 2023 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2021,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-765\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"A/C on heading 300M. OBS window indicates 300degree VOR CDI shows 3Dots deflection to the left & To/from indicates TO. A/C is now turned onto HDG 120 degree. OBS setting remains unchanged. What will the CDI indicate in this position?\",\"opts\":[\"CDI will show 3 dots deflection to the right\",\"To will change to indicate FROM\",\"There will be no change in VOR CDI Indications\"],\"ans\":2,\"exp\":\"A VOR/CDI shows the aircraft's position relative to the selected radial; it does not depend on the aircraft's heading, so turning the aircraft changes nothing.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-766\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Flying at the MOCA, acceptable navigation signal coverage is only assured within:\",\"opts\":[\"22 NM of the VOR\",\"40 NM of the VOR\",\"100 NM of the VOR\",\"the whole route segment\"],\"ans\":0,\"exp\":\"MOCA gives obstacle clearance on the whole segment but guarantees VOR signal coverage only within 22 NM (25 SM) of the VOR. MEA guarantees both for the whole segment.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-767\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"On an RMI whose compass deviation is not zero, the VOR needle indications are:\",\"opts\":[\"magnetic\",\"compass\",\"relative\",\"true\"],\"ans\":0,\"exp\":\"The VOR needle shows the magnetic bearing to the station derived from the VOR signal itself, so card deviation does not affect it (the ADF needle, which is relative bearing added to the card, would carry the deviation).\",\"seenIn\":[\"Sep 2024 · Regular 03\",\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":2,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-768\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"The accuracy of DME (DME/N) is about:\",\"opts\":[\"+/- 0.25 NM + 1.25 % of range\",\"+/- 3 % of range\",\"+/- 1.25 % of range\",\"+/- 0.5 NM\"],\"ans\":0,\"exp\":\"ICAO DME/N system accuracy: +/- 0.25 NM plus 1.25 % of the distance measured.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-769\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"The polar diagram of an ADF loop aerial alone is ...... ; combined with the sense aerial it becomes ......:\",\"opts\":[\"a cardioid; a figure of eight\",\"a figure of eight; a cardioid\",\"circular; a figure of eight\",\"a limacon; a circle\"],\"ans\":1,\"exp\":\"The loop gives a figure of eight with two nulls (180 deg ambiguity); adding the omni-directional sense aerial gives a cardioid with a single null, resolving the ambiguity.\",\"seenIn\":[\"Mar 2023 · ATPL\",\"Nov 2023 · OLODE (29 Nov)\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-770\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Identifying a co-located VOR/DME, you hear the ident four times in 30 seconds. The DME ident is:\",\"opts\":[\"the one at a higher pitch, heard once\",\"the one at a lower pitch, heard several times\",\"not transmitted - a range reading proves it\",\"the same tone each time\"],\"ans\":0,\"exp\":\"In each 30-40 s cycle the VOR identifies three times at 1020 Hz and the DME once at a higher tone (1350 Hz).\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Dec 2023 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-771\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"If an aircraft is traveling a distance of 140 NM and after 90 NM it experiences crosswinds with an ADF reading of 190, what is the total correction to reach the destination?\",\"opts\":[\"30° port\",\"30° starboard\",\"10° port or starboard\"],\"ans\":0,\"exp\":\"With ADF reading 190 the aircraft is 10 deg off track (track error). After 90 of 140 NM, closing angle = 10 x 90/50 = 18 deg; the total correction is about 30 deg, to port (the aircraft is right of track).\",\"seenIn\":[\"May 2024 · OLODE 04\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-772\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Errors caused by the effect of coastal refraction on bearings at lower altitudes are maximum when the NDB is:\",\"opts\":[\"inland and the bearing crosses the coast at an acute angle\",\"inland and the bearing crosses the coast at right angles\",\"near the coast and the bearing crosses the coast at right angles\"],\"ans\":0,\"exp\":\"Coastal refraction is worst when the bearing crosses the coastline at a shallow (acute) angle and the NDB is inland; at right angles there is no refraction error.\",\"seenIn\":[\"Jun 2023 · Regular\",\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-773\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"The phase of the VOR reference signal is 110 deg and of the variable signal 315 deg. The phase difference (radial) is:\",\"opts\":[\"205\",\"025\",\"155\",\"335\"],\"ans\":2,\"exp\":\"Phase difference = reference - variable = 110 - 315 = -205; add 360: 155. Always reference minus variable.\",\"seenIn\":[\"Mar 2023 · ATPL\",\"Jun 2024 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-774\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Tracking to an NDB on QDM 045, the ADF reads 354 relative. The drift is:\",\"opts\":[\"6 deg port\",\"6 deg starboard\",\"9 deg port\",\"nil\"],\"ans\":0,\"exp\":\"Heading = QDM - RB (as 354 = -6) = 045 + 6 = 051. Steering 6 deg right of track to hold it means the wind is from the right and the drift is 6 deg PORT.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-775\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft is on the 274 radial of a VOR (variation 10 W). The magnetic bearing (QDM) from the aircraft to the VOR is:\",\"opts\":[\"094\",\"084\",\"274\",\"104\"],\"ans\":0,\"exp\":\"Radials are magnetic bearings FROM the station. The QDM is the reciprocal: 094(M). Variation only matters when converting to true.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-776\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"In an ADF system, night effect is most pronounced:\",\"opts\":[\"during long winter nights\",\"at low altitude\",\"at high altitude\",\"at dusk and dawn\"],\"ans\":3,\"exp\":\"Night effect is sky-wave contamination as the ionosphere changes; it is worst when the D layer is forming or disappearing - around sunrise and sunset.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-777\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Homing to a VOR/DME, an aircraft loses 2500 ft while the DME range changes by 11.1 NM. The descent gradient is:\",\"opts\":[\"4.1 %\",\"3.5 %\",\"3.9 %\",\"3.7 %\"],\"ans\":3,\"exp\":\"2500 / (11.1 x 6076) = 0.037 = 3.7 %.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-778\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft at 35,000 ft passes directly over a DME station. The DME reads about:\",\"opts\":[\"0 NM\",\"5.8 NM\",\"3.5 NM\",\"35 NM\"],\"ans\":1,\"exp\":\"Overhead, the slant range is just the height: 35,000 / 6076 = 5.8 NM.\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-779\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"A conventional VOR has:\",\"opts\":[\"an FM reference signal and an AM variable signal\",\"a 150 Hz reference and a 90 Hz variable\",\"an AM reference and a 150 Hz variable\",\"an AM reference and an FM variable\"],\"ans\":0,\"exp\":\"Conventional VOR: reference 30 Hz carried as FM on a 9960 Hz subcarrier; variable 30 Hz AM produced by the rotating pattern. Doppler VOR reverses them.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-780\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"A standard (right-hand) holding pattern has an inbound track of 090. An aircraft arrives over the fix heading 250. Which entry should it fly?\",\"opts\":[\"direct\",\"offset (teardrop)\",\"parallel\",\"any of them\"],\"ans\":1,\"exp\":\"Measure the arrival heading against the inbound track: 250 - 090 = 160 deg. Right-hand hold: within -70 to +110 deg is direct, +110 to +180 offset (teardrop), +180 to +290 parallel. 160 falls in the offset sector.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-781\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft is passed a true bearing from a VDF station of 353 deg. If variation is 8 E and the bearing is classified as 'B', then the\",\"opts\":[\"QDM is 345 +/- 5\",\"QDR is 345 +/- 2\",\"QTE is 353 +/- 5\"],\"ans\":2,\"exp\":\"A bearing passed by a VDF station is a true bearing from the station (QTE). Class B accuracy is +/- 5 deg, so QTE 353 +/- 5. (QDR would be 345 magnetic and class A is +/- 2.)\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-782\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft is tracking inbound on the 105 radial. What should be set on the OBS?\",\"opts\":[\"285 TO\",\"285 FROM\"],\"ans\":0,\"exp\":\"To track inbound along the 105 radial the aircraft flies 285; the OBS is set to the inbound course, 285, with a TO flag.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-783\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft tracks due north (000 T) to a VOR, with 10 deg drift from an easterly wind. A second VOR lies exactly abeam to the right of track. Its relative bearing is:\",\"opts\":[\"080\",\"090\",\"270\",\"100\"],\"ans\":0,\"exp\":\"An easterly wind gives port drift, so heading = 010. The abeam station bears 090(T) from the aircraft: RB = 090 - 010 = 080.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-784\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Homing to a VOR on the 064 radial, the CDI shows 4 dots fly right with TO; the co-located DME reads 45 NM. The aircraft is:\",\"opts\":[\"6 NM right of track\",\"3 NM right of track\",\"6 NM left of track\",\"3 NM left of track\"],\"ans\":2,\"exp\":\"4 dots x 2 deg = 8 deg off. Fly-right means the track is to your right, so you are LEFT of it: 45 x 8 / 60 = 6 NM.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-785\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"A full-scale CDI deflection on a VOR indicates the aircraft is off the selected radial by:\",\"opts\":[\"5 deg\",\"10 deg or more\",\"15 deg\",\"20 deg\"],\"ans\":1,\"exp\":\"Full scale = 5 dots x 2 deg = 10 deg; the needle cannot show more, so it means \\\"10 or more\\\".\",\"seenIn\":[\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-786\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Heading 355(M). A feature is seen 30 deg left of the nose. The magnetic bearing of the aircraft FROM the feature is:\",\"opts\":[\"325\",\"145\",\"025\",\"205\"],\"ans\":1,\"exp\":\"Bearing to the feature = 355 - 30 = 325(M); from the feature to the aircraft is the reciprocal, 145(M) - the line you plot from the feature.\",\"seenIn\":[\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-787\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"A VOR's monitor removes the ident or switches the beacon off when the bearing information is in error by more than:\",\"opts\":[\"1 deg\",\"5 deg\",\"10 deg\",\"0.5 deg\"],\"ans\":0,\"exp\":\"The monitor checks a fixed radial; a shift of more than 1 deg (or loss of modulation) makes it remove the ident/transmission or change over to the standby.\",\"seenIn\":[\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-788\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Given: Magnetic heading 311° Drift angle 10° left Relative bearing of NDB 270° What is the magnetic bearing of the NDB measured from the aircraft?\",\"opts\":[\"211°\",\"208°\",\"221°\",\"180°\"],\"ans\":2,\"exp\":\"Magnetic bearing to the NDB = magnetic heading + relative bearing = 311 + 270 = 581 - 360 = 221. Drift does not enter.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-789\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Given magnetic heading 075', variation 4°W, drift angle 12°R, relative bearing to the station 270°. What is the true bearing of the aircraft from the station?\",\"opts\":[\"149°\",\"173°\",\"169°\",\"161°\"],\"ans\":3,\"exp\":\"Magnetic bearing to the station = 075 + 270 = 345; true = 345 - 4 = 341; from the station the aircraft is on 161.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-790\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Abeam a VOR, the bearing changes 10 deg in 5 min 30 s. Groundspeed 160 kt. The approximate distance to the VOR is:\",\"opts\":[\"88 NM\",\"15 NM\",\"160 NM\",\"33 NM\"],\"ans\":0,\"exp\":\"Time to station = time for the bearing change x 60 / degrees changed = 5.5 x 60 / 10 = 33 min. Distance = 160 x 33 / 60 = 88 NM.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-791\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Course Deviation Indicator (CDI) for a VOR is selected to 090 deg. The From/To indicator indicates TO. The CDI needle is deflected halfway to the right. On what radial is the aircraft?\",\"opts\":[\"095 deg\",\"275 deg\",\"085 deg\"],\"ans\":1,\"exp\":\"A TO flag with OBS 090 puts the aircraft west of the station (radial about 270). Half-scale deflection to the right is about 5 deg: the aircraft is on the 275 radial.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-792\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Plotting an ADF bearing on a Lambert chart, the bearing should be plotted:\",\"opts\":[\"from the NDB meridian, applying chart convergence\",\"from a line parallel to the aircraft's meridian, drawn through the NDB\",\"from the aircraft position directly\",\"from the mid-meridian\"],\"ans\":1,\"exp\":\"An ADF bearing is measured at the aircraft against the aircraft's meridian. Draw that meridian's direction through the NDB and plot the reciprocal from it; on a Lambert the straight line then approximates the great circle.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true,\"note\":\"Our independent check found that more than one option can be argued for, as worded in the recall. The key gives the answer most references support.\"},{\"id\":\"CPLNAV-793\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"On a cross-country from place A to B, distance 135 NM, due to crosswind the aircraft drifts and ADF reads 170° at a distance of 90 NM. How many degrees of heading correction should be applied to go direct to station B?\",\"opts\":[\"30° port\",\"30° starboard\",\"15° port\",\"15° starboard\"],\"ans\":1,\"exp\":\"ADF 170 on a track of 090 puts the aircraft 10 deg left of track; after 90 of 135 NM the closing angle is 10 x 90/45 = 20, so the total correction is 30 deg to starboard.\",\"seenIn\":[\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-794\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft heads 060(T) with 5 deg starboard drift, variation 3 deg W, and is tracking directly to a VOR. The QDM and the QDR are:\",\"opts\":[\"068 and 248\",\"065 and 245\",\"062 and 242\",\"248 and 068\"],\"ans\":0,\"exp\":\"Track = heading + starboard drift = 065(T); magnetic = 065 + 3W = 068(M). Flying TO the station, the magnetic track is the QDM: 068; the QDR (from the station) is the reciprocal, 248.\",\"seenIn\":[\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-795\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"QDM 047, variation 17 E. The QTE (true bearing from the station) is:\",\"opts\":[\"244\",\"227\",\"064\",\"210\"],\"ans\":0,\"exp\":\"QDR = 047 + 180 = 227(M); true = 227 + 17 (east) = 244 = QTE. (QUJ, true bearing TO the station, would be 064.)\",\"seenIn\":[\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-796\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Homing to a radio station is more practical for:\",\"opts\":[\"Long distance\",\"Short distance\",\"Both\"],\"ans\":1,\"exp\":\"Homing (keeping the ADF needle on the nose) curves the track downwind, so it is only practical over short distances.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-797\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"While tracking a VOR on an ADM, you receive the instruction: \\\"Hold north of VOR on the 360 radial for one standard hold pattern.\\\" Select the VOR OBS and outbound holding leg to/from QDM:\",\"opts\":[\"360 FROM\",\"360 TO\",\"180 TO\"],\"ans\":2,\"exp\":\"North of the VOR on the 360 radial the inbound leg is flown on 180 TO.\",\"seenIn\":[\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"As recalled, this question depended on a chart or table that is not reproduced here; the key is the recalled paper's answer.\"},{\"id\":\"CPLNAV-798\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"The maximum theoretical range at which an aircraft at FL80 can obtain bearings from ground VDF facility sites 325ft above MSL is:\",\"opts\":[\"114Nm\",\"107Nm\",\"133Nm\"],\"ans\":2,\"exp\":\"Range = 1.23 (sqrt 8000 + sqrt 325) = 1.23 (89.4 + 18.0) = 132 NM.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-799\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft on MH 190 and RB 340 given. Find RMI indication and tail\",\"opts\":[\"170 and tail 350\",\"350 and tail 170\"],\"ans\":0,\"exp\":\"RMI pointer = heading + relative bearing = 190 + 340 = 530 - 360 = 170; the tail is 350.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-800\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An a/c heading 140M bears 320T from a VOR variation 10E the bearing selection on the OBS should make the VOR/ILS deviation indicator show\",\"opts\":[\"120\",\"130\",\"320\"],\"ans\":1,\"exp\":\"The aircraft is on the 310 (magnetic) radial from the VOR (320 T - 10 E variation). To centre the needle with a TO flag the OBS is set to the reciprocal, 130.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-801\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An a/c on Hdg 340M with ADF reading 190 degree, what will be the indication by RMI\",\"opts\":[\"Pointer reads 170 & tail reads 350\",\"pointer reads 350 & tail reads 170\",\"point reads 150 & tail reads 330\"],\"ans\":0,\"exp\":\"RMI pointer shows the magnetic bearing to the station = heading + relative bearing = 340 + 190 = 530 - 360 = 170; the tail reads the reciprocal, 350.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-802\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Coastal error at its worst for an a/c at low level\",\"opts\":[\"beacon inland 90\",\"Beacon inland at an acute angle to coast\",\"beacon close to coast\"],\"ans\":1,\"exp\":\"Coastal refraction bends the signal where it crosses the shoreline obliquely, so the error is worst when the bearing crosses the coast at a shallow (acute) angle; at 90 deg there is none.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-803\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Morse code ident of DME is transmitted once every ____\",\"opts\":[\"10 sec\",\"20 sec\",\"30 sec\"],\"ans\":2,\"exp\":\"A DME ident is transmitted once every 30 seconds (the associated VOR three times in that period).\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-804\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"A/C hdg 170° M. ADF reading 345° Relative. Make 45° intercept of 355° Track Hdg to intercept will be ___ and ADF reading at the time of intercept will be __?\",\"opts\":[\"310°/ 175°\",\"135°/ 040°\",\"130°/045°\"],\"ans\":2,\"exp\":\"Present QDM = 170 + 345 - 360 = 155, so the aircraft is on the 335 radial, west of the 355 radial. Inbound on the 355 radial is QDM 175. A 45 deg intercept means heading 175 - 45 = 130, and on intercept the relative bearing is 175 - 130 = 045.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-805\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"In which frequency band do VOR transmitters operate?\",\"opts\":[\"SHF\",\"EHF\",\"VHF\"],\"ans\":2,\"exp\":\"VOR operates at 108-117.95 MHz, in the VHF band.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-806\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"aircraft is on radial 120 with a magnetic heading of 300°, the track selector (OBS) reads: 330. The indications on the Course Deviation Indicator (CDI) are:-\",\"opts\":[\"left with \\\"FROM\\\" showing\",\"left with \\\"TO\\\" showing\",\"right with \\\"TO\\\" showing\"],\"ans\":1,\"exp\":\"The aircraft is on radial 120, northeast of the 150 reference radial of course 330: needle left, TO flag.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-807\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"VOR scalloping is caused by:\",\"opts\":[\"mountains blocking the signal\",\"multipath reflections from terrain and buildings\",\"night effect\",\"precipitation\"],\"ans\":1,\"exp\":\"Reflected signals mix with the direct one and make the CDI needle wander rhythmically (scallop) along the radial.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-808\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"In a standard holding pattern the outbound leg time in still air is:\",\"opts\":[\"1 min at or below 14,000 ft, 1.5 min above\",\"1 min at all levels\",\"2 min above FL140\",\"1.5 min below 14,000 ft, 1 min above\"],\"ans\":0,\"exp\":\"PANS-OPS: 1 minute at or below 14,000 ft, 1 minute 30 seconds above 14,000 ft (adjusted for wind).\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-809\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"On a DME display the counters keep rotating continuously. This means the DME is:\",\"opts\":[\"in search mode, not yet locked on\",\"unserviceable\",\"overhead the station\",\"receiving no transmission at all\"],\"ans\":0,\"exp\":\"Until it recognises its own replies, the interrogator searches and the counters run; once locked on (track mode) a steady range is shown.\",\"seenIn\":[\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-810\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Heading 345(M), variation 20 E. An island is seen by radar 30 deg left of the nose. The bearing to plot from the island is:\",\"opts\":[\"160(T)\",\"155(T)\",\"140(T)\",\"180(T)\"],\"ans\":1,\"exp\":\"Bearing to the island = 345 - 30 = 315(M) = 335(T) (east variation added). Plot the reciprocal from the island: 155(T).\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-811\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft at the equator homes to a VOR on heading 090(T). Variation is 10 E at the aircraft and 15 E at the VOR. The radial the aircraft is on is:\",\"opts\":[\"255\",\"260\",\"270\",\"075\"],\"ans\":0,\"exp\":\"The aircraft is due west of the VOR: true bearing FROM the station 270. Radials use the station's variation: 270 - 15 E = 255.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-812\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"In an airborne dual-VOR check (two independent receivers), the maximum allowable difference between the two indications is:\",\"opts\":[\"+/- 4 deg\",\"+/- 6 deg\",\"+/- 1 deg\",\"+/- 10 deg\"],\"ans\":0,\"exp\":\"With both receivers tuned to the same VOR, the bearings must agree within 4 deg; a ground checkpoint allows +/- 4 deg, an airborne checkpoint +/- 6 deg.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true,\"note\":\"Our independent check could not confirm this answer from the official sources we hold; treat it with care and confirm with your instructor.\"},{\"id\":\"CPLNAV-813\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Airfield B is in the southern hemisphere. Its QTE to you is 315 and the earth convergency between you and B is 2 deg. The bearing to plot from B on a Mercator chart is:\",\"opts\":[\"316\",\"314\",\"317\",\"313\"],\"ans\":0,\"exp\":\"A QTE is a great-circle bearing; a Mercator straight line is a rhumb line. Apply the conversion angle (half convergency = 1 deg) towards the equator: the great circle lies on the pole side, so the rhumb line from B is 1 deg nearer north: 316.\",\"seenIn\":[\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-814\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"The main advantage of a Doppler VOR over a conventional VOR is:\",\"opts\":[\"longer range\",\"a large reduction in site error\",\"no need for a monitor\",\"operation at UHF\"],\"ans\":1,\"exp\":\"The wide-aperture aerial ring of a DVOR is much less affected by reflections near the site, so site error is greatly reduced.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-815\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Two NDBs are 20 NM and 50 NM inland. With the same coastal refraction, the position line error over the sea is:\",\"opts\":[\"greater from the 20 NM beacon\",\"greater from the 50 NM beacon\",\"the same from both at RB 180/360\",\"the same from both at RB 090/270\"],\"ans\":1,\"exp\":\"The same angular error produces a bigger lateral error the further the beacon is from the aircraft.\",\"seenIn\":[\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-816\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft flying at 290 kt groundspeed has the ADF reading 170 at 1200 and 210 at 1220. The distance flown is:\",\"opts\":[\"97 NM\",\"145 NM\",\"58 NM\",\"290 NM\"],\"ans\":0,\"exp\":\"Distance flown = GS x time = 290 x 20/60 = 97 NM; the bearings do not change that.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-817\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"A VOR has an accuracy of +/- 1 deg. At 200 NM the aircraft could be off the centreline by up to:\",\"opts\":[\"3.5 NM\",\"1.75 NM\",\"7 NM\",\"1 NM\"],\"ans\":0,\"exp\":\"200 x tan 1 = 3.5 NM (1 in 60: 200/60 = 3.3).\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-818\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"What is the minimum height for an aircraft to receive a VOR at 196 ft AMSL at a range of 175 NM?\",\"opts\":[\"26,000 ft\",\"16,000 ft\",\"24,000 ft\",\"20,000 ft\"],\"ans\":1,\"exp\":\"175 = 1.23 (sqrt 196 + sqrt h) = 1.23 (14 + sqrt h): sqrt h = 128, h = 16,400 ft - about 16,000.\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-819\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Fixing by bearings from an inland NDB while over the sea, the plotted position compared with the actual position is:\",\"opts\":[\"further from the coast\",\"closer to the coast\",\"the same\",\"random\"],\"ans\":1,\"exp\":\"Coastal refraction bends the wave towards the coast, so position lines plotted from it put you closer to the coast than you really are.\",\"seenIn\":[\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-820\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Coastal refraction: an NDB surface wave crossing from land to sea ...... and bends ...... the normal to the coast.\",\"opts\":[\"accelerates; towards\",\"decelerates; towards\",\"accelerates; away from\",\"decelerates; away from\"],\"ans\":2,\"exp\":\"Over water the surface wave travels faster, so it bends away from the normal (towards the coastline) - the bearing appears displaced towards the coast.\",\"seenIn\":[\"Aug 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-821\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"With 2 deg per dot, an aircraft 3 deg to the LEFT of the selected radial (TO, correct sensing) sees the CDI:\",\"opts\":[\"1.5 dots right\",\"1.5 dots left\",\"3 dots right\",\"centred\"],\"ans\":0,\"exp\":\"The needle shows where the course is: 3 deg off = 1.5 dots, on the right (fly right).\",\"seenIn\":[\"Oct 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-822\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"A VDF gives a true bearing from the station of 358, class B; variation 7 W. Which is correct?\",\"opts\":[\"QUJ 178 +/- 5\",\"QTE 358 +/- 5\",\"QDM 005 +/- 2\",\"QDR 358 +/- 2\"],\"ans\":1,\"exp\":\"True bearing from the station is the QTE; class B is +/- 5 deg. (QDM would be 178 + 7 = 185, QUJ 178.)\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":true,\"note\":\"As recalled, this question depended on a chart or table that is not reproduced here; the key is the recalled paper's answer.\"},{\"id\":\"CPLNAV-823\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Heading 90(M), ADF 60 what is the A/C bearing to station\",\"opts\":[\"150\",\"060\",\"030\"],\"ans\":0,\"exp\":\"Bearing to the station = heading + relative bearing = 090 + 060 = 150.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-824\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"The principle used in VOR bearing measurement is:\",\"opts\":[\"envelope matching\",\"phase comparison\",\"bearing by loop theory\"],\"ans\":1,\"exp\":\"VOR bearing is measured by phase comparison of the reference and variable signals.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-825\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"The coded identification of the VOR is transmitted about every ------ seconds:\",\"opts\":[\"20 seconds\",\"10 seconds\",\"30 seconds\"],\"ans\":1,\"exp\":\"A VOR transmits its identification in Morse (or voice) at least once every 10 seconds, so a pilot can confirm the station before using it.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-826\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"What is the minimum level that an aircraft, at a range of 113 NM, must fly in order to contact the tower on R/T for a VDF bearing from an airport sited 169 FT above MSL?\",\"opts\":[\"FL 60\",\"FL 50\",\"FL 80\"],\"ans\":0,\"exp\":\"Line-of-sight range = 1.25 (sqrt H + sqrt h), H and h in feet. 113 = 1.25 (sqrt H + 13), so sqrt H = 77.4 and H = about 6,000 ft: FL60. FL50 would give only about 105 NM.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-827\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"A ground feature appears 30° to the left of the centre line of the CRT of an airborne weather radar. If the heading of the aircraft is 355° (M) and the magnetic variation is 15°East, the true bearing of the aircraft from the feature is?\",\"opts\":[\"310°\",\"130°\",\"160°\"],\"ans\":2,\"exp\":\"Relative bearing 330: magnetic bearing to the feature = 355 - 30 = 325; true = 340; the true bearing of the aircraft from the feature is the reciprocal, 160.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-828\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft homes to a VOR along the 270 radial (inbound track 090 M at the VOR) with 10 deg south (starboard) drift. Variation is 5 W at the VOR and 8 W at the aircraft. The initial heading (magnetic, at the aircraft) is:\",\"opts\":[\"080\",\"083\",\"075\",\"090\"],\"ans\":1,\"exp\":\"Inbound magnetic track 090 at the VOR = 085(T). Starboard drift 10: heading 075(T). Convert with the AIRCRAFT's variation: 075 + 8 = 083(M).\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-829\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft tracks inbound to a VOR on the 144 radial; variation 10 W. The OBS should be set to:\",\"opts\":[\"144 TO\",\"324 TO\",\"334 TO\",\"144 FROM\"],\"ans\":1,\"exp\":\"Inbound on the 144 radial means tracking 324 (the reciprocal) towards the station: set 324, TO. Radials are already magnetic - the variation does not enter.\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-830\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Heading 130(M), variation 17 W. An island bears 15 deg left of the nose. The true bearing to plot from the island is:\",\"opts\":[\"278\",\"098\",\"115\",\"295\"],\"ans\":0,\"exp\":\"130 - 15 = 115(M) to the island; - 17 W = 098(T). From the island: 278(T).\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-831\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"A VOR and DME share the first two letters of their identifiers, and the DME's last letter is Z. This means they:\",\"opts\":[\"are co-located\",\"are more than 600 m apart but serve the same location\",\"are widely separated and serve different places\",\"are within 30 m of each other\"],\"ans\":1,\"exp\":\"Co-located beacons share the same ident. A last letter Z marks an associated pair that is separated (more than about 600 m) but serves the same place.\",\"seenIn\":[\"Mar 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-832\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"In a conventional VOR the 30 Hz variable signal is produced by:\",\"opts\":[\"adding 30 Hz to the transmission\",\"rotating the radiation pattern at 30 revolutions per second\",\"varying amplitude at +/- 30 Hz\",\"Doppler techniques\"],\"ans\":1,\"exp\":\"The limacon pattern rotates 30 times a second (1800 rpm), so a fixed receiver sees a 30 Hz amplitude modulation whose phase depends on its bearing.\",\"seenIn\":[\"Aug 2024 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-833\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft at 10,000 ft and a VOR at sea level. Using 1.23 x sqrt(height in ft), the maximum line-of-sight range is about:\",\"opts\":[\"123 NM\",\"100 NM\",\"150 NM\",\"250 NM\"],\"ans\":0,\"exp\":\"Range = 1.23 (sqrt h_aircraft + sqrt h_station) = 1.23 x 100 = 123 NM (1.25 is sometimes used: 125 NM).\",\"seenIn\":[\"May 2022\",\"Mar 2023 · ATPL\",\"Jun 2023 · Regular\",\"Jul 2025 · OLODE 05\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":5,\"years\":[2022,2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-834\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Magnetic heading 040, ADF relative bearing 010. The QDM and QDR are:\",\"opts\":[\"050 and 230\",\"030 and 210\",\"050 and 050\",\"230 and 050\"],\"ans\":0,\"exp\":\"QDM = MH + RB = 040 + 010 = 050 (bearing TO the beacon); QDR = 230 (from it).\",\"seenIn\":[\"Apr 2024 · OLODE 03\",\"Jun 2024 · Regular\",\"Mar 2026 · Regular 01\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-835\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Tracking inbound to a VOR on the 090 radial (track 270), the OBS should be set to ...... for correct (command) sensing:\",\"opts\":[\"090 with FROM\",\"270 with TO\",\"090 with TO\",\"270 with FROM\"],\"ans\":1,\"exp\":\"Set the course you are flying: 270, and the flag reads TO. The CDI then deflects towards the radial - fly towards the needle. With 090 set you would get reverse sensing.\",\"seenIn\":[\"Aug 2024 · OLODE 06\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-836\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"The TO/FROM indicator of a VOR shows TO when:\",\"opts\":[\"the aircraft is heading towards the station\",\"the selected course, if flown, would take the aircraft towards the station (the radial the aircraft is on is within 90 deg of the reciprocal of the OBS)\",\"the aircraft is within 10 NM\",\"the CDI is centred\"],\"ans\":1,\"exp\":\"TO/FROM depends only on the aircraft's position relative to the OBS course line through the station, never on heading. Abeam the station (90 deg to the course) the flag changes over.\",\"seenIn\":[\"Mar 2026 · Regular 01\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-837\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"You want to intercept the 090 radial outbound and are north of it. With the OBS on 090, a 30 deg intercept means a heading of:\",\"opts\":[\"060\",\"090\",\"120\",\"270\"],\"ans\":2,\"exp\":\"North of an easterly radial, the radial lies to your right (south): turn right of the course by 30 deg - heading 120 - and turn onto 090 as the CDI centres.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-838\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Compared with rho-theta (VOR/DME) fixing, rho-rho (DME/DME) fixing is:\",\"opts\":[\"less accurate\",\"more accurate, best when the range circles cut at about 90 deg\",\"the same\",\"only usable over water\"],\"ans\":1,\"exp\":\"DME ranges are accurate to a fraction of a mile at any distance, whereas a VOR bearing error grows with range; two good DME cuts give the best fix.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-839\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft homes to an NDB (keeping the relative bearing at 000) on QDM 060 with a crosswind. Its path over the ground is:\",\"opts\":[\"a straight line on 060\",\"a curve that ends with the aircraft heading into wind near the beacon\",\"a straight line displaced downwind\",\"a circle round the beacon\"],\"ans\":1,\"exp\":\"Homing points the nose at the beacon all the time; the wind blows the aircraft sideways, the heading keeps changing, and the path curves until it arrives roughly into wind. Tracking (heading off for drift) gives a straight path.\",\"seenIn\":[\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-840\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"A DME interrogator recognises the replies to its own interrogations because:\",\"opts\":[\"each aircraft uses its own frequency\",\"its pulse pairs are sent at a random (jittered) rate and it looks for replies with the same pattern\",\"the beacon codes each reply\",\"replies arrive on a separate channel\"],\"ans\":1,\"exp\":\"All aircraft on the channel share frequencies. Each interrogator jitters its pulse-pair timing; only replies that keep the same spacing after each interrogation are accepted (stroboscopic lock-on).\",\"seenIn\":[\"May 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-841\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"On a VOR indicator the OBS (omni bearing / track selector) is used to:\",\"opts\":[\"select the frequency\",\"select the radial or track against which the CDI shows deviation\",\"show the aircraft heading\",\"test the receiver\"],\"ans\":1,\"exp\":\"The OBS sets the course: the CDI then shows displacement from that radial and the TO/FROM flag shows whether that course leads to or from the station. Heading has nothing to do with it.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-842\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"An aircraft joins a holding pattern from Sector 2. The entry flown is:\",\"opts\":[\"direct\",\"offset (teardrop)\",\"parallel\",\"racetrack reversal\"],\"ans\":1,\"exp\":\"ICAO sectors: 1 = parallel entry, 2 = offset (teardrop) entry, 3 = direct entry.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-843\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Tracking inbound to an NDB on QDM 090 with 10 deg starboard drift, the heading and ADF relative bearing are:\",\"opts\":[\"080 and 010\",\"100 and 350\",\"090 and 000\",\"080 and 350\"],\"ans\":0,\"exp\":\"Starboard drift: steer left of track, heading 080. The beacon is on track ahead, 10 deg right of the nose: RB 010.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-844\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Heading 090(M) with the NDB dead ahead (QDM 090). To join the inbound QDM 060 with a 45 deg intercept, the heading is:\",\"opts\":[\"105\",\"015\",\"060\",\"135\"],\"ans\":0,\"exp\":\"The aircraft is on QDR 270, north of the inbound track 060 (which comes from QDR 240). Turn right of the required track by 45 deg: 060 + 45 = 105, then turn onto 060 as the ADF reads 315 (45 left).\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-845\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"The DME ground beacon:\",\"opts\":[\"radiates omni-directionally and provides range only\",\"provides a bearing\",\"radiates a rotating beam\",\"needs line of sight only for bearing\"],\"ans\":0,\"exp\":\"The beacon answers interrogations from all directions with an omni-directional aerial; it gives slant range, no bearing.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-846\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"With the ADF needle pointing to relative bearing 180, the aircraft is:\",\"opts\":[\"flying towards the NDB\",\"flying away from the NDB with it directly behind\",\"abeam the NDB\",\"overhead the NDB\"],\"ans\":1,\"exp\":\"Relative bearing 180 = the beacon is on the tail: the aircraft is flying away from it (QDR = heading).\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-847\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Which of these is NOT an error that affects VOR bearings?\",\"opts\":[\"site error\",\"propagation (terrain/scalloping) error\",\"equipment (station and airborne) error\",\"coastal refraction\"],\"ans\":3,\"exp\":\"Coastal refraction bends LF/MF surface waves - an ADF error. VOR (VHF line of sight) suffers site, propagation/scalloping and equipment errors.\",\"seenIn\":[\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-848\",\"topic\":\"VOR, ADF, DME & Bearings\",\"stem\":\"Without changing the OBS or position, the aircraft turns from an inbound to an outbound heading. The CDI and TO/FROM indication:\",\"opts\":[\"reverse\",\"do not change - VOR indications do not depend on heading\",\"show OFF\",\"swing to centre\"],\"ans\":1,\"exp\":\"The VOR receiver uses only the radial the aircraft is on and the OBS setting; heading never enters. What changes is whether \\\"fly toward the needle\\\" is still correct - flying the opposite way gives reverse sensing.\",\"seenIn\":[\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-849\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"A radio altimeter can be defined as a\",\"opts\":[\"ground radio aid used to measure the true height of the aircraft\",\"ground radio aid used to measure the true altitude of the aircraft\",\"self-contained on-board aid used to measure the true height of the aircraft\"],\"ans\":2,\"exp\":\"A radio altimeter is a self-contained on-board aid that measures true height above the terrain.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Oct 2023 · OLODE\",\"Nov 2023 · OLODE (29 Nov)\",\"Dec 2023 · Regular\",\"Jan 2024 · Regular (Day 2)\",\"Apr 2024 · OLODE 03\",\"Aug 2024 · OLODE 06\",\"Sep 2024 · Regular 03\",\"Jun 2025 · Regular 02\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":10,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-850\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"A RADALT provides\",\"opts\":[\"Height above terrain\",\"Pressure altitude\",\"Density altitude\"],\"ans\":0,\"exp\":\"A radio altimeter gives true height above the terrain directly below the aircraft, not altitude.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Nov 2023 · OLODE (29 Nov)\",\"Mar 2024 · Regular 01\",\"Apr 2024 · OLODE 03\",\"Mar 2025 · Regular 01\",\"May 2025 · OLODE 04\",\"Aug 2025 · OLODE 06\",\"Jan 2026 · OLODE 01\",\"Sep 2026 · Regular 03\"],\"undated\":false,\"times\":9,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-851\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"radio altimeter are accurate within height range of\",\"opts\":[\"0-500ft\",\"50 to 2700ft\",\"0 to 2500ft\"],\"ans\":2,\"exp\":\"A low-range radio altimeter measures true height above the terrain from 0 to about 2,500 ft.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Jul 2023 · OLODE\",\"Nov 2023 · OLODE (30 Nov)\",\"Feb 2024 · OLODE 02\",\"Sep 2024 · Regular 03\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":6,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-852\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"Radio altimeters are based on the principle of?\",\"opts\":[\"Frequency modulated carrier wave.\",\"Pulse modulated carrier wave.\",\"Amplitude modulated carrier wave.\"],\"ans\":0,\"exp\":\"A radio altimeter transmits a frequency-modulated carrier and measures the frequency difference of the echo.\",\"seenIn\":[\"Nov 2023 · OLODE (29 Nov)\",\"Mar 2024 · Regular 01\",\"Jun 2024 · Regular\",\"Jul 2024 · OLODE 05\",\"Aug 2024 · OLODE 06\"],\"undated\":false,\"times\":5,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-853\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"Radio Altimeter works on which frequency band?\",\"opts\":[\"UHF\",\"VHF\",\"SHF\"],\"ans\":2,\"exp\":\"Radio altimeters operate in the SHF band (about 4.3 GHz).\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Mar 2023 · ATPL\",\"Mar 2024 · Regular 01\",\"Sep 2024 · Regular 03\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":5,\"years\":[2021,2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-854\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"Wavelength of radio altimeter ?\",\"opts\":[\"7 cm\",\"7 mm\",\"14 cm\"],\"ans\":0,\"exp\":\"A radio altimeter works near 4.3 GHz (SHF): wavelength = 300 / 4300 = about 7 cm.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Sep 2022 · FC 03\",\"Nov 2023 · OLODE (29 Nov)\",\"Dec 2023 · Regular\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":5,\"years\":[2021,2022,2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-855\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"The outer marker is modulated at ...... and keyed with ......:\",\"opts\":[\"400 Hz; dashes\",\"1300 Hz; dots and dashes\",\"3000 Hz; dots\",\"1020 Hz; dots\"],\"ans\":0,\"exp\":\"Outer marker 400 Hz, continuous dashes, blue light; middle 1300 Hz dot-dash, amber; inner 3000 Hz dots, white. All on 75 MHz.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Jan 2025 · OLODE 01\",\"Aug 2025 · OLODE 06\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-856\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"What does a CVR record?\",\"opts\":[\"cabin crew conversation on intercom\",\"PA announcements even when not selected on the flight deck\",\"radio conversations\"],\"ans\":2,\"exp\":\"A CVR records voice communications by radio and interphone and the flight-deck sounds; it does not record cabin-crew intercom or PA announcements that were not selected on the flight deck.\",\"seenIn\":[\"May 2022\",\"Sep 2022 · FC 03\",\"Mar 2024 · Regular 01\",\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":4,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-857\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"On an EFIS display (CS-25 colour code) the ILS deviation pointer is shown in:\",\"opts\":[\"magenta\",\"cyan\",\"green\",\"amber\"],\"ans\":0,\"exp\":\"Magenta is used for the ILS deviation pointer, active route and selected heading; cyan for selected/sky items; amber for cautions.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Aug 2023 · OLODE\",\"Jul 2024 · OLODE 05\",\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":4,\"years\":[2022,2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-858\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"Given EFIS display and what is the color code of selected heading ?\",\"opts\":[\"Magenta\",\"Amber\",\"white\"],\"ans\":0,\"exp\":\"On an EFIS display the selected heading and the ILS deviation are magenta.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Aug 2024 · OLODE 06\",\"Sep 2024 · Regular 03\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":4,\"years\":[2021,2024,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-859\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"On a 3 deg ILS, one glide path dot = 0.14 deg. At 1.9 NM from the threshold the glide path deviation bar is 2 dots BELOW centre (fly down). The aircraft's height above the threshold is about:\",\"opts\":[\"660 ft\",\"550 ft\",\"605 ft\",\"760 ft\"],\"ans\":0,\"exp\":\"The bar shows where the glide path is: below centre means the aircraft is above it by 2 x 0.14 = 0.28 deg. Height = 1.9 x 6076 x tan(3.28) = 660 ft (on the path it would be about 605 ft).\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Mar 2024 · Regular 01\",\"Aug 2025 · OLODE 06\"],\"undated\":false,\"times\":3,\"years\":[2022,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-860\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"For the landing configuration a radio altimeter indicates?\",\"opts\":[\"Altitude of the main wheel above ground\",\"Height of the flight deck above the ground.\",\"Height of the main wheel above the ground.\"],\"ans\":2,\"exp\":\"In the landing configuration the radio altimeter is calibrated to indicate the height of the main wheels above the ground.\",\"seenIn\":[\"Aug 2023 · OLODE\",\"Mar 2024 · Regular 01\",\"Jul 2024 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-861\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"On an ILS approach the receiver detects more 150 Hz than 90 Hz on both the localiser and the glide path. To regain the centreline and glide path the pilot should fly:\",\"opts\":[\"down and left\",\"up and left\",\"up and right\",\"down and right\"],\"ans\":1,\"exp\":\"150 Hz dominates to the right of the localiser and below the glide path; so fly left and up. (More 90 Hz: fly right and down.)\",\"seenIn\":[\"Mar 2023 · ATPL\",\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-862\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"On a Category II/III approach, the decision height is measured by:\",\"opts\":[\"the pressure altimeter set to QNH\",\"the radio altimeter\",\"the DME\",\"the GPS altitude\"],\"ans\":1,\"exp\":\"CAT II/III minima are true heights above the touchdown zone, so the DH is set and read on the radio altimeter. CAT I normally uses a barometric decision altitude.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-863\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"The middle marker is usually located at a range of ____, with an audio frequency of ____ and illuminates the ____ light\",\"opts\":[\"4-6 NM, 1300 Hz, white\",\"1 km, 400 Hz, white\",\"1 km, 1300 Hz, amber\"],\"ans\":2,\"exp\":\"The middle marker is about 1 km out, 1300 Hz, amber.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Dec 2023 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-864\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"A modern low altitude radio altimeter uses the principle of\",\"opts\":[\"pulse modulated waves, with the difference between the transmitted and received waves displayed on a circular screen\",\"frequency modulated waves, where the difference between the transmitted wave and the received wave is measured\",\"wave modulation, with frequency shift due to the Doppler effect of the ground reflected wave being measured\"],\"ans\":1,\"exp\":\"A modern radio altimeter transmits a frequency-modulated (FMCW) signal and measures the frequency difference between the transmitted and returned waves to get height.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-865\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"A radio altimeter reads 1280 ft. Allowing for its accuracy, the minimum height the aircraft could be at is about:\",\"opts\":[\"1236 ft in the cruising attitude\",\"1236 ft in the landing attitude\",\"1323 ft in the cruising attitude\",\"1323 ft in the landing attitude\"],\"ans\":1,\"exp\":\"Typical radio altimeter accuracy is about +/- 3 % (+/- 5 ft): 1280 - 38 - 5 = 1236 ft. It is calibrated (installation delay) to be correct in the landing attitude.\",\"seenIn\":[\"Jan 2019\",\"Dec 2023 · Regular\"],\"undated\":false,\"times\":2,\"years\":[2019,2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-866\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"False glidepath will be intercepted if 3° glide slope is maintained at\",\"opts\":[\"6°\",\"1.35° to 5.25°\",\"0.45° to 1.75°\"],\"ans\":0,\"exp\":\"The first false glide path appears at about twice the true glide angle, so 6 deg for a 3 deg glide path (the usable path lies between 0.45 and 1.75 times the glide angle).\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\",\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-867\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"On a standard two-bar VASI, a pilot on the correct glide path sees:\",\"opts\":[\"white over white\",\"red over white (far bar red, near bar white)\",\"red over red\",\"white over red\"],\"ans\":1,\"exp\":\"Near (lower) bar white and far (upper) bar red = on slope. Both white = too high; both red = too low. (On a 3-bar VASI, long-bodied aircraft use the middle and far bars.)\",\"seenIn\":[\"Mar 2024 · Regular 01\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2025],\"kind\":\"asked\",\"optionsWritten\":false,\"note\":\"Our independent check could not confirm this answer from the official sources we hold; treat it with care and confirm with your instructor.\"},{\"id\":\"CPLNAV-868\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"For a glide slope of 3 deg, the glide path coverage in elevation extends from:\",\"opts\":[\"0.35 deg to 0.70 deg\",\"3 deg to at least 6 deg\",\"1.35 deg (0.45 theta) to 5.25 deg (1.75 theta)\",\"10 deg to 35 deg\"],\"ans\":2,\"exp\":\"ICAO glide path coverage: from 0.45 theta to 1.75 theta above the horizontal: 0.45 x 3 = 1.35 deg, 1.75 x 3 = 5.25 deg.\",\"seenIn\":[\"Jun 2024 · Regular\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-869\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"On a 3 deg glide path that crosses the threshold at 50 ft, at 5 NM from the threshold the height above the threshold is about (1 in 60, 300 ft per NM):\",\"opts\":[\"1550 ft\",\"1500 ft\",\"1050 ft\",\"2050 ft\"],\"ans\":0,\"exp\":\"The correct answer is: 1550 ft.\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2021,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-870\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"An aircraft carrying out an ILS approach is receiving more 90 Hz than 150 Hz modulation notes from both the localiser and glidepath transmitters. The ILS indication will show:\",\"opts\":[\"Fly right and fly down\",\"Fly left and fly down\",\"Fly right and fly up\"],\"ans\":0,\"exp\":\"More 90 Hz: the aircraft is to the left of the localiser (fly right) and above the glide path (fly down).\",\"seenIn\":[\"Dec 2023 · Regular\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":2,\"years\":[2023,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-871\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"The ILS glide path transmitter operates in the ...... band\",\"opts\":[\"UHF\",\"VHF\",\"SHF\",\"VLF\"],\"ans\":0,\"exp\":\"Glide path 329.15-335 MHz (UHF), paired automatically with the VHF localiser (108.10-111.95 MHz).\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-872\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"A CAT I precision approach requires a runway visual range of at least:\",\"opts\":[\"550 m\",\"350 m\",\"800 m\",\"500 m\"],\"ans\":0,\"exp\":\"CAT I: DH not below 200 ft with visibility 800 m or RVR not less than 550 m.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-873\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"If a radio altimeter fails during an approach:\",\"opts\":[\"it keeps showing the last height\",\"the height indication is removed and a failure flag appears\",\"it reads zero\",\"it switches to barometric height\"],\"ans\":1,\"exp\":\"A detected system failure removes the reading and shows a warning flag (with an alert), so the crew never uses a false height near the ground.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-874\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"ILS is subject to false glide paths resulting from\",\"opts\":[\"ground returns ahead of the antennas\",\"back-scattering of antennas\",\"multiple lobes of radiation patterns\"],\"ans\":2,\"exp\":\"False glide paths arise from the multiple lobes in the glide path antenna radiation pattern.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-875\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"The frequencies used in a low altitude radio altimeter are\",\"opts\":[\"5400 MHz and 9400 MHz\",\"4200 MHz to 4400 MHz\",\"2700 MHz to 2900 MHz\"],\"ans\":1,\"exp\":\"Low-range radio altimeters use 4200-4400 MHz.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-876\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"Runway touchdown zone markings are laid in pairs at longitudinal intervals of:\",\"opts\":[\"150 m\",\"300 m\",\"50 m\",\"500 m\"],\"ans\":0,\"exp\":\"ICAO Annex 14: touchdown zone markings are pairs of rectangular marks spaced 150 m apart, starting 150 m from the threshold.\",\"seenIn\":[\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-877\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"What is the distance to touchdown when you are 670 ft QFE on a 3.2° glide slope Approach?\",\"opts\":[\"2.06 NM\",\"2.40 NM\",\"1.96 NM\",\"1.63 NM\"],\"ans\":2,\"exp\":\"Distance = 670 / tan 3.2 deg = 11,970 ft = 1.97 NM.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-878\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"You must descend from FL230 to FL50 over 32 NM in 7 minutes, with a 25 kt wind component. The descent path angle (glide slope) is:\",\"opts\":[\"4.07 deg\",\"5.29 deg\",\"6.25 deg\",\"4.68 deg\"],\"ans\":1,\"exp\":\"The angle is set by height and ground distance only: 18,000 ft over 32 x 6076 = 194,400 ft: tan = 0.0926, angle 5.29 deg. The wind changes the TAS needed, not the angle.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-879\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"On a 3 deg glide slope the headwind decreases by 17 kt. To stay on the glide slope the rate of descent must:\",\"opts\":[\"increase by about 85 ft/min\",\"decrease by about 85 ft/min\",\"increase by about 51 ft/min\",\"stay the same\"],\"ans\":0,\"exp\":\"Less headwind = 17 kt more groundspeed. ROD for 3 deg is about 5 x GS, so it must increase by about 5 x 17 = 85 ft/min.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-880\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"AWR equipment operation on the ground is:\",\"opts\":[\"totally prohibited\",\"Unrestrictedly permitted in aerodrome maintenance areas\",\"only permitted with certain precautions, to safeguard the health of personnel and to protect equipment\",\"all the above are correct\"],\"ans\":2,\"exp\":\"Airborne weather radar may be operated on the ground only with precautions to protect people (radiation hazard) and equipment.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-881\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"At what approximate distance from the threshold would an aircraft intercept the glide path if the aircraft height is 2500 ft and the ILS glide path angle is 3 deg?\",\"opts\":[\"7 nm\",\"7.8 nm\"],\"ans\":1,\"exp\":\"Distance = height / tan 3 deg = 2500 / 0.0524 = 47,700 ft = 7.85 NM.\",\"seenIn\":[\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-882\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"Aircraft height 2500' , GP angle 3° At what approximate distance from THR can you expect to capture the GP?\",\"opts\":[\"8.3Nm\",\"7.0Nm\",\"13.1Nm\"],\"ans\":0,\"exp\":\"A 3 deg glide path descends about 300 ft per NM, so 2,500 / 300 = 8.3 NM. Exact trigonometry gives 2,500 / tan 3 = 7.9 NM; 8.3 NM is the expected answer among the options offered.\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-883\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"Failure of radio altimeter will result in\",\"opts\":[\"Loss of true altitude data\",\"Loss of true height data\",\"Loss of density altitude data\"],\"ans\":1,\"exp\":\"A radio altimeter supplies true height above the terrain; if it fails, that height data is lost.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-884\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"Which of these is a VOR frequency rather than an ILS localiser frequency?\",\"opts\":[\"109.90 MHz\",\"108.10 MHz\",\"112.20 MHz\",\"111.95 MHz\"],\"ans\":2,\"exp\":\"Between 108 and 112 MHz, localisers use ODD tenths (108.10, 109.90, 111.95) and VORs EVEN tenths; above 112 MHz everything is VOR.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-885\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"Radio altimeter can accurately give reading between\",\"opts\":[\"0 to 2700 ft\",\"50 to 2700 ft\",\"0 to 2500 ft\"],\"ans\":2,\"exp\":\"A radio altimeter reads true height from 0 to about 2,500 ft.\",\"seenIn\":[\"Jun 2025 · Regular 02\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-886\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"Which of the following is an ILS localiser frequency?\",\"opts\":[\"109.15MHz\",\"112.10MHz\",\"110.20MHz\"],\"ans\":0,\"exp\":\"ILS localiser frequencies are 108.10-111.95 MHz with an odd tenth (109.15).\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-887\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"The ILS localiser coverage is:\",\"opts\":[\"+/- 10 deg to 25 NM and +/- 35 deg to 17 NM\",\"+/- 8 deg to 10 NM\",\"+/- 35 deg to 25 NM\",\"+/- 10 deg to 10 NM\"],\"ans\":0,\"exp\":\"Localiser: 25 NM within 10 deg of the centreline, 17 NM between 10 and 35 deg.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-888\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"An ILS receiver shows predominant 90 Hz on both localiser and glide path; the runway QDM is 264. The aircraft is:\",\"opts\":[\"north of the localiser, below the glide path\",\"south of the localiser, above the glide path\",\"north of the localiser, above the glide path\",\"south of the localiser, below the glide path\"],\"ans\":1,\"exp\":\"90 Hz dominant = left of the localiser (looking along the approach) and above the glide path. Approaching on 264 (westwards), left is south.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-889\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"ILS glide path coverage in azimuth is:\",\"opts\":[\"+/- 8 deg out to 10 NM\",\"+/- 10 deg out to 8 NM\",\"+/- 12 deg to 17 NM\",\"+/- 35 deg to 25 NM\"],\"ans\":0,\"exp\":\"Glide path: 8 deg either side of the localiser centreline to 10 NM.\",\"seenIn\":[\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-890\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"The specified maximum safe fly-up indication on a 5-dot ILS (glide path) indicator is:\",\"opts\":[\"half full scale\",\"2.5 dots fly up\",\"just before full scale\",\"1.3 dots fly up\"],\"ans\":1,\"exp\":\"Below 2.5 dots fly-up obstacle clearance is no longer guaranteed by the glide path coverage.\",\"seenIn\":[\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true,\"note\":\"Our independent check found that more than one option can be argued for, as worded in the recall. The key gives the answer most references support.\"},{\"id\":\"CPLNAV-891\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"What approximate rate of descent keeps a 3 deg glide path at a groundspeed of 120 kt?\",\"opts\":[\"600 ft/min\",\"360 ft/min\",\"900 ft/min\",\"1200 ft/min\"],\"ans\":0,\"exp\":\"Rule of thumb for 3 deg: ROD = GS x 5 = 600 ft/min (exactly 120 x 101 x tan 3 = 637).\",\"seenIn\":[\"Aug 2023 · OLODE\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-892\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"A category I precision approach (CAT I) has :\",\"opts\":[\"decision height equal to at least 100 ft.\",\"decision height equal to at least 50 ft\",\"decision height equal to at least 200 ft\"],\"ans\":2,\"exp\":\"A Category I precision approach has a decision height of not less than 200 ft.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-893\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"A full-scale localiser needle deflection means the aircraft is off the centreline by about:\",\"opts\":[\"2.5 deg or more\",\"less than 2.5 deg\",\"10 deg\",\"0.7 deg\"],\"ans\":0,\"exp\":\"The localiser is much more sensitive than a VOR: full scale is about 2.5 deg (course width about 5 deg), so a pinned needle means 2.5 deg or more.\",\"seenIn\":[\"May 2024 · OLODE 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-894\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"The ILS glide slope warning flag appears when:\",\"opts\":[\"the aircraft is more than 2.5 dots low\",\"the received signal is absent or too weak (or the receiver fails)\",\"the aircraft is above the glide path\",\"the marker is passed\"],\"ans\":1,\"exp\":\"The flag monitors signal strength and receiver health, not position: deviation is shown by the needle, loss of a usable signal by the flag.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-895\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"A full-scale glide path deflection corresponds to about:\",\"opts\":[\"0.7 deg above or below the glide path\",\"2.5 deg\",\"5 deg\",\"10 deg\"],\"ans\":0,\"exp\":\"The glide path indicator is very sensitive: full scale about 0.7 deg (0.14 deg per dot on a 5-dot scale).\",\"seenIn\":[\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-896\",\"topic\":\"ILS, Radio Altimeter & Landing Aids\",\"stem\":\"A Category IIIA approach has a decision height:\",\"opts\":[\"of at least 200 ft\",\"lower than 100 ft, or no decision height\",\"of 200 ft with RVR 550 m\",\"of exactly 50 ft\"],\"ans\":1,\"exp\":\"CAT I: DH not below 200 ft. CAT II: 100-200 ft. CAT IIIA: below 100 ft or none, with an RVR minimum of a few hundred metres.\",\"seenIn\":[\"May 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-897\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The NAVSTAR/GPS constellation comprises\",\"opts\":[\"24 satellites in 6 orbits\",\"24 satellites in 4 orbits\",\"24 satellites in 3 orbits\"],\"ans\":0,\"exp\":\"The NAVSTAR constellation is 24 satellites in 6 orbital planes.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Dec 2023 · Regular\",\"Apr 2024 · OLODE 03\",\"Mar 2025 · Regular 01\",\"May 2025 · OLODE 04\",\"May 2026 · OLODE 04\",\"Aug 2026 · OLODE 06\"],\"undated\":false,\"times\":7,\"years\":[2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-898\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The sensors of an INS measure:\",\"opts\":[\"precession\",\"velocity\",\"the horizontal component of the earth's rotation\",\"acceleration\"],\"ans\":3,\"exp\":\"The accelerometers of an INS measure acceleration; the computer integrates it to velocity and then to distance.\",\"seenIn\":[\"Jan 2019\",\"May 2022\",\"Dec 2023 · Regular\",\"Apr 2024 · OLODE 03\",\"Jul 2024 · OLODE 05\",\"Jun 2025 · Regular 02\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":7,\"years\":[2019,2022,2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-899\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"Satellite used in GNSS, orbit the earth is\",\"opts\":[\"12 hours\",\"8 hours\",\"24 hours\"],\"ans\":0,\"exp\":\"GPS satellites orbit at about 20,200 km with a period of about 12 hours (one orbit per half sidereal day).\",\"seenIn\":[\"Oct 2021 · Attempt 2\",\"Jun 2023 · Regular\",\"Nov 2023 · OLODE (30 Nov)\",\"Dec 2023 · Regular\",\"Oct 2024 · OLODE 07\",\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":6,\"years\":[2021,2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-900\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The most significant error in single-frequency GNSS is ......, and it is greatly reduced by ......:\",\"opts\":[\"ionospheric propagation; using two frequencies (L1/L2)\",\"multipath; RAIM\",\"receiver clock; atomic clocks in the receiver\",\"ephemeris; differential corrections only\"],\"ans\":0,\"exp\":\"The ionosphere delays the signal by an amount that depends on frequency, so comparing two frequencies largely removes it.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Aug 2023 · OLODE\",\"May 2024 · OLODE 04\",\"Jun 2024 · Regular\",\"Dec 2024 · Regular 04\",\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":6,\"years\":[2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-901\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"NAVSTAR/GPS operates in the ____ band and the receiver determines position by ____\",\"opts\":[\"UHF, range position lines\",\"UHF, secondary radar principles\",\"SHF, secondary radar principles\"],\"ans\":0,\"exp\":\"NAVSTAR/GPS transmits in the UHF band (L1 1575.42 MHz) and the receiver fixes position from simultaneous ranges (range position lines) to the satellites.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Nov 2023 · OLODE (30 Nov)\",\"May 2025 · OLODE 04\",\"Feb 2026 · OLODE 02\"],\"undated\":false,\"times\":4,\"years\":[2022,2023,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-902\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"TCAS II provides:\",\"opts\":[\"resolution advisories only\",\"terrain warnings\",\"traffic advisories and resolution advisories in the vertical plane\",\"weather information\"],\"ans\":2,\"exp\":\"TCAS II: TA (\\\"Traffic, traffic\\\") plus vertical RAs (climb/descend). It never gives turn instructions; TCAS I gives TAs only.\",\"seenIn\":[\"Feb 2024 · OLODE 02\",\"Mar 2024 · Regular 01\",\"Jun 2025 · Regular 02\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-903\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"An inertial system whose gyros and accelerometers are fixed rigidly to the aircraft structure is called:\",\"opts\":[\"solid state\",\"rigid\",\"strapdown\",\"ring laser\"],\"ans\":2,\"exp\":\"Strapdown (IRS): no stabilised platform; the computer resolves the body-axis accelerations using the laser-gyro rates. A gimballed INS keeps its platform level and aligned.\",\"seenIn\":[\"May 2022\",\"Dec 2023 · Regular\",\"Jul 2024 · OLODE 05\",\"Jul 2026 · OLODE 05\"],\"undated\":false,\"times\":4,\"years\":[2022,2023,2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-904\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The orbits of the navstar GPS satellite are inclined at:\",\"opts\":[\"55 degree to the earth axis\",\"55 degree to the plane of equator\",\"65 degree to the plane of equator\"],\"ans\":1,\"exp\":\"GPS orbits are inclined 55 deg to the equatorial plane.\",\"seenIn\":[\"Jun 2023 · Regular\",\"Dec 2024 · Regular 04\",\"Jun 2025 · Regular 02\",\"Jan 2026 · OLODE 01\"],\"undated\":false,\"times\":4,\"years\":[2023,2024,2025,2026],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-905\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"How many satellites are needed for a 4D GNSS fix (latitude, longitude, altitude and time)?\",\"opts\":[\"3\",\"4\",\"5\",\"6\"],\"ans\":1,\"exp\":\"Four unknowns (three position co-ordinates and the receiver clock error) need four pseudo-ranges. RAIM needs a fifth; fault exclusion a sixth.\",\"seenIn\":[\"Feb 2024 · OLODE 02\",\"Mar 2026 · Regular 01\",\"May 2026 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2024,2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-906\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"Position fixing by satellite is by means of:\",\"opts\":[\"Simultaneous bearing from a number of satellites\",\"Range and bearing from a single satellite position\",\"Simultaneous range from a number of satellites\"],\"ans\":2,\"exp\":\"GNSS position is found from simultaneous ranges (pseudo-ranges) to several satellites, not from bearings.\",\"seenIn\":[\"Mar 2022\",\"Nov 2023 · OLODE (30 Nov)\",\"Jul 2025 · OLODE 05\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-907\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"Validity of Navigational database\",\"opts\":[\"28 days\",\"1 month\",\"____\"],\"ans\":0,\"exp\":\"The FMS/FMC navigation database is valid for 28 days (one AIRAC cycle).\",\"seenIn\":[\"Jan 2019\",\"Jun 2023 · Regular\",\"Dec 2023 · Regular\"],\"undated\":false,\"times\":3,\"years\":[2019,2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-908\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The TCAS gives RA advisory in\",\"opts\":[\"quickly and steadily descent or climb\",\"quickly and steadily increase GS or DEcrease\",\"quickly and steadily turn left or right\"],\"ans\":0,\"exp\":\"A TCAS resolution advisory gives vertical avoidance: climb or descend.\",\"seenIn\":[\"May 2022\",\"Jun 2023 · Regular\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-909\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"GPWS Mode 1 warns of:\",\"opts\":[\"excessive descent rate\",\"altitude loss after take-off\",\"unsafe terrain clearance not in landing configuration\",\"excessive terrain closure rate\"],\"ans\":0,\"exp\":\"Mode 1 excessive descent rate (\\\"Sink rate / Pull up\\\"); Mode 2 excessive terrain closure; Mode 3 altitude loss after take-off or go-around (\\\"Don't sink\\\"); Mode 4 unsafe terrain clearance not in landing configuration (\\\"Too low gear/flaps\\\"); Mode 5 below glide slope; Mode 6 callouts.\",\"seenIn\":[\"May 2022\",\"Oct 2023 · OLODE\",\"May 2025 · OLODE 04\"],\"undated\":false,\"times\":3,\"years\":[2022,2023,2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-910\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"An altitude alerting system must at least be capable of alerting the crew on: 1. approaching selected altitude 2. excessive deviation from selected altitude 3. excessive vertical speed 4. excessive terrain closure 5. abnormal gear/flap combination\",\"opts\":[\"1 & 2\",\"1,2,3 & 4\",\"1,2,3,4 & 5\"],\"ans\":0,\"exp\":\"An altitude alerting system warns on approaching the selected altitude and on deviation from it.\",\"seenIn\":[\"Mar 2023 · ATPL\",\"May 2024 · OLODE 04\",\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":3,\"years\":[2023,2024,2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-911\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"In control wheel steering (CWS) mode, the autopilot:\",\"opts\":[\"disengages\",\"stays engaged, manoeuvres the aircraft in response to pressure on the control wheel and holds the attitude when released\",\"holds altitude only\",\"follows the FMS route\"],\"ans\":1,\"exp\":\"CWS: the pilot steers through the autopilot servos; release the wheel and the attitude is held.\",\"seenIn\":[\"May 2022\",\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":2,\"years\":[2022,2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-912\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The distance measured between a satellite and a receiver is known as a pseudo-range because\",\"opts\":[\"it is measured using pseudo-random codes\",\"it includes receiver clock error\",\"satellite and receiver are continually moving in relation to each other\"],\"ans\":1,\"exp\":\"Pseudo-range includes the receiver clock error because the receiver clock is not perfectly synchronised.\",\"seenIn\":[\"Sep 2022 · FC 03\",\"Jan 2024 · Regular (Day 2)\"],\"undated\":false,\"times\":2,\"years\":[2022,2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-913\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"In an INS, groundspeed is obtained:\",\"opts\":[\"from TAS and W/V from RNAV\",\"from TAS and W/V from the ADC\",\"by integrating measured acceleration\",\"by integrating gyro precession\"],\"ans\":2,\"exp\":\"Accelerometers measure acceleration; the first integration gives velocity (groundspeed), the second distance.\",\"seenIn\":[\"Nov 2023 · OLODE (30 Nov)\",\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":2,\"years\":[2023,2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-914\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"With the IRS mode selector at ATT (attitude), the IRS provides:\",\"opts\":[\"full navigation\",\"attitude only (heading must be entered manually), no navigation\",\"position only\",\"nothing\"],\"ans\":1,\"exp\":\"ATT is a reversionary mode after loss of alignment in flight: pitch and roll, and heading if set by the crew - no present position.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-915\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"INS/IRS alignment can take place with the mode selector in:\",\"opts\":[\"ALIGN and ATT\",\"NAV and ATT\",\"ALIGN only\",\"NAV and ALIGN\"],\"ans\":3,\"exp\":\"Alignment runs in ALIGN, and also if NAV is selected directly from OFF (the system aligns, then enters NAV). ATT gives attitude only.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-916\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"Waypoints and the route are entered into the FMS through the:\",\"opts\":[\"flight management computer directly\",\"multi-function control display unit (MCDU/CDU)\",\"IRS mode panel\",\"flight director\"],\"ans\":1,\"exp\":\"The pilot types the route and performance data on the CDU keyboard; the FMC stores and computes; the IRS supplies position.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-917\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"An IRS/FMS obtains magnetic variation from:\",\"opts\":[\"the flux valve\",\"a table of variation stored in its memory\",\"the DGI\",\"the VOR\"],\"ans\":1,\"exp\":\"The IRS computes true heading; it converts to magnetic using a world magnetic variation model stored in memory.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-918\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"An IRS must be aligned, and NAV selected:\",\"opts\":[\"before the aircraft is moved\",\"on the runway before take-off\",\"after take-off\",\"at any time in flight\"],\"ans\":0,\"exp\":\"Alignment needs the aircraft stationary (it senses earth rate and gravity); moving it during alignment spoils it, so NAV is selected before taxi.\",\"seenIn\":[\"Jun 2023 · Regular (ATPL)\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-919\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"GPWS Mode 3 warns of:\",\"opts\":[\"excessive descent rate\",\"altitude loss after take-off or missed approach\",\"excessive terrain closure\",\"descent below the glide slope\"],\"ans\":1,\"exp\":\"Mode 3 is active after take-off/go-around until a safe height is gained: any significant loss of altitude gives \\\"Don't sink\\\".\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-920\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"TCAS can only detect intruders that carry a transponder. An intruder with a Mode A transponder (no altitude reporting) gives:\",\"opts\":[\"a TA only, no RA\",\"an RA only\",\"both TA and RA\",\"nothing\"],\"ans\":0,\"exp\":\"Without altitude (Mode C/S) TCAS cannot judge the vertical conflict, so it can only show traffic (TA), never resolve it (RA).\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-921\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The main advantage of a ring laser gyro over a conventional spinning gyro is:\",\"opts\":[\"no moving parts, so long life, no spin-up time and no precession or gimbal errors\",\"greater weight\",\"it needs a vacuum supply\",\"it measures acceleration\"],\"ans\":0,\"exp\":\"A ring laser gyro measures rotation from the phase shift between two laser beams travelling opposite ways round a closed path. With no rotor it is reliable and long-lived, and ready almost immediately.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-922\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"In a ring laser gyro the dither motor is used to:\",\"opts\":[\"improve accuracy at high rates\",\"overcome laser lock-in at low rates of rotation\",\"compensate for transport wander\",\"stabilise the laser frequency\"],\"ans\":1,\"exp\":\"At very low rotation rates the two beams lock together and show no rotation; mechanically vibrating (dithering) the block keeps it out of the lock-in zone.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-923\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"An engine fire is shown on an electronic engine display:\",\"opts\":[\"on the primary display, in red\",\"on the secondary display, in amber\",\"only on the FMC\",\"on the EFIS in white\"],\"ans\":0,\"exp\":\"Warnings (red) are given the highest priority on the primary engine/warning display.\",\"seenIn\":[\"Mar 2023 · ATPL\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-924\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"GPS satellites, in orbits inclined at 55 deg, pass directly overhead only up to latitudes of about:\",\"opts\":[\"55 deg\",\"90 deg\",\"80 deg\",\"45 deg\"],\"ans\":0,\"exp\":\"A satellite's ground track reaches the latitude equal to its orbit inclination. Higher up they are always seen at an angle - though still in view.\",\"seenIn\":[\"Apr 2025 · OLODE 03\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-925\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The FMC combines:\",\"opts\":[\"the long-term accuracy of the IRS with the short-term accuracy of radio aids\",\"the short-term accuracy of the IRS with the long-term accuracy of radio aids\",\"two IRS only\",\"GPS and the ADC only\"],\"ans\":1,\"exp\":\"IRS positions are smooth and precise over minutes but drift with time; radio (DME/DME, GPS) fixes do not drift but are noisy. The FMC blends them.\",\"seenIn\":[\"Mar 2025 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-926\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The frequency band of the NAVSTAR/GPS L1 and L2 frequencies is\",\"opts\":[\"VHF\",\"UHF\",\"EHF\"],\"ans\":1,\"exp\":\"GPS L1 and L2 are in the UHF band.\",\"seenIn\":[\"Sep 2022 · FC 03\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-927\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The task of the GPS control segment is to:\",\"opts\":[\"determine availability to users\",\"monitor the satellites' ephemeris and clocks (and upload corrections)\",\"apply selective availability\",\"relay positions to the user\"],\"ans\":1,\"exp\":\"Monitor stations track the satellites; the master control station computes orbit and clock corrections and uploads them via ground antennas.\",\"seenIn\":[\"Feb 2024 · OLODE 02\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-928\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"Which of the following lists the first three pages of the FMC/CDU normally used to enter data on initial start-up of the B737-400 Electronic Flight Instrument System?\",\"opts\":[\"IDENT - RTE = DEPARTURE\",\"POS INIT - RTE - IDENT\",\"IDENT - POS INIT —RTE\",\"POS INIT - RTE - DEPARTURE\"],\"ans\":2,\"exp\":\"The first three CDU pages at start-up are IDENT, POS INIT and RTE.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-929\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"During the initial alignment of an inertial navigation system (INS) the equipment:\",\"opts\":[\"will accept a 10 deg error in initial latitude but will not accept a 10 deg error in initial longitude\",\"will not accept a 10 deg error in initial latitude but will accept a 10 deg error in initial longitude\",\"will not accept a 10 deg error in initial latitude or initial longitude\",\"will accept a 10 deg error in initial latitude and initial longitude\"],\"ans\":1,\"exp\":\"During alignment the INS checks the entered latitude against the earth-rate measurement and rejects a gross latitude error, but a longitude error does not affect alignment.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-930\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"A pilot accidentally turning OFF the INS in flight, and then turns it back ON a few moments later. Following this incident:\",\"opts\":[\"everything returns to normal and is usable\",\"no useful information can be obtained from the INS\",\"it can only be used for attitude reference\",\"the INS is usable in NAV MODE after a position update\"],\"ans\":2,\"exp\":\"After an INS has lost power in flight it cannot re-align; it can be used only as an attitude reference.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-931\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"An aircraft is flying with the aid of an inertial navigation system (INS) connected to the autopilot. The following two points have been entered in the INS computer: WPT 1: 60°N 030°W WPT 2: 60°N 020°W When 025°W is passed the latitude shown on the display unit of the inertial navigation system will be:\",\"opts\":[\"60 00.0 N\",\"60 05.7 N\",\"59 49.0 N\",\"60 11.0 N\"],\"ans\":1,\"exp\":\"The INS flies the great circle, which bows towards the pole: at the mid-longitude, tan lat = tan 60 / cos 5 = 1.739, i.e. 60 deg 05.7 N.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-932\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"A “resolution advisory” (RA) is represented on the display system of the TCAS 2 (Traffic Collision Avoidance System) by a?\",\"opts\":[\"Blue or white empty lozenge.\",\"Red full circle.\",\"Red full square.\",\"Blue or white full lozenge.\"],\"ans\":2,\"exp\":\"On TCAS a resolution advisory is a red filled square; a traffic advisory is an amber filled circle.\",\"seenIn\":[\"Jan 2019\"],\"undated\":false,\"times\":1,\"years\":[2019],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-933\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"An INS/IRS data base is valid for\",\"opts\":[\"7 days\",\"28days\",\"depends upon operational requirement\"],\"ans\":1,\"exp\":\"The navigation database in an INS/IRS/FMS is updated every 28 days (AIRAC cycle).\",\"seenIn\":[\"Jun 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-934\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The Airbus electronic centralised aircraft monitor (ECAM), unlike a basic engine indicating system, has:\",\"opts\":[\"three automatic display modes plus one manual mode, showing system synoptics and the actions to take\",\"no warnings\",\"only engine indications\",\"mechanical gauges\"],\"ans\":0,\"exp\":\"ECAM shows warnings with corrective actions and the affected system page automatically (flight phase, advisory, failure modes). Boeing's EICAS concentrates on engine indications and crew alerts.\",\"seenIn\":[\"May 2022\"],\"undated\":false,\"times\":1,\"years\":[2022],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-935\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The FMC receives updating data from external (radio) sources such as:\",\"opts\":[\"the INS only\",\"pressure altitude only\",\"the compass\",\"VOR/DME (and DME/DME, GPS)\"],\"ans\":3,\"exp\":\"Radio updates (DME/DME, VOR/DME, GPS) correct the IRS drift; altitude comes from the ADC and heading from the IRS.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-936\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"During the alignment procedure of the INS, the aircraft?\",\"opts\":[\"must not be moved\",\"may be taxied slowly but not subjected to accelerations of the magnitude used for take off\",\"May taxi but not get airborne, as this involves vertical accelerations.\"],\"ans\":0,\"exp\":\"An INS must be stationary during alignment; any movement corrupts the gyro-compassing and level alignment.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-937\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The initial range calculation at the receiver is known as a pseudo-range, because it is not yet corrected for:\",\"opts\":[\"receiver clock errors\",\"receiver and satellite clock errors\",\"receiver and satellite clock errors and propagation errors\"],\"ans\":0,\"exp\":\"The first range is not yet corrected for receiver clock error.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-938\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"An \\\"all-in-view\\\" satellite receiver is one that:\",\"opts\":[\"monitors all 24 satellites\",\"tracks only selected satellites\",\"tracks all satellites in view and uses the best ones for the fix\",\"tracks the closest satellites\"],\"ans\":2,\"exp\":\"It has enough channels to track every visible satellite at once, choosing the best geometry (lowest DOP) - unlike a sequential receiver.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-939\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The input the FMC receives from the air data computer (ADC) is:\",\"opts\":[\"heading\",\"groundspeed\",\"TAS\",\"position\"],\"ans\":2,\"exp\":\"The ADC supplies TAS, Mach, altitude and temperature; heading and position come from the IRS, groundspeed from the IRS/FMC.\",\"seenIn\":[\"Mar 2024 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-940\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"RAIM (receiver autonomous integrity monitoring):\",\"opts\":[\"is done by ground stations\",\"is done within the receiver, which needs at least 5 satellites to detect a faulty one\",\"needs only 3 satellites\",\"corrects ionospheric errors\"],\"ans\":1,\"exp\":\"The receiver checks the consistency of redundant ranges: 5 satellites to detect a failure, 6 to exclude it.\",\"seenIn\":[\"Mar 2026 · Regular 01\"],\"undated\":false,\"times\":1,\"years\":[2026],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-941\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"An IRS displays track 090 deg (T) and drift 9 deg right. The true heading is:\",\"opts\":[\"081 deg\",\"090 deg\",\"099 deg\",\"279 deg\"],\"ans\":0,\"exp\":\"Track = heading + drift (right drift is added). So heading = track - drift = 090 - 9 = 081. An IRS shows drift directly from its groundspeed vector, but the relationship is the same as on the CX-3.\",\"seenIn\":[\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-942\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"A 2D GNSS fix (latitude and longitude, altitude known) needs at least ...... satellites; the GLONASS constellation orbits at about ...... km, inclined ......:\",\"opts\":[\"3; 19,100 km; 64.8 deg\",\"4; 20,180 km; 55 deg\",\"3; 20,180 km; 55 deg\",\"2; 35,800 km; 0 deg\"],\"ans\":0,\"exp\":\"With altitude supplied, three ranges solve two positions plus clock. GLONASS: about 19,100 km, inclination 64.8 deg (GPS: 20,180 km, 55 deg).\",\"seenIn\":[\"Sep 2024 · Regular 03\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-943\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The most accurate fixing information will be obtained from:\",\"opts\":[\"four satellites spaced 90° apart at 30° above the visual horizon\",\"one satellite close to the horizon and 3 equally at 60° above the horizon\",\"one satellite directly overhead and 3 equally spaced at 60° above the horizon\",\"one satellite directly overhead and 3 spaced 120° apart close to the horizon\"],\"ans\":3,\"exp\":\"The best geometry (lowest DOP) is one satellite overhead plus three spread 120 deg apart low on the horizon.\",\"seenIn\":[\"Jan 2025 · OLODE 01\"],\"undated\":false,\"times\":1,\"years\":[2025],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-944\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"The FMC position is:\",\"opts\":[\"the average of the IRS positions\",\"the average of the IRS and radio positions\",\"computer-generated from the IRS and radio navigation positions\",\"computer-generated from radio positions only\"],\"ans\":2,\"exp\":\"The FMC filters the IRS positions with radio updates to produce its own best estimate - not a simple average.\",\"seenIn\":[\"Dec 2024 · Regular 04\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-945\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"In GPS, position is calculated from\",\"opts\":[\"the time taken for each satellite signal to arrive (ranges)\",\"the receiver clock error\",\"the bearing of each satellite\"],\"ans\":0,\"exp\":\"The receiver measures the signal travel time from each satellite, converts it to range, and fixes position from the ranges.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-946\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"On an EFIS map display the track line shows:\",\"opts\":[\"a manually selected track\",\"the selected heading\",\"the actual track over the ground\",\"the track the FMS will fly next\"],\"ans\":2,\"exp\":\"The track line runs from the aircraft symbol along the track made good (heading +/- drift); the lubber line/top of the rose is heading.\",\"seenIn\":[\"Oct 2021 · Attempt 2\"],\"undated\":false,\"times\":1,\"years\":[2021],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-947\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"A TCAS \\\"preventive\\\" resolution advisory requires the pilot to:\",\"opts\":[\"climb or descend immediately\",\"keep the vertical speed out of the restricted (red) band - no change is needed if already outside it (\\\"Monitor vertical speed\\\")\",\"turn away from the traffic\",\"reduce speed\"],\"ans\":1,\"exp\":\"A preventive RA tells you what NOT to do - avoid the vertical speeds shown in red. A corrective RA requires a change of vertical speed (\\\"Climb, climb\\\" / \\\"Adjust vertical speed\\\"). TCAS II never commands turns.\",\"seenIn\":[\"Dec 2023 · Regular\"],\"undated\":false,\"times\":1,\"years\":[2023],\"kind\":\"asked\",\"optionsWritten\":false},{\"id\":\"CPLNAV-948\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"In an INS, the first integration of the north/south accelerometer output gives:\",\"opts\":[\"latitude\",\"velocity along the local meridian\",\"groundspeed\",\"change of latitude\"],\"ans\":1,\"exp\":\"acceleration -> (1st integration) velocity -> (2nd integration) distance / change of position.\",\"seenIn\":[\"Aug 2024 · OLODE 06\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":true},{\"id\":\"CPLNAV-949\",\"topic\":\"GNSS, INS/IRS & FMS\",\"stem\":\"WGS-84 is:\",\"opts\":[\"the geodetic datum (reference ellipsoid and coordinate system) used by GPS and adopted by ICAO\",\"a model of magnetic variation\",\"a chart projection for polar areas\",\"the time standard used by GNSS\"],\"ans\":0,\"exp\":\"WGS-84 (World Geodetic System 1984) is the reference ellipsoid and coordinate frame in which GPS computes positions; ICAO requires published aeronautical coordinates to be referred to WGS-84.\",\"seenIn\":[\"Oct 2024 · OLODE 07\"],\"undated\":false,\"times\":1,\"years\":[2024],\"kind\":\"asked\",\"optionsWritten\":false}]}]");
